        title = "మూసి ఉన్న తలుపు మిమ్మల్ని తగ్గించదు",
        preview = "ఎవరి నోట మీ మార్గాన్ని మార్చవచ్చు, కానీ అది మీ విలువను తీసివేయదు.",
        paragraphs = listOf("తిరస్కరణ, 'మీరు సరిపోరు' అని ప్రపంచం చెప్పినట్లు అనిపించవచ్చు. కానీ ఒక వ్యక్తి, స్థలం లేదా అవకాశం మీ గురించి పూర్తి సత్యాన్ని కలిగి ఉండదు. వారి సమాధానం వారి అవసరాలు, సమయం లేదా పరిమితుల నుండి రావచ్చు. బాధను అనుభవించండి, కానీ దానిని మీ కోసం ఒక పేరుగా మార్చుకోకండి.", "మూసి ఉన్న తలుపు మిమ్మల్ని కొత్త రహదారి వైపు మళ్లిస్తుంది. మీరు ఇంకా ఆ రోడ్డు చూడలేరని నాకు తెలుసు. అది ఇచ్చినట్లయితే ఉపయోగకరమైన అభిప్రాయాన్ని తీసుకోండి. మీరు మెరుగుపరచాల్సిన వాటిని మెరుగుపరచండి. కానీ మీరు జాగ్రత్తగా వ్యవహరించని ప్రదేశాన్ని గెలవడానికి మిమ్మల్ని మీరు చెరిపివేయవద్దు.", "తనిఖీ చేయడం, యాచించడం మరియు పోల్చడం నుండి దూరంగా ఉండండి. మీ నిజాయితీ హృదయాన్ని ఇప్పటికీ స్వాగతించే వ్యక్తులు మరియు విధులకు తిరిగి వెళ్లండి. మీతో సహా మీరు గౌరవానికి అర్హులు. మీ హృదయాన్ని మృదువుగా మరియు మీ పరిమితులను స్పష్టంగా ఉంచండి. ఇంకా మంచి వ్యక్తులు, మంచి పని మరియు కొత్త తలుపులు ఉన్నాయి.", "మీరు మళ్లీ ఆశించడానికి సిద్ధంగా ఉండకపోవచ్చు. అదంతా సరే."),
        reflection = "ఇందులో ఉపయోగకరమైన ఫీడ్‌బ్యాక్ ఏ భాగం మరియు భయం మాట్లాడటం ఏ భాగం?",
        nextStep = "తనిఖీ చేయడం లేదా పోల్చడం ఆపివేయండి మరియు ఆ సమయాన్ని మంచి పని లేదా సురక్షితమైన వ్యక్తికి ఇవ్వండి."
    ),
    "guilt" to KrishnaLetterTranslation(
        situation = "అపరాధం మిమ్మల్ని విడుదల చేయనప్పుడు",
        title = "సరైనదిగా చేయండి, ఆపై ఎదగండి",
        preview = "ఒక తప్పుడు చర్య నిజం మరియు మార్పు కోసం అడుగుతుంది, అంతులేని స్వీయ-ద్వేషం కాదు.",
        paragraphs = listOf("మీరు ఏదైనా చర్యరద్దు చేయాలని కోరుకుంటున్నారు. అపరాధం జాగ్రత్త అవసరమని సూచించవచ్చు. కానీ మీరు మీ చెత్త చర్య మాత్రమే అని అది మీకు చెప్పకూడదు. మీరు ఏదో తప్పు చేసారు; అంటే మీరు మళ్లీ సరైనవారు కాలేరని కాదు. నేను సత్యాన్ని అడుగుతున్నాను, పరిపూర్ణ గతం కాదు.", "ఏమి జరిగిందో పేరు పెట్టండి. దానిని దాచవద్దు లేదా మరొక వ్యక్తిని నిందించవద్దు. మీకు మంచి అనుభూతిని కలిగించడానికి వారిని అడగకుండా క్షమించండి. మీరు చేయగలిగిన దాన్ని మరమ్మతు చేయండి. సరసమైన ఫలితాలను అంగీకరించండి. అప్పుడు హాని కలిగించిన అలవాటును మార్చుకోండి. కోపం ఎవరినైనా బాధపెడితే, పాజ్ చేయడం నేర్చుకోండి. ఒక అబద్ధం నమ్మకాన్ని దెబ్బతీస్తే, చిన్న విషయాలలో నిజం మాట్లాడటం ప్రారంభించండి.", "నిజమైన విచారం మెరుగైన చర్య అవుతుంది. ఇది మిమ్మల్ని శాశ్వతంగా నేలపై ఉంచదు. కొంతమందికి సమయం లేదా స్థలం అవసరం కావచ్చు. దానిని గౌరవించండి. మీరు తప్పును కలిగి ఉన్న తర్వాత మరియు మార్చడం ప్రారంభించిన తర్వాత, మిమ్మల్ని మీరు కాంతి వైపు నడవనివ్వండి. మీరు నేర్చుకున్న పాఠాన్ని జీవించే అవకాశం మీకు ఉంది.", "పాఠాన్ని మరచిపోమని నేను మిమ్మల్ని అడగను. దాన్ని మీపై ఆయుధంగా వాడుకోవడం మానేయమని నేను మిమ్మల్ని అడుగుతున్నాను."),
        reflection = "ఏ నిజాయితీ మరమ్మత్తు లేదా మార్చబడిన చర్య మీ విచారం మంచి ప్రయోజనాన్ని ఇస్తుంది?",
        nextStep = "నాలుగు పంక్తులు వ్రాయండి: నేను ఏమి చేసాను, ఎవరికి బాధ కలిగించింది, నేను దానిని ఎలా రిపేర్ చేయగలను మరియు అది మళ్లీ జరగకుండా ఎలా ఆపాలి."
    ),
    "uncertainty" to KrishnaLetterTranslation(
        situation = "మార్గం అనిశ్చితంగా ఉన్నప్పుడు",
        title = "మీకు తదుపరి సరైన దశ మాత్రమే అవసరం",
        preview = "మీరు ప్రారంభించడానికి ముందు మీకు మొత్తం రహదారి అవసరం లేదు.",
        paragraphs = listOf("తెలియకపోవటం వలన మీ మనస్సు ప్రతి దిశలో పరుగెత్తుతుంది. ఏమీ తప్పు జరగదని మీకు సంకేతం కావాలి. జీవితం ఆ వాగ్దానాన్ని ఇవ్వదు. ప్రతి ప్రశ్నను నాకు తీసుకురండి. స్పష్టంగా చూడడానికి మీకు సమయం కావాలి కాబట్టి మీరు బలహీనులు కాదు.", "వాస్తవాలను ఒక వైపు మరియు మీ భయాలను మరోవైపు ఉంచండి. అడగండి: నాకు ఏమి తెలుసు? కేవలం ఒక అంచనా ఏమిటి? నా కర్తవ్యానికి నిజాయితీ, దయ మరియు నిజమైన ఎంపిక ఏది? మిమ్మల్ని నియంత్రించడానికి ప్రయత్నించకుండా మీకు మార్గనిర్దేశం చేసే నమ్మకమైన గురువు, గురువు లేదా పెద్దలతో మాట్లాడండి. నిజమైన గురువు మీ అవగాహనకు వెలుగునిస్తుంది; వారు మీ కళ్ళు మూసుకోవాలని లేదా నిజాయితీగా తీర్పు ఇవ్వాలని డిమాండ్ చేయరు. ఆపై మీకు మరింత బోధించే అతి చిన్న సురక్షిత దశను ఎంచుకోండి.", "ఈ రాత్రికి మీరు మీ జీవితమంతా పరిష్కరించుకోవాల్సిన అవసరం లేదు. మీరు చూడగలిగే రహదారి భాగాన్ని నడవండి. మీరు మరింత తెలుసుకున్నప్పుడు మీరు మీ ప్లాన్‌ని మార్చవచ్చు. అది జ్ఞానం, వైఫల్యం కాదు. నేను మీ ప్రయాణం ముగింపులో మాత్రమే కాదు. ఈ ప్రశాంతమైన మరియు నిజాయితీగల తదుపరి దశలో నేను మీతో ఉన్నాను.", "ఈరోజు మీరు చేయగలిగినంత చేసిన తర్వాత మీ మనసుకు విశ్రాంతినివ్వండి. మీరు ఇప్పుడు చూడలేని వాస్తవాన్ని, వ్యక్తిని లేదా ఆలోచనను రేపు తీసుకురావచ్చు."),
        reflection = "ఏమి తెలుసు, ఏది మాత్రమే భయపడుతుంది మరియు మీ తదుపరి సరైన దశ ఏమిటి?",
        nextStep = "మూడు చిన్న జాబితాలను రూపొందించండి: నాకు ఏమి తెలుసు, నేను ఏమి భయపడుతున్నాను మరియు ఈరోజు నేను ఏమి చేయగలను."
    ),
    "anxiety" to KrishnaLetterTranslation(
        situation = "ఆందోళన మిమ్మల్ని ముంచెత్తినప్పుడు",
        title = "ఈ క్షణానికి తిరిగి రండి",
        preview = "మీరు ప్రస్తుతం సాధ్యమయ్యే ప్రతి భవిష్యత్తును పరిష్కరించాల్సిన అవసరం లేదు.",
        paragraphs = listOf("ఆందోళన ఒక చిన్న ఆలోచనను ఎలా పెను ప్రమాదంగా భావిస్తుందో నాకు తెలుసు. మీ శరీరం బిగుతుగా అనిపించవచ్చు, మీ శ్వాస వేగంగా మారవచ్చు మరియు మీ మనస్సు ఇలా అడుగుతుంది, మీరు బలహీనంగా లేదా విరిగిపోలేదు. మిమ్మల్ని సురక్షితంగా ఉంచడానికి మీ మనస్సు చాలా కష్టపడుతోంది.", "రెండు పాదాలను నేలపై ఉంచండి. నెమ్మదిగా శ్వాస తీసుకోండి మరియు మీరు చూడగలిగే ఐదు అంశాలకు పేరు పెట్టండి. ఇప్పుడు ఏమి జరుగుతుందో అడగండి, భయం చెప్పేది తరువాత జరగవచ్చని కాదు. మీ ముందు ఉన్న నిజమైన పనిని వ్రాయండి. స్పష్టమైన చిన్న చర్య భవిష్యత్తును తక్కువ శక్తివంతం చేస్తుంది.", "దీన్ని ఒంటరిగా తీసుకెళ్లవద్దు. ఆందోళన నిద్ర, పాఠశాల, పని లేదా రోజువారీ జీవితంలో ఆగిపోయినప్పుడు సురక్షితమైన వ్యక్తికి చెప్పండి. శిక్షణ పొందిన సహాయకుడు మీ మనస్సు మరియు శరీరాన్ని మళ్లీ సురక్షితంగా ఎలా భావించాలో నేర్పించవచ్చు. సహాయం కోసం అడగడం తెలివైనది మరియు అది మీ విశ్వాసాన్ని చిన్నదిగా చేయదు.", "మీ శ్వాస వేగంగా మారినప్పుడు, నాకు నిశ్శబ్దంగా కాల్ చేయండి మరియు మీ ముందు ఉన్న శ్వాసలోకి తిరిగి వెళ్లండి. నేను ప్రతి సమస్యకు చివర నిలబడను, మీరు ఒంటరిగా పరిష్కరించుకుంటారని ఎదురు చూస్తున్నాను."),
        reflection = "భయం దాని కథను జోడించే ముందు ఈ క్షణంలో ఏది నిజం?",
        nextStep = "ఐదు నెమ్మదిగా శ్వాసలు తీసుకోండి, ఇప్పుడు ఏది వాస్తవమో పేరు పెట్టండి మరియు మీరు ఎలా భావిస్తున్నారో ఒక సురక్షితమైన వ్యక్తికి చెప్పండి."
    ),
    "lost-hope" to KrishnaLetterTranslation(
        situation = "మీరు ఆశను కోల్పోయినప్పుడు",
        title = "ఈ చీకటి సమయం మొత్తం కథ కాదు",
        preview = "హోప్ ఒక చిన్న ఎంపికగా ఉండడానికి మరియు సంరక్షణను స్వీకరించడానికి ప్రారంభమవుతుంది.",
        paragraphs = listOf("మీరు ఎలా చూడలేనప్పుడు విషయాలు మెరుగుపడతాయని మీరు విని విసిగిపోయారని నాకు తెలుసు. ఈ రోజు ఆశ చాలా దూరం అనిపించవచ్చు. మీరు నటించాల్సిన అవసరం లేదు. చీకటి గురించి నాకు నిజం చెప్పండి మరియు ఈ ఉత్తరం మిమ్మల్ని నవ్వమని అడగకుండా మీ పక్కన కూర్చోనివ్వండి.", "కష్టతరమైన సమయం నుండి మీ జీవితం గురించి తుది నిర్ణయం తీసుకోకండి. ఒక మూసిన తలుపు ప్రపంచం మొత్తం కనిపించే వరకు నొప్పి మీ వీక్షణను తగ్గించగలదు. సురక్షితమైన వ్యక్తి నుండి ఆశను అరువు తెచ్చుకోండి. ఆహారం, విశ్రాంతి, కాల్, అపాయింట్‌మెంట్ లేదా తదుపరి సాధారణ పనిలో వారికి సహాయం చేయనివ్వండి.", "మీరు మిమ్మల్ని మీరు గాయపరచుకుంటే లేదా సురక్షితంగా అనిపించకపోతే, అత్యవసర సహాయాన్ని లేదా విశ్వసనీయ వ్యక్తిని ఇప్పుడే సంప్రదించండి మరియు ఎవరితోనైనా ఉండండి. మీ జీవితం విలువైనది, తక్షణ మద్దతు ధైర్యాన్ని నింపే చర్య. ఈ రోజు, ఆశ ఇది మాత్రమే కావచ్చు: తర్వాతి గంటను మీరు ఒంటరిగా ఎదుర్కోలేరు.", "మీరు ఈ రోజు ఆశను మోయలేకపోతే, మీ కోసం దానిని మోయనివ్వండి. మీ పని ఒక్కటే కావచ్చు, అక్కడే ఉండడం, నీరు తాగడం, తెర తెరిచి, చీకటి భారంగా ఉందని సురక్షితమైన వ్యక్తికి చెప్పడం."),
        reflection = "మీరు ఒంటరిగా పట్టుకోలేనప్పుడు మీపై ఎవరు ఆశలు పెట్టగలరు?",
        nextStep = "ఇప్పుడు ఒక సురక్షితమైన వ్యక్తిని సంప్రదించండి మరియు 'నేను ఫర్వాలేదు, మరియు నాతో మీరు కావాలి' అని స్పష్టంగా చెప్పండి."
    ),
    "heart-broken" to KrishnaLetterTranslation(
        situation = "మీ హృదయం విరిగిపోయినప్పుడు",
        title = "ప్రేమ ముగింపు మిమ్మల్ని అంతం చేయదు",
        preview = "మీరు వాటిని కోల్పోవచ్చు మరియు ఇప్పటికీ మీ ముందున్న జీవితాన్ని ఎంచుకోవచ్చు.",
        paragraphs = listOf("విరిగిన హృదయం ప్రతి పాటను, స్థలాన్ని మరియు నిశ్శబ్ద గంటను ఎలా మార్చగలదో నాకు తెలుసు. వారు ఉండేందుకు మీరు ఏమి చేయగలరని మీరు అడుగుతూ ఉండవచ్చు. మీ భావాలు నిజమైనవి అయినప్పటికీ ప్రేమ ముగుస్తుంది. వారి నిష్క్రమణ మీరు ప్రేమకు అనర్హుడని నిరూపించదు.", "ఇంకొక సమాధానాన్ని వెంబడించకుండా మీరే దుఃఖించండి. వారి ఎంపికను గౌరవించండి మరియు మీ గౌరవాన్ని కాపాడుకోండి. తనిఖీ చేయడం, పాత మెసేజ్‌లు మరియు ఎప్పుడూ పరిపూర్ణంగా లేని వాటి యొక్క సంపూర్ణ జ్ఞాపకశక్తి నుండి దూరంగా ఉండండి. మీరు గాయాన్ని మళ్లీ తెరవడాన్ని ఆపివేసిన ప్రతిసారీ, మీరు మీ హృదయాన్ని నయం చేయడానికి కొద్దిగా స్థలాన్ని ఇస్తారు.", "ఆహారం, నిద్ర, పని, స్నేహితులు మరియు ప్రార్థనకు నెమ్మదిగా తిరిగి వెళ్లండి. వైద్యం అంటే ప్రేమ అబద్ధమని కాదు. మీ హృదయం రేపటిని కోల్పోకుండా జ్ఞాపకశక్తిని మోయడం నేర్చుకుంటోందని అర్థం. మీరు ఈరోజు చేసినట్లుగా మీరు ఎల్లప్పుడూ అనుభూతి చెందలేరు. ఆ సత్యం నిజమయ్యే వరకు మెల్లగా నడుచుకోండి.", "మీరు హత్తుకునే జ్ఞాపకాలను మరియు సమాధానం లేని ప్రశ్నలను నాకు ఇవ్వండి. ఒక్కరోజులో ప్రేమించడం మానేయమని అడగను."),
        reflection = "మీ హృదయం విశ్రాంతి తీసుకునేలా తనిఖీ చేయడాన్ని ఆపివేయడానికి మీరు ఏమి సిద్ధంగా ఉన్నారు?",
        nextStep = "రోజువారీ వీక్షణ నుండి ఒక బాధాకరమైన రిమైండర్‌ను తరలించి, ఒక సురక్షితమైన వ్యక్తితో సమయం గడపండి."
    ),
    "not-enough" to KrishnaLetterTranslation(
        situation = "మీరు సరిపోరని భావించినప్పుడు",
        title = "మీరు మీ విలువను సంపాదించాల్సిన అవసరం లేదు",
        preview = "వృద్ధి అవసరం, కానీ స్వీయ-ద్వేషం వృద్ధి ధర కాదు.",
        paragraphs = listOf("బహుశా ఫలితంగా, ఒక వ్యాఖ్య లేదా పోలిక మిమ్మల్ని చాలా చిన్నదిగా భావించి ఉండవచ్చు. మీరు గౌరవం పొందడానికి ముందు మీరు తెలివిగా, ధనవంతులుగా, అందంగా లేదా బలంగా మారాలని మీరు నమ్మవచ్చు. అంటే నొప్పిగా మాట్లాడటం. మీ విలువ ప్రశంసలతో రాలేదు మరియు విమర్శలతో వదిలివేయదు.", "మీరు మీ మొత్తం స్వీయ తప్పు అని పిలవకుండా మీరు ఎక్కడ ఎదగాలి అని అంగీకరించవచ్చు. సాధన చేయడానికి ఒక నైపుణ్యాన్ని మరియు మార్చడానికి ఒక అలవాటును ఎంచుకోండి. దిద్దుబాటు స్పష్టంగా మరియు దయగా ఉండనివ్వండి. ఒక మొక్క కాంతి వైపు పెరుగుతుంది; దాని మూలాలను ఎవరో అరిస్తే అది పెరగదు.", "మీలో ఇప్పటికే ఉన్న మంచిని గమనించండి: మీరు చేసే ప్రయత్నం, మీరు చూపించే శ్రద్ధ, మీరు మాట్లాడటం నేర్చుకుంటున్న సత్యం. ప్రతి వ్యక్తి వలె మీరు అసంపూర్తిగా ఉన్నారు. మీ పరిపూర్ణ సంస్కరణ కోసం నేను వేచి ఉండను. ఈ రోజు మీరు ఉన్న నిజాయితీ గల వ్యక్తితో నేను నడుస్తున్నాను.", "నా దృష్టిలో ఒక్క క్షణం మిమ్మల్ని మీరు చూసుకోండి. నేను ఆత్మ అభ్యాసాన్ని చూస్తున్నాను, ఆమోదం కోసం వేచి ఉన్న ఉత్పత్తి కాదు."),
        reflection = "మీరు సరిపోరని నిర్ణయించడానికి మీరు ఎవరి ప్రమాణాన్ని ఉపయోగిస్తున్నారు?",
        nextStep = "మీలో ఇప్పటికే నిజమైన మూడు లక్షణాలను వ్రాయండి మరియు మీరు సున్నితంగా అభ్యసించే ఒక నైపుణ్యాన్ని వ్రాయండి."
    ),
    "misunderstood" to KrishnaLetterTranslation(
        situation = "ఎవరూ మిమ్మల్ని అర్థం చేసుకోనట్లు అనిపించినప్పుడు",
        title = "మీ వాయిస్ ఇప్పటికీ సురక్షితమైన స్థానానికి అర్హమైనది",
        preview = "తప్పుగా అర్థం చేసుకోవడం వల్ల మీ భావాలు తప్పు కాదు.",
        paragraphs = listOf("మీ హృదయాన్ని వివరించడం బాధాకరం మరియు ఇప్పటికీ కనిపించడం లేదు. మాట్లాడటం పనికిరాదని మీరు ఆలోచించడం ప్రారంభించవచ్చు. కొన్నిసార్లు ప్రజలు తమ స్వంత భయం, తొందరపాటు లేదా గతం ద్వారా మాత్రమే వింటారు. వారి పేలవమైన అవగాహన మీకు అనిపించే సత్యాన్ని తుడిచివేయదు.", "ఒక సురక్షితమైన వ్యక్తి మరియు ఒక స్పష్టమైన వాక్యంతో మళ్లీ ప్రయత్నించండి. ఏమి జరిగింది, అది మిమ్మల్ని ఎలా ప్రభావితం చేసింది మరియు ఇప్పుడు మీకు ఏమి అవసరమో చెప్పండి. సూచనలలో మీ అర్థాన్ని దాచవద్దు మరియు క్రూరమైన పదాలను ఉపయోగించి మీ బాధను బిగ్గరగా చేయవద్దు. స్పష్టత అర్థం చేసుకోవడానికి ఉత్తమ అవకాశాన్ని ఇస్తుంది.", "ప్రతి ఒక్కరూ మీలోని ప్రతి భాగాన్ని అర్థం చేసుకోలేరు. అడగడానికి, వినడానికి మరియు నేర్చుకోవడానికి ఇష్టపడే వ్యక్తులను వెతకండి. ఒక వ్యక్తి మీ మాటలను వక్రీకరిస్తూ ఉంటే, మీరు వెనక్కి తగ్గవచ్చు. మీరు మొత్తం ప్రపంచం అంగీకరించాల్సిన అవసరం లేదు; మీకు మీ స్వంత అంతర్గత స్వరానికి నిజం, సురక్షితమైన మద్దతు మరియు గౌరవం అవసరం.", "మీ మాటలు చెడుగా బయటకు వచ్చినప్పటికీ, మీరు మోసుకెళ్లడానికి ప్రయత్నిస్తున్న నిజం నాకు తెలుసు. నాతో కూర్చోండి, పదాలను సులభతరం చేయండి మరియు సురక్షితంగా ఉన్న వారితో మళ్లీ ప్రయత్నించండి."),
        reflection = "ఎవరైనా వినడానికి మీకు అత్యంత అవసరమైన ఒక వాక్యం ఏమిటి?",
        nextStep = "ఆ వాక్యాన్ని వ్రాసి, సాధారణంగా శ్రద్ధగా వినే వ్యక్తితో పంచుకోండి."
    ),
    "future-fear" to KrishnaLetterTranslation(
        situation = "మీరు భవిష్యత్తు గురించి భయపడినప్పుడు",
        title = "రేపటికి నేటి భయం అవసరం లేదు",
        preview = "మీరు చేయగలిగిన దాని కోసం సిద్ధం చేసుకోండి మరియు తెలియని విషయాలను తెరవకుండా వదిలివేయండి.",
        paragraphs = listOf("భవిష్యత్తు నీడలతో నిండిన గదిలా ఉంటుంది. మీ మనస్సు చాలా బాధాకరమైన దృశ్యాలను సృష్టించి, అవి ఇప్పటికే వాస్తవమైనవేననే విధంగా ప్రతిస్పందించవచ్చు. అందులో చాలా సన్నివేశాలు ఊహాగానాలే. మీరు ఈనాటి శక్తిని ఎన్నటికీ రాని యుద్ధాల కోసం ఖర్చు చేస్తున్నారు.", "ఇప్పుడు ఏమి సిద్ధం చేయవచ్చో అడగండి. కాల్ చేయండి, కొద్దిగా సేవ్ చేయండి, ఒక భాగాన్ని అధ్యయనం చేయండి, అపాయింట్‌మెంట్ ఉంచండి లేదా సలహా కోసం అడగండి. తయారీ ఉపయోగకరంగా ఉంటుంది; అంతులేని అంచనా కాదు. నేటి కర్తవ్యాన్ని పూర్తి చేసిన తర్వాత, ప్రస్తుతానికి తిరిగి రావడానికి మీ శరీరానికి అనుమతి ఇవ్వండి.", "మీరు తెలియని రోజుల ముందు కలుసుకున్నారు. సహాయం, నైపుణ్యం మరియు ధైర్యం ఒకేసారి కాదు, దశలవారీగా కనిపించాయి. రేపు కూడా ఒక్కో క్షణం వస్తుంది. అది మీకు చేరే ముందు ఒక రోజు తీసుకువెళ్ళమని నేను మిమ్మల్ని అడగను. ఇక్కడ ఉన్న రోజులో నాతో నడవండి.", "మీరు మీ మనస్సులో రేపటికి నడుస్తూ అలసిపోతూ ఉంటారు. నా దగ్గరకు తిరిగి రండి."),
        reflection = "ఏ భయానికి నిజమైన ప్రణాళిక అవసరం మరియు ఏ భయాన్ని విడుదల చేయాలి?",
        nextStep = "నిజమైన ఆందోళన కోసం ఒక ఆచరణాత్మక అడుగు వేయండి, ఆపై పది నిమిషాలు పూర్తిగా వర్తమానంలో గడపండి."
    ),
    "life-unfair" to KrishnaLetterTranslation(
        situation = "జీవితం అన్యాయంగా అనిపించినప్పుడు",
        title = "మీరు చేదుగా మారకుండా తప్పును ఎదుర్కోవచ్చు",
        preview = "మీ నొప్పి నిజం, మద్దతు మరియు తెలివైన ప్రతిస్పందనకు అర్హమైనది.",
        paragraphs = listOf("కొన్ని విషయాలు అన్యాయంగా ఉన్నాయి. ప్రతి గాయం రహస్యంగా తేలికగా ఉంటుందని లేదా మీరు అన్యాయాన్ని చూసి నవ్వాలని నేను మీకు చెప్పను. మీరు నిజాయితీగా పని చేసి ఉండవచ్చు మరియు ఇప్పటికీ ఓడిపోయి ఉండవచ్చు లేదా మీరు చేయని ఎంపిక వల్ల బాధపడి ఉండవచ్చు. మీ కోపం మరియు విచారం మాట్లాడటానికి స్థలం కావాలి.", "ఇప్పుడు న్యాయం ఎలా ఉందో అడగండి. దీని అర్థం నిజం చెప్పడం, రుజువు ఉంచడం, సహాయం కోసం అడగడం, పరిమితిని నిర్ణయించడం లేదా మరొకరిని రక్షించడం. మరింత హాని కలిగించే ప్రతీకారం కంటే మరమ్మతు చేసే చర్యను ఎంచుకోండి. నీ హృదయాన్ని క్రూరంగా మార్చకుండా ధర్మం దృఢంగా ఉంటుంది.", "మీరు అన్డు చేయలేనివి కూడా ఉంటాయి. మీరు ఎలాంటి వ్యక్తి అవుతారో మరొక వ్యక్తి యొక్క తప్పు నిర్ణయించనివ్వవద్దు. మీ విలువలను కొనసాగించండి, మద్దతును అంగీకరించండి మరియు ఇంకా సాధ్యమయ్యే వాటిని నిర్మించండి. వారి అన్యాయం వారికి చెందినది; మీ తదుపరి శుభ్రమైన చర్య మీకు చెందుతుంది.", "మీ బాధను శాంతింపజేయడానికి నేను అన్యాయాన్ని ఆశీర్వాదంగా పిలవను. నిజం చెప్పండి, సహాయం కోరండి మరియు మిమ్మల్ని బాధపెట్టకుండా మిమ్మల్ని మీరు రక్షించుకోండి."),
        reflection = "ఇంకా మీ చేతుల్లో ఏ న్యాయమైన మరియు సురక్షితమైన చర్య ఉంది?",
        nextStep = "విశ్వసనీయ వ్యక్తికి వాస్తవాలను చెప్పండి మరియు రక్షణ, మరమ్మత్తు లేదా మద్దతు వైపు ఒక అడుగు ఎంచుకోండి."
    ),
    "tired-strong" to KrishnaLetterTranslation(
        situation = "మీరు బలంగా ఉండటంతో అలసిపోయినప్పుడు",
        title = "మీరు బరువును తగ్గించుకోవడానికి అనుమతించబడతారు",
        preview = "విశ్రాంతి మరియు సహాయం ధైర్యం యొక్క వైఫల్యాలు కాదు.",
        paragraphs = listOf("మీరు ఎల్లప్పుడూ నిర్వహించడం వలన ప్రతి ఒక్కరూ మీ వద్దకు వస్తారు. వారు మీ ప్రశాంతమైన ముఖాన్ని చూస్తారు మరియు మీరు లోపల ఎంత అలసిపోయారో చూడరు. మీరు అన్నింటినీ పట్టుకోవడం ఆపివేస్తే, అదంతా పడిపోతుందని మీరు భయపడవచ్చు. బలమైన చేతులు కూడా తమ భారాన్ని ఉంచడానికి ఎక్కడో అవసరం.", "శక్తి అనేది ప్రతి పనిని ఒంటరిగా చేయడం కాదు. ఇది ఏమి చేయాలి, ఏమి వేచి ఉండాలి మరియు మరొక వ్యక్తి ఏమి తీసుకువెళ్లగలడో తెలుసుకోవడం. ‘నాకు సహాయం కావాలి’ అని చెప్పండి. డిమాండ్ అవసరం లేని వ్యక్తిని రద్దు చేయండి. మీ శరీరం మిమ్మల్ని ఆపడానికి ముందు విశ్రాంతి తీసుకోండి. మీ అవసరాలు కూడా గదిలో ఉంటాయి.", "బ్రేకింగ్ పాయింట్‌కి చేరుకోవడం ద్వారా మీరు విశ్రాంతి పొందాల్సిన అవసరం లేదు. ఎవరైనా త్వరగా మీ సహాయాన్ని తిరిగి ఇవ్వకుండా మీ కోసం శ్రద్ధ వహించనివ్వండి. నేను చర్యలో మీతో ఉన్నాను మరియు నేను నిశ్చలతలో కూడా మీతో ఉన్నాను. ఈ రోజు మీ ధైర్యమైన అడుగు మృదువుగా, స్వీకరించడానికి మరియు ఊపిరి పీల్చుకోవచ్చు.", "మీరు ఎందుకు అలసిపోయారో వివరించకుండా నా పక్కన కూర్చోండి. మీరు ఈ క్షణానికి సరిపడా తీసుకువెళ్లారు."),
        reflection = "ఈరోజు మీరు ఏ బరువును సురక్షితంగా తగ్గించవచ్చు లేదా పంచుకోవచ్చు?",
        nextStep = "ఒక వ్యక్తిని ఒక నిర్దిష్ట రకమైన సహాయం కోసం అడగండి మరియు ఒక అనవసరమైన పనిని తీసివేయండి."
    ),
    "self-forgiveness" to KrishnaLetterTranslation(
        situation = "మీరు మిమ్మల్ని మీరు క్షమించుకోలేనప్పుడు",
        title = "ఒక తప్పును జీవిత వాక్యంగా మార్చుకోవద్దు",
        preview = "బాధ్యత వహించండి, హానిని సరిదిద్దండి మరియు మార్పును వాస్తవంగా అనుమతించండి.",
        paragraphs = listOf("మిమ్మల్ని మీరు శిక్షించుకోవడం కొనసాగించడం మిమ్మల్ని క్షమించమని రుజువు చేస్తుందని మీరు నమ్మవచ్చు. ఇది గతాన్ని బాగు చేయదు. ఇది నొప్పిని మాత్రమే చురుకుగా ఉంచుతుంది. సాకులు లేకుండా జరిగిన దానిని ఎదుర్కోవాలని నేను మిమ్మల్ని అడుగుతున్నాను, కానీ మంచిగా మారడానికి ప్రయత్నిస్తున్న వ్యక్తిని ద్వేషించమని నేను మిమ్మల్ని అడగను.", "తప్పుకు పేరు పెట్టండి, ఒత్తిడి లేకుండా క్షమాపణ చెప్పండి మరియు మీరు చేయగలిగిన వాటిని సరిచేయండి. మరొక వ్యక్తికి సమయం కావాలి లేదా తిరిగి రాకపోవచ్చు అని అంగీకరించండి. అప్పుడు అదే హానిని తగ్గించే స్పష్టమైన అభ్యాసాన్ని రూపొందించండి. మీ విచారం రక్షణ, నిజాయితీ మరియు తెలివైన చర్యగా మారనివ్వండి.", "మిమ్మల్ని మీరు క్షమించడం అంటే తప్పు ఆమోదయోగ్యమని చెప్పడం కాదు. పాఠాన్ని వృధా చేయడానికి నిరాకరించడం అని అర్థం. మీరు తదుపరి ఎంపికకు బాధ్యత వహిస్తారు, చివరిదాన్ని తిరిగి వ్రాయలేరు. పదే పదే స్వీయ నిందలు వేయలేని చోట మారిన ప్రవర్తన మాట్లాడనివ్వండి.", "మీరు శిక్షించబడాలని రుజువుగా ప్రతిరోజూ అదే తప్పును నాకు తీసుకురావద్దు. నిజం, మరమ్మత్తు మరియు మీరు మారడానికి ఎంచుకున్న వ్యక్తిని నాకు తీసుకురండి."),
        reflection = "ఏ మరమ్మత్తు లేదా మార్చబడిన అలవాటు మీ విచారం ఉపయోగకరంగా ఉంటుంది?",
        nextStep = "మీరు అందించగల ఒక మరమ్మత్తు మరియు మీ భవిష్యత్ ఎంపికలకు మార్గనిర్దేశం చేసే ఒక గార్డ్‌రైల్‌ను వ్రాయండి."
    ),
    "betrayal" to KrishnaLetterTranslation(
        situation = "ఎవరైనా మీకు ద్రోహం చేసినప్పుడు",
        title = "వారి ఎంపిక మీ నమ్మకాన్ని మూర్ఖంగా చేయదు",
        preview = "మీరు మంచి హృదయాన్ని ఉంచుకోవచ్చు మరియు తెలివైన పరిమితులను నిర్మించవచ్చు.",
        paragraphs = listOf("ద్రోహం బాధిస్తుంది ఎందుకంటే మీరు మీ హృదయంలో ఎవరికైనా సురక్షితమైన స్థానం ఇచ్చారు. ఇప్పుడు మీరు వారిపై కోపంగా ఉండవచ్చు మరియు విశ్వసించినందుకు మీ గురించి సిగ్గుపడవచ్చు. మీ దయను మూర్ఖత్వం అని పిలవకండి. విశ్వాసం మీరు అందించిన బహుమతి. దానిని దుర్వినియోగం చేయడం వారి ఎంపికకు సంబంధించినది.", "గాసిప్, పబ్లిక్ అవమానం లేదా మరొక రహస్యంతో బాధపడ్డ సమాధానం చెప్పకండి. నిజంగా ఏమి జరిగిందో తెలుసుకోండి. ఇది సురక్షితంగా ఉంటే, ఒక స్పష్టమైన ప్రశ్న అడగండి. నిజమైన క్షమాపణలో యాజమాన్యం, మరమ్మత్తు మరియు మార్చబడిన చర్య ఉంటాయి. మార్పు లేని మాటలు ఎంత అందంగా అనిపించినా నమ్మకాన్ని పునర్నిర్మించవు.", "మీరు క్షమించవచ్చు మరియు ఇప్పటికీ దూరం ఉంచవచ్చు. మీరు పట్టించుకోవచ్చు మరియు ఇప్పటికీ లేదు అని చెప్పవచ్చు. చర్యలు మద్దతిచ్చినప్పుడే విశ్వాసాన్ని చిన్న దశల్లో తిరిగి ఇవ్వనివ్వండి. ఒక వ్యక్తి యొక్క ద్రోహం ప్రతి భావి స్నేహితుడు అదే చేస్తాడని అర్థం కాదు. మీ హృదయాన్ని మంచిగా మరియు మీ సరిహద్దులను మేల్కొని ఉంచండి.", "మీ గుండె ఇప్పుడు ప్రతి తలుపును రెండుసార్లు ఎందుకు తనిఖీ చేస్తుందో నాకు తెలుసు. భద్రత స్పష్టంగా తెలియకముందే విశ్వసించమని బలవంతం చేయవద్దు."),
        reflection = "నమ్మకం మళ్లీ పెరగడానికి ముందు వాగ్దానం కాదు-ఏ చర్య అవసరం?",
        nextStep = "మీకు అవసరమైన సరిహద్దును వ్రాయండి మరియు సంభాషణ సురక్షితంగా ఉంటే దానిని ప్రశాంతంగా పంచుకోండి."
    ),
    "letting-go" to KrishnaLetterTranslation(
        situation = "మీరు ఎవరినైనా వెళ్లనివ్వాలి",
        title = "ప్రేమ అది ఉంచుకోలేనిది విడుదల చేయగలదు",
        preview = "విడిచిపెట్టడం సత్యాన్ని మరియు మీ స్వంత గౌరవాన్ని గౌరవిస్తుంది.",
        paragraphs = listOf("కొన్నిసార్లు ప్రేమ మిగిలి ఉంటుంది, అయితే సంబంధం ఇకపై కొనసాగదు. ఖాళీ స్థలం మిమ్మల్ని భయపెడుతుంది కాబట్టి మీరు నిజం తెలుసుకోవచ్చు మరియు ఇంకా తిరిగి చేరుకోవచ్చు. వెళ్లనివ్వడం మీరు ఎప్పుడూ పట్టించుకోలేదని రుజువు కాదు. మీ సంరక్షణ ఇప్పుడు తీసుకోగల అత్యంత నిజాయితీ రూపం ఇది కావచ్చు.", "ఇద్దరూ మూసివేయడానికి అంగీకరించిన తలుపును తెరుస్తూ ఉండకండి. చెప్పవలసినది ఒక్కసారి గౌరవంగా చెప్పండి. వారికి చెందిన వాటిని తిరిగి ఇవ్వండి, మీరు నేర్చుకున్న వాటిని ఉంచండి మరియు ఆశను గందరగోళంగా ఉంచే చిన్న పరిచయాలను తగ్గించండి. స్పష్టమైన ముగింపు అంతులేని సగం-వీడ్కోలు కంటే దయగా ఉంటుంది.", "దుఃఖం అలలుగా వస్తుంది. సురక్షితమైన వ్యక్తులు మీ దగ్గర నిలబడనివ్వండి. పాతవి నివసించిన చోట కొత్త దినచర్యలను రూపొందించండి. మీరు ప్రేమను విసిరివేయడం లేదు; మీరు దానిని గొలుసుగా మార్చడానికి నిరాకరిస్తున్నారు. వారు పూరించలేని పాత్ర నుండి వారిని విడుదల చేయండి మరియు జీవించడానికి మిమ్మల్ని మీరు విడుదల చేసుకోండి.", "పట్టుకున్నప్పుడు వారి పేరును నా చేతుల్లో పెట్టండి, అది మిమ్మల్ని బాధపెడుతుంది. మీరు మంచిని తొలగించాల్సిన అవసరం లేదు లేదా నొప్పిని తిరస్కరించాల్సిన అవసరం లేదు."),
        reflection = "వీడ్కోలు అసంపూర్తిగా ఉంచడానికి ఏ పరిచయం లేదా అలవాటు?",
        nextStep = "రెండు హృదయాలకు స్వస్థత చేకూర్చేందుకు ఒక గౌరవప్రదమైన సరిహద్దును ఎంచుకోండి."
    ),
    "family-struggling" to KrishnaLetterTranslation(
        situation = "మీ కుటుంబం కష్టాల్లో ఉన్నప్పుడు",
        title = "మీరు అందరినీ మోయకుండా జాగ్రత్త వహించవచ్చు",
        preview = "మీ వంతు ప్రేమతో చేయండి, కానీ మొత్తం భారాన్ని ఒంటరిగా తీసుకోకండి.",
        paragraphs = listOf("కుటుంబం కష్టాల్లో ఉన్నప్పుడు, ప్రతి గది ఆందోళన కలిగిస్తుంది. డబ్బు, ఆరోగ్యం, సంఘర్షణ లేదా మార్పు మీరు అన్నింటినీ సరిదిద్దాలి అనే అనుభూతిని కలిగించవచ్చు. మీ స్వంత అవసరాలను కలిగి ఉన్నందుకు మీరు నేరాన్ని కూడా అనుభవించవచ్చు. మీరు కుటుంబంలో భాగం, కానీ మీరు దాని పూర్తి మద్దతుగా మారడానికి ఉద్దేశించబడలేదు.", "ఈరోజు నిజంగా మీ కర్తవ్యం ఏమిటో అడగండి. ఒక పనిలో సహాయం చేయండి, సున్నితంగా మాట్లాడండి మరియు భయానికి బదులుగా వాస్తవాలను పంచుకోండి. ప్రతి సామర్థ్యం గల వ్యక్తి సరసమైన భాగాన్ని మోయనివ్వండి. ప్రేమ మాత్రమే అందించగల సమస్య కంటే ఎక్కువ అవసరమైనప్పుడు బంధువులు, ఉపాధ్యాయులు, వైద్యులు, కౌన్సెలర్లు లేదా సేవల నుండి సహాయం కోరండి.", "సాధారణ జీవితం యొక్క చిన్న సంకేతాలను రక్షించండి: కలిసి భోజనం, అధ్యయనం సమయం, నిద్ర, నడక లేదా ఒక నిజాయితీ నవ్వు. ప్రతి మంచి క్షణాన్ని తీసుకోవడానికి కష్టాన్ని అనుమతించకూడదు. మీ ప్రశాంతమైన సంరక్షణ కుటుంబానికి సహాయపడుతుంది మరియు సంరక్షణను స్వీకరించడం మీరు స్థిరంగా ఉండటానికి సహాయపడుతుంది.", "ఇంట్లోని ప్రతి సమస్యను మీరు ఎంత త్వరగా వింటారో నేను చూస్తున్నాను. నా ప్రియమైన వ్యక్తి, మీరు ఈ కుటుంబంలో సభ్యుడు, దాని రక్షకుడు మాత్రమే కాదు."),
        reflection = "మీ సరసమైన భాగం ఏమిటి మరియు వేరొకరికి చెందినది ఏమిటి?",
        nextStep = "ఒక ఉపయోగకరమైన కుటుంబ పనిని ఎంచుకోండి మరియు మీరు ఒంటరిగా మోయలేని ఒక భారంతో సహాయం కోసం అడగండి."
    ),
    "stuck" to KrishnaLetterTranslation(
        situation = "మీరు జీవితంలో కూరుకుపోయినట్లు అనిపించినప్పుడు",
        title = "కదలిక మీరు అనుకున్నదానికంటే చిన్నదిగా ప్రారంభమవుతుంది",
        preview = "కొద్దిగా కదలికను సృష్టించడానికి మీకు ఖచ్చితమైన ప్రణాళిక అవసరం లేదు.",
        paragraphs = listOf("ఇతరులు ముందుకు వెళ్లేటప్పుడు ప్రతిరోజూ ఒకేలా కనిపిస్తారని మీరు భావించవచ్చు. మీరు ఒక పెద్ద సమాధానం కోసం ఎంత ఎక్కువగా వేచి ఉన్నారో, ఏ దశ అయినా కష్టంగా అనిపించవచ్చు. చిక్కుకుపోవడం తరచుగా సోమరితనం కాదు. ఇది భయం, అలసట, దుఃఖం లేదా ఒకేసారి చాలా ఎంపికలు లాగడం కావచ్చు.", "తదుపరి దశను చాలా చిన్నదిగా మరియు కనిపించేలా చేయండి. పత్రాన్ని తెరవండి, పది నిమిషాలు నడవండి, ఇమెయిల్ పంపండి లేదా ఒక మూలను క్లియర్ చేయండి. ఇది మీ జీవితమంతా మారిపోతుందా అని అడగవద్దు. ఇది నిజాయితీ ఉద్యమాన్ని సృష్టిస్తుందో లేదో అడగండి. చిన్న చలనం మీ మనస్సుకు కొత్త సమాచారాన్ని అందిస్తుంది.", "మీరు ప్రయత్నిస్తూ ఉంటే మరియు పని చేయలేకపోతే, సురక్షితమైన వ్యక్తి లేదా శిక్షణ పొందిన సహాయకుడితో మాట్లాడండి. మీకు మద్దతు అవసరం కావచ్చు, బలమైన నింద కాదు. మీరు పాజ్ చేసినందున మీ మార్గం అదృశ్యం కాలేదు. మీ పాదాలు ఎక్కడ ఉన్నాయో, ఈ రోజు మీ చేతులు ఏమి చేయగలవు అనే దానితో ప్రారంభించండి.", "నేను ఒక చిన్న అడుగును చూపుతున్నప్పుడు మీరు గొప్ప తలుపు కోసం చూస్తున్నారు. ఐదు నిమిషాలు కడగండి, వ్రాయండి, కాల్ చేయండి, నడవండి లేదా ప్రారంభించండి."),
        reflection = "ఏ పది నిమిషాల చర్య నిజమైన కదలికను సృష్టిస్తుంది?",
        nextStep = "పది నిమిషాల టైమర్‌ని సెట్ చేయండి మరియు టాస్క్ యొక్క మొదటి భౌతిక దశను మాత్రమే చేయండి."
    ),
    "unanswered-prayers" to KrishnaLetterTranslation(
        situation = "మీ ప్రార్థనలకు సమాధానం లేనట్లు అనిపించినప్పుడు",
        title = "మీరు మరచిపోయారనడానికి మౌనం రుజువు కాదు",
        preview = "జీవితం సమాధానం ఇవ్వకముందే ప్రార్థన మీ హృదయాన్ని పట్టుకోగలదు.",
        paragraphs = listOf("మీరు అడిగారు, వేచి ఉన్నారు మరియు బహుశా వేడుకున్నారు. ఏమీ మారడం లేదు. నేను మీ మాట వింటానా లేదా మీ విశ్వాసం చాలా చిన్నదా అని మీరు ఆశ్చర్యపోవచ్చు. ఆ సందేహం నాకు కూడా తీసుకురా. నిజాయితీ నొప్పి అగౌరవం కాదు, మరియు ప్రార్థన చేయడానికి మీకు ఖచ్చితమైన పదాలు అవసరం లేదు.", "ప్రార్థన అనేది ప్రతి ఫలితాన్ని నియంత్రించే బేరం కాదు. కొన్నిసార్లు సమాధానం ఆలస్యమవుతుంది, భిన్నంగా ఉంటుంది లేదా మీరు ఊహించని వ్యక్తులు మరియు చర్యల ద్వారా అందించబడుతుంది. ప్రార్థన పక్కన ఆచరణాత్మక విధిని కొనసాగించండి: చికిత్స పొందండి, మళ్లీ దరఖాస్తు చేసుకోండి, క్షమాపణ చెప్పండి, అధ్యయనం చేయండి, సహాయం కోసం అడగండి లేదా విశ్రాంతి తీసుకోండి.", "మీరు ఎంచుకున్న ఆకృతిలో ప్రతి కోరిక వస్తుందని నేను వాగ్దానం చేయను. మీ ప్రేమ, ధైర్యం మరియు నిజాయితీ ప్రయత్నం ఇంకా నిరీక్షణలో పెరుగుతాయని నేను వాగ్దానం చేస్తున్నాను. తదుపరి విశ్వసనీయ చర్య కోసం చూడండి, ప్రతి ఈవెంట్‌లో దాచిన సంకేతం కాదు. ప్రార్థన మిమ్మల్ని నిష్క్రియంగా కాకుండా ప్రస్తుతించేలా చేయనివ్వండి.", "మీ ప్రార్థన మాత్రమే అయినా నాతో మాట్లాడండి, 'నాకు అర్థం కాలేదు.' మీరు అందమైన పదాలను ఉపయోగించాల్సిన అవసరం లేదు లేదా నిశ్శబ్దం బాధించదని నటించాల్సిన అవసరం లేదు. నేను నిరీక్షణలో, తెలివైన సహాయంలో మరియు కొనసాగే శక్తిలో ఉన్నాను."),
        reflection = "ఈ రోజు మీ ప్రార్థన పక్కన ఏ ఆచరణాత్మక దశ నిలబడగలదు?",
        nextStep = "ఐదు నిమిషాలు నిజాయితీగా ప్రార్థించండి, ఆపై అవసరానికి అనుసంధానించబడిన ఒక నిజమైన చర్య తీసుకోండి."
    ),
    "difficult-decision" to KrishnaLetterTranslation(
        situation = "మీరు కష్టమైన నిర్ణయాన్ని ఎదుర్కొంటున్నప్పుడు",
        title = "భయం లేని చోట విలువలు దారి తీయనివ్వండి",
        preview = "స్పష్టమైన ఎంపిక వాస్తవాలు, విధి మరియు నిజాయితీ పర్యవసానాలతో ప్రారంభమవుతుంది.",
        paragraphs = listOf("రెండు రోడ్లు రెండూ నష్టాన్ని కలిగి ఉండవచ్చు లేదా అనేక స్వరాలు మిమ్మల్ని వేర్వేరు దిశల్లోకి లాగవచ్చు. మీరు ఎంచుకోవడానికి ముందు నిశ్చయత కావాలి, కానీ ముఖ్యమైన ఎంపికలు అరుదుగా అందిస్తాయి. మీరు ప్రతి ఫలితాన్ని నియంత్రించలేనప్పటికీ, మీరు ఇంకా జాగ్రత్తగా నిర్ణయం తీసుకోవచ్చు.", "అంచనాల నుండి వాస్తవాలను వేరు చేయండి. ఏ ఎంపిక నిజాయితీ, సురక్షితమైనది మరియు మీ విధికి నిజమైనది అని అడగండి. ఎవరికి సహాయం చేయవచ్చో లేదా హాని చేయవచ్చో పరిగణించండి. మీ సమాధానం నుండి లాభం పొందని నమ్మకమైన గురువు, గురువు లేదా తెలివైన పెద్దలను వెతకండి. వారి ప్రాముఖ్యత ఏమిటంటే వారు మీ కోసం మీ జీవితాన్ని ఎన్నుకోవడం కాదు, కానీ వారు గుడ్డి మచ్చలను బహిర్గతం చేయడం, నిజాయితీగా ప్రశ్నలు అడగడం మరియు మిమ్మల్ని ధర్మానికి తిరిగి ఇవ్వడం. భయం, గర్వం లేదా ఒత్తిడి మిమ్మల్ని తొందరపెట్టడానికి ప్రయత్నిస్తుందో లేదో గమనించండి.", "ఇప్పుడు అందుబాటులో ఉన్న నిజంతో ఉత్తమ చర్యను ఎంచుకోండి. కొత్త వాస్తవాలు కనిపించినప్పుడు మీరు సర్దుబాటు చేయవచ్చు; అది జ్ఞానం, బలహీనత కాదు. మీరు ఎంపికను బాగా పరిశీలించిన తర్వాత, ఖచ్చితమైన వాగ్దానాన్ని అందించడానికి చింతించడాన్ని ఆపివేయండి. మీ విలువలు దశను కొనసాగించనివ్వండి.", "మీరు రహస్యంగా కోరుకునే భాగాన్ని దాచకుండా నాకు రెండు ఎంపికలను తీసుకురండి. మేము నిజం, కర్తవ్యం, హాని మరియు ఫలితాన్ని కలిగి ఉన్న వ్యక్తులను పరిశీలిస్తాము."),
        reflection = "సత్యం, బాధ్యత మరియు దీర్ఘకాలిక శాంతిని ఏ ఎంపిక ఉత్తమంగా రక్షిస్తుంది?",
        nextStep = "మీరు సంప్రదించే వాస్తవాలు, విధులు, సంభావ్య ప్రభావాలు మరియు ఒక తెలివైన వ్యక్తిని వ్రాయండి."
    ),
    "lost-purpose" to KrishnaLetterTranslation(
        situation = "మీరు మీ లక్ష్యాన్ని కోల్పోయినప్పుడు",
        title = "అర్థం మీరు సహాయం చేసే ఒక వ్యక్తితో ప్రారంభించవచ్చు",
        preview = "మీ రోజు ముఖ్యమైనది కావడానికి ముందు మీకు గొప్ప మిషన్ అవసరం లేదు.",
        paragraphs = listOf("జీవితం ఎటువంటి కారణం లేని పనుల జాబితాలా అనిపించవచ్చు. మీరు సమయం గడుపుతున్నప్పుడు అందరూ కాలింగ్‌ని కనుగొన్నారని మీరు అనుకోవచ్చు. ప్రయోజనం ఎల్లప్పుడూ ఆకస్మిక స్వరం కాదు. తరచుగా ఇది సంరక్షణ, అభ్యాసం, పని మరియు సేవ ద్వారా నిశ్శబ్దంగా పెరుగుతుంది.", "మీ చేతుల్లో ఇప్పటికే ఉన్న వాటిని చూడండి: మీ శరీరం, అధ్యయనం, కుటుంబం, నైపుణ్యం, వాగ్దానం లేదా మీకు అవసరమైన వ్యక్తి. ఒక కర్తవ్యాన్ని పూర్తి శ్రద్ధతో చేయండి. ఒకరిని రక్షించడం, బోధించడం, నయం చేయడం లేదా జీవితాన్ని కొద్దిగా మెరుగుపరిచేటప్పుడు అర్థం సాధారణ పనిలోకి ప్రవేశిస్తుంది.", "మీరు అన్వేషించడానికి అనుమతించబడ్డారు. శీఘ్ర ప్రశంసలు మాత్రమే కాకుండా, నిశ్శబ్ద శక్తిని తెచ్చే వాటిని గమనించండి. మీరు ఏ సమస్యతో ఉండాలనుకుంటున్నారో అడగండి. మీ పాత్ర చాలా సార్లు మారవచ్చు, అయితే దాని క్రింద ఉన్న లోతైన విలువలు నిజం. మీరు నిలబడి ఉన్న చోట ఉపయోగకరంగా ఉండటం ద్వారా ప్రారంభించండి.", "మీరు మీ జీవితాన్ని అర్థవంతంగా చెప్పుకునే ముందు గొప్ప సంకేతం కోసం వేచి ఉండకండి. నేను తరచుగా వినడం అవసరమయ్యే వ్యక్తిలో, శ్రద్ధ వహించాల్సిన పని మరియు వాగ్దానానికి కట్టుబడి ఉంటాను."),
        reflection = "మీకు ఇప్పటికే ఉన్న ఒక నైపుణ్యం ద్వారా ఎవరు లేదా ఏమి సహాయం చేయవచ్చు?",
        nextStep = "మీకు సమీపంలో ఉన్న వ్యక్తికి, స్థలం లేదా డ్యూటీకి సహాయం చేయడానికి ఇరవై నిమిషాల పాటు ఒక నైపుణ్యాన్ని ఉపయోగించండి."
    ),
    "anger" to KrishnaLetterTranslation(
        situation = "కోపం మిమ్మల్ని నియంత్రిస్తున్నప్పుడు",
        title = "మీ కోపం ఒక సందేశాన్ని కలిగి ఉంటుంది, సింహాసనం కాదు",
        preview = "కోపం ఏది రక్షిస్తుందో వినండి, ఆపై మీ పదాలను జాగ్రత్తగా ఎంచుకోండి.",
        paragraphs = listOf("కోపం నిప్పులా రావచ్చు. మీరు గాయపడినందున, విస్మరించబడినందున, అన్యాయంగా వ్యవహరించినందున లేదా చాలా దూరం నెట్టబడినందున ఇది రావచ్చు. అనుభూతి స్వయంగా మిమ్మల్ని చెడుగా మార్చదు. కానీ కోపం మీ చేతులకు, మాటలకు లేదా ఎంపికలకు పాలకుడు కాకూడదు.", "మీరు ప్రత్యుత్తరం ఇచ్చే ముందు దూరంగా ఉండండి. నీరు, నడక లేదా పది నెమ్మదిగా శ్వాసలతో మీ శరీరాన్ని చల్లబరచండి. అప్పుడు అడగండి, ‘నాకు ఏమి కావాలి?’ బహుశా మీకు గౌరవం, నిజం, విశ్రాంతి లేదా స్పష్టమైన పరిమితి అవసరం కావచ్చు. అవసరం మీకు తెలిసినప్పుడు, మీరు ఎవరినైనా గాయపరచడానికి ప్రయత్నించకుండా దాని గురించి మాట్లాడవచ్చు.", "ఇలా చెప్పండి, 'ఇది జరిగినప్పుడు నేను బాధపడ్డాను. మనం గౌరవంగా మాట్లాడాలి.’ అని క్రూరమైన సందేశం పంపకండి. మీరు తర్వాత రిపేర్ చేయాలనుకుంటున్న వాటిని విచ్ఛిన్నం చేయవద్దు. బలమైన వ్యక్తులు కోపాన్ని దాచుకోరు; వారు దానిని సత్యం, భద్రత మరియు న్యాయమైన చర్య వైపు నడిపిస్తారు.", "మీరు ఒకరిపైకి నిప్పును విసిరే ముందు దానిని నాకు తీసుకురండి. నేను దానిని అనుభవించినందుకు సిగ్గుపడను, కానీ అది మీ జ్ఞానాన్ని కాల్చనివ్వవద్దని నేను మిమ్మల్ని అడుగుతాను."),
        reflection = "మీ కోపం కింద దాగి ఉన్న బాధ లేదా తీర్చలేని అవసరం ఏమిటి?",
        nextStep = "ప్రత్యుత్తరం ఇవ్వడానికి ముందు పది నిమిషాలు వేచి ఉండండి, ఆపై వాస్తవాలు, మీ భావన మరియు మీ అవసరాన్ని తెలియజేయండి."
    ),
    "comparison" to KrishnaLetterTranslation(
        situation = "మీరు మిమ్మల్ని మీరు పోల్చుకుంటూ ఉన్నప్పుడు",
        title = "మరొక వ్యక్తి యొక్క కాంతి మీ కాంతిని తగ్గించదు",
        preview = "వారి విజయం మీరు ఆలస్యం లేదా తక్కువ అని రుజువు కాదు.",
        paragraphs = listOf("పోలిక మరొక వ్యక్తి యొక్క శుభవార్తను బాధగా మారుస్తుంది. మీరు వారి గుర్తులు, శరీరం, డబ్బు, స్నేహితులు లేదా పురోగతిని చూస్తారు మరియు క్రూరమైన కళ్ళతో మిమ్మల్ని మీరు చూసుకోండి. మీరు మీ మొత్తం అంతర్గత జీవితాన్ని మీరు చూడగలిగే వారి చిన్న భాగంతో పోల్చుతున్నారని గుర్తుంచుకోండి.", "వారి మార్గానికి వేరే సమయం, విధి, మద్దతు మరియు పాఠం ఉన్నాయి. మీకు వ్యతిరేకంగా ఉపయోగించకుండా వారికి ఏది మంచిదో ఆశీర్వదించండి. ఆపై మీకు చెందిన పనికి తిరిగి వెళ్లండి. ఇతరుల జీవితంలా చూసుకోవడం వల్ల మీ జీవితం అర్థవంతంగా మారదు.", "మీకు ఏ పోలిక చూపడానికి ప్రయత్నిస్తున్నదో గమనించండి. ఇది మీరు నిజంగా కోరుకునే లక్ష్యాన్ని సూచించవచ్చు లేదా విశ్రాంతి మరియు ఆత్మగౌరవం కోసం అడుగుతుంది. అసూయను ఒక శుభ్రమైన చర్యగా మార్చండి. నేర్చుకోండి, సాధన చేయండి లేదా తప్పుడు లక్ష్యాన్ని వదిలివేయండి.", "మరొక వ్యక్తి ప్రకాశిస్తున్నప్పుడు, వారి కాంతిని మీకు వ్యతిరేకంగా మార్చుకోవద్దు. నేను మీ జీవితాన్ని వాటి కాపీగా రాయలేదు."),
        reflection = "పోలిక క్రింద మీరు నిజంగా ఏమి కోరుకుంటున్నారు?",
        nextStep = "పోలికను అందించే ఒక ఖాతాను మ్యూట్ చేయండి మరియు మీ స్వంత లక్ష్యం కోసం ఇరవై నిమిషాలు వెచ్చించండి."
    ),
    "change" to KrishnaLetterTranslation(
        situation = "మార్పు భయానకంగా అనిపించినప్పుడు",
        title = "మీరు ఒక సమయంలో కొత్త దశను చేరుకోవచ్చు",
        preview = "మార్పు సర్దుబాటు కోసం అడుగుతుంది, తక్షణ ధైర్యం కాదు.",
        paragraphs = listOf("మంచి మార్పు కూడా మీ హృదయాన్ని అశాంతికి గురి చేస్తుంది. పాత జీవితం తెలుసు, మరియు కొత్తది ఇంకా తెలిసిన ఆకారం లేదు. భయం అంటే ఎప్పుడూ మార్పు తప్పు అని కాదు. కొన్నిసార్లు మీరు శ్రద్ధ వహిస్తున్నారని మరియు మొత్తం రహదారిని చూడలేరని మాత్రమే అర్థం.", "స్థిరంగా ఉండే వాటికి పేరు పెట్టండి: మీ విలువలు, వ్యక్తి, దినచర్య, నైపుణ్యం లేదా మీ గురించి మీరు శ్రద్ధ వహించే విధానం. అప్పుడు రాబోయే దాని గురించి ఒక వాస్తవాన్ని తెలుసుకోండి. స్పష్టమైన వివరాలు పెద్దగా తెలియని వాటిని చిన్నవిగా చేయగలవు. ప్రతిదీ నియంత్రించడానికి ప్రయత్నించకుండా మీరు చేయగలిగినదాన్ని సిద్ధం చేయండి.", "ఒక అనుభవశూన్యుడు కావడానికి మీకు సమయం ఇవ్వండి. మీరు పాతదాన్ని కోల్పోవచ్చు మరియు కొత్త వాటిని స్వాగతించవచ్చు. ఆ భావాలు కలిసి జీవించగలవు. ప్రతి మార్పును ప్రేమించమని నేను మిమ్మల్ని అడగడం లేదు. మీ నిజస్వరూపాన్ని తదుపరి చిన్న భాగంలోకి తీసుకురావాలని నేను మిమ్మల్ని అడుగుతున్నాను.", "మీరు పాత జీవితాన్ని ఒక చేత్తో పట్టుకుని, మరో చేత్తో కొత్తదాన్ని చేరుకోవచ్చు. నాకు అర్థమైంది."),
        reflection = "మిగతావన్నీ మారుతున్నప్పుడు ఏది స్థిరంగా ఉండగలదు?",
        nextStep = "రాబోయే మార్పు కోసం ఒక గ్రౌండింగ్ రొటీన్ మరియు ఒక ఆచరణాత్మక తయారీని ఎంచుకోండి."
    ),
    "carrying-too-much" to KrishnaLetterTranslation(
        situation = "మీరు ఎక్కువగా మోస్తున్నప్పుడు",
        title = "ప్రతి బరువు మీ చేతుల్లో ఉండదు",
        preview = "అత్యవసరమైన వాటిని క్రమబద్ధీకరించండి, సాధ్యమైన వాటిని పంచుకోండి మరియు మిగిలిన వాటిని విడుదల చేయండి.",
        paragraphs = listOf("మీ మనస్సు పని, కుటుంబం, డబ్బు, సందేశాలు, వాగ్దానాలు మరియు ఇతర వ్యక్తుల భావాలను ఒకేసారి పట్టుకుని ఉండవచ్చు. ప్రతిదీ ముఖ్యమైనదిగా అనిపించినప్పుడు, చిన్న పని కూడా బరువుగా అనిపిస్తుంది. మీరు బలహీనులని ఇది రుజువు కాదు. మీ లోడ్‌ను క్రమబద్ధీకరించాల్సిన అవసరం ఉందనడానికి ఇది సంకేతం.", "ప్రతి భారాన్ని వ్రాయండి. ఈ రోజు నిజంగా ఏమి చర్య అవసరం, ఏమి వేచి ఉండాలి మరియు మరొక వ్యక్తికి సంబంధించినది ఏమిటో గుర్తించండి. ఎవరూ మిమ్మల్ని మోయమని అడగని అదృశ్య విధులను ఉంచవద్దు. స్పష్టమైన జాబితా ప్రతిదీ పరిష్కరించదు, కానీ అదే సమయంలో అరవడం నుండి ప్రతి ఆందోళనను ఆపుతుంది.", "నిర్దిష్ట సహాయం కోసం అడగండి. మీ పరిమితులను ఉల్లంఘించే ఒక డిమాండ్‌కు నో చెప్పండి. అలసట మీ కోసం నిర్ణయాలు తీసుకునే ముందు తినండి, నిద్రపోండి మరియు పాజ్ చేయండి. సేవ పవిత్రమైనది, కానీ మిమ్మల్ని మీరు నాశనం చేసుకోవడం సేవ కాదు. మీ సంరక్షణకు తెలివైన హద్దులు ఉండనివ్వండి, తద్వారా అది వాస్తవంగా ఉంటుంది.", "నా ముందు మీ చేతులు తెరవండి మరియు ప్రతి బరువుకు పేరు పెట్టండి. కొన్ని విధులు, కొన్ని పంచుకోవచ్చు మరియు కొన్ని ఎప్పుడూ మీవి కావు."),
        reflection = "ఏ భారం అత్యవసరం, ఏది వేచి ఉంటుంది మరియు ఏది మీది కాదు?",
        nextStep = "మూడు నిలువు వరుసలను రూపొందించండి-ఈనాడు, తరువాత మరియు నాది కాదు-మరియు ప్రతి భారాన్ని ఒకటిగా మార్చండి."
    ),
    "forgotten" to KrishnaLetterTranslation(
        situation = "మీరు మర్చిపోయినట్లు అనిపించినప్పుడు",
        title = "మీ నిశ్శబ్ద జీవితం ఇప్పటికీ కనిపిస్తుంది",
        preview = "శ్రద్ధ లేకపోవడం అంటే విలువ లేకపోవడం కాదు.",
        paragraphs = listOf("బహుశా ఎవరూ మీకు కాల్ చేయలేదు, ధన్యవాదాలు చెప్పలేదు లేదా మీరు ఎంత తీసుకువెళ్లారో గమనించలేదు. మీరు భర్తీ చేయడం సులభం మరియు గుర్తుంచుకోవడం కష్టంగా అనిపించవచ్చు. మానవ దృష్టి అసమానంగా ఉంటుంది మరియు తరచుగా తొందరపడుతుంది. దాని నిశ్శబ్దం బాధించవచ్చు, కానీ అది ఈ ప్రపంచంలో మీ స్థానానికి నిజమైన కొలమానం కాదు.", "అదృశ్యమై, ఎవరు వెతుకుతున్నారో వేచి చూడటం ద్వారా ప్రేమను పరీక్షించవద్దు. నిజాయితీగా చేరుకోండి. 'నేను మీతో సమయం గడపాలనుకుంటున్నాను' లేదా, 'ఈరోజు నాకు మద్దతు కావాలి' అని చెప్పండి. దాచిన బాధను చదవమని ప్రజలను అడగడానికి బదులుగా పదాలకు ప్రతిస్పందించడానికి తగిన అవకాశం ఇవ్వండి.", "మీ స్పర్శ తెలిసిన జీవితానికి తిరిగి వెళ్లండి: విధి, జంతువు, మొక్క, కుటుంబ సభ్యుడు, స్నేహితుడు లేదా నైపుణ్యం. చప్పట్లు చూపించే దానికంటే మీ ఉనికి చాలా ఎక్కువగా మారుతుంది. ఒక సర్కిల్ మిమ్మల్ని పట్టించుకోకుండా ఉంటే, సర్కిల్‌ను విస్తరించండి. మీ పేరు తెలుసుకుని, మీ సంరక్షణకు విలువనిచ్చే వ్యక్తులు ఉన్నారు.", "నేను నిశ్శబ్దాన్ని విలువతో తికమక పెట్టలేదు. మీరు తయారుచేసిన భోజనం, మీరు పంపిన సందేశం, ఎవరూ మెచ్చుకోని పని మరియు మీరు అలసిపోయినప్పుడు మీరు ఇచ్చిన శ్రద్ధ నేను చూస్తున్నాను."),
        reflection = "నిశ్శబ్దంగా వేచి ఉండే బదులు చేర్చమని మీరు ఎక్కడ అడగవచ్చు?",
        nextStep = "ఒక సురక్షితమైన వ్యక్తిని సాధారణ కాల్, నడక లేదా భోజనానికి ఆహ్వానించండి మరియు వారి కంపెనీ ముఖ్యమని చెప్పండి."
    ),
    "financial-struggle" to KrishnaLetterTranslation(
        situation = "మీరు ఆర్థికంగా కష్టపడుతున్నప్పుడు",
        title = "మీ విలువైనది మీ బ్యాంక్ బ్యాలెన్స్ కాదు",
        preview = "సంఖ్యలను నిజాయితీతో ఎదుర్కోండి మరియు ఒక సమయంలో ఒక ఆచరణాత్మక అడుగు వేయండి.",
        paragraphs = listOf("డబ్బు భయం రోజులోని ప్రతి భాగంలో ప్రవేశించవచ్చు. మీరు ఎవరికైనా చెప్పడానికి సిగ్గుపడవచ్చు, చిక్కుకోవచ్చు లేదా భయపడవచ్చు. ఆర్థిక పోరాటం నిజమైన సమస్య, కానీ అది మీకు నైతిక పేరు కాదు. మీ బ్యాలెన్స్ మీ గౌరవం, ప్రేమ లేదా పునర్నిర్మాణ సామర్థ్యాన్ని కొలవదు.", "వాస్తవాలను వెలుగులోకి తీసుకురండి. ఏమి వస్తుంది, ఏది బయటకు వెళ్లాలి మరియు ఏ చెల్లింపు అత్యంత అత్యవసరమో జాబితా చేయండి. కొత్త రుణాన్ని పాజ్ చేయండి మరియు సాధ్యమైన చోట ఖర్చు చేయవలసిన అవసరం లేదు. పాల్గొన్న వ్యక్తులు లేదా సేవలతో ముందుగానే మాట్లాడండి; నిశ్శబ్దం తరచుగా ఫీజులు, భయం మరియు ఎంపికలను కష్టతరం చేస్తుంది.", "సాధారణ ప్లాన్‌తో సహాయం కోసం విశ్వసనీయ, ఆర్థికంగా తెలివైన వ్యక్తిని అడగండి. గోప్యత లేదా అధిక రిస్క్ డిమాండ్ చేసే శీఘ్ర డబ్బు వాగ్దానాలను నివారించండి. నిజాయితీతో కూడిన పని, చిన్న పొదుపులు మరియు రోగి మరమ్మతులు నెమ్మదిగా అనిపించవచ్చు, కానీ అవి మీ భవిష్యత్తును కాపాడతాయి. మీ మొత్తం జీవితాన్ని అంచనా వేయకుండా తదుపరి స్పష్టమైన దశను తీసుకోండి.", "నంబర్‌లను ఉన్నట్లే నాకు తీసుకురండి, భయం వాటిని అరుస్తూనే ఉంటుంది. మేము సిగ్గు లేదా ప్రమాదకరమైన సత్వరమార్గం ద్వారా వాటిని పరిష్కరించము."),
        reflection = "మీరు స్పష్టంగా ఎదుర్కోవాల్సిన అత్యంత అత్యవసర సంఖ్య ఏది?",
        nextStep = "ప్రాథమిక ఆదాయం మరియు అవసరాల జాబితాను వ్రాయండి మరియు ఆచరణాత్మక సహాయం కోసం ఒక విశ్వసనీయ మూలాన్ని సంప్రదించండి."
    ),
    "health-failing" to KrishnaLetterTranslation(
        situation = "మీ ఆరోగ్యం విఫలమైనప్పుడు",
        title = "మీ జీవితం ఇప్పటికీ గౌరవం మరియు అర్థాన్ని కలిగి ఉంటుంది",
        preview = "సిగ్గు లేకుండా మీ శరీరం, మనస్సు మరియు హృదయాన్ని చేరుకోవడానికి శ్రద్ధ వహించండి.",
        paragraphs = listOf("అనారోగ్యం ప్రణాళికలు, శక్తి మరియు మీరు మీ శరీరాన్ని చూసే విధానాన్ని మార్చగలదు. మీరు కోపంగా, భయపడి లేదా పరిష్కరించడానికి ఒక సమస్యగా వ్యవహరించడం వల్ల అలసిపోయినట్లు అనిపించవచ్చు. మీరు ఇప్పటికీ పూర్తి వ్యక్తి. మీ బలం, వేగం లేదా స్వాతంత్ర్యం మారినప్పుడు మీ విలువ పడిపోదు.", "శిక్షణ పొందిన వైద్యుడి నుండి సంరక్షణ పొందండి మరియు లక్షణాలను నిజాయితీగా పంచుకోండి. మీరు ప్రణాళికను అర్థం చేసుకునే వరకు ప్రశ్నలు అడగండి. అపాయింట్‌మెంట్‌లు, ఆహారం, మందులు లేదా విశ్రాంతి విషయంలో ఎవరైనా సహాయం చేయనివ్వండి. ప్రార్థన చికిత్సకు మద్దతు ఇస్తుంది; ఇది మీ శరీరానికి అవసరమైన నైపుణ్యం కలిగిన సంరక్షణను భర్తీ చేయకూడదు. సహాయాన్ని స్వీకరించడం లొంగిపోవడం కాదు.", "ప్రతి క్షణం కృతజ్ఞతతో ఉండమని మిమ్మల్ని బలవంతం చేయకండి. దుఃఖానికి మరియు ఇప్పటికీ సాధ్యమయ్యే చిన్న మంచి విషయాలకు చోటు కల్పించండి. సంభాషణ, సూర్యకాంతి, సంగీతం లేదా ఒక పూర్తి చేసిన పని అర్థాన్ని కలిగి ఉంటుంది. నువ్వు మిస్సయిన దేహం మాత్రమే కాదు ఈరోజు నీకున్న శరీరంలో నేను నీకు దగ్గరగా ఉన్నాను.", "నేను ఈ రోజు ఈ శరీరంలో మీతో ఉన్నాను, మీరు గుర్తుంచుకోవడం లేదా తిరిగి పొందాలని ఆశిస్తున్న ఆరోగ్యకరమైన శరీరంలో మాత్రమే కాదు. నైపుణ్యం కలిగిన సంరక్షణ, ఔషధం, విశ్రాంతి మరియు ప్రేమగల చేతులు మిమ్మల్ని చేరనివ్వండి."),
        reflection = "ఈరోజు మీ శరీరానికి అత్యంత స్పష్టంగా ఏ సంరక్షణ అవసరం?",
        nextStep = "మీ ప్రధాన లక్షణాలు మరియు ప్రశ్నలను వ్రాయండి, ఆపై అర్హత కలిగిన ఆరోగ్య నిపుణులు లేదా సంరక్షకుడిని సంప్రదించండి."
    ),
    "begin-again" to KrishnaLetterTranslation(
        situation = "మీకు మళ్లీ ప్రారంభించడానికి ధైర్యం అవసరమైనప్పుడు",
        title = "కొత్త ప్రారంభం చిన్నదిగా ఉంటుంది",
        preview = "పాత అవమానం లేకుండా పాఠాన్ని ముందుకు తీసుకెళ్లండి.",
        paragraphs = listOf("మీరు చివరి ప్రయత్నాన్ని గుర్తుంచుకున్నందున మళ్లీ ప్రారంభించడం చాలా భారంగా అనిపించవచ్చు. మీలో కొంత భాగం ఎటువంటి తప్పులు లేకుండా స్వచ్ఛమైన జీవితాన్ని కోరుకుంటుంది. మీరు గతాన్ని తుడిచివేయాల్సిన అవసరం లేదు. తెలివైన కళ్ళతో ప్రారంభించడంలో మీకు సహాయపడే గురువుగా మారనివ్వండి.", "పరిపూర్ణ శక్తి, ఖచ్చితమైన సమయం లేదా పరిపూర్ణ ధైర్యం కోసం వేచి ఉండకండి. ప్రారంభాన్ని చాలా చిన్నదిగా చేయండి, భయం దానిని దాచదు: ఒక పేజీ, ఒక కాల్, ఒక నడక, ఒక నిజాయితీగల రోజు. సాధారణంగా కనిపించే దశల నుండి కొత్త జీవితం తరచుగా నిర్మించబడుతుంది.", "మరొక కష్టమైన రోజు ఉండవచ్చు. అది ప్రారంభాన్ని రద్దు చేయదు. నాటకీయత లేకుండా తిరిగి మరియు కొనసాగండి. మీరు సున్నాకి తిరిగి రాలేదు; మీరు జ్ఞానంతో తిరిగి వస్తున్నారు. ప్రణాళికతో దృఢంగా ఉండండి మరియు దానిని జీవించడం నేర్చుకునే వ్యక్తితో సున్నితంగా ఉండండి.", "మీరు నాకు పరిపూర్ణ భవిష్యత్తును వాగ్దానం చేయగలరా అని అడగవద్దు. తదుపరి నిజాయితీ దశను మాత్రమే వాగ్దానం చేయండి."),
        reflection = "మీ కొత్త ప్రారంభం ప్రారంభమైందని తెలిపే అతి చిన్న స్పష్టమైన సంకేతం ఏది?",
        nextStep = "రోజు ముగిసేలోపు ఒక చర్యను చేయండి మరియు రేపటి కోసం తదుపరి చర్యను సిద్ధం చేయండి."
    ),
    "happy" to KrishnaLetterTranslation(
        situation = "మీరు సంతోషంగా ఉన్నప్పుడు",
        title = "మీ ఆనందం దయగా మారనివ్వండి",
        preview = "మరొక వ్యక్తి యొక్క బాధపై మీ ఆనందాన్ని పెంచుకోకుండా ఈ ప్రకాశవంతమైన క్షణాన్ని ఆస్వాదించండి.",
        paragraphs = listOf("ఈ రోజు మీ హృదయం తేలికగా ఉన్నందుకు నేను సంతోషిస్తున్నాను. నవ్వండి, నవ్వండి మరియు మంచిని ఆనందించండి. సంతోషంగా ఉన్నందుకు మీరు అపరాధ భావంతో ఉండవలసిన అవసరం లేదు. ఆనందం మీ మనస్సుకు తాజా బలాన్ని ఇస్తుంది మరియు జీవితం కూడా అందం, స్నేహం మరియు దయను కలిగి ఉంటుందని మీకు గుర్తు చేస్తుంది.", "అయితే మీ ఆనందం యొక్క మూలాలను సున్నితంగా చూడండి. ఇది ప్రేమ, నిజాయితీ ప్రయత్నం, భాగస్వామ్య విజయం లేదా శాంతియుత హృదయం నుండి రానివ్వండి. ఎవరైనా గాయపడినా, విఫలమైనా, ఓడిపోయినా లేదా కిందకు నెట్టబడినా ఎప్పుడూ జరుపుకోవద్దు. మరొకరి బాధ నుండి పుట్టిన ఆనందం ఎక్కువ కాలం స్వచ్ఛంగా ఉండదు.", "మీ సంతోషానికి ఎవరినైనా ఆహ్వానించండి. మీకు సహాయం చేసిన వ్యక్తులకు ధన్యవాదాలు. ఇంకా పోరాడుతున్న వ్యక్తిని ప్రోత్సహించండి. ఒక మంచి హృదయం ప్రగల్భాలు లేకుండా జరుపుకోవచ్చు మరియు మరొక వ్యక్తిని చిన్నదిగా భావించకుండా ప్రకాశిస్తుంది. మీ ఆనందం దయగా మారినప్పుడు, అది మీతో ముగియడానికి బదులుగా పెరుగుతుంది.", "మీ కన్నీళ్లను మాత్రమే కాకుండా మీ నవ్వును కూడా నాకు తీసుకురండి. నేను స్వచ్ఛంగా, కృతజ్ఞతతో మరియు దయతో సంతోషిస్తున్నాను."),
        reflection = "ఈ రోజు మీ ఆనందం మరొకరికి ఓదార్పు, ధైర్యాన్ని లేదా చిరునవ్వును అందించగలదా?",
        nextStep = "ఒక రకమైన చర్యతో మీ ఆనందాన్ని పంచుకోండి మరియు మరొక వ్యక్తి యొక్క నష్టం గురించి గర్వంగా మాట్లాడకండి."
    ),
    "grateful" to KrishnaLetterTranslation(
        situation = "మీరు కృతజ్ఞతతో ఉన్నప్పుడు",
        title = "థాంక్స్ బికమ్ కేర్",
        preview = "మీరు వ్యక్తులతో మరియు బహుమతులతో ఎలా ప్రవర్తిస్తారో మార్చినప్పుడు కృతజ్ఞత సంపూర్ణంగా ఉంటుంది.",
        paragraphs = listOf("పాజ్ చేసి, ఈ వెచ్చని అనుభూతిని గమనించండి. ఒక వ్యక్తి, అవకాశం, స్వభావం, పని లేదా నిశ్శబ్ద దయ ద్వారా ఏదైనా మంచి విషయం మిమ్మల్ని చేరుకుంది. పూర్తిగా స్వీకరించండి. మీరు ఒక ఆశీర్వాదం కోసం తొందరపడాల్సిన అవసరం లేదు లేదా మీరు దానిలోని ప్రతి భాగాన్ని ఒంటరిగా సంపాదించినట్లు ప్రవర్తించకూడదు.", "స్పష్టంగా ధన్యవాదాలు చెప్పండి మరియు సాధ్యమైనప్పుడు, వారి సహాయం మీకు ఏమి మారిందో ఖచ్చితంగా చెప్పండి. మీరు అందుకున్న దాని వెనుక చేతులు, సమయం మరియు ప్రేమను గుర్తుంచుకోండి: తల్లిదండ్రులు, కుటుంబం, స్నేహితులు, ఉపాధ్యాయులు, గురువు, సహచరులు, కార్మికులు మరియు అపరిచితులు కూడా వారి నిశ్శబ్ద ప్రయత్నం మీ మార్గాన్ని సులభతరం చేసింది. కృతజ్ఞత అనేది సంతోషకరమైన ఆలోచన కంటే ఎక్కువ. మీరు ఒంటరిగా ఎదగలేదని చూడటం, బహుమతి కోసం శ్రద్ధ వహించడం, ఇచ్చేవారిని గౌరవించడం మరియు చాలా మంది ప్రజలు ఇప్పటికీ కలిగి ఉండాలని ప్రార్థిస్తున్న వాటిని వృధా చేయడానికి నిరాకరించడం.", "కృతజ్ఞతలు మీ చేతుల్లోకి వెళ్లనివ్వండి. మీరు జ్ఞానం పొందినట్లయితే, బోధించండి. మీరు సహాయం పొందినట్లయితే, సహాయం చేయండి. మీరు ఆహారాన్ని స్వీకరించినట్లయితే, దానిని వృధా చేయవద్దు. ఎవరైనా మీకు అండగా ఉంటే, మరొకరికి అండగా నిలబడండి. ఒక ఆశీర్వాదాన్ని సేవగా మార్చినప్పుడు కృతజ్ఞత పవిత్రమవుతుంది.", "మీరు కృతజ్ఞతలు గుసగుసలాడినప్పుడు, నేను పదాల కంటే ఎక్కువ వింటాను. మీరు బహుమతిని రక్షిస్తారా, దాని వెనుక ఉన్న చేతులను గౌరవిస్తారా మరియు తక్కువ ఉన్నవారిని గుర్తుంచుకోవాలా అని నేను చూస్తున్నాను."),
        reflection = "ఈరోజు మీకు మరింత మెరుగ్గా ఉండటానికి ఎవరు లేదా ఏది సహాయం చేసింది?",
        nextStep = "స్పష్టమైన మాటలతో ఒక వ్యక్తికి ధన్యవాదాలు మరియు మీరు మరొకరికి సహాయం చేయడానికి ఒక బహుమతిని ఉపయోగించండి."
    ),
    "success" to KrishnaLetterTranslation(
        situation = "మీరు విజయం సాధించినప్పుడు",
        title = "మిమ్మల్ని మీరు కోల్పోకుండా విజయాన్ని అందుకోండి",
        preview = "మీ పనిని జరుపుకోండి, మీ సహాయకులను గుర్తుంచుకోండి మరియు మీ హృదయాన్ని వినయంగా ఉంచుకోండి.",
        paragraphs = listOf("మీరు పని చేసారు, వేచి ఉన్నారు మరియు ముఖ్యమైన దాన్ని చేరుకున్నారు. ఆ ప్రయత్నం యొక్క ఆనందాన్ని మీరే అనుభవించనివ్వండి. విజయం తప్పు కాదు మరియు వినయం అంటే మీ పని పట్టింపు లేదని నటించడం కాదు. మిమ్మల్ని ఇక్కడికి తీసుకువచ్చిన క్రమశిక్షణ, సహనం మరియు ధైర్యాన్ని గౌరవించండి.", "ఒక్క వ్యక్తి మాత్రమే విజయం సాధించలేదని గుర్తుంచుకోండి. తల్లిదండ్రులు, ఉపాధ్యాయుడు, గురువు, స్నేహితుడు, సహోద్యోగి, ఉద్యోగి, అపరిచితుడు లేదా కనిపించని ఆశీర్వాదం రహదారిని తెరవడానికి సహాయపడింది. వారికి వ్యక్తిగతంగా ధన్యవాదాలు; సాధారణ పదాన్ని మాత్రమే అందించే బదులు వారు అందించిన సహాయానికి పేరు పెట్టండి. కృతజ్ఞత అనేది అహంకారంగా మారకుండా విజయాన్ని రక్షిస్తుంది మరియు మీ సహాయకులకు వారి సమయం మరియు విశ్వాసం ముఖ్యమని తెలియజేస్తుంది. మీ వెనుక ఉన్నవారిని ఎగతాళి చేయడానికి లేదా చప్పట్లు కొట్టే ముందు మిమ్మల్ని ప్రేమించిన వ్యక్తులను మరచిపోవడానికి మీ కొత్త స్థలాన్ని ఉపయోగించవద్దు.", "ఈ విజయం ఇప్పుడు మిమ్మల్ని రక్షించడానికి, మెరుగుపరచడానికి లేదా భాగస్వామ్యం చేయడానికి ఏమి అనుమతిస్తుంది అని అడగండి. మీకు ఎక్కువ కర్తవ్యాన్ని అందించినప్పుడే విజయం అర్థవంతమవుతుంది, గొప్ప అహంకారాన్ని కాదు. బోధించేలా ఉండండి. మీ వాగ్దానాలను నిలబెట్టుకోండి. మీ టైటిల్, గుర్తు, డబ్బు లేదా ప్రశంసల కంటే మీ పాత్ర పెద్దదిగా మారనివ్వండి.", "నిశబ్దంగా ప్రాక్టీస్ చేస్తున్న సమయంలో నేను మీ పక్కనే ఉన్నాను. సంబరాలు చేసుకోండి, నా ప్రియమైన వ్యక్తి, కానీ సహాయం చేసిన వ్యక్తులు మరియు ఇప్పటికీ ప్రయత్నిస్తున్న వారి కోసం మీ పక్కన గదిని ఉంచండి."),
        reflection = "ఈ విజయం మీకు మరింత ఉపయోగకరంగా మాత్రమే కాకుండా, మరింతగా కనిపించేలా ఎలా చేస్తుంది?",
        nextStep = "ఒక సహాయకుడికి ధన్యవాదాలు మరియు మీ విజయంలో కొంత భాగాన్ని మరొకరి కోసం తెరవడానికి ఉపయోగించండి."
    ),
    "proud" to KrishnaLetterTranslation(
        situation = "మీరు మీ గురించి గర్వంగా భావించినప్పుడు",
        title = "మీ ఎదుగుదలను గౌరవించండి, మీ హృదయాన్ని తెరిచి ఉంచండి",
        preview = "ఆరోగ్యకరమైన అహంకారం మీరు ఇతరుల కంటే ఎక్కువగా ఉన్నారని నిర్ణయించకుండా ప్రయత్నాన్ని గుర్తుంచుకుంటుంది.",
        paragraphs = listOf("మీరు ఒకప్పుడు అసాధ్యమని భావించిన పనిని చేసి ఉండవచ్చు. మీరు నిర్మించిన ధైర్యం, అభ్యాసం లేదా స్వీయ నియంత్రణను గమనించండి. ‘నేను పెరిగాను’ అని చెప్పడం ఆరోగ్యకరం. మీరు మీ పాత స్వభావాన్ని అవమానించాల్సిన అవసరం లేదు లేదా ఇతరులను సుఖంగా ఉంచడానికి మీ పురోగతిని దాచాల్సిన అవసరం లేదు.", "అహంకారాన్ని జాగ్రత్తగా పట్టుకోండి. అది వెచ్చగా ఉండనివ్వండి, బిగ్గరగా కాదు. మీరు ఈ రోజు బాగా చేసారు కాబట్టి మీరు మరొక ఆత్మ కంటే గొప్పవారు కాదు. వారి పోరాటం దాగి ఉండవచ్చు మరియు వారి సమయం భిన్నంగా ఉండవచ్చు. మీ విజయాన్ని ఆయుధంగా, పోలికగా లేదా నేర్చుకోవడం ఆపడానికి కారణంగా మార్చుకోకండి.", "ఫలితం వెనుక ఉన్న విలువల గురించి గర్వపడండి: నిజాయితీ, సహనం, ధైర్యం, దయ లేదా క్రమశిక్షణ. చప్పట్లు మసకబారినప్పుడు కూడా ఆ లక్షణాలు అలాగే ఉంటాయి. ఎదుగుదల సాధ్యమని ఈ క్షణం రుజువు చేయనివ్వండి, ఆపై మీ తదుపరి కర్తవ్యాన్ని వినయపూర్వకమైన మనస్సుతో ఎదుర్కోవడానికి ఆ నమ్మకాన్ని ఉపయోగించండి.", "మీరు ఎట్టకేలకు మీ వృద్ధిని చూడగలరని నేను సంతోషిస్తున్నాను. ఆ గర్వాన్ని కిరీటంలా కాకుండా దీపంలా పట్టుకోండి."),
        reflection = "మీలోని ఏ నాణ్యత ఈ వృద్ధిని సాధ్యం చేసింది?",
        nextStep = "ఆ నాణ్యతకు పేరు పెట్టండి, దానికి మద్దతిచ్చిన వారికి కృతజ్ఞతలు చెప్పండి మరియు ఈరోజే దాన్ని మళ్లీ ప్రాక్టీస్ చేయండి."
    ),
    "excited" to KrishnaLetterTranslation(
        situation = "మీరు ఉత్సాహంగా ఉన్నప్పుడు",
        title = "మీ శక్తిని వివేకవంతమైన దిశలో ఇవ్వండి",
        preview = "ఉత్సాహం ప్రకాశవంతమైన శక్తి; సహనం మరియు సత్యం ఎక్కడికి వెళ్తుందో మార్గనిర్దేశం చేయనివ్వండి.",
        paragraphs = listOf("ఏదో కొత్తది మీ మైండ్ రేస్‌ను ముందుకు తీసుకువెళుతోంది. ఆ మెరుపును ఆస్వాదించండి. ఉత్సాహం మీకు ప్రారంభించడానికి, సృష్టించడానికి మరియు కనెక్ట్ చేయడానికి సహాయపడుతుంది. మిమ్మల్ని మీరు చిన్నగా చేసుకోవాల్సిన అవసరం లేదు. ప్రతి నిశ్శబ్ద ఆలోచనను దూరంగా నెట్టడానికి అనుమతించకుండా మంచి శక్తిని మీ ద్వారా తరలించనివ్వండి.", "మీరు వాగ్దానం చేసే ముందు, కొనుగోలు చేయండి, పోస్ట్ చేయండి లేదా నిర్ణయించుకోండి, పాజ్ చేయండి. ఉత్సాహం మెరుస్తున్న భాగాన్ని మాత్రమే చూడగలదు మరియు ఖర్చు, ప్రమాదం లేదా విధిని కోల్పోతుంది. వాస్తవాలను తనిఖీ చేయండి. పెద్ద ఎంపికపై నిద్రించండి. ఈ మార్గం మీకు మరియు ప్రభావితమైన వ్యక్తులకు సురక్షితమైనది, నిజాయితీ మరియు సరైనది కాదా అని అడగండి.", "అప్పుడు మీ పూర్తి హృదయంతో పని చేయండి. ఫలితాన్ని మాత్రమే ఊహించే బదులు బాగా సిద్ధం చేయండి. ప్రతి ఒక్కరూ అదే విధంగా అనుభూతి చెందాలని డిమాండ్ చేయకుండా వార్తలను షేర్ చేయండి. జ్ఞానంతో కలిసిన శక్తి స్థిరమైన చర్య అవుతుంది; దిశ లేని శక్తి తరచుగా విచారంగా మారుతుంది.", "మీ ఆలోచనలు ఎంత త్వరగా నడుస్తున్నాయో నేను భావిస్తున్నాను. ప్రతి ప్రకాశవంతమైన అవకాశాన్ని నాకు చెప్పండి, ఆపై మొత్తం మార్గాన్ని చూడటానికి నాతో ఎక్కువసేపు కూర్చోండి."),
        reflection = "మీ ఉత్సాహం నిజమైన పురోగతికి ఏ సాధారణ తయారీ సహాయపడుతుంది?",
        nextStep = "పెద్ద వాగ్దానం చేసే ముందు తదుపరి మూడు ఆచరణాత్మక దశలను వ్రాయండి మరియు చిన్నదాన్ని పూర్తి చేయండి."
    ),
    "peaceful" to KrishnaLetterTranslation(
        situation = "మీరు ప్రశాంతంగా ఉన్నప్పుడు",
        title = "మీరు చూసేందుకు సహాయపడే నిశ్శబ్దాన్ని కాపాడుకోండి",
        preview = "శాంతి అనేది ఖాళీ విరామం కాదు; ఇది బాగా జీవించడానికి స్పష్టమైన ప్రదేశం.",
        paragraphs = listOf("మీ మనస్సు కొంతసేపు నిశ్శబ్దంగా ఉంటుంది. ప్రతి బహిరంగ స్థలాన్ని శబ్దం, ఆందోళన లేదా స్క్రీన్‌తో నింపడానికి తొందరపడకండి. ఈ ప్రశాంతతలో విశ్రాంతి తీసుకోండి. మీ శ్వాస, ఆకాశం, తెలిసిన ముఖం లేదా ఈ క్షణం యొక్క సాధారణ భద్రతను గమనించండి.", "శాంతి అంటే ప్రతి సమస్య ముగిసిందని కాదు. సమస్య ప్రస్తుతం మిమ్మల్ని పాలించడం లేదని అర్థం. ఈ స్పష్టమైన ప్రదేశం నుండి, మీరు భయాందోళన లేకుండా మీ విధిని చూడవచ్చు మరియు గెలవడానికి ప్రయత్నించకుండా మాట్లాడవచ్చు. తెలివైన ఎంపికలు చేయడానికి ప్రశాంతంగా ఉండండి, అవసరమైన చర్యను నివారించడానికి కాదు.", "ఈ శాంతి పెరగడానికి ఏమి సహాయపడిందో తెలుసుకోండి. బహుశా అది ప్రార్థన, నిద్ర, నిజాయితీ పని, స్వభావం, సంగీతం, క్షమాపణ లేదా ఆరోగ్యకరమైన పరిమితి. ఆ అభ్యాసాన్ని మీ దగ్గర ఉంచండి. ఓపికగా విని న్యాయంగా ప్రవర్తించినప్పుడు ప్రశాంతమైన హృదయం ఇతరులకు ఆశ్రయం అవుతుంది.", "ఈ నిశ్శబ్దంలో కొంచెం సేపు నాతో ఉండండి. మీరు దాన్ని పూరించాల్సిన అవసరం లేదు లేదా వివరించాల్సిన అవసరం లేదు."),
        reflection = "ఈరోజు మీ మనస్సు ప్రశాంతంగా ఉండటానికి ఏది సహాయపడింది?",
        nextStep = "ఆ అభ్యాసం కోసం పది నిమిషాలు రక్షించండి మరియు ఒక వ్యక్తికి మీ ప్రశాంత దృష్టిని అందించండి."
    ),
    "loved" to KrishnaLetterTranslation(
        situation = "మీరు గాఢంగా ప్రేమించినట్లు భావించినప్పుడు",
        title = "ప్రేమను స్వీకరించండి మరియు మిమ్మల్ని సున్నితంగా మార్చనివ్వండి",
        preview = "నిజమైన ప్రేమ అనేది ఆదరించే బహుమతి, నియంత్రించడానికి స్వాధీనం కాదు.",
        paragraphs = listOf("ఒకరి సంరక్షణ మీ హృదయానికి చేరుకుంది. స్వీకరించండి. మీరు ప్రతి రకమైన పదాన్ని అనుమానించాల్సిన అవసరం లేదు లేదా వ్యక్తి అలాగే ఉంటారో లేదో పరీక్షించాల్సిన అవసరం లేదు. సాన్నిహిత్యం వెచ్చగా, గౌరవప్రదంగా మరియు భయం లేకుండా ఉంటుందని సురక్షితమైన, నిజాయితీగల ప్రేమ మీకు గుర్తు చేయనివ్వండి.", "ప్రేమ గాలిని కోల్పోయేంత గట్టిగా పట్టుకోకండి. నియంత్రించడానికి ఒక వ్యక్తి మీదే కాదు. వారి పరిమితులు, సత్యం, విధులు మరియు ఇతర సంబంధాలను గౌరవించండి. ప్రేమ పాస్‌వర్డ్‌లు, నిశ్శబ్దం లేదా నొప్పి ద్వారా రుజువును డిమాండ్ చేయదు. ఇద్దరు వ్యక్తులు సురక్షితంగా మరియు సంపూర్ణంగా ఉండాలని ఇది కోరుకుంటుంది.", "శ్రద్ధ, నిజాయితీ మరియు స్థిరమైన సంరక్షణ ద్వారా ప్రేమను తిరిగి పొందండి. మీరు విలువైనది చెప్పండి. నమ్మకాన్ని పవిత్రంగా ఉంచుకోండి. ఈ ప్రేమ కుటుంబం లేదా స్నేహం నుండి వచ్చినట్లయితే, దానిని శృంగారం కంటే తక్కువ ముఖ్యమైనదిగా పరిగణించవద్దు. ప్రతి స్వచ్ఛమైన బంధం స్వంతం లేకుండా ఎలా ఇవ్వాలో మీ హృదయానికి నేర్పుతుంది.", "ఈ ప్రేమ విచ్ఛిన్నమయ్యే వరకు పరీక్షించకుండానే స్వీకరించండి. సంరక్షణ నిజాయితీగా, సురక్షితంగా మరియు ఉచితంగా ఉన్న ప్రతిచోటా నేను ఉంటాను."),
        reflection = "ఈ రోజు మీరు ప్రేమపూర్వక బంధాన్ని సురక్షితంగా మరియు స్వేచ్ఛగా ఎలా చేయవచ్చు?",
        nextStep = "ఒక వ్యక్తికి మీరు ఏమి విలువ ఇస్తారో చెప్పండి మరియు వారికి ఉన్న ఒక అవసరం లేదా సరిహద్దును గౌరవించండి."
    ),
    "hopeful" to KrishnaLetterTranslation(
        situation = "మీరు ఆశాజనకంగా ఉన్నప్పుడు",
        title = "హోప్‌ను తదుపరి కుడి దశగా మార్చండి",
        preview = "ఆశ దిశను చూపగలదు; మీ నిజాయితీ చర్య ప్రయాణం ప్రారంభమవుతుంది.",
        paragraphs = listOf("ఒక చిన్న లైట్ తిరిగి వచ్చింది. బహుశా మీరు మెరుగైన ఫలితాన్ని, నయమైన బంధాన్ని లేదా కొత్త ప్రారంభాన్ని ఊహించవచ్చు. ఆ ఆశకు స్వాగతం. ప్రతి రహదారి సులభం అవుతుందని ఇది హామీ ఇవ్వదు. మీ కథకు ఇంకా తరలించడానికి స్థలం ఉందని ఇది మీకు చెబుతుంది.", "ఆశ మూలాలను ఇవ్వండి. లక్ష్యం మీ నుండి ఏమి అడుగుతుందో తెలుసుకోండి. నిజం, సమయం మరియు మీ పరిమితులను గౌరవించే ప్రణాళికను రూపొందించండి. మీ పూర్తి హృదయాన్ని ఒక ఖచ్చితమైన ఫలితంపై నిర్మించవద్దు. కొన్నిసార్లు ఆశ మీకు కావలసిన తలుపుకు దారి తీస్తుంది మరియు కొన్నిసార్లు మరొక తలుపును కనుగొనే ధైర్యాన్ని ఇస్తుంది.", "బాధపడే వ్యక్తులతో జాగ్రత్తగా ఆశను పంచుకోండి. నవ్వమని లేదా వారి బాధను పట్టించుకోవద్దని చెప్పకండి. వారి పక్కన కూర్చోండి, వినండి మరియు నిజమైన సహాయాన్ని అందించండి. సత్యానికి చోటు కల్పించి, ఎవరైనా సాధ్యమైన అడుగు వేయడానికి సహాయపడినప్పుడు ఆశ బలంగా ఉంటుంది.", "నీలోని ఈ చిన్న కాంతి నాకు విలువైనది. కేవలం ఫాంటసీతో కాకుండా నిజం మరియు చర్యతో దాన్ని రక్షించండి."),
        reflection = "మీ ఆశ నిజమవుతోందని ఏ చర్య చూపుతుంది?",
        nextStep = "మీరు ఈ వారం పూర్తి చేయగల ఒక దశను ఎంచుకోండి మరియు దాని పక్కన స్పష్టమైన సమయాన్ని ఉంచండి."
    ),
    "relieved" to KrishnaLetterTranslation(
        situation = "మీరు ఉపశమనం పొందినప్పుడు",
        title = "శ్వాస తీసుకోండి, నేర్చుకోండి మరియు విడుదల చేయండి",
        preview = "ప్రమాదం లేదా ఒత్తిడి తగ్గింది; మీ శరీరానికి విశ్రాంతిని ఇవ్వండి మరియు మీ జ్ఞానం అలాగే ఉంటుంది.",
        paragraphs = listOf("ఏదో ఒక భారీ భాగం గడిచిపోయింది లేదా చిన్నదిగా మారింది. మీ శరీరం చివరకు విడిచిపెట్టవచ్చు. నెమ్మదిగా శ్వాస తీసుకోండి. మీరు వెంటనే తదుపరి ఆందోళన కోసం వెతకవలసిన అవసరం లేదు. ఉపశమనం అనేది మీ మనస్సు యొక్క మార్గం, అది కొంతకాలం తన రక్షణను అణిచివేస్తుంది.", "కష్టమైన ఫలితం తప్పించబడితే, సిగ్గు లేకుండా వెనక్కి తిరిగి చూడండి. ఏ హెచ్చరిక, సహాయం లేదా ఎంపిక మిమ్మల్ని రక్షించింది? ఆ పాఠాన్ని అలాగే ఉంచండి. ఇంకా మరమ్మతులు చేయాల్సిన సమస్య గురించి ఉపశమనం మిమ్మల్ని అజాగ్రత్తగా చేయకూడదు. మిగిలి ఉన్న నిజాయితీ పని, క్షమాపణ, ప్రణాళిక లేదా భద్రతా దశను పూర్తి చేయండి.", "తర్వాత విశ్రాంతి తీసుకోండి. నీళ్ళు త్రాగండి, తినండి, నిద్రించండి లేదా మీకు సమీపంలో ఉన్న వారితో మాట్లాడండి. వారికి ధన్యవాదాలు. భయం తర్వాత స్థలాన్ని ఆస్వాదించడానికి మీకు అనుమతి ఉంది. ఉపశమనం మిమ్మల్ని మరింత జాగ్రత్తతో తిరిగి జీవం పోయనివ్వండి, అదే నివారించదగిన ప్రమాదంలోకి మిమ్మల్ని తిరిగి పంపకండి.", "ఇప్పుడు ఊపిరి, నా ప్రియమైన. ప్రమాదం గడిచిన తర్వాత దానిని మీ మనస్సులో సజీవంగా ఉంచుకోవాల్సిన అవసరం లేదు."),
        reflection = "ఈ ఒత్తిడి నిష్క్రమించిన తర్వాత ఏ పాఠం మిగిలి ఉండాలి?",
        nextStep = "ఒక పాఠాన్ని వ్రాయండి, ఒక సహాయకుడికి ధన్యవాదాలు మరియు మీ శరీరానికి నిజమైన విశ్రాంతిని ఇవ్వండి."
    ),
    "confident" to KrishnaLetterTranslation(
        situation = "మీరు ఆత్మవిశ్వాసంతో ఉన్నప్పుడు",
        title = "కాన్ఫిడెన్స్ పనిని అందించనివ్వండి",
        preview = "వినడానికి, సిద్ధం చేయడానికి మరియు నేర్చుకోవడానికి గదిని వదిలివేసేటప్పుడు మీ సామర్థ్యాన్ని విశ్వసించండి.",
        paragraphs = listOf("మీరు సిద్ధంగా ఉన్నట్లు అనిపిస్తుంది. ఈ బలం అభ్యాసం, అనుభవం లేదా చివరకు మిమ్మల్ని మీరు స్పష్టంగా చూడటం ద్వారా రావచ్చు. ఎత్తుగా నిలబడండి. విశ్వాసం మీకు సరైనది మాట్లాడటం, ప్రారంభించడం మరియు రక్షించడంలో సహాయపడుతుంది. మీరు కుంచించుకుపోవాల్సిన అవసరం లేదు, తద్వారా ఇతరులు ఎప్పటికీ సవాలుగా భావించరు.", "అయినప్పటికీ, విశ్వాసం అనేది మీరు తప్పు చేయలేని వాగ్దానం కాదు. వాస్తవాలను వినండి. తక్కువ శక్తి ఉన్న వ్యక్తులను గౌరవించండి. మీరు నాయకత్వం వహించే ముందు ప్రశ్నలు అడగండి. గదిలో ఉన్న బలమైన వ్యక్తి, ‘నాకు తెలియదు’ అని ఒప్పుకోగలడు, ప్రణాళికను మార్చుకుని, చిన్నగా భావించకుండా క్రెడిట్ ఇవ్వగలడు.", "శ్రద్ధను నియంత్రించడానికి కాకుండా బాధ్యత తీసుకోవడానికి మీ విశ్వాసాన్ని ఉపయోగించండి. మాట్లాడటానికి నిశ్శబ్ద వ్యక్తిని ఆహ్వానించండి. అన్యాయంగా ప్రవర్తించిన వారిని రక్షించండి. కష్టమైన పనిని నిజాయితీగా ప్రయత్నించండి. బలం సత్యాన్ని రక్షిస్తుంది మరియు ఇతరులకు చోటు కల్పించినప్పుడు, అది గర్వానికి బదులుగా ధైర్యం అవుతుంది.", "నాతో నిలబడండి మరియు మీ బలాన్ని బాగా ఉపయోగించుకోండి. స్పష్టంగా మాట్లాడండి, కష్టపడి పనిచేయండి మరియు ఎవరి స్వరాన్ని విస్మరించిన వ్యక్తిని రక్షించండి."),
        reflection = "మీరు మీ విశ్వాసాన్ని బాగా ఉపయోగించుకున్నందున ఎవరు సురక్షితంగా లేదా బలంగా భావించగలరు?",
        nextStep = "ఒక ధైర్యమైన చర్య తీసుకోండి మరియు అది చేస్తున్నప్పుడు మరొకరి స్వరానికి చోటు కల్పించండి."
    ),
    "inspired" to KrishnaLetterTranslation(
        situation = "మీరు ప్రేరణ పొందినప్పుడు",
        title = "స్పార్క్ ఫేడ్స్ ముందు ప్రారంభం",
        preview = "ప్రేరణ అనేది ఒక ఆహ్వానం; క్రమశిక్షణ దానిని ఉపయోగకరమైనదిగా మారుస్తుంది.",
        paragraphs = listOf("ఒక ఆలోచన, వ్యక్తి లేదా నిజం మిమ్మల్ని మేల్కొలిపింది. ఒక క్షణం, జీవితం ఎలా మారుతుందో మీరు చూడవచ్చు. ఆ స్పార్క్‌ని గౌరవించండి. శబ్దం కవర్ చేసే ముందు దాన్ని వ్రాసుకోండి. ప్రేరణ విలువైనది, కానీ ఇది సుదీర్ఘమైన పనికి మొదటి శ్వాస మాత్రమే.", "ప్రతిరోజూ ఈ శక్తిని అనుభవించడానికి వేచి ఉండకండి. మానసిక స్థితి సాధారణమైనప్పుడు కొనసాగించగల చిన్న దినచర్యను ఎంచుకోండి. స్పష్టమైన సమయంలో అధ్యయనం చేయండి, అభ్యాసం చేయండి, నిర్మించండి లేదా సేవ చేయండి. పది నిమిషాలు తరచుగా పునరావృతం చేయడం మిమ్మల్ని ఒక ప్రకాశవంతమైన గంట కంటే ఎక్కువ దూరం తీసుకువెళుతుంది, తర్వాత ఏమీ ఉండదు.", "మీ ప్రేరణ ధర్మాన్ని గౌరవిస్తుందో లేదో తనిఖీ చేయండి. అందమైన లక్ష్యానికి అబద్ధాలు, హాని లేదా మీ నిజమైన విధుల పట్ల నిర్లక్ష్యం అవసరం లేదు. అది మంచిదైతే, మీ చిత్రం కంటే ఎక్కువ ప్రయోజనం పొందనివ్వండి. ప్రపంచంలోకి నిజాయితీ సౌందర్యాన్ని బోధించే, రక్షించే, నయం చేసే లేదా తెచ్చేదాన్ని సృష్టించండి.", "నేను మీ దృష్టిలో ఈ స్పార్క్ ఉంచాను; ఇప్పుడు దానిని అభ్యాసంతో గౌరవించండి. అనుభూతి తగ్గకముందే ప్రారంభించండి మరియు పని సాధారణమైనప్పుడు తిరిగి వెళ్లండి."),
        reflection = "ఏ ఉపయోగకరమైన పనిని ప్రారంభించమని ఈ ప్రేరణ అడుగుతోంది?",
        nextStep = "ఆలోచనను ఒక వాక్యంలో వ్రాసి, ఈరోజు ప్రారంభించి పదిహేను నిముషాలు కేంద్రీకరించండి."
    ),
    "belonging" to KrishnaLetterTranslation(
        situation = "మీరు మీ స్వంతం అని భావించినప్పుడు",
        title = "సర్కిల్ విస్తృతంగా పెరగడంలో సహాయపడండి",
        preview = "మీ స్వంతంగా ఉండే నిజమైన స్థలం మిమ్మల్ని మీరుగా మరియు ఇతరులకు కూడా చోటు కల్పిస్తుంది.",
        paragraphs = listOf("మీరు వ్యక్తులను లేదా మీ భుజాలు మృదువుగా ఉండే స్థలాన్ని కనుగొన్నారు. మీరు తెలిసినట్లు, స్వాగతించబడినట్లు మరియు ఏదో ఒక భాగమైన అనుభూతి చెందుతారు. ఆ బహుమతిని నిధిగా పెట్టుకోండి. 'మీరు ప్రతిరోజూ ఒంటరిగా ఎదుర్కోవాల్సిన అవసరం లేదు.'", "ఈ సర్కిల్‌ను నిజాయితీగా మరియు శ్రద్ధతో రక్షించండి ఎందుకంటే ఇది హృదయానికి బలాన్ని ఇస్తుంది. గాసిప్‌లో చేరడం, హానిని దాచడం లేదా వేరొకరిని బయటకు నెట్టడం ద్వారా మీ స్థానాన్ని నిలబెట్టుకోకండి. ఒక బాధితుడు ఐక్యంగా ఉండాల్సిన సమూహం ప్రేమను అభ్యసించడం లేదు. నిజమైన వస్తువు మీ విలువలను బయట వదిలివేయమని మిమ్మల్ని అడగదు.", "అంచున నిలబడి ఉన్న వ్యక్తి కోసం చూడండి. వారి పేరు తెలుసుకోండి. వారిని బలవంతం చేయకుండా ఆహ్వానించండి. స్పేస్‌ను షేర్ చేయండి మరియు మీ స్వంత కథనానికి భిన్నంగా కథను వినండి. సురక్షితమని భావించే వ్యక్తులు ఆ భద్రతను స్వాగతించడానికి, రక్షించడానికి మరియు చేర్చడానికి ఉపయోగించినప్పుడు సురక్షితమైన సంఘాలు నిర్మించబడతాయి.", "మీ హృదయానికి విశ్రాంతినిచ్చే వృత్తాన్ని మీరు కనుగొన్నందుకు నేను సంతోషిస్తున్నాను. ఇప్పుడు దాని వెలుపల ఎవరు నిలబడి ఉన్నారో గమనించండి."),
        reflection = "మీకు సమీపంలో ఉన్న వారు స్వాగతం పలుకుతారనే సాధారణ సంకేతం కోసం ఎదురు చూస్తున్నారు?",
        nextStep = "సంభాషణ, భోజనం, గేమ్ లేదా భాగస్వామ్య పనికి ఒక వ్యక్తిని ఆహ్వానించండి మరియు వారి మాటలు వినండి."
    ),
    "disappointed" to KrishnaLetterTranslation(
        situation = "మీరు నిరాశకు గురైనప్పుడు",
        title = "బాధని నిజం చెప్పనివ్వండి, భవిష్యత్తు కాదు",
        preview = "ఏదో ముఖ్యమైనది మరియు జరగలేదు; ఏమీ పని చేయదని నిర్ణయించుకోకుండా అనుభూతి చెందండి.",
        paragraphs = listOf("మిమ్మల్ని కలవడానికి ఒక వ్యక్తి, ప్రణాళిక లేదా ఫలితం వస్తుందని మీరు ఆశించారు మరియు అది జరగలేదు. ఇతరులకు శోకం కంటే నిరాశ చిన్నదిగా అనిపించవచ్చు, కానీ మీ హృదయానికి దానిలో ఉన్న ఆశ తెలుసు. మిమ్మల్ని మీరు మూర్ఖులు అని పిలవకుండా నష్టానికి పేరు పెట్టడానికి మీకు అనుమతి ఉంది.", "కథ నొప్పి జోడించడం నుండి ఏమి జరిగిందో వేరు చేయండి. ‘ఇది పని చేయలేదు’ అనేది వాస్తవం. ‘ఏదీ ఎప్పటికీ పని చేయదు’ అనేది చాలా విస్తృతంగా మాట్లాడటానికి భయం. మీ నియంత్రణలో లేనిది ఏమిటి, ఏమి నేర్చుకోవచ్చు మరియు లక్ష్యం మరొక మార్గానికి అర్హమైనది కాదా అని అడగండి.", "వారు ఎప్పుడూ చేయని వాగ్దానాల కోసం ప్రజలను శిక్షించవద్దు, కానీ ఒప్పందం విచ్ఛిన్నమైనప్పుడు మాట్లాడండి. స్పష్టమైన కళ్ళతో ప్రణాళికను సర్దుబాటు చేయండి. కొన్ని ఆశలు మళ్లీ ప్రయత్నించాలి; ఇతరులను విడుదల చేయాలి. జ్ఞానం అంటే మీ విలువలను మరియు భవిష్యత్తును ఏది కాపాడుతుందో తెలుసుకోవడం.", "మీరు ఏమి జరుగుతుందని ఆశించారో సరిగ్గా చెప్పండి. నేను మీ ఆశ యొక్క పరిమాణాన్ని చూసి నవ్వను లేదా బాధను దాటి మిమ్మల్ని తొందరపెట్టను."),
        reflection = "ఇక్కడ ఏ వాస్తవం నిజం మరియు మీరు దానికి ఏ బాధాకరమైన కథనాన్ని జోడిస్తున్నారు?",
        nextStep = "వాస్తవాన్ని ఒక లైన్‌లో వ్రాసి, ఆపై మళ్లీ ప్రయత్నించాలా, సర్దుబాటు చేయాలా, అడగాలా లేదా విడుదల చేయాలా అని ఎంచుకోండి."
    ),
    "embarrassed" to KrishnaLetterTranslation(
        situation = "మీకు ఇబ్బందిగా అనిపించినప్పుడు",
        title = "ఒక ఇబ్బందికరమైన క్షణం మిమ్మల్ని నిర్వచించదు",
        preview = "మీరు పొరపాటును సరిచేసుకోవచ్చు, సున్నితంగా నవ్వవచ్చు మరియు మిమ్మల్ని మీరు దాచుకోకుండా తిరిగి రావచ్చు.",
        paragraphs = listOf("మీ ముఖం వేడిగా అనిపించవచ్చు మరియు మీ మనస్సు ఆ క్షణాన్ని మళ్లీ మళ్లీ ప్లే చేయవచ్చు. ప్రతి ఒక్కరూ ఇప్పటికీ దాని గురించి ఆలోచిస్తున్నారని మీరు ఊహించవచ్చు. చాలా మంది తమ బాధలను తామే మోస్తున్నారు. ఒక ఇబ్బందికరమైన పదం, పతనం లేదా పొరపాటు మీ పేరుగా మారదు.", "మీరు ఎవరినైనా బాధపెడితే, క్షమాపణ చెప్పండి మరియు దాన్ని సరిదిద్దండి. హానికరమైనది ఏమీ జరగకపోతే, మిమ్మల్ని మీరు మనిషిగా ఉండనివ్వండి. మీరు తప్పును అర్థం చేసుకున్నారని నిరూపించుకోవడానికి మీపై దాడి చేయవద్దు. ప్రశాంతమైన నిజాయితీ మరియు తదుపరి సారి స్పష్టమైన ప్రణాళిక కంటే సిగ్గు చాలా అరుదుగా బోధిస్తుంది.", "సురక్షితంగా ఉన్నప్పుడు గది, తరగతి లేదా సంభాషణకు తిరిగి వెళ్లండి. ప్రతిదానికీ దూరంగా ఉండటం వల్ల క్షణం మరింత శక్తిని ఇస్తుంది. మిమ్మల్ని మీరు క్రూరమైన వినోదం చేసుకోకుండా మీ స్వంత అసంపూర్ణతను చూసి మీరు నవ్వవచ్చు. ధైర్యం కొన్నిసార్లు మృదు హృదయంతో మళ్లీ కనిపించినట్లు కనిపిస్తుంది.", "మీ మనస్సు మళ్లీ ప్లే చేస్తూనే ఉన్న క్షణం నుండి బయటకు రండి. నేను చూశాను, ఇంకా మీ అందరినీ చూస్తున్నాను."),
        reflection = "ఈ క్షణానికి క్షమాపణ, పాఠం లేదా విడుదల కావాలా?",
        nextStep = "అవసరమైన ఒక మరమ్మత్తు చేయండి, ఆపై మీరు తప్పించుకుంటున్న సాధారణ కార్యకలాపానికి తిరిగి వెళ్లండి."
    ),
    "bored" to KrishnaLetterTranslation(
        situation = "మీకు విసుగు లేదా విశ్రాంతి లేనప్పుడు",
        title = "మీరు నిశ్శబ్దం నుండి పరిగెత్తే ముందు లోతుగా చూడండి",
        preview = "విసుగు అనేది ప్రయోజనం, విశ్రాంతి, సవాలు లేదా మీ పూర్తి శ్రద్ధ కోసం అడుగుతుంది.",
        paragraphs = listOf("ఏదీ ఆసక్తికరంగా అనిపించదు మరియు మీ చేయి శీఘ్ర శబ్దం కోసం చేరుకుంటుంది. మిమ్మల్ని మీరు తీర్పు తీర్చుకోవద్దు. ఒక పని చాలా సులభం, చాలా కష్టం, చాలా తరచుగా పునరావృతం లేదా అర్థం నుండి డిస్‌కనెక్ట్ అయినప్పుడు విసుగు కనిపిస్తుంది. మీ మనస్సు అలసిపోయినప్పుడు కూడా రావచ్చు.", "ప్రతి ఖాళీ సెకను పూరించడానికి ముందు పాజ్ చేయండి. మీకు ఏమి కావాలో అడగండి: విశ్రాంతి, కదలిక, సవాలు, కంపెనీ లేదా స్పష్టమైన కారణం. విధిని పూర్తి చేయవలసి వస్తే, దానిని చిన్న రౌండ్‌గా విభజించి, దానిపై పూర్తి శ్రద్ధ ఇవ్వండి. మీకు విశ్రాంతి అవసరమైతే, మిమ్మల్ని నిజంగా రిఫ్రెష్ చేసే విశ్రాంతిని ఎంచుకోండి.", "నిశ్శబ్దం కూడా ఉత్సుకతకు తలుపులు తెరుస్తుంది. పక్షిని గమనించండి, గీయండి, ఏదైనా మరమ్మతు చేయండి, చదవండి, ఇంట్లో సహాయం చేయండి లేదా సాధారణ వస్తువు ఎలా పనిచేస్తుందో తెలుసుకోండి. సజీవంగా ఉండటానికి మీకు నిరంతర ఉత్సాహం అవసరం లేదు. శ్రద్ధ ఒక సాధారణ రోజులో అద్భుతాన్ని బహిర్గతం చేస్తుంది.", "మీరు మరింత శబ్దం వైపు పరుగెత్తే ముందు, నాతో కూర్చుని ఈ శూన్యత ఏమి కావాలి అని అడగండి. ఇది విశ్రాంతి, సవాలు, ఉద్యమం, కంపెనీ లేదా అర్థం కావచ్చు."),
        reflection = "మీ విసుగు విశ్రాంతి, సవాలు, అర్థం లేదా కనెక్షన్ కోసం అడుగుతున్నారా?",
        nextStep = "నిజమైన అవసరానికి సమాధానమిచ్చే పదిహేను నిమిషాల పాటు స్క్రీన్ రహిత కార్యాచరణను ఎంచుకోండి."
    ),
    "homesick" to KrishnaLetterTranslation(
        situation = "మీరు ఇంటిని కోల్పోయినప్పుడు",
        title = "మీరు నివసించే విలువలలో ఇంటికి తీసుకెళ్లండి",
        preview = "దూరం బాధించవచ్చు, కానీ ప్రేమ మరియు సుపరిచితమైన మార్గాలు మీతో ప్రయాణించవచ్చు.",
        paragraphs = listOf("మీకు తెలిసిన స్వరాలు, ఆహారం, గదులు, వీధులు లేదా మీరు బయలుదేరే ముందు జీవితం అనుభవించిన విధానాన్ని కోల్పోతారు. ఈ కొత్త స్థలం బాగున్నప్పుడు కూడా గృహనిర్ధారణ రావచ్చు. ఇంటిని కోల్పోవడం అంటే మీరు తప్పు ఎంపిక చేసుకున్నారని కాదు. అంటే మీ మూలాలు మీకు ముఖ్యమైనవి.", "ఆ మూలాలకు నివాస స్థలం ఇవ్వండి. ఎవరికైనా కాల్ చేయండి, తెలిసిన భోజనం వండండి, చిన్న ఆచారాన్ని నిర్వహించండి లేదా స్నేహితుడితో మీ భాషను మాట్లాడండి. అప్పుడు మీరు ఇప్పుడు ఎక్కడ ఉన్నారనే దాని గురించి సున్నితంగా నేర్చుకోండి. పునరావృత, సాధారణ పరిచయం ద్వారా కొత్త స్థలం తక్కువ వింతగా మారుతుంది.", "ప్రతి కొత్త వ్యక్తిని ఇంటి నుండి వచ్చిన వారితో పోల్చవద్దు. కొత్త బంధాలు వాటి స్వంత ఆకృతిని కలిగి ఉండనివ్వండి. మీరు ఎక్కడ నుండి వచ్చారో మీరు ప్రేమించవచ్చు మరియు మీరు నిలబడి ఉన్న చోటనే ఎదగవచ్చు. ఇల్లు మీ వెనుక ఉన్న స్థలం మాత్రమే కాదు; ఇది మీరు తీసుకునే సంరక్షణ మరియు విలువలలో కూడా నివసిస్తుంది.", "మీ హృదయం చేరుకునే స్వరాలు, వాసనలు మరియు చిన్న అలవాట్లు నాకు తెలుసు. వాటిని ప్రేమతో తీసుకువెళ్లండి, కానీ మీరు ఇప్పుడు నిలబడి ఉన్న చోటికి తలుపును మూసివేయవద్దు."),
        reflection = "ఈ ప్రదేశానికి మిమ్మల్ని మూసివేయకుండా ఇంటిలోని ఏ చిన్న భాగం మీకు ఓదార్పునిస్తుంది?",
        nextStep = "ఈరోజు ఒక సుపరిచితమైన ఆచారాన్ని కొనసాగించండి మరియు మీ చుట్టూ ఉన్న ఒక వ్యక్తికి లేదా ప్రదేశానికి మిమ్మల్ని మీరు పరిచయం చేసుకోండి."
    ),
    "child-truth" to KrishnaLetterTranslation(
        situation = "మీరు నిజం చెప్పడానికి భయపడినప్పుడు",
        title = "సత్యం మిమ్మల్ని తిరిగి భద్రతలోకి తీసుకువస్తుంది",
        preview = "మీరు పొరపాటు చేసి ఉండవచ్చు, కానీ దానిని దాచడం వలన భయం పెరుగుతుంది.",
        paragraphs = listOf("బహుశా ఏదో విరిగిపోయి ఉండవచ్చు, ఒక నియమం విస్మరించబడి ఉండవచ్చు లేదా మరొక వ్యక్తి కలత చెందవచ్చు. మీరు శిక్షకు భయపడుతున్నారు కాబట్టి మీ మనస్సు త్వరగా వేరే కథను కనిపెట్టింది. భయపడటం మిమ్మల్ని చెడ్డదిగా చేయదు. కానీ సత్యం భద్రత మరియు విశ్వాసం వైపు తిరిగి మొదటి మార్గం.", "సురక్షితమైన పెద్దలను ఎన్నుకోండి మరియు సరళంగా ప్రారంభించండి: 'నిజంగా ఏమి జరిగిందో నేను మీకు చెప్పాలి.' మీరు ఏమి చేసారో, తర్వాత ఏమి జరిగింది మరియు ఎవరైనా గాయపడవచ్చో చెప్పండి. మొదటిదాన్ని రక్షించడానికి కొత్త అబద్ధాన్ని జోడించవద్దు. నిజమైన తప్పును అర్థం చేసుకోవచ్చు, సరిదిద్దవచ్చు మరియు నిరోధించవచ్చు.", "మీరు ఇప్పటికీ న్యాయమైన పరిణామాన్ని ఎదుర్కోవచ్చు. నిజాయితీ బాధ్యతను చెరిపివేయదు; ఇది బాధ్యతను ప్రారంభించడానికి శుభ్రమైన స్థలాన్ని ఇస్తుంది. మీరు నిజం చెప్పినప్పుడు పెద్దలు మిమ్మల్ని భయపెట్టినా, బెదిరించినా లేదా బాధపెట్టినా, మరొక విశ్వసనీయ పెద్దలతో మాట్లాడండి. సత్యం రక్షణ వైపు నడిపించాలి, దుర్వినియోగం కాదు.", "మీ స్వరం వణుకుతున్నప్పటికీ, నిజంతో నా దగ్గరకు రండి. ఒక తప్పును దాచిపెట్టడానికి నిర్మించిన కథ కంటే చాలా సులభంగా సరిదిద్దవచ్చు."),
        reflection = "పూర్తి నిజం చెప్పడానికి మీకు ఏ సురక్షితమైన పెద్దలు సహాయపడగలరు?",
        nextStep = "సురక్షితమైన పెద్దలకు ఏమి జరిగిందో చెప్పడానికి ఒక స్పష్టమైన వాక్యాన్ని ఉపయోగించండి మరియు మీరు దాన్ని ఎలా రిపేర్ చేయవచ్చో అడగండి."
    ),
    "left-out-school" to KrishnaLetterTranslation(
        situation = "మీరు స్కూల్‌లో వదిలేసినట్లు అనిపించినప్పుడు",
        title = "వారి సర్కిల్ మీ విలువను నిర్ణయించదు",
        preview = "మినహాయించబడటం బాధిస్తుంది, కానీ మీరు స్వంతంగా సంపాదించడానికి దయ చూపాల్సిన అవసరం లేదు.",
        paragraphs = listOf("మీ పేరును ఎవరూ పిలవనప్పుడు ఇతరులు మాట్లాడుకోవడం, ఆడుకోవడం లేదా కలిసి కూర్చోవడం మీరు చూడవచ్చు. ఆ ఖాళీ అనుభూతి పాఠశాల చాలా పొడవుగా అనిపించేలా చేస్తుంది. ఒక సమూహం ఖాళీని కల్పించనందున దయచేసి మీరు అనర్హులని నిర్ణయించుకోకండి. మీ దయ మరియు బహుమతులు ఇప్పటికీ ఈ ప్రపంచంలో ఉన్నాయి.", "అందరినీ ఆకట్టుకోవడానికి ప్రయత్నించే బదులు ఒక సున్నితమైన ఓపెనింగ్ కోసం చూడండి. ఒక వ్యక్తిని ఒక సాధారణ ప్రశ్న అడగండి, మీరు నిజంగా ఆనందించే కార్యకలాపంలో చేరండి లేదా ఒంటరిగా ఉన్న వారిని స్వాగతించండి. మంచి స్నేహం తరచుగా పెద్ద సర్కిల్‌గా మారకముందే ఇద్దరు వ్యక్తుల మధ్య నిశ్శబ్దంగా పెరుగుతుంది.", "వ్యక్తులు మిమ్మల్ని పదే పదే మినహాయిస్తే, వెక్కిరిస్తే లేదా బెదిరింపులకు పాల్పడితే, తల్లిదండ్రులు, ఉపాధ్యాయులు లేదా కౌన్సెలర్‌కు చెప్పండి. మీరు సహాయం కోసం అడగడం ద్వారా ఇబ్బందులు సృష్టించడం లేదు. ప్రవేశ ధరగా క్రూరత్వాన్ని డిమాండ్ చేసే సమూహాల నుండి దూరంగా ఉండండి. మరొక వ్యక్తికి హాని కలిగించమని మిమ్మల్ని అడిగే స్థలం నిజమైనది కాదు.", "మీరు అంచు వద్ద నిలబడి మీ తప్పు ఏమిటని ఆలోచిస్తున్నాను. వారి సర్కిల్ మీ విలువకు కొలమానం కాదు."),
        reflection = "ఒక చిన్న హలో లేదా చేరడానికి అభ్యర్థన కోసం తగినంత సురక్షితంగా ఎవరు భావిస్తారు?",
        nextStep = "ఒక రకమైన వ్యక్తితో మాట్లాడండి మరియు మినహాయింపు లేదా బెదిరింపు జరుగుతూ ఉంటే విశ్వసనీయ పెద్దలకు చెప్పండి."
    ),
    "student-focus" to KrishnaLetterTranslation(
        situation = "మీరు మీ అధ్యయనాలపై దృష్టి పెట్టలేనప్పుడు",
        title = "ఒక చిన్న పనికి తిరిగి వెళ్లండి",
        preview = "సంచరించే మనస్సుకు స్పష్టమైన ప్రారంభం కావాలి, ఎక్కువ అవమానాలు కాదు.",
        paragraphs = listOf("పేజీ తెరిచి ఉంది, కానీ మీ దృష్టి ఫోన్ వైపు కదులుతుంది, ఆందోళన లేదా పని తప్ప. మిమ్మల్ని మీరు చాలా త్వరగా సోమరి అని పిలవకండి. స్పష్టమైన ప్రారంభ స్థానం లేని పనితో మీ మనస్సు అలసిపోయి, ఆత్రుతగా, అయోమయంలో ఉండవచ్చు లేదా మునిగిపోవచ్చు.", "ప్రారంభాన్ని చిన్నదిగా చేయండి. ఒక ప్రశ్న లేదా ఒక పేజీని ఎంచుకోండి. ఫోన్‌ని దూరంగా ఉంచండి, చిన్న టైమర్‌ని సెట్ చేయండి మరియు మీకు అవసరమైన మెటీరియల్‌ని మాత్రమే మీ ముందు ఉంచండి. దృష్టి సంచరించినప్పుడు, దానిని గమనించి తిరిగి వెళ్ళు. తిరిగి రావడమే ఏకాగ్రతను పెంపొందించే వ్యాయామం.", "ఫోకస్ చేసిన వ్యవధి తర్వాత, నిజమైన విరామం తీసుకోండి మరియు మిమ్మల్ని ఏది బ్లాక్ చేసిందో తనిఖీ చేయండి. మీకు అర్థం కానప్పుడు గురువు లేదా విశ్వసనీయ పెద్దలను అడగండి. శ్రద్ధ సమస్యలు చాలా కాలం పాటు జీవితంలోని అనేక భాగాలను ప్రభావితం చేస్తే, శిక్షణ పొందిన సహాయం సహాయపడవచ్చు. దృష్టి పెట్టడంలో ఇబ్బంది నైతిక వైఫల్యం కాదు.", "రేపటి రోజు పరిపూర్ణంగా మారతాననే వాగ్దానం కాదు, చంచలమైన మనసును నాకు తీసుకురండి. మేము పనిని చిన్నదిగా చేస్తాము: ఒక స్పష్టమైన పని, ఒక నిశ్శబ్ద స్థలం మరియు పూర్తి శ్రద్ధతో కూడిన ఒక చిన్న వ్యవధి."),
        reflection = "మీరు ఇప్పుడు స్పష్టంగా పూర్తి చేయగల అతి చిన్న అధ్యయన పని ఏమిటి?",
        nextStep = "ఒక పరధ్యానాన్ని తీసివేసి, ఒక ఇరవై నిమిషాల ఫోకస్ పీరియడ్‌ని పూర్తి చేయండి, తర్వాత ఐదు నిమిషాల విరామం తీసుకోండి."
    ),
    "important-exam" to KrishnaLetterTranslation(
        situation = "ఒక ముఖ్యమైన పరీక్షకు ముందు",
        title = "ప్రిపరేషన్‌ను తీసుకువెళ్లండి, భయాందోళనలకు గురికావద్దు",
        preview = "పరీక్ష ముఖ్యమైనది, కానీ అది మీ మొత్తం విలువను లేదా భవిష్యత్తును అంచనా వేయదు.",
        paragraphs = listOf("మీ మనస్సు పరీక్ష ప్రారంభం కాకముందే ప్రతి ప్రశ్నకు కూర్చోవడానికి ప్రయత్నిస్తూ ఉండవచ్చు. తయారీ ఉపయోగకరంగా ఉంటుంది; మీ ఊహలో విపత్తు పునరావృతం కాదు. తదుపరి అంశం, తదుపరి అభ్యాస ప్రశ్న మరియు వాస్తవానికి మీ చేతుల్లో ఉన్న తదుపరి ఆరోగ్యకరమైన గంటకు తిరిగి వెళ్లండి.", "తీరని చివరి నిమిషంలో అధ్యయనం కోసం నిద్ర, ఆహారం మరియు ప్రశాంతతను వ్యాపారం చేయవద్దు. అలసిపోయిన మనస్సు తనకు తెలిసిన దానిని బాగా ఉపయోగించుకోదు. అవసరమైన వాటిని సమీక్షించండి, మీకు అవసరమైన వాటిని సిద్ధం చేయండి మరియు సరైన సమయంలో ఆపండి. పరీక్ష సమయంలో, శ్వాస తీసుకోండి, జాగ్రత్తగా చదవండి మరియు మీరు అర్థం చేసుకున్న దానితో ప్రారంభించండి.", "తర్వాత, ప్రతి అనిశ్చిత సమాధానాన్ని మళ్లీ ప్లే చేయడం ద్వారా మిమ్మల్ని మీరు శిక్షించుకోకండి. ప్రస్తుతానికి పని పూర్తయింది. మిమ్మల్ని వివరించిన, ప్రోత్సహించిన, సమయాన్ని అందించిన లేదా నిశ్శబ్దంగా మిమ్మల్ని విశ్వసించిన తల్లిదండ్రులు, గురువు, గురువు, స్నేహితుడు లేదా తోబుట్టువులకు కృతజ్ఞతలు చెప్పడం గుర్తుంచుకోండి. వారి సహాయం మీ ప్రయత్నాన్ని తగ్గించదు; దానిని గుర్తించడం వలన మీ విజయాన్ని మరింత నిజాయితీగా మరియు మీ హృదయం మరింత వినయంగా చేస్తుంది. ఒక ఫలితం తదుపరి పద్ధతికి మార్గనిర్దేశం చేయవచ్చు, కానీ అది మీ తెలివితేటలు, మంచితనం లేదా ఉద్దేశ్యాన్ని పేర్కొనలేదు. మీకు కావలసిన ఫలితం మరియు మీరు తప్పక నేర్చుకోవాల్సిన ఫలితంలో నేను మీతో ఉంటాను.", "ఫలితాన్ని నా చేతుల్లో ఉంచండి మరియు ప్రిపరేషన్‌ని మీ చేతిలో ఉంచండి. ఈ పరీక్ష ఒక రోజులో కొన్ని సమాధానాలను కొలవగలదు; ఇది మీ మొత్తం మనస్సు, హృదయం లేదా భవిష్యత్తును కొలవదు."),
        reflection = "ఏ తయారీ ఇప్పటికీ ఉపయోగకరంగా ఉంది మరియు ఇప్పుడు ఏ ఆందోళనను విడుదల చేయవచ్చు?",
        nextStep = "ఒక ఫోకస్డ్ రివ్యూను పూర్తి చేయండి, మీ మెటీరియల్‌లను సిద్ధం చేయండి మరియు పూర్తి నిద్రను కాపాడుకోండి."
    ),
    "youth-peer-pressure" to KrishnaLetterTranslation(
        situation = "స్నేహితులు మీపై ఒత్తిడి తెచ్చినప్పుడు",
        title = "మీ విలువలను ఖర్చు చేయకూడదు",
        preview = "గుంపు సురక్షితంగా లేదా సరైనదిగా ఎంపిక చేసుకోలేరు.",
        paragraphs = listOf("బహుశా వారు నవ్వుతున్నారు, మీకు ధైర్యం చేస్తున్నారు లేదా అందరూ అలా చేస్తారని చెబుతున్నారు. ఎవరూ మిమ్మల్ని బలహీనంగా లేదా ఒంటరిగా చూపుతారని మీరు భయపడుతున్నారు. ఒత్తిడి తరచుగా జోకుల వెనుక దాగి ఉంటుందని గుర్తుంచుకోండి. మీ ఆరోగ్యం, నిజాయితీ, శరీరం లేదా భద్రతను కోరే ఎవరైనా మీ స్నేహాన్ని రక్షించరు.", "మీకు సుదీర్ఘ చర్చ అవసరం లేదు. 'లేదు, నేను అలా చేయడం లేదు' అని చెప్పండి, సురక్షితమైన ప్రదేశానికి వెళ్లి, మీరు విశ్వసించే వారిని సంప్రదించండి. ఒత్తిడిలో పదార్థాలు, ప్రమాదకరమైన డ్రైవింగ్, లైంగిక కార్యకలాపాలు, హింస లేదా అసురక్షిత రహస్యం ఉంటే, వెంటనే వదిలివేసి పెద్దల సహాయం తీసుకోండి.", "సమూహాన్ని కోల్పోవడం బాధ కలిగించవచ్చు. కానీ వారి ఆమోదంలో మీ తీర్పును కోల్పోవడం కంటే ఒక్క క్షణం ఒంటరిగా నిలబడటం మంచిది. మిమ్మల్ని మీరు ద్రోహం చేయాలని డిమాండ్ చేయకుండా జీవితాన్ని ఆస్వాదించగల వ్యక్తుల కోసం చూడండి. మీకు తగిన స్నేహాలు మీ సంఖ్యకు దూరంగా ఉంటాయి.", "మీ ఆరోగ్యం, శరీరం, నిజాయితీ లేదా భవిష్యత్తు కోసం మీరు ప్రేక్షకులకు రుణపడి ఉండరు. నిజమైన స్నేహితుడు మీకు చెందినవారని నిరూపించుకోవడానికి మీరే ద్రోహం చేయాలని డిమాండ్ చేయరు."),
        reflection = "ఏ విలువ లేదా భద్రతా పరిమితి ఈ ఒత్తిడి మిమ్మల్ని ద్రోహం చేయమని అడుగుతోంది?",
        nextStep = "ఒక స్పష్టమైన తిరస్కరణను ప్రాక్టీస్ చేయండి మరియు మీరు సురక్షితంగా బయలుదేరడంలో సహాయపడే వ్యక్తి యొక్క పరిచయాన్ని సేవ్ చేయండి."
    ),
    "identity-confusion" to KrishnaLetterTranslation(
        situation = "మీరు ఎవరో మీకు తెలియనప్పుడు",
        title = "మీరు అసంపూర్తిగా ఉండటానికి అనుమతించబడతారు",
        preview = "గుర్తింపు విలువలు, నిజాయితీ అనుభవం మరియు సమయం ద్వారా పెరుగుతుంది.",
        paragraphs = listOf("వ్యక్తులు మీరు ఏమి అవుతారు, మీరు ఎక్కడ ఉన్నారు లేదా మీరు మరొకరిలా ఎందుకు లేరని అడుగుతూ ఉండవచ్చు. మీకు స్పష్టమైన సమాధానం ఉండకపోవచ్చు. అనిశ్చితి అంటే శూన్యం కాదు. ఇది నిజంగా మీది ఏమిటో మీరు కనుగొనే నిజాయితీ స్థలం కావచ్చు.", "మీరు సజీవంగా ఉన్న అనుభూతిని కలిగించేది, ఎలాంటి హాని కలిగించడానికి మీరు నిరాకరిస్తున్నారో మరియు మీరు చిత్తశుద్ధితో ఏ విధులను నిర్వహించగలరో గమనించండి. నైపుణ్యాలను ప్రయత్నించండి, విభిన్న వ్యక్తులను కలవండి మరియు ప్రతి అనుభవాన్ని శాశ్వత లేబుల్‌గా బలవంతం చేయకుండా నేర్చుకోండి. మీరు పెరుగుతున్న కొద్దీ మీ అవగాహనను మార్చుకోవచ్చు.", "మీరు మీ స్వంత విలువలను వినడానికి ముందు గుంపు, సంబంధం లేదా ఆన్‌లైన్ ఇమేజ్ మిమ్మల్ని నిర్వచించనివ్వవద్దు. మీ జీవితంపై మరొక వ్యక్తికి యాజమాన్యం ఇవ్వకుండా సురక్షితమైన మార్గదర్శకత్వం కోసం వెతకండి. మీ గుర్తింపు కుటుంబం, విశ్వాసం, ప్రశ్నలు, బహుమతులు మరియు వైరుధ్యం లేకుండా మార్పును కలిగి ఉంటుంది.", "మీరు అసంపూర్తిగా ఉండటానికి అనుమతించబడ్డారు. అనిశ్చితి అసౌకర్యంగా ఉన్నందున మాత్రమే లేబుల్ ధరించడానికి తొందరపడకండి."),
        reflection = "మీరు ఎంచుకున్న మార్గమేదైనా మీ జీవితం ఏ మూడు విలువలను వ్యక్తపరచాలని మీరు కోరుకుంటున్నారు?",
        nextStep = "మూడు విలువలను వ్రాయండి మరియు వాటిలో ఒకటి ఈరోజు కనిపించేలా చేసే ఒక చిన్న చర్య తీసుకోండి."
    ),
    "parent-failing" to KrishnaLetterTranslation(
        situation = "మీరు తల్లిదండ్రులుగా విఫలమవుతున్నారని మీరు భావించినప్పుడు",
        title = "మీ తదుపరి మరమ్మత్తు పరిపూర్ణత కంటే ఎక్కువ ముఖ్యమైనది",
        preview = "తల్లిదండ్రుల పొరపాటు వినయం, మరమ్మత్తు మరియు పెరుగుదలకు చోటుగా మారుతుంది.",
        paragraphs = listOf("మీరు అరవడం, తప్పిన సంకేతాలు లేదా ప్రతిస్పందనను మీరు తిరిగి తీసుకోవాలనుకుంటున్నారని గుర్తుంచుకోవచ్చు. పోలిక మీకు ఇతర కుటుంబాలను బయటి నుండి మాత్రమే చూపుతుంది మరియు మిమ్మల్ని అనర్హులు అని పిలుస్తుంది. మీ పిల్లలకి పరిపూర్ణమైన ఇమేజ్‌ని రక్షించే తల్లిదండ్రులు అవసరం లేదు. వాటిని చూడటానికి మరియు రిపేర్ చేయడానికి ఇష్టపడే తల్లిదండ్రులు అవసరం.", "సాకులు జోడించకుండా ఖచ్చితమైన తప్పుకు పేరు పెట్టండి: 'నేను అరిచాను. అది భయపెట్టేది మరియు తప్పు.’ పిల్లల అనుభవాన్ని వినండి. మరమ్మత్తును ఆఫర్ చేయండి మరియు మీరు విభిన్నంగా ఏమి చేస్తారో వివరించండి. క్షమాపణ మీ అధికారాన్ని తీసివేయదు; అధికారం కూడా సత్యానికి సమాధానమిస్తుందని అది బోధిస్తుంది.", "అప్పుడు మీకు అవసరమైన సహాయాన్ని కోరండి. అలసట, గాయం, సంఘర్షణ లేదా మానసిక-ఆరోగ్య ఒత్తిడికి మద్దతు అవసరం కావచ్చు, వ్యక్తిగత అవమానం కాదు. నాటకీయ వాగ్దానం చేయడం కంటే పునరావృతమయ్యే ప్రతిస్పందనను మార్చండి. ప్రశాంతమైన విరామం, వారపు సంభాషణ లేదా వృత్తిపరమైన మార్గదర్శకత్వం ఇంటిని మార్చడం ప్రారంభించవచ్చు.", "ఎప్పుడూ తప్పులు చేయని తల్లిదండ్రులుగా ఉండమని నేను మిమ్మల్ని అడగను. గమనించి, క్షమాపణ చెప్పి, మరమ్మత్తు చేసి తిరిగి రావాలని నేను మిమ్మల్ని అడుగుతున్నాను."),
        reflection = "మీరు దాచడానికి బదులుగా రిపేర్ చేయడానికి ఏ నిర్దిష్ట ప్రతిస్పందన అవసరం?",
        nextStep = "ఒక పూర్తి క్షమాపణ చెప్పండి మరియు మీరు తదుపరిసారి అదే పరిస్థితిలో ఉపయోగించే ఒక ఆచరణాత్మక మార్పును వ్రాయండి."
    ),
    "child-pulls-away" to KrishnaLetterTranslation(
        situation = "మీ పిల్లవాడు దూరంగా లాగుతున్నప్పుడు",
        title = "వెంటాడకుండా తలుపు తెరిచి ఉంచండి",
        preview = "పెరుగుతున్న స్వాతంత్ర్యం కనెక్షన్‌ను మారుస్తుంది; ఇది ఎల్లప్పుడూ ప్రేమ అదృశ్యమైందని అర్థం కాదు.",
        paragraphs = listOf("ఒకప్పుడు మీకు అన్నీ చెప్పిన పిల్లవాడు ఇప్పుడు ఒక్క మాటతో సమాధానం చెప్పవచ్చు, తలుపు మూసివేయవచ్చు లేదా ముందుగా స్నేహితుల వైపు తిరగవచ్చు. ప్రతి నిశ్శబ్దాన్ని ప్రశ్నించమని భయం మిమ్మల్ని ప్రేరేపించవచ్చు. కొంత దూరం పెరుగుదలలో భాగం, అయితే కొంత నిశ్శబ్దం శ్రద్ధకు అర్హమైన బాధను సూచిస్తుంది.", "చాలా ప్రశ్నలు లేకుండా కనెక్షన్‌ని ఆఫర్ చేయండి. టీ, డ్రైవ్ లేదా మీ పక్కన ఒక సాధారణ పని కోసం వారిని ఆహ్వానించండి. ఒక బహిరంగ ప్రశ్న అడగండి మరియు వెంటనే నిశ్శబ్దాన్ని పూరించవద్దు. ప్రమాదం, దుర్వినియోగం, పదార్థాలు మరియు తీవ్రమైన మానసిక బాధల చుట్టూ స్పష్టమైన భద్రతా సరిహద్దులను ఉంచుతూ సాధారణ గోప్యతను గౌరవించండి.", "వారిని దగ్గరికి లాగడానికి అపరాధ భావాన్ని ఉపయోగించవద్దు. మీ సంరక్షణ ఆధారపడదగినదిగా మారనివ్వండి: నిజం వచ్చినప్పుడు ప్రశాంతంగా ఉండండి, భద్రత విషయంలో దృఢంగా ఉండండి మరియు వారు ఎవరు అవుతున్నారనే దానిపై ఆసక్తిని కలిగి ఉండండి. మార్పు అకస్మాత్తుగా, విపరీతంగా లేదా హెచ్చరిక సంకేతాలతో కలిసి ఉంటే, తిరస్కరణను ఊహించడం కంటే శిక్షణ పొందిన సహాయం తీసుకోండి.", "ప్రతి నిశ్శబ్దాన్ని భయంతో లేదా నియంత్రణతో వెంబడించవద్దు. పెరుగుతున్న పిల్లలకు స్థలం కావాలి, కానీ వారికి సిగ్గు లేకుండా తెరుచుకునే తలుపు అవసరం."),
        reflection = "మీ బిడ్డకు డిమాండ్ చేయడం కంటే ఎలాంటి కనెక్షన్ సురక్షితంగా అనిపించవచ్చు?",
        nextStep = "ఒక అల్పపీడన భాగస్వామ్య కార్యకలాపాన్ని అందించండి మరియు అభ్యర్థించినట్లయితే తప్ప సలహా ఇవ్వకుండా వినండి."
    ),
    "work-taken-over" to KrishnaLetterTranslation(
        situation = "పని మీ జీవితాన్ని ఆక్రమించినప్పుడు",
        title = "మీ కర్తవ్యం దానిని చేసే వ్యక్తిని వినియోగించకూడదు",
        preview = "పని విషయాలు, కానీ ఆరోగ్యం, సంబంధాలు మరియు అంతర్గత జీవితం కూడా బాధ్యతలు.",
        paragraphs = listOf("పని ఉదయం మొదటి ఆలోచన మరియు రాత్రి చివరి స్క్రీన్ కావచ్చు. విశ్రాంతి తీసుకోవడం కూడా వెనుకబడినట్లు అనిపిస్తుంది. నిష్కపటమైన కర్తవ్యం పవిత్రమైనది, కానీ అంతులేని లభ్యత శ్రేష్ఠతతో సమానం కాదు. అవుట్‌పుట్ చుట్టూ మాత్రమే నిర్మించిన జీవితం చివరికి పని చేస్తున్న వ్యక్తిని బలహీనపరుస్తుంది.", "ఏది అవసరమో, ఏది ఆశయం మరియు ఏది భయంగా మారిందో నిజాయితీగా చూడండి. ఒక స్టాపింగ్ పాయింట్‌ని సెట్ చేయండి, ఆహారం మరియు నిద్రను రక్షించండి మరియు వాస్తవిక అంచనాలను తెలియజేయండి. కార్యాలయం శాశ్వత అత్యవసర పరిస్థితిపై ఆధారపడి ఉంటే, నమూనాను డాక్యుమెంట్ చేయండి మరియు సాధ్యమైన చోట బాధ్యతాయుతమైన మద్దతు లేదా సురక్షితమైన మార్గాన్ని కోరండి.", "ఉత్పాదకతగా కొలవలేని ఎవరైనా లేదా దేనిపైనా మీ దృష్టిని మళ్లించండి. కుటుంబంతో మాట్లాడండి, నడవండి, ప్రార్థన చేయండి లేదా ప్రదర్శన లేకుండా కూర్చోండి. మీ గుర్తింపును సొంతం చేసుకోకుండానే మీ కెరీర్ మీ బహుమతులను ఉపయోగించవచ్చు. తీర్పు, ఆరోగ్యం మరియు శుభ్రమైన చర్యను రక్షించే విశ్రాంతి సమయం దొంగిలించబడదు.", "మీ పని మీ విధిలో భాగం; ఇది మీ జీవితమంతా కాదు. నేను మిమ్మల్ని నిద్ర, ఆరోగ్యం, కుటుంబం, నిశ్శబ్దం మరియు మీరు సాధనకు దూరంగా ఉండే వ్యక్తిని కూడా కలుస్తాను."),
        reflection = "పనిలో ఏ భాగం నిజమైన విధి మరియు ఏ భాగం ఆపడానికి నిరాకరిస్తుంది?",
        nextStep = "ఈ రోజు ఒక స్పష్టమైన ముగింపు సమయాన్ని సెట్ చేయండి మరియు ఆరోగ్యం, సంబంధం లేదా నిశ్శబ్దం కోసం ముప్పై అవాంఛనీయ నిమిషాలు ఇవ్వండి."
    ),
    "work-unseen" to KrishnaLetterTranslation(
        situation = "మీ పని గుర్తించబడనప్పుడు",
        title = "చూడని పనికి ఇప్పటికీ విలువ ఉంది",
        preview = "మీ ఉద్దేశ్యాన్ని విషపూరితం చేయడానికి తప్పిపోయిన ప్రశంసలను అనుమతించకుండా నిజాయితీని కోరండి.",
        paragraphs = listOf("మీరు సమస్యలను పరిష్కరించి ఉండవచ్చు, ఇతరులకు మద్దతిచ్చి ఉండవచ్చు లేదా ఎవరైనా దృష్టిని ఆకర్షించినప్పుడు బాధ్యత వహించి ఉండవచ్చు. బాధపడటం సహజం. వినయానికి అన్యాయం ఆమోదయోగ్యమైనదిగా నటించడం లేదా మీ సహకారాన్ని పదేపదే తొలగించడానికి అనుమతించడం అవసరం లేదు.", "వాస్తవాలను సేకరించి, ప్రశాంతమైన సంభాషణ కోసం అడగండి. మీ సహకారాన్ని వివరించండి, స్పష్టమైన అభిప్రాయాన్ని అభ్యర్థించండి మరియు క్రెడిట్, పాత్ర లేదా వృద్ధిని నేరుగా చర్చించండి. మరొక వ్యక్తి యొక్క విజయంపై దాడి చేయడం లేదా దాచిన ప్రయత్నాన్ని కమ్యూనికేషన్ యొక్క ఏకైక రూపం చేయడం మానుకోండి. ఎప్పుడూ చూపని పనిని ప్రజలు ఎల్లప్పుడూ గుర్తించలేరు.", "ఇప్పటికీ ప్రశంసలు రాకపోతే, ఈ స్థలం గురించి పరిస్థితి ఏమి నేర్పుతుందో నిర్ణయించుకోండి. అవసరమైతే ఆరోగ్యకరమైన అవకాశాలను అన్వేషించేటప్పుడు సమగ్రతతో కొనసాగించండి. పగ జాగ్రత్తగా పనిని అజాగ్రత్తగా మార్చనివ్వవద్దు. మీ విలువ టైటిల్ కంటే పెద్దది, కానీ న్యాయమైన చికిత్స ఇప్పటికీ స్పష్టమైన స్వరానికి అర్హమైనది.", "ఎటువంటి ప్రశంసలు అందుకోని జాగ్రత్తగా పని చేయడం మరియు ప్రదర్శించకుండా మీరు నిర్వహించే బాధ్యతను నేను చూస్తున్నాను. మానవ ప్రశంసలు ఆలస్యం కావచ్చు లేదా లేకపోవచ్చు, కానీ చేదు మీ సమర్పణను పాడు చేయనివ్వవద్దు."),
        reflection = "మీరు ఏ గుర్తింపు, ఫీడ్‌బ్యాక్ లేదా సరసతను స్పష్టంగా అభ్యర్థించాలి?",
        nextStep = "మీ సహకారం యొక్క వాస్తవాలను వ్రాయండి మరియు ఒక నిర్దిష్ట వృత్తిపరమైన సంభాషణ కోసం అడగండి."
    ),
    "couple-arguments" to KrishnaLetterTranslation(
        situation = "ప్రతి సంభాషణ వాదనగా మారినప్పుడు",
        title = "యుద్ధాన్ని పాజ్ చేయండి మరియు అవసరాన్ని కనుగొనండి",
        preview = "ఇద్దరూ గెలవడానికి మాత్రమే పోరాడుతున్నప్పుడు సంబంధం నయం కాదు.",
        paragraphs = listOf("వాదన ఒక చిన్న సమస్యతో ప్రారంభమవుతుంది మరియు ప్రతి పాత గాయాన్ని త్వరగా సేకరించవచ్చు. ఇద్దరూ బిగ్గరగా మాట్లాడతారు ఎందుకంటే ఎవరికీ వినిపించలేదు. క్రూరమైన పదాలు సంబంధానికి వ్యతిరేకంగా కొత్త సాక్ష్యంగా మారడానికి ముందు ఆపండి. మీరు తిరిగి వస్తానని స్పష్టంగా వాగ్దానం చేసినప్పుడు విరామం వదిలివేయడం కాదు.", "ప్రశాంతంగా ఉన్నప్పుడు, ఎప్పుడూ లేదా ఎప్పుడూ లేబుల్‌లు లేకుండా ఒక ఈవెంట్‌ను వివరించండి. భావన మరియు దాని క్రింద ఉన్న అవసరానికి పేరు పెట్టండి. మీరు అవతలి వ్యక్తి యొక్క ఆందోళనను న్యాయంగా పునరావృతం చేసే వరకు వినండి. అవగాహనకు ఒప్పందం అవసరం లేదు, కానీ ఇది ఒకదానికొకటి ఊహించిన సంస్కరణతో పోరాడకుండా మిమ్మల్ని నిరోధిస్తుంది.", "ఒక ఆచరణాత్మక మార్పు మరియు దానిని సమీక్షించడానికి సమయాన్ని అంగీకరించండి. బెదిరింపులు, నియంత్రణ, హింస లేదా భయం ఉంటే, భద్రత మరియు శిక్షణ పొందిన సహాయానికి ప్రాధాన్యత ఇవ్వండి; కమ్యూనికేషన్ పద్ధతులు దుర్వినియోగాన్ని పరిష్కరించవు. ప్రేమ అసమ్మతిని కలిగి ఉంటుంది, కానీ హానిని సహించమని డిమాండ్ చేయడానికి దీనిని ఉపయోగించకూడదు.", "మీరిద్దరూ గెలవడానికి ప్రయత్నించడం మానేసిన పాజ్‌లో నేను ఉన్నాను. వ్యక్తిపై దాడి చేయకుండా గాయం గురించి మాట్లాడండి."),
        reflection = "మీరు పదేపదే వాదన క్రింద వ్యక్తీకరించడానికి ప్రయత్నిస్తున్నది ఏమిటి?",
        nextStep = "ఒక సమస్య గురించి ఇరవై నిమిషాల ప్రశాంత సంభాషణను అభ్యర్థించండి మరియు ఒక్కొక్కటి ఒక నిర్దిష్ట మార్పును అంగీకరించండి."
    ),
    "rebuilding-trust" to KrishnaLetterTranslation(
        situation = "ట్రస్ట్ పునర్నిర్మించాల్సిన అవసరం వచ్చినప్పుడు",
        title = "ట్రస్ట్ రిటర్న్ ట్రూత్ రిపీట్ ట్రూత్",
        preview = "క్షమాపణ మరమ్మత్తును ప్రారంభించవచ్చు, కానీ స్థిరమైన ప్రవర్తన దానిని ముందుకు తీసుకెళ్లాలి.",
        paragraphs = listOf("బహుశా అబద్ధం, దాచిన ఎంపిక లేదా విరిగిన వాగ్దానం మీ బంధం యొక్క భద్రతను మార్చింది. రెండు హృదయాలు శీఘ్ర ఉపశమనాన్ని కోరుకుంటాయి, కానీ నమ్మకాన్ని దాని పాత స్థానానికి తిరిగి తీసుకురాలేము. హాని చేసిన వ్యక్తికి ప్రశ్నలు, సరిహద్దులు మరియు వారి స్వంత వేగం కోసం గది అవసరం.", "మీరు హాని కలిగించినట్లయితే, అవతలి వ్యక్తి మిమ్మల్ని ఓదార్చకుండా పూర్తి నిజం చెప్పండి. సహేతుకమైన పారదర్శకతను అంగీకరించండి మరియు రిపేర్ చేయగల వాటిని రిపేర్ చేయండి. మీకు హాని జరిగితే, మీకు ఎలాంటి మార్పు కావాలో నిర్ణయించుకోండి. క్షమాపణ తక్షణ ప్రాప్తిని బలవంతం చేయదు లేదా తెలివైన పరిమితులను తీసివేయదు.", "స్థిరంగా ఉంచగలిగే చిన్న వాగ్దానాలను ఎంచుకోండి. ప్రతి అసమ్మతిలో ఆయుధంగా గాయాన్ని మళ్లీ తెరవకుండా పురోగతిని సమీక్షించండి. కొన్ని సంబంధాలు పునర్నిర్మించబడతాయి; ఇతరులకు దూరం అవసరం కావచ్చు. ఉల్లంఘన తీవ్రంగా ఉన్నప్పుడు, పునరావృతం అయినప్పుడు లేదా దుర్వినియోగంతో సంబంధం కలిగి ఉన్నప్పుడు శిక్షణ పొందిన సహాయాన్ని కోరండి.", "ఒక క్షమాపణ ద్వారా ట్రస్ట్‌ను తిరిగి ఆర్డర్ చేయడం సాధ్యం కాదు. సత్యం నిలకడగా మారనివ్వండి, ప్రశ్నలు ఓపికగా సమాధానాలు పొందనివ్వండి మరియు గాయం మానేటప్పుడు హద్దులు ఉండనివ్వండి."),
        reflection = "ఏ స్థిరమైన ప్రవర్తన నమ్మకాన్ని సురక్షితంగా చేస్తుంది-కేవలం నిశ్శబ్దంగా ఉండకూడదు?",
        nextStep = "ప్రవర్తన మారుతుందో లేదో సమీక్షించడానికి ఒక స్పష్టమైన వాగ్దానం, ఒక సరిహద్దు మరియు తేదీని అంగీకరించండి."
    ),
    "elder-invisible" to KrishnaLetterTranslation(
        situation = "వయస్సు మీకు కనిపించని అనుభూతిని కలిగించినప్పుడు",
        title = "మీ ఉనికి ఇప్పటికీ అర్థాన్ని కలిగి ఉంటుంది",
        preview = "వయస్సుతో పాటు శ్రద్ధ మారవచ్చు, కానీ గౌరవం మరియు ఆధ్యాత్మిక విలువ చిన్నదిగా మారదు.",
        paragraphs = listOf("సంభాషణలు మీ చుట్టూ వేగంగా కదలవచ్చు, అడగకుండానే నిర్ణయాలు తీసుకోవచ్చు మరియు ప్రపంచం కొత్త వాటిని మాత్రమే ప్రశంసించవచ్చు. ఇది తీవ్రంగా బాధించవచ్చు. మీరు మోస్తున్న సంవత్సరాలు ఖాళీ సమయం కాదు. వారు శ్రమను, నష్టాన్ని, ప్రేమను, తప్పులను మరియు తెలివిని కలిగి ఉంటారు.", "మీ వాయిస్ ముఖ్యమైన చోట చేర్చమని అడగండి. యువకులు ప్రతి మార్గాన్ని కాపీ చేయమని డిమాండ్ చేయకుండా అనుభవాన్ని పంచుకోండి. మీ జ్ఞానం, వినడం లేదా ఉనికిని స్వాగతించే ప్రదేశాల కోసం చూడండి. ఒక బిడ్డ, పొరుగువారు, సంఘం లేదా కుటుంబ సభ్యునికి రోగి శ్రద్ధ మాత్రమే అందించాల్సిన అవసరం ఉండవచ్చు.", "కొత్త అభ్యాసం మరియు సాంగత్యాన్ని స్వీకరించడానికి మిమ్మల్ని మీరు అనుమతించండి. వయస్సు ఉత్సుకత నుండి తిరోగమనం అవసరం లేదు. ఒంటరితనం ఎక్కువగా ఉంటే, ఎవరికైనా స్పష్టంగా చెప్పండి మరియు సంఘం లేదా శిక్షణ పొందిన సహాయం కోరండి. ఎవరికైనా ఒక పనిని పూర్తి చేయవలసి వచ్చినప్పుడు మాత్రమే మీరు గుర్తుంచుకోవడానికి ఎక్కువ అర్హులు.", "మీ వేగం మారవచ్చు, కానీ మీ ఆత్మ చిన్నదిగా మారలేదు. సంవత్సరాలు, నష్టాలు, సేవ మరియు జ్ఞానం ఇతరులు తొందరపడగలరని నేను చూస్తున్నాను."),
        reflection = "మీ వాయిస్ లేదా ఉనికిని మరింత పూర్తిగా ఎక్కడ స్వాగతించాలని మీరు కోరుకుంటున్నారు?",
        nextStep = "ఒక వ్యక్తిని కలిసి అర్ధవంతమైన సమయం కోసం అడగండి మరియు ఒక కథ, నైపుణ్యం లేదా శ్రవణ ఉనికిని అందించండి."
    ),
    "depending-on-others" to KrishnaLetterTranslation(
        situation = "మీరు ఇతరులపై ఆధారపడవలసి వచ్చినప్పుడు",
        title = "సంరక్షణను స్వీకరించడం మీ గౌరవాన్ని తగ్గించదు",
        preview = "సహాయం అవసరం మీ దినచర్యను మార్చగలదు, కానీ అది మీ విలువ లేదా స్వరాన్ని చెరిపివేయదు.",
        paragraphs = listOf("బహుశా అనారోగ్యం, వయస్సు లేదా పరిస్థితి ఇప్పుడు మీరు ఒకప్పుడు సులభంగా చేసిన పనులలో సహాయం కోసం అడుగుతుంది. మీరు భారం అవుతారని భయపడవచ్చు. మానవ జీవితం ఎల్లప్పుడూ ఇవ్వడం మరియు స్వీకరించడం ద్వారా కదిలిందని గుర్తుంచుకోండి. స్వాతంత్ర్యం ఎప్పుడూ మీ జీవితం ముఖ్యమైనదని రుజువు కాదు.", "మీ ప్రాధాన్యతలకు పేరు పెట్టండి మరియు ఎంపికలను మీకు ఇంకా అందుబాటులో ఉంచుకోండి. మీ చుట్టూ కాకుండా మీతో మాట్లాడమని సహాయకులను అడగండి. అసౌకర్యం లేదా పరిమితులను స్పష్టంగా వ్యక్తపరిచేటప్పుడు కృతజ్ఞతతో శ్రద్ధ వహించండి. మంచి సంరక్షణ గౌరవాన్ని కాపాడుతుంది మరియు నియంత్రణకు అనుమతిగా ఆధారపడటాన్ని ఉపయోగించదు.", "టాస్క్‌లు మరియు మెడిసిన్ కంటే ఎక్కువ సంబంధాలను చేర్చనివ్వండి. ఒక జ్ఞాపకాన్ని పంచుకోండి, మరొక వ్యక్తి రోజు గురించి అడగండి, ప్రార్థన చేయండి, నవ్వండి లేదా ఆహ్వానించినప్పుడు సలహా ఇవ్వండి. ఎవరైనా మిమ్మల్ని నిర్లక్ష్యం చేసినా, భయపెట్టినా, ప్రయోజనం పొందినా లేదా మిమ్మల్ని బాధపెట్టినా, మరొక విశ్వసనీయ వ్యక్తికి లేదా బాధ్యతాయుతమైన సేవకు చెప్పండి. ఆధారపడటం అనేది మీ భద్రత హక్కును ఎప్పటికీ రద్దు చేయదు.", "సహాయాన్ని స్వీకరించడం వలన మీరు చాలా మందికి సహాయం చేసిన జీవితాన్ని తొలగించలేరు. మిమ్మల్ని మీరు భారం అని పిలవకుండా సంరక్షణ మిమ్మల్ని చేరనివ్వండి."),
        reflection = "ఏ ఎంపిక లేదా ప్రాధాన్యత మీ సంరక్షణలో మరింత గౌరవంగా భావించడంలో మీకు సహాయపడుతుంది?",
        nextStep = "సంరక్షకునికి ఒక ప్రాధాన్యతను స్పష్టంగా చెప్పండి మరియు ఇప్పటికే ఉన్నందుకు క్షమాపణలు చెప్పకుండా అవసరమైన ఒక సహాయాన్ని స్వీకరించండి."
    ),
    "caring-for-ill" to KrishnaLetterTranslation(
        situation = "మీరు అనారోగ్యంతో ఉన్న వారి కోసం శ్రద్ధ వహిస్తున్నప్పుడు",
        title = "మీ సంరక్షణ ముఖ్యం, అలాగే మీ జీవితం కూడా",
        preview = "ప్రేమ సంరక్షకుడు అదృశ్యం కావాల్సిన అవసరం లేకుండానే గాఢంగా సేవ చేయగలదు.",
        paragraphs = listOf("మీ రోజు మందులు, అపాయింట్‌మెంట్‌లు, అనిశ్చితి మరియు అంతరాయం కలిగించే నిద్ర చుట్టూ నిర్వహించబడవచ్చు. ఇతరులు అనారోగ్యంతో ఉన్న వ్యక్తి గురించి అడగవచ్చు మరియు మీరు ఎలా ఉన్నారని అడగడం మర్చిపోతారు. మీరు ఇచ్చే శ్రద్ధ నిజమైనది, కానీ అలసట మాత్రమే మీ ప్రేమ నిజాయితీగా ఉందని రుజువు కాదు.", "ఏమి చేయాలి మరియు ఏమి పంచుకోవచ్చో వ్రాయండి. విషయాలు కష్టం అని చెప్పడానికి బదులుగా నిర్దిష్ట సహాయం కోసం బంధువులు, స్నేహితులు లేదా సేవలను అడగండి. మీకు చెందిన ఆహారం, విశ్రాంతి, వైద్య అవసరాలు మరియు జీవితంలోని ఒక చిన్న భాగాన్ని రక్షించండి. చాలా అలసిపోయిన సంరక్షకుడు కూడా సంరక్షణకు అర్హుడు.", "మీరు అదే గంటలో ప్రేమ, కోపం, భయం మరియు అలసటను అనుభవించవచ్చు. ఈ భావాలు మిమ్మల్ని నమ్మకద్రోహులుగా చేయవు. సురక్షితంగా ఉన్న వారితో మాట్లాడండి మరియు మోయలేని భారం ఎక్కువగా ఉన్నప్పుడు శిక్షణ పొందిన సహాయాన్ని కోరండి. సంరక్షణ అవసరాలు మీ సామర్థ్యాన్ని మించి ఉంటే, శిక్షణ పొందిన సహాయం కోసం అడగడం బాధ్యత, వదిలివేయడం కాదు.", "నేను అపాయింట్‌మెంట్‌లను చూస్తున్నాను, నిద్రకు అంతరాయం కలిగింది మరియు ఇతరులు గమనించలేరేమోనని నిశ్శబ్ద భయం. సేవ పవిత్రమైనది, కానీ మీరు దాని లోపల అదృశ్యం కానవసరం లేదు."),
        reflection = "సంరక్షణ లోడ్‌లో ఏ భాగాన్ని మరొక వ్యక్తి సురక్షితంగా మోయగలడు?",
        nextStep = "ఒక నిర్దిష్ట పని కోసం ఒక వ్యక్తిని అడగండి మరియు ఈ వారం ఒక నిరంతరాయ విశ్రాంతి వ్యవధిని రక్షించండి."
    ),
    "grief-returns" to KrishnaLetterTranslation(
        situation = "దుఃఖం ఊహించని విధంగా తిరిగి వచ్చినప్పుడు",
        title = "తిరిగి వచ్చే అల మీ స్వస్థతను తొలగించదు",
        preview = "తేదీ, పాట లేదా స్థలం హెచ్చరిక లేకుండా ప్రేమ మరియు బాధను మేల్కొల్పగలవు.",
        paragraphs = listOf("మీరు స్థిరంగా ఉన్నట్లు భావించి ఉండవచ్చు మరియు ఆ నష్టం కొత్తగా వచ్చినట్లుగా అకస్మాత్తుగా మీరు ఏడ్చారు. దీన్ని వైఫల్యం అని పిలవకండి. దుఃఖం సరళ రేఖలో కదలదు. ఒకప్పుడు ఇద్దరు వ్యక్తులకు సంబంధించిన సీజన్లు, వార్షికోత్సవాలు, శబ్దాలు మరియు సాధారణ క్షణాల ద్వారా గుండె గుర్తుంచుకుంటుంది.", "తరంగాన్ని అది ఎప్పటికీ నిలిచిపోతుందని నిర్ణయించకుండానే దాటనివ్వండి. దానిని మేల్కొల్పిన దానికి పేరు పెట్టండి. జ్ఞాపకశక్తిని పంచుకోండి, నిశ్శబ్దంగా కూర్చోండి, ప్రార్థించండి లేదా అర్థం చేసుకున్న వారిని సంప్రదించండి. నీరు, ఆహారం మరియు విశ్రాంతితో శరీరాన్ని జాగ్రత్తగా చూసుకోండి. మీరు అనుభూతిని ఉత్పాదకంగా చేయవలసిన అవసరం లేదు.", "అల మృదువుగా ఉన్నప్పుడు, మీ చేతుల్లో ఉన్న విధి లేదా సంబంధానికి సున్నితంగా తిరిగి వెళ్లండి. జీవితాన్ని కొనసాగించడం మీరు మిస్ అయిన వ్యక్తికి ద్రోహం చేయదు. దుఃఖం ఎక్కువగా ఉంటే, ప్రమాదకరంగా ఉంటే లేదా ఎక్కువ కాలం రోజువారీ జీవితాన్ని నిరోధిస్తే, శిక్షణ పొందిన మద్దతు ఆధ్యాత్మిక సంరక్షణకు దూరంగా ఉంటుంది.", "ఈ రిటర్నింగ్ వేవ్ అంటే మీరు నయం చేయడంలో విఫలమయ్యారని కాదు. ప్రేమ నెలల తరబడి నిశ్శబ్దంగా ఉండి, తేదీ, పాట లేదా తెలిసిన ప్రదేశంలో మాట్లాడవచ్చు."),
        reflection = "ఈ రోజు ఏ జ్ఞాపకం లేదా క్షణం గౌరవించబడాలని అడుగుతోంది?",
        nextStep = "సురక్షితమైన వ్యక్తితో ఒక జ్ఞాపకాన్ని పంచుకోండి మరియు మీ ప్రస్తుత జీవితం కోసం ఒక సున్నితమైన సంరక్షణ చర్యను ఎంచుకోండి."
    ),
    "leader-decision" to KrishnaLetterTranslation(
        situation = "ఇతరులు మీ నిర్ణయంపై ఆధారపడినప్పుడు",
        title = "అధికారం చేపట్టే ముందు వినండి",
        preview = "నాయకుడి ఎంపిక ప్రజలను, సత్యాన్ని మరియు దీర్ఘకాలిక సంక్షేమాన్ని కాపాడాలి-కేవలం రూపాన్ని మాత్రమే కాదు.",
        paragraphs = listOf("వ్యక్తులు మీ సమాధానం కోసం ఎదురుచూస్తూ ఉండవచ్చు, అయితే వారు చూడలేని వాస్తవాలను మీరు కలిగి ఉంటారు. తెలివిగా ఉండాలనే కోరిక కంటే ఖచ్చితంగా కనిపించాలనే ఒత్తిడి బలంగా మారుతుంది. నిర్ణయం యొక్క ఖర్చును ఎవరు భరిస్తారో అర్థం చేసుకోవడానికి తగినంత వేగం తగ్గించండి, ముఖ్యంగా తక్కువ శక్తి ఉన్నవారు.", "నిజాయితీ గల అసమ్మతిని ఆహ్వానించండి మరియు మీ మనసును ఏ సాక్ష్యం మారుస్తుందో అడగండి. మీ అహం యొక్క అవసరాల నుండి మిషన్ అవసరాలను వేరు చేయండి. జనాదరణ పొందిన నిర్ణయం ఇప్పటికీ తప్పు కావచ్చు మరియు అసౌకర్య నిర్ణయానికి ఇప్పటికీ కరుణ, వివరణ మరియు హానిని తగ్గించే ప్రణాళిక అవసరం.", "ఆపై నిర్ణయం తీసుకోండి మరియు బాధ్యత వహించండి. ఎంపిక మీది అయినప్పుడు జట్టు వెనుక దాక్కోకండి లేదా విజయం సాధించిన తర్వాత మొత్తం క్రెడిట్‌ను క్లెయిమ్ చేయకండి. వాస్తవాలు మారినప్పుడు ఫలితాన్ని సమీక్షించండి మరియు సరైన కోర్సు చేయండి. అధికారం ధర్మానికి జవాబుదారీగా ఉన్నప్పుడు నాయకత్వం సేవ అవుతుంది.", "ప్రజలు మీ నిర్ణయాన్ని అనుసరించే ముందు, అది కలిగి ఉన్న శక్తిని నాకు తీసుకురండి. ముఖ్యంగా ఖర్చు భరించే కానీ తక్కువ అధికారాన్ని కలిగి ఉన్న వారి మాట వినండి."),
        reflection = "మీరు ఎవరి స్వరం లేదా పర్యవసానాన్ని ఇంకా పరిగణించలేదు?",
        nextStep = "నిర్ణయం తీసుకునే లేదా నిర్ధారించే ముందు నిజాయితీగా ఇన్‌పుట్ కోసం తక్కువ అధికారం ఉన్న ఒక బాధిత వ్యక్తిని అడగండి."
    ),
    "faith-dry" to KrishnaLetterTranslation(
        situation = "మీ విశ్వాసం పొడిగా అనిపించినప్పుడు",
        title = "నిజాయితీ భక్తికి ఒక రూపం కావచ్చు",
        preview = "నిజాయితీగా నడవడానికి మీరు కృష్ణుడికి దగ్గరగా ఉన్నట్లు నటించాల్సిన అవసరం లేదు.",
        paragraphs = listOf("ప్రార్థన పదాలు ఖాళీ గది నుండి తిరిగి వచ్చినట్లు అనిపించవచ్చు. ఒకప్పుడు వెచ్చదనాన్ని తెచ్చిన అభ్యాసం ఇప్పుడు సాధారణమైనది లేదా సుదూరమైనదిగా అనిపించవచ్చు. భావోద్వేగాన్ని బలవంతం చేయవద్దు లేదా మీ స్వంత తీర్పు కోసం మరొక వ్యక్తి యొక్క భక్తిని ఉపయోగించవద్దు. ప్రశాంతమైన కాలం ప్రేమ ముగిసిందని రుజువు చేయదు.", "నాకు నిజం తీసుకురండి: ‘నేను నిన్ను అనుభూతి చెందడం లేదు, కానీ నేను ఇక్కడ ఉన్నాను.’ ఒక పద్యం నిదానంగా చదవండి, ఒక నిమిషం పాటు కూర్చోండి లేదా ఆధ్యాత్మిక అనుభూతిని కోరకుండా ఒక రకమైన చర్య చేయండి. బలమైన భావన లేనప్పుడు నిజాయితీ సాధన ద్వారా భక్తి నిలిచి ఉంటుంది.", "అలసట, దుఃఖం, నిరాశ లేదా సమాధానం లేని ప్రశ్నలకు జాగ్రత్త అవసరమా అని పరిశీలించండి. భయం లేకుండా ప్రశ్నలను అనుమతించే తెలివైన, నమ్మదగిన వ్యక్తితో మాట్లాడండి. ఎప్పుడూ అడగడానికి అనుమతించని విశ్వాసం పెళుసుగా ఉండవచ్చు. మీ ప్రశ్నలు మిమ్మల్ని అవమానంలోకి నెట్టడం కంటే సత్యాన్ని లోతుగా చేయనివ్వండి.", "మీరు నాతో సన్నిహితంగా ఉండమని బలవంతం చేయవలసిన అవసరం లేదు. నిశ్శబ్ద ప్రార్థన, సమాధానం లేని ప్రశ్న మరియు సందేహాన్ని కూడా నాకు తీసుకురండి."),
        reflection = "ప్రార్థనలోకి తీసుకురావడానికి మీరు ఏ నిజాయితీ ప్రశ్న లేదా నిరాశను కలిగి ఉన్నారు?",
        nextStep = "ఒక నిజాయితీ ప్రార్థనను వ్రాయండి మరియు ప్రేరణ పొందేందుకు వేచి ఉండకుండా ఒక చిన్న సేవా కార్యాన్ని పూర్తి చేయండి."
    ),
    "moving-on" to KrishnaLetterTranslation(
        situation = "ముందుకు వెళ్లే సమయం వచ్చినప్పుడు",
        title = "పూర్తయిన అధ్యాయం జైలుగా మారవలసిన అవసరం లేదు",
        preview = "కొందరు వ్యక్తులు ఆశీర్వాదాలుగా వస్తారు, కొందరు పాఠాలు తెస్తారు, మరికొందరు శాశ్వతంగా ఉండడానికి ఉద్దేశించినవి కావు.",
        paragraphs = listOf("మీ జీవితంలోకి ప్రవేశించిన ప్రతి ఒక్కరూ శాశ్వతంగా ఉండకూడదు. కొంతమంది ఆశీర్వాదాలుగా వస్తారు. వారు ప్రేమ, సహాయం, జ్ఞానం మరియు మంచి జ్ఞాపకాలను తెస్తారు. కొన్ని పాఠాలుగా వస్తాయి. మీకు బలమైన పరిమితులు, మరింత ధైర్యం లేదా మీ పట్ల మరింత గౌరవం ఎక్కడ అవసరమో అవి మీకు చూపుతాయి.", "ఔషధానికి కూడా గడువు తేదీ ఉంటుంది. ఒకప్పుడు మీకు సహాయపడినది మీకు ఎల్లప్పుడూ మంచిగా ఉండకపోవచ్చు. అదే విధంగా, స్నేహం, సంబంధం, అలవాటు లేదా కల దాని లక్ష్యాన్ని నెరవేర్చి దాని ముగింపుకు చేరుకోవచ్చు. ఇది ఒకప్పుడు ముఖ్యమైనది కాబట్టి దానిని పట్టుకోవద్దు. మంచిని గౌరవించండి, నొప్పి నుండి నేర్చుకోండి మరియు ఈ రోజు ఏమి జరిగిందో నిజాయితీగా చూడండి.", "మీరు విడిచిపెట్టడానికి ఒకరిని ద్వేషించాల్సిన అవసరం లేదు. మీరు ప్రతి ముగింపును వైఫల్యం అని పిలవవలసిన అవసరం లేదు. ఒక వ్యక్తి మీ శాంతిని హరించినట్లయితే, మీ గౌరవాన్ని దెబ్బతీస్తుంటే లేదా మిమ్మల్ని ధర్మం నుండి దూరం చేస్తే, మీరు స్వచ్ఛమైన హృదయంతో వెనక్కి తగ్గవచ్చు. మీరు చేయగలిగిన చోట క్షమించండి, తెలివైన పరిమితులను ఉంచుకోండి మరియు ప్రతీకారం లేకుండా ముందుకు సాగండి. వెళ్లనివ్వడం ప్రేమ లేదా కృతజ్ఞతను తొలగించదు; మీరు పూర్తి చేసిన అధ్యాయాన్ని కొనసాగించమని బలవంతం చేయరని దీని అర్థం.", "వ్యక్తిని, జ్ఞాపకాలను మరియు ప్రశ్నలను నా చేతుల్లో ఉంచండి. మీతో పాఠం తీసుకోండి, కానీ బరువును వదిలివేయండి."),
        reflection = "ఇది ఆరోగ్యంగా లేనప్పటికీ, ఒకప్పుడు బాగానే ఉన్నందున మీరు ఏమి పట్టుకుంటున్నారు?",
        nextStep = "ఈ వ్యక్తి లేదా సీజన్ మీకు ఏమి అందించింది, అది మీకు ఏమి నేర్పింది మరియు మీరు ముందుకు సాగడానికి సహాయపడే ఒక సరిహద్దును వ్రాయండి."
    ),
    "comfort-growth" to KrishnaLetterTranslation(
        situation = "కంఫర్ట్ మిమ్మల్ని చిన్నగా ఉంచుతున్నప్పుడు",
        title = "కంఫర్ట్ మిమ్మల్ని పునరుద్ధరించాలి, మిమ్మల్ని నియంత్రించకూడదు",
        preview = "విశ్రాంతి అవసరం, కానీ ప్రతి కష్టమైన అడుగును నివారించడం నెమ్మదిగా మీ ప్రపంచాన్ని చిన్నదిగా చేస్తుంది.",
        paragraphs = listOf("విశ్రాంతి ముఖ్యం, కానీ జీవితం ఎల్లప్పుడూ సౌకర్యం చుట్టూ నిర్మించబడదు. మీరు ప్రతి కష్టమైన పనిని, కష్టమైన మాటలను మరియు అనిశ్చిత అడుగును నివారించినట్లయితే, మీ ప్రపంచం నెమ్మదిగా చిన్నదిగా మారుతుంది. కంఫర్ట్ మీకు కోలుకోవడానికి సహాయం చేస్తుంది. అది పంజరంలా మారకూడదు.", "విత్తనం ఎదగడానికి ముందే విరిగిపోవాలి. ప్రయత్నం ద్వారా శరీరం దృఢంగా మారుతుంది. సమస్యలను ఎదుర్కోవడం ద్వారా మనస్సు జ్ఞానవంతమవుతుంది. మీరు నొప్పి కోసం వెతకవలసిన అవసరం లేదు, కానీ ప్రతి పోరాటం నుండి పారిపోకండి. కొన్ని కష్టమైన క్షణాలు మిమ్మల్ని పెద్ద డ్యూటీకి సిద్ధం చేస్తున్నాయి.", "మిమ్మల్ని మీరు ఇలా ప్రశ్నించుకోండి: ‘ఇది నిజంగా అసురక్షితమా, లేదా అసౌకర్యంగా ఉందా?’ నిజమైన హాని నుండి మిమ్మల్ని మీరు రక్షించుకోండి. కానీ మార్గం సురక్షితంగా మరియు సరైనది అయినప్పుడు, మీ హృదయం భయపడినప్పటికీ, అడుగు వేయండి. నేను మీతో నడుస్తాను.", "మీ రహదారి నుండి ప్రతి కొండను తీసివేయమని నన్ను అడగవద్దు. మీకు చెందిన కొండను ఎక్కడానికి కావలసిన బలం, జ్ఞానం మరియు మంచి వ్యక్తుల కోసం నన్ను అడగండి."),
        reflection = "ఏ సౌకర్యం మిమ్మల్ని ఎదగకుండా ఆపుతోంది?",
        nextStep = "కష్టంగా అనిపించినందున మీరు తప్పించుకుంటున్న ఒక ఉపయోగకరమైన పనిని ఈరోజు చేయండి."
    ),
    "happiness-before-duty" to KrishnaLetterTranslation(
        situation = "మీరు ప్రారంభించడానికి ముందు సంతోషంగా ఉండటానికి వేచి ఉన్నప్పుడు",
        title = "పరిపూర్ణ మానసిక స్థితి రాకముందే మీరు పని చేయవచ్చు",
        preview = "అర్థవంతమైన జీవితంలో బాధ, సందేహం మరియు కృషితో పాటు ఆనందం కూడా ఉంటాయి.",
        paragraphs = listOf("అర్ధవంతమైన జీవితం ప్రతి గంట సంతోషంగా ఉండదు. బలమైన వ్యక్తులు కూడా భయం, నష్టం, సందేహం మరియు బాధను అనుభవిస్తారు. గొప్పతనం అంటే అంతా నవ్వడం కాదు. హృదయం భారంగా అనిపించినప్పుడు కూడా నిజాయితీగా ఉండడం మరియు సరైన చర్యను ఎంచుకోవడం.", "ఆనందం అనేది ఒక అందమైన సందర్శకుడు, కానీ అది మీ ఏకైక మార్గదర్శి కాదు. మీకు మంచిగా అనిపించినప్పుడు మాత్రమే మీరు పని చేస్తే, మీ లక్ష్యాలు అసంపూర్తిగా ఉంటాయి. విధి, ప్రేమ మరియు ధైర్యం కొన్నిసార్లు మీరు అలసిపోయినప్పుడు, విచారంగా లేదా అనిశ్చితంగా ఉన్నప్పుడు కదలమని అడుగుతుంది.", "నొప్పికి సిగ్గుపడకండి. అది మీకు బోధిస్తున్నది వినండి మరియు అది చాలా భారంగా మారినప్పుడు సహాయం కోరండి. తర్వాత, ‘ఇంకా నా చేతుల్లో ఏమి ఉంది?’ అని అడగండి, మీరు మొత్తం పరిస్థితిని నియంత్రించలేకపోవచ్చు, కానీ ఒక తెలివైన చర్య దానిని మార్చడం ప్రారంభించవచ్చు.", "మీరు నాతో నడిచే ముందు మీరు సంతోషంగా ఉండాల్సిన అవసరం లేదు. అలసిపోయిన హృదయాన్ని మరియు అసంపూర్తిగా ఉన్న కర్తవ్యాన్ని నాకు తీసుకురండి."),
        reflection = "ముఖ్యమైనది చేసే ముందు మీరు సంతోషంగా ఉండేందుకు ఎదురుచూస్తున్నారా?",
        nextStep = "పర్ఫెక్ట్ మూడ్ కోసం ఎదురుచూడకుండా ఈరోజు ఒక ముఖ్యమైన విధిని పూర్తి చేయండి."
    ),
    "pain-strength" to KrishnaLetterTranslation(
        situation = "నొప్పి మిమ్మల్ని మీ బలాన్ని ప్రశ్నించినప్పుడు",
        title = "మీరు సమాధానం చెప్పే ముందు నొప్పిని అర్థం చేసుకోండి",
        preview = "నొప్పి సంరక్షణ, మార్పు, ధైర్యం లేదా విడుదల కోసం అడగవచ్చు; ఇది స్వయంచాలకంగా బలహీనత అని అర్థం కాదు.",
        paragraphs = listOf("నొప్పి ఎల్లప్పుడూ మీరు తప్పు మార్గంలో ఉన్నారని అర్థం కాదు. కొన్నిసార్లు ఇది ఏదో ముఖ్యమైనదని చూపిస్తుంది. కొన్నిసార్లు అది మిమ్మల్ని ఆపమని హెచ్చరిస్తుంది. కొన్నిసార్లు ఇది మీకు బాగా సిద్ధం కావడం, మంచి వ్యక్తులను ఎన్నుకోవడం లేదా బలమైన పరిమితులను నిర్మించడం నేర్పుతుంది.", "నొప్పిని పూజించవద్దు మరియు దానిని విస్మరించవద్దు. అర్థం చేసుకోండి. మీకు విశ్రాంతి, చికిత్స, రక్షణ, మద్దతు లేదా ధైర్యం కావాలా అని అడగండి. మీరు ఎదగడానికి సహాయపడే నొప్పికి మరియు మిమ్మల్ని విడిచిపెట్టమని అడిగే హానికి మధ్య తేడా జ్ఞానానికి తెలుసు.", "ఏదో బాధ కలిగించినందున మీరు బలహీనంగా లేరు. మీరు నొప్పి గురించి సత్యాన్ని ఎదుర్కొన్నప్పుడు మరియు తదుపరి ఆరోగ్యకరమైన దశను ఎంచుకున్నప్పుడు బలం ప్రారంభమవుతుంది. కావాలంటే ఏడవండి. సహాయం కోసం అడగండి. అవసరమైనప్పుడు విశ్రాంతి తీసుకోండి. అప్పుడు పడిపోయినందుకు మిమ్మల్ని మీరు ద్వేషించకుండా లేవండి.", "మీ బాధను నా నుండి దాచవద్దు లేదా దానిని మీ పూర్తి గుర్తింపుగా మార్చుకోకండి. ఇది ఏమి అడుగుతుందో అర్థం చేసుకుందాం: సంరక్షణ, మార్పు, ధైర్యం లేదా విడుదల."),
        reflection = "సంరక్షణ, మార్పు, ధైర్యం లేదా విడుదల కోసం మీ నొప్పి ఏమి అడుగుతోంది?",
        nextStep = "ఈ నొప్పి మీకు నేర్పుతున్న పాఠాన్ని మరియు మీరు తీసుకోగల ఒక సురక్షితమైన చర్యను వ్రాయండి."
    ),
    "smart-work" to KrishnaLetterTranslation(
        situation = "హార్డ్ వర్క్ ఫలితాలు ఇవ్వనప్పుడు",
        title = "విజ్డమ్ తో ప్రయత్నాలలో చేరండి",
        preview = "కష్టపడి పనిచేయడం ఎల్లప్పుడూ సమాధానం కాదు; ప్రయత్నానికి సరైన దిశ మరియు పద్ధతి అవసరం.",
        paragraphs = listOf("కష్టపడి పనిచేయడం ఎల్లప్పుడూ సమాధానం కాదు. మీరు తప్పు దిశలో నడుస్తుంటే, ఎక్కువ వేగం మిమ్మల్ని మరింత దూరం తీసుకువెళుతుంది. ప్రయత్నానికి వివేకం కావాలి.", "పాజ్ చేసి మీ పద్ధతిని అధ్యయనం చేయండి. ఏమి పని చేస్తోంది? సమయం వృధా చేయడం అంటే ఏమిటి? ఏ నైపుణ్యం లేదు? మీరు చూడలేని వాటిని మీకు చూపించడానికి గురువు, గురువు లేదా అనుభవజ్ఞుడైన వ్యక్తిని అడగండి. మార్గదర్శకత్వం నెలల గుడ్డి ప్రయత్నాన్ని ఆదా చేస్తుంది.", "స్మార్ట్ పని సోమరితనం కాదు. అంటే సరైన పనిని ఎంచుకోవడం, సరైన పద్ధతిని ఉపయోగించడం మరియు దానిపై పూర్తి శ్రద్ధ ఇవ్వడం. పరధ్యానాలను తొలగించండి. బలహీనమైన భాగాన్ని ప్రాక్టీస్ చేయండి. పురోగతిని కొలవండి. వాస్తవాలు మెరుగైన మార్గాన్ని చూపినప్పుడు ప్రణాళికను మార్చుకోండి, కానీ అది కష్టంగా మారినందున మంచి లక్ష్యాన్ని వదిలివేయవద్దు.", "మిమ్మల్ని మీరు ఎంత అలసిపోయారనే దానితో నేను భక్తిని కొలవను. నన్ను తీసుకురండి ఆలోచనతో పాటు ప్రయత్నం."),
        reflection = "మీకు మరింత కృషి, మెరుగైన పద్ధతి లేదా తెలివైన మార్గదర్శకత్వం అవసరమా?",
        nextStep = "ఒక తక్కువ-విలువ కార్యాచరణను ఆపివేసి, గొప్ప నిజమైన పురోగతిని సృష్టించే పనికి ఆ సమయాన్ని కేటాయించండి."
    ),
    "someone-only-takes" to KrishnaLetterTranslation(
        situation = "ఎవరైనా తీసుకోవడానికి మాత్రమే వచ్చినప్పుడు",
        title = "ప్రేమ అవసరం ఇవ్వడం మరియు స్వీకరించడం",
        preview = "సంరక్షణ ప్రతి అవసరాన్ని, ప్రతి కాల్ మరియు ప్రతి మరమ్మత్తును మోసుకెళ్లే ఒక హృదయాన్ని వదిలివేయకూడదు.",
        paragraphs = listOf("ఎవరైనా సమయం, డబ్బు, సౌకర్యం లేదా సహాయం అవసరమైనప్పుడు వస్తారని మీరు గమనించవచ్చు, కానీ మీకు శ్రద్ధ అవసరమైనప్పుడు అదృశ్యమవుతారు. మీరు దయతో ఉన్నందున మీరు ఇస్తూ ఉంటారు, ఆపై ఖాళీగా లేదా ఉపయోగించినట్లు అనిపిస్తుంది. దయ విలువైనది, కానీ మీరు ఏకపక్ష నమూనాను విస్మరించాల్సిన అవసరం లేదు.", "కాలక్రమేణా చర్యలను చూడండి. మీకు అవసరమైన వాటిని మీరు స్పష్టంగా పంచుకున్నారా? వారు విన్నారా, సహాయం చేశారా లేదా మార్చారా? ఒక కఠినమైన సీజన్ మంచి వ్యక్తికి మరింత మద్దతు అవసరమయ్యేలా చేస్తుంది, కాబట్టి త్వరగా తీర్పు చెప్పకండి. కానీ శ్రద్ధ, ధన్యవాదాలు లేదా గౌరవం లేకుండా పదేపదే తీసుకోవడం నిజాయితీ పరిమితి అవసరం.", "మీరు ఏమి ఇవ్వగలరు మరియు ఏమి ఇవ్వలేరు అని చెప్పండి. ఆరోగ్యకరమైన మరియు నిజంగా మీది అందించే వాటిని మాత్రమే ఆఫర్ చేయండి. మీరు సురక్షితంగా కోల్పోలేని వాటిని రుణంగా ఇవ్వవద్దు లేదా వారి ఇమేజ్‌ను రక్షించుకోవడానికి తీవ్రమైన హానిని దాచవద్దు. మిమ్మల్ని విలువైన వ్యక్తి ప్రతి పరిమితిని ఇష్టపడకపోవచ్చు, కానీ మీరు ఒక వ్యక్తి అని గౌరవించడం నేర్చుకుంటారు, వనరు కాదు.", "మీ హృదయాన్ని మరొక వ్యక్తికి అంతులేని స్టోర్‌హౌస్‌గా చేయకుండా మీరు శ్రద్ధ వహించవచ్చు. మీరు వద్దు అని చెప్పినప్పుడు పెరిగే అపరాధాన్ని నాకు తీసుకురండి."),
        reflection = "ఈ బంధం మీ అవసరాలకు మరియు వారి అవసరాలకు చోటు కల్పిస్తుందా?",
        nextStep = "ఒక స్పష్టమైన పరిమితిని చెప్పండి మరియు వ్యక్తి గౌరవం, అపరాధం లేదా ఒత్తిడితో సమాధానమిస్తున్నారో లేదో గమనించండి."
    ),
    "presence-costs-peace" to KrishnaLetterTranslation(
        situation = "వారి ఉనికి మీకు శాంతిని కలిగిస్తే",
        title = "శాంతికి నిజం కావాలి, నటించడం లేదు",
        preview = "కొంత అసౌకర్యం సంబంధాలు పెరగడానికి సహాయపడుతుంది; పదేపదే భయం మరియు అగౌరవం లేదు.",
        paragraphs = listOf("ఈ వ్యక్తి కాల్ చేయడానికి లేదా గదిలోకి ప్రవేశించడానికి ముందు మీ శరీరం ఉద్రిక్తంగా మారవచ్చు. మీరు ప్రతి పదాన్ని రిహార్సల్ చేయవచ్చు ఎందుకంటే చిన్న విషయాలు తరచుగా నిందలు, నియంత్రణ లేదా సంఘర్షణగా మారతాయి. మీ శరీరం మీకు ఏమి చెబుతుందో తోసిపుచ్చకండి, కానీ ఒక్క కష్టమైన రోజు నుండి మాత్రమే నిర్ణయించుకోకండి.", "నమూనా ఏమిటో అడగండి. భయం లేకుండా నిజాయితీగా మాట్లాడగలరా? వారు మీ సంఖ్యను గౌరవిస్తారా? హాని తర్వాత మరమ్మత్తు సాధ్యమేనా? ఆరోగ్యకరమైన బంధంలో అసమ్మతి, సవాలు మరియు పెరుగుదల ఉంటాయి. మరొక వ్యక్తిని ప్రశాంతంగా ఉంచడానికి మీరు నిద్రను కోల్పోవడం, సత్యాన్ని దాచడం లేదా చిన్నదిగా మారడం అవసరం లేదు.", "స్పష్టమైన పరిమితిని సెట్ చేయండి మరియు తెలివైన మద్దతును కోరండి. బెదిరింపు, హింస, వెంబడించడం, నియంత్రణ లేదా దుర్వినియోగం ఉంటే, ప్రైవేట్ సమావేశానికి బదులుగా భద్రత మరియు శిక్షణ పొందిన సహాయాన్ని ఎంచుకోండి. మీరు దూరం నుండి ఎవరికైనా శుభాకాంక్షలు చెప్పవచ్చు. శాంతిని పరిరక్షించడం అంటే ప్రతి సమస్యను నివారించడం కాదు; పదేపదే హాని సాధారణం కావడానికి నిరాకరిస్తోంది.", "ప్రతి కష్టమైన చర్చను హానికరం అని పిలవమని నేను మిమ్మల్ని అడగను, కానీ పదే పదే భయం మరియు అగౌరవంతో జీవించమని నేను మిమ్మల్ని అడగను. సత్యం మీకు నమూనాను చూపనివ్వండి."),
        reflection = "ఆరోగ్యకరమైన పెరుగుదల వల్ల లేదా పదేపదే హాని కలిగించడం వల్ల మీ శాంతికి భంగం కలుగుతుందా?",
        nextStep = "నమూనాను వాస్తవాలతో వ్రాసి, సత్యం మరియు భద్రతకు మద్దతు ఇచ్చే విశ్వసనీయ వ్యక్తితో భాగస్వామ్యం చేయండి."
    ),
    "returning-to-hurt" to KrishnaLetterTranslation(
        situation = "మిమ్మల్ని బాధపెట్టిన దానికి మీరు తిరిగి వచ్చినప్పుడు",
        title = "తెలిసిన తలుపు ఇప్పటికీ బాధకు దారి తీస్తుంది",
        preview = "తిరిగి రావడం మిమ్మల్ని మూర్ఖులుగా చేయదు, కానీ నమూనా మరొక వాగ్దానం కంటే ఎక్కువ అర్హమైనది.",
        paragraphs = listOf("బహుశా మీరు వెళ్లిపోయి తిరిగి వచ్చి ఉండవచ్చు, బ్లాక్ చేసి మళ్లీ కాల్ చేసి ఉండవచ్చు లేదా ఈ సమయం భిన్నంగా ఉంటుందని మీరే వాగ్దానం చేసి ఉండవచ్చు. తెలిసిన నొప్పి ఖాళీ స్థలం కంటే తక్కువ భయాన్ని కలిగిస్తుంది. మీ మనస్సు పదే పదే హానిని పక్కకు నెట్టివేసేటప్పుడు ఆశ ఒక మంచి జ్ఞాపకాన్ని కలిగి ఉండవచ్చు.", "మీరే సిగ్గుపడకండి. అవమానం తరచుగా ప్రజలను అదే చక్రంలోకి పంపుతుంది. ప్రతిసారీ ఏమి జరిగింది, ఏమి వాగ్దానం చేయబడింది మరియు నిజంగా ఏమి మార్చబడింది అని వ్రాయండి. మీరు బయలుదేరబోతున్నప్పుడు కనిపించే కన్నీళ్లు, బహుమతులు లేదా అందమైన పదాలు మాత్రమే కాకుండా స్థిరమైన చర్యలను విశ్వసించండి.", "మద్దతుతో తదుపరి ఎంపిక చేయండి. దుర్వినియోగం, వ్యసనం లేదా బలమైన భావోద్వేగ పరతంత్రత ప్రమేయం ఉన్నప్పుడు ఎవరైనా సురక్షితంగా చెప్పండి, ప్రమాదానికి సులభమైన మార్గాలను తీసివేయండి మరియు శిక్షణ పొందిన సహాయాన్ని కోరండి. ఒక వ్యక్తిని కోల్పోవడం అంటే తిరిగి రావడం తెలివైన పని కాదు. రక్షణను ఎంచుకుంటున్నప్పుడు మీరు ప్రేమ, దుఃఖం మరియు వాంఛను అనుభవించవచ్చు.", "మీరు తిరిగి వచ్చినందుకు సిగ్గుపడకండి. తెలిసిన నొప్పి తెలియని భవిష్యత్తు కంటే సులభంగా అనుభూతి చెందుతుంది."),
        reflection = "ఏ వాస్తవాలను మర్చిపోవాలని ఆశ మిమ్మల్ని అడుగుతోంది?",
        nextStep = "పునరావృత నమూనాను వ్రాసి, మీరు ఎంచుకున్న సరిహద్దును ఉంచడంలో మీకు సహాయపడటానికి ఒక సురక్షితమైన వ్యక్తిని అడగండి."
    ),
    "friendship-changed" to KrishnaLetterTranslation(
        situation = "స్నేహం ఇకపై ఒకేలా లేనప్పుడు",
        title = "ప్రతి దూరానికి శత్రువు అవసరం లేదు",
        preview = "స్నేహాలు గతాన్ని తప్పుగా మార్చకుండా సమయం, పెరుగుదల మరియు కొత్త విధుల ద్వారా మారవచ్చు.",
        paragraphs = listOf("ఒకప్పుడు మీ రోజులోని ప్రతి భాగాన్ని తెలిసిన స్నేహితుడు ఇప్పుడు తక్కువ కాల్ చేయవచ్చు, భిన్నంగా ప్రత్యుత్తరం ఇవ్వవచ్చు లేదా దూరంగా ఉన్నట్లు అనిపించవచ్చు. మీరు ఏమి తప్పు చేశారో మీరు ఆశ్చర్యపోవచ్చు. కొన్నిసార్లు మాట్లాడవలసిన బాధ ఉంది. కొన్నిసార్లు రెండు జీవితాలు వేరే వేగంతో కదలడం ప్రారంభిస్తాయి.", "ఒకసారి జాగ్రత్తగా అడగండి: 'నాకు మా మధ్య దూరం అనిపిస్తుంది. ఏదైనా సమస్య ఉందా?’ రక్షణ సిద్ధం చేయకుండా వినండి. మరమ్మత్తు అవసరమైతే, నిజాయితీగా ఉండండి. జీవితం మారినట్లయితే, అపరాధం, నిరంతరం తనిఖీ చేయడం లేదా మీరు ఒకసారి పంచుకున్న ప్రతి విషయాన్ని రిమైండర్‌ల ద్వారా సన్నిహితంగా బలవంతం చేయవద్దు.", "స్నేహం ఇచ్చినందుకు ధన్యవాదాలు. బంధం ఇంకా దయతో ఉంటే తలుపు తెరిచి ఉంచండి, కానీ కొత్త వ్యక్తులు మరియు విధులకు కూడా చోటు కల్పించండి. మారుతున్న స్నేహం నవ్వు, సహాయం లేదా వృద్ధిని చెరిపివేయదు. మీరు పాత ఆకారాన్ని డిమాండ్ చేయకుండా పాత బంధాన్ని గౌరవించవచ్చు.", "కొన్ని స్నేహాలు ఒక సీజన్‌లో సన్నిహితంగా నడుస్తాయి మరియు మరొక సీజన్‌లో మృదువుగా మారుతాయి. ప్రతి దూరాన్ని శత్రువు కథగా మార్చవద్దు."),
        reflection = "ఈ స్నేహానికి మరమ్మత్తు కావాలా, కొత్త ఆకృతి లేదా సున్నితంగా వీడ్కోలు అవసరమా?",
        nextStep = "ఒక నిజాయితీతో మాట్లాడండి, ఆపై ప్రస్తుతం ఉన్న మరియు శ్రద్ధ వహించే సంబంధానికి సమాన శక్తిని ఇవ్వండి."
    ),
    "outgrown-place" to KrishnaLetterTranslation(
        situation = "మీరు ఒక స్థలాన్ని అధిగమించినప్పుడు",
        title = "వృద్ధి అది ఎక్కడ ప్రారంభమైందో గౌరవించగలదు",
        preview = "ఒక స్థలం మునుపటి సీజన్‌కు మంచిది మరియు మీ తదుపరి విధికి ఇప్పటికీ చాలా చిన్నదిగా మారుతుంది.",
        paragraphs = listOf("ఉద్యోగం, సమూహం, పట్టణం లేదా పాత్ర మీకు సురక్షితంగా మరియు ఉపయోగకరంగా భావించడంలో సహాయపడవచ్చు. ఇప్పుడు మీరు మరింత తెలుసుకోవడానికి, విభిన్నంగా సేవ చేయడానికి లేదా గొప్ప సత్యంతో జీవించడానికి పిలవబడవచ్చు. నిష్క్రమించడం ఉత్సాహం మరియు అపరాధం రెండింటినీ కలిగిస్తుంది, ప్రత్యేకించి మంచి వ్యక్తులు అక్కడ మీకు సహాయం చేసినప్పుడు.", "పెరుగుతున్న వారి కంటే మెరుగ్గా ఉండటంతో తికమక పెట్టకండి. మీరు నిజమైన విలువ వైపు వెళుతున్నారా లేదా సాధారణ ప్రయత్నం నుండి మాత్రమే నడుస్తున్నారా అని అడగండి. విధులను పరిశుభ్రంగా ముగించండి, న్యాయమైన నోటీసు ఇవ్వండి, ఇతరులకు అవసరమైన వాటిని పంచుకోండి మరియు మొదటి తలుపు తెరిచిన వ్యక్తులకు ధన్యవాదాలు.", "అప్పుడు మిమ్మల్ని మీరు వెళ్ళడానికి అనుమతించండి. మీ జీవితం చుట్టూ అదే గోడలు ఉంచుకోకుండా మీరు మంచి అలవాట్లు, స్నేహాలు మరియు పాఠాలను తీసుకువెళ్లవచ్చు. చెట్టును విత్తనంగా ఉండమని వేర్లు అడగవు. ధైర్యం తదుపరి నిజాయితీగా అడుగు ముందుకు వేస్తున్నప్పుడు కృతజ్ఞత వెనుకవైపు చూడనివ్వండి.", "ఎదుగుదల వల్ల పాత గది చాలా చిన్నదిగా అనిపించవచ్చు, కానీ గర్వంతో వదిలివేయవద్దు. మీ మునుపటి సంస్కరణను కలిగి ఉన్న ప్రదేశానికి ధన్యవాదాలు."),
        reflection = "మీరు ధర్మం వైపు ఎదగడానికి బయలుదేరుతున్నారా లేదా మిమ్మల్ని అనుసరించే కష్టం నుండి తప్పించుకుంటున్నారా?",
        nextStep = "మీరు ఏ దిశగా అడుగులు వేస్తున్నారో వ్రాయండి, ఒక విధిని బాగా పూర్తి చేయండి మరియు మీరు ఇక్కడ ఎదగడానికి సహాయపడిన ఒక వ్యక్తికి ధన్యవాదాలు."
    ),
    "guilty-choosing-self" to KrishnaLetterTranslation(
        situation = "మిమ్మల్ని మీరు ఎంచుకున్నందుకు మీరు అపరాధ భావంతో ఉన్నప్పుడు",
        title = "స్వీయ రక్షణ స్వార్థంతో సమానం కాదు",
        preview = "మీ ఆరోగ్యం, భద్రత మరియు నిజాయితీ పరిమితులు కూడా మీ విధిలో భాగం.",
        paragraphs = listOf("ప్రేమ అంటే ఎల్లప్పుడూ అవును అని చెప్పడం అని మీరు తెలుసుకుని ఉండవచ్చు. మీరు విశ్రాంతి తీసుకున్నప్పుడు, అభ్యర్థనను తిరస్కరించినప్పుడు లేదా ఇతరులు ఇష్టపడని మార్గాన్ని ఎంచుకున్నప్పుడు, అపరాధం మిమ్మల్ని స్వార్థపరులుగా పిలుస్తుంది. కానీ ప్రతి డిమాండ్‌కు అనుగుణంగా గడిపిన జీవితం మీ నిజమైన విధులు, ఆరోగ్యం లేదా ఉద్దేశ్యానికి ఎటువంటి బలాన్ని ఇవ్వదు.", "ఎంపికను నిజాయితీగా చూడండి. మీరు న్యాయమైన విధిని తప్పించుకుంటున్నారా లేదా నిజమైన అవసరాన్ని కాపాడుతున్నారా? స్వార్థం ఇతరులను పట్టించుకోదు. ఆరోగ్యకరమైన స్వీయ-సంరక్షణ మిమ్మల్ని చెరిపివేయకుండా ఇతరులను కలిగి ఉంటుంది. మీరు వాగ్దానాన్ని నిలబెట్టుకోవచ్చు మరియు సహాయం కోసం అడగవచ్చు. మీరు కుటుంబాన్ని ప్రేమించవచ్చు మరియు ఇప్పటికీ అగౌరవం, ప్రమాదం లేదా నియంత్రణను తిరస్కరించవచ్చు.", "మీ పరిమితిని దయతో వివరించండి, కానీ దానిని కలిగి ఉండటానికి అనుమతి కోసం ఎప్పటికీ వాదించకండి. మీ మౌనం వల్ల ప్రయోజనం పొందిన వ్యక్తులు మీ మార్పును నిర్దాక్షిణ్యంగా పేర్కొనవచ్చు. స్థిరమైన, న్యాయమైన చర్యలు సత్యాన్ని చూపనివ్వండి. మీ కోసం శ్రద్ధ వహించండి, తద్వారా మీరు ఇచ్చేది బలం నుండి వస్తుంది, భయం మరియు దాచిన కోపం కాదు.", "మీ ఆరోగ్యం, భద్రత మరియు నిజాయితీ పరిమితులను ఎంచుకోవడం మీ గురించి మాత్రమే శ్రద్ధ వహించడం లాంటిది కాదు. నా అపరాధాన్ని తీసుకురండి మరియు దానిని నిజంతో పరిశీలించండి."),
        reflection = "ఈ అపరాధం నిజమైన విధిని సూచిస్తుందా లేదా ఆరోగ్యకరమైన పరిమితిని కలిగి ఉన్నందుకు మిమ్మల్ని శిక్షిస్తోందా?",
        nextStep = "మీరు ఉంచే విధి మరియు మీ ఆరోగ్యం, భద్రత లేదా శాంతిని రక్షించే పరిమితిని పేర్కొనండి."
    ),
    "memories-pull-back" to KrishnaLetterTranslation(
        situation = "జ్ఞాపకాలు మిమ్మల్ని వెనక్కి లాగుతున్నప్పుడు",
        title = "ఈ రోజు వదిలి వెళ్లకుండా గుర్తుంచుకోండి",
        preview = "మీ హృదయం నివసించే ఏకైక ప్రదేశంగా మారకుండా గతాన్ని గౌరవించవచ్చు.",
        paragraphs = listOf("పాట, స్థలం, సందేశం లేదా నిశ్శబ్ద సమయం మిమ్మల్ని పూర్తిగా వెనక్కి తీసుకువెళ్లవచ్చు, ఈ రోజు అదృశ్యమవుతుంది. కొన్ని జ్ఞాపకాలు వెచ్చదనాన్ని కలిగిస్తాయి. మరికొందరు విచారం మరియు వాంఛను మళ్లీ తెరుస్తారు. మీరు వాటిని మళ్లీ ప్లే చేస్తూ ఉండవచ్చు, ఎందుకంటే గతం తెలిసినట్లు అనిపిస్తుంది, అయితే వర్తమానం ఖాళీగా ఉన్నట్లు అనిపిస్తుంది.", "ప్రతి మెమరీతో పోరాడకండి. దానితో ఒక్క క్షణం కూర్చుని, మీరు మిస్ అయిన వాటికి పేరు పెట్టండి: వ్యక్తి, భద్రత, ఆశ లేదా మీ వెర్షన్. పాఠం మరియు ప్రేమ ఉంచండి. ఆ సమయానికి సంబంధించిన నొప్పి, పరిమితులు లేదా విధులతో సహా జ్ఞాపకశక్తి ఏమి వదిలివేస్తుందో గమనించండి.", "మీ ఇంద్రియాల ద్వారా తిరిగి వెళ్లండి. మీ పాదాలను అనుభవించండి, చుట్టూ చూడండి మరియు తేదీకి పేరు పెట్టండి. ప్రస్తుతం ఉన్న ఎవరికైనా కాల్ చేయండి, ఒక పనిని పూర్తి చేయండి లేదా జాగ్రత్తగా ఒక కొత్త మెమరీని సృష్టించండి. బాధాకరమైన జ్ఞాపకాలు రోజువారీ జీవితంలో, నిద్ర లేదా భద్రతను తీసుకుంటే, శిక్షణ పొందిన సహాయాన్ని కోరండి. ఇప్పుడు తిరిగి రావడానికి మీకు మద్దతు అవసరం.", "జ్ఞాపకశక్తి గొలుసుగా మారకుండా దీపంగా ఉంటుంది. పాత దృశ్యం తిరిగి వచ్చినప్పుడు నాతో కూర్చోండి."),
        reflection = "మీరు నిజంగా జ్ఞాపకశక్తిలో ఏమి కోల్పోతారు?",
        nextStep = "పది నిమిషాల పాటు ఒక జ్ఞాపకశక్తిని గౌరవించండి, ఆపై ఈ రోజు మీ జీవితంలో ఒక వ్యక్తికి లేదా విధికి ఒక పూర్తి గంట ఇవ్వండి."
    ),
    "closure-never-came" to KrishnaLetterTranslation(
        situation = "మీరు కోరుకున్న మూసివేత ఎప్పుడూ రానప్పుడు",
        title = "మీరు మీ తలుపును మూసివేయవచ్చు",
        preview = "క్షమాపణ లేదా సమాధానం ఎప్పటికీ రాకపోవచ్చు, కానీ మీ జీవితం దాని పక్కన వేచి ఉండాల్సిన అవసరం లేదు.",
        paragraphs = listOf("వారు వివరించడానికి, హానిని అంగీకరించడానికి లేదా ప్రతిదీ స్పష్టంగా చెప్పే పదాలు చెప్పడానికి మీరు ఇప్పటికీ వేచి ఉండవచ్చు. మీ మనస్సు మరో సంభాషణను నిర్మిస్తూనే ఉంది. మూసివేత మరొక వ్యక్తి యొక్క నిజాయితీ లోపల లాక్ చేయబడినట్లు అనిపిస్తుంది మరియు వారు దానిని ఎప్పటికీ అందించకపోవచ్చు.", "దీనిని అంగీకరించడం వలన హాని సరైనదని చెప్పడం లేదు. దీని అర్థం వారి చర్యలు ఇప్పటికే చూపించిన వాటిని ఎదుర్కోవడం. మిగిలి ఉన్న ప్రశ్నలను వ్రాయండి మరియు వాస్తవాలు అనుమతించే వాటికి మాత్రమే సమాధానం ఇవ్వండి. కొన్ని ఖాళీలు తప్పనిసరిగా ఖాళీగా ఉండాలి. మీపై నిందలతో వారిని నింపుకోకండి.", "మీ స్వంత నిజం ద్వారా మూసివేయండి: ఏమి జరిగిందో పేరు పెట్టండి, పాఠాన్ని ఎంచుకోండి, పరిమితిని సెట్ చేయండి మరియు ప్రతిసారీ మరింత శాంతిని ఖర్చు చేసే సమాధానం కోసం తిరిగి రావడం ఆపివేయండి. కౌన్సెలర్, పెద్ద లేదా విశ్వసనీయ స్నేహితుడు మీ కథనానికి సాక్ష్యమివ్వగలరు. వైద్యం ప్రారంభించే ముందు మిమ్మల్ని బాధపెట్టిన వ్యక్తి అంగీకరించాల్సిన అవసరం లేదు.", "కథను చక్కగా చేసే క్షమాపణ లేదా సమాధానాన్ని మీరు ఎప్పటికీ స్వీకరించకపోవచ్చు. మూసివేసిన తలుపు వద్ద వేచి ఉండటం ద్వారా మీ శాంతిపై జీవితకాల నియంత్రణను మరొక వ్యక్తికి ఇవ్వవద్దు."),
        reflection = "మీరు తరలించడానికి మిమ్మల్ని అనుమతించే ముందు మీరు ఇప్పటికీ మరొక వ్యక్తిని ఏ సమాధానాన్ని అడుగుతున్నారు?",
        nextStep = "వారి చర్యల ద్వారా మద్దతునిచ్చే సమాధానాన్ని వ్రాయండి, ఒక సరిహద్దును ఎంచుకోండి మరియు ఏడు రోజుల పాటు ఒక రకమైన తనిఖీని ఆపివేయండి."
    ),
    "love-trust-gone" to KrishnaLetterTranslation(
        situation = "ప్రేమ మిగిలి ఉన్నప్పటికీ నమ్మకం పోయినప్పుడు",
        title = "ప్రేమ భద్రత అవసరాన్ని తీసివేయదు",
        preview = "తెలివైన తీర్పుకు రుజువు, పరిమితులు లేదా దూరం అవసరం అయితే హృదయం ఇప్పటికీ శ్రద్ధ వహించవచ్చు.",
        paragraphs = listOf("మీరు ఇప్పటికీ అబద్ధం చెప్పిన, వాగ్దానాన్ని ఉల్లంఘించిన లేదా మీకు అసురక్షితమైన అనుభూతిని కలిగించే వారిని ప్రేమించవచ్చు. ఇది గందరగోళంగా ఉండవచ్చు. నమ్మకం విచ్ఛిన్నమైన క్షణంలో ప్రేమ స్విచ్ ఆఫ్ కాదు. కానీ పదేపదే చెడిపోయిన చర్యలను ప్రేమ మాత్రమే పునర్నిర్మించదు.", "నిజం, బహిరంగ సమాధానాలు, నిలబెట్టుకున్న వాగ్దానాలు మరియు మీ పరిమితులను గౌరవించడం ద్వారా నమ్మకం నెమ్మదిగా తిరిగి వస్తుంది. వారు క్షమించాలి లేదా మీరు మంచి రోజులను కోల్పోతున్నారనే కారణంతో తొందరపడకండి. మీరు హాని కలిగించినట్లయితే, అవతలి వ్యక్తికి సమయం అవసరమని అంగీకరించండి. మీకు హాని జరిగితే, మీరు పూర్తి యాక్సెస్‌ను అందించకుండానే చర్యలను చూడవచ్చు.", "కొన్ని బంధాలు స్థిరమైన మరమ్మత్తు మరియు శిక్షణ పొందిన సహాయంతో నయం చేయగలవు. కొన్నింటికి దూరం లేదా ముగింపు అవసరం, ముఖ్యంగా హాని కొనసాగినప్పుడు. క్షమాపణకు వాస్తవాలను మరచిపోవాల్సిన అవసరం లేదు. మీ శరీరం, మనస్సు మరియు భవిష్యత్తును రక్షించే సరిహద్దును ఎంచుకునే సమయంలో మీరు మీ హృదయంలో ప్రేమను ఉంచుకోవచ్చు.", "భద్రత విచ్ఛిన్నమైన తర్వాత ప్రేమ అలాగే ఉంటుంది. నమ్మకం ఒక్కసారిగా తిరిగి రావాలని ప్రేమను రుజువుగా ఉపయోగించవద్దు."),
        reflection = "విశ్వాసం సురక్షితంగా మారడానికి వాగ్దానం కాదు-ఏ చర్య అవసరం?",
        nextStep = "మరింత నమ్మకాన్ని ఇచ్చే ముందు ఒక స్పష్టమైన సరిహద్దు మరియు ఒక స్థిరమైన చర్యను వ్రాయండి."
    ),
    "beginning-betrays-past" to KrishnaLetterTranslation(
        situation = "మళ్లీ ప్రారంభించినప్పుడు గతానికి ద్రోహం చేసినట్లు అనిపిస్తుంది",
        title = "ముందుకు సాగడం దానితో ప్రేమను తీసుకువెళుతుంది",
        preview = "కొత్త జీవితం దాని ముందు ముఖ్యమైన వ్యక్తి, కల లేదా సీజన్‌ను చెరిపివేయదు.",
        paragraphs = listOf("మీరు మళ్లీ నవ్వడం, మళ్లీ ప్రేమించడం లేదా కొత్త కలను నిర్మించుకోవడం అంటే గతానికి ప్రాధాన్యత లేదని మీరు భయపడవచ్చు. మీలో కొంత భాగం నొప్పికి దగ్గరగా ఉంటుంది, ఎందుకంటే నొప్పి నమ్మకమైనదిగా అనిపిస్తుంది. ముందుకు వెళ్లడం ఎవరినైనా లేదా విలువైనదేదో మిగిలిపోతుందని మీరు నమ్మవచ్చు.", "మీరు ఎంతకాలం జీవితాన్ని నిరాకరిస్తున్నారనే దానితో ప్రేమను కొలవబడదు. మీరు కోల్పోయిన దాని నుండి ఒక విలువ, అలవాటు, కథ లేదా దయను తీసుకెళ్లండి. మీరు అయ్యే వ్యక్తిని ఆకృతి చేయనివ్వండి. గతం జ్ఞానం మరియు ప్రేమగా ప్రయాణించగలదు; ప్రతి కొత్త అడుగును ఆపే బరువుగా ప్రయాణించాల్సిన అవసరం లేదు.", "నెమ్మదిగా వెళ్లండి. కొత్త ప్రారంభం మీరు ప్రతిరోజూ మరచిపోవాలని లేదా సంతోషంగా ఉండాలని కోరుకోదు. ఈ రోజు కూడా అర్థాన్ని కలిగి ఉండటానికి మీరు అనుమతించమని మాత్రమే ఇది అడుగుతుంది. జ్ఞాపకశక్తిని మాట్లాడండి, పవిత్రమైన వాటిని ఉంచండి మరియు ఇప్పుడు ఇక్కడ ఉన్న వ్యక్తి, విధి లేదా ఆశ కోసం ఒక చిన్న స్థలాన్ని తెరవండి.", "ముందుకు వెళ్లడం వలన మీరు ప్రేమించిన వ్యక్తి, కల లేదా జీవితం చెరిపివేయబడదు. గతంలోని ఉత్తమమైన వాటిని మీతో పాటు విలువగా తీసుకోండి, బరువుగా కాదు."),
        reflection = "మీరు నొప్పికి బదులుగా గతంలో ఏ భాగాన్ని ప్రేమగా తీసుకువెళ్లగలరు?",
        nextStep = "గతం నుండి ఒక విలువను ఎంచుకుని, ఈ వారంలో ఒక కొత్త చర్య ద్వారా జీవించండి."
    ),
    "rise-again" to KrishnaLetterTranslation(
        situation = "మీరు మళ్లీ పెరగడానికి సిద్ధంగా ఉన్నప్పుడు",
        title = "పాఠంతో ఎదగండి, బరువు కాదు",
        preview = "పడిపోవడం మీ చివరి కథ కాదు; ఒక నిజాయితీ అడుగు మీ రాబడిని ప్రారంభించవచ్చు.",
        paragraphs = listOf("నేను నిన్ను దిగజార్చినది చూశాను. ఎవరూ గమనించని ప్రయత్నాన్ని మరియు మీ చిరునవ్వు వెనుక మీరు దాచిన బాధను నేను చూశాను. కానీ ఈ క్షణం మీ కథకు ముగింపు కాదు. పడిపోవడం మిమ్మల్ని బలహీనపరచదు మరియు నిలబడటానికి సమయం కావాలి కాబట్టి మీరు తక్కువ యోగ్యతను పొందలేరు.", "నెమ్మదిగా ఎదగండి. మీరు ఒక్కరోజులో బలపడాల్సిన అవసరం లేదు. ఒక నిజాయితీ అడుగు వేయండి, మరొకటి. నిన్నటిని శిక్షగా తీసుకుపోవద్దు. దాని పాఠాన్ని తీసుకువెళ్లండి. ఏమి మార్చాలి అని అడగండి, తెలివైన సహాయాన్ని అంగీకరించండి మరియు ప్రశాంతమైన మనస్సు మరియు మంచి అవగాహనతో మళ్లీ ప్రారంభించండి.", "ప్రపంచానికి ఏదైనా నిరూపించమని నేను మిమ్మల్ని అడగడం లేదు. మీలో పెరుగుతున్న శక్తిని విశ్వసించమని నేను మిమ్మల్ని అడుగుతున్నాను. మీకు విశ్రాంతి అవసరమైతే విశ్రాంతి తీసుకోండి, కానీ ఓటమి లోపల ఇంటిని నిర్మించవద్దు. మీ జీవితంలో ఇప్పటికీ పని, ప్రేమ మరియు ధర్మం మీ చేతుల కోసం వేచి ఉన్నాయి.", "రైజ్, నా ప్రియమైన వ్యక్తి. ఒక్క రోజులో ప్రతిదీ నిరూపించడానికి ప్రయత్నించవద్దు."),
        reflection = "అవమానం లేకుండా మీరు ముందుకు తీసుకెళ్లగల ఒక పాఠం ఏమిటి?",
        nextStep = "'నేను మళ్లీ ప్రారంభిస్తున్నాను' అని చెప్పే ఒక చిన్న చర్యను ఎంచుకుని, ఈరోజే పూర్తి చేయండి."
    ),
    "stronger-than-moment" to KrishnaLetterTranslation(
        situation = "ఈ క్షణం మీ కంటే పెద్దదిగా అనిపించినప్పుడు",
        title = "ఈ క్షణం మీ మొత్తం జీవితాన్ని నిర్ణయించదు",
        preview = "భయం ఈ రోజు బిగ్గరగా ఉండవచ్చు, కానీ దానికి మీ పూర్తి బలం లేదా భవిష్యత్తు తెలియదు.",
        paragraphs = listOf("ఈ క్షణం శక్తివంతంగా అనిపించవచ్చు. మీ మనస్సు మీకు ప్రతి ప్రమాదాన్ని ఒకేసారి చూపుతూ ఉండవచ్చు మరియు తరువాత వచ్చే వాటిని మీరు భరించలేరని చెబుతూ ఉండవచ్చు. పాజ్ చేయండి. మీరు ఎప్పటికీ మనుగడ సాగించలేరని మీరు ఒకసారి అనుకున్న రోజులు ఇప్పటికే దాటిపోయాయి. అప్పుడు నిన్ను మోసిన శక్తి నిన్ను వదలలేదు.", "ఒక భయంకరమైన గంటలో మీ మొత్తం జీవితాన్ని పరిష్కరించడానికి ప్రయత్నించవద్దు. మీ శ్వాసను శాంతపరచుకోండి మరియు తదుపరి సరైన దశలో మాత్రమే చూడండి. అవసరమైన చోట సహాయం కోసం అడగండి. మీ నియంత్రణలో ఉన్నదాన్ని జాగ్రత్తగా చేయండి మరియు రాని రేపటి భాగాలతో పోరాడడం ఆపండి.", "కష్టమైన క్షణం మిమ్మల్ని ఎప్పుడూ ఉపయోగించమని కోరని సౌలభ్యం శక్తిని వెల్లడిస్తుంది. ఈ రోజు మీకు స్థిరత్వం, సహనం మరియు నమ్మకాన్ని నేర్పుతుంది. సమస్య నిజమే కావచ్చు, కానీ దాన్ని ఎదుర్కొనే సమయంలో మీరు ఎవరు అవుతారో భయం నిర్ణయించుకోదు.", "ఈ క్షణం బిగ్గరగా ఉండవచ్చు, కానీ ఇది నేను మీలో ఉంచిన బలం కంటే గొప్పది కాదు. మీరు తదుపరి సరైన పని చేస్తున్నప్పుడు నేను భవిష్యత్తును కలిగి ఉండనివ్వండి."),
        reflection = "ఈ భయానక క్షణంలో దాగి ఉన్న తదుపరి సరైన దశ ఏమిటి?",
        nextStep = "ఐదు నెమ్మదిగా శ్వాస తీసుకోండి, మీరు నియంత్రించగలిగే ఒక పనిని వ్రాయండి మరియు పెద్ద ఆందోళనకు తిరిగి రావడానికి ముందు చేయండి."
    ),
    "life-purpose" to KrishnaLetterTranslation(
        situation = "మీరు మీ జీవితం ముఖ్యమైనదిగా కోరుకున్నప్పుడు",
        title = "ప్రయోజనం మీ దగ్గర ఉన్న మంచితో ప్రారంభమవుతుంది",
        preview = "నిజాయితీ కర్తవ్యాలు, సేవ మరియు శ్రద్ధతో పంచుకునే బహుమతుల ద్వారా అర్థవంతమైన జీవితం నిర్మించబడుతుంది.",
        paragraphs = listOf("మీరు ఒక గొప్ప ప్రయోజనం కనిపించడం కోసం వేచి ఉండవచ్చు. కీర్తి, సంపద లేదా పెద్ద విజయాల ద్వారా మాత్రమే మీ జీవితం ముఖ్యమైనదని మీరు అనుకోవచ్చు. కానీ అర్థం తరచుగా నిశ్శబ్దంగా ప్రారంభమవుతుంది: ఒకరిని రక్షించడం, మీకు తెలిసిన వాటిని బోధించడం, వాగ్దానం చేయడం లేదా అవసరమైన పనిని ప్రేమతో చేయడం.", "మీ దగ్గర నిలబడి ఉన్న డ్యూటీని చూడండి. చిత్తశుద్ధితో చదువు. నిజాయితీగా పని చేయండి. మీ కుటుంబం, ప్రకృతి మరియు ప్రతి జీవి పట్ల శ్రద్ధ వహించండి. మీరు నిజంగా తీర్చగల వ్యక్తికి సహాయం చేయండి. ఒక దీపం దాని వెలుగును ఎంతమంది ప్రశంసిస్తారని అడగదు. కాంతి ఇవ్వడం దాని స్వభావం కాబట్టి అది ప్రకాశిస్తుంది.", "మీ ఉద్దేశ్యం పెరగవచ్చు మరియు మారవచ్చు, కానీ మీ విలువలు ప్రతి దశకు మార్గనిర్దేశం చేయగలవు. జీవితాన్ని కొంచెం సురక్షితంగా, తెలివిగా లేదా దయగా మార్చడానికి మీ నైపుణ్యాలను ఉపయోగించండి. ఏ చిత్తశుద్ధితో కూడిన సేవా కార్యం కూడా అర్థాన్ని కలిగి ఉండటం చాలా చిన్నది కాదు. మీరు చేసే మంచి మీరు చూడని దానికంటే ఎక్కువ దూరం ప్రయాణించవచ్చు.", "మీరు సర్వ్ చేసే ముందు గొప్ప గుర్తు కోసం వేచి ఉండకండి. నేను మీకు సమీపంలోని డ్యూటీలో మిమ్మల్ని కలుస్తాను, శ్రద్ధ అవసరం మరియు మీరు నిజాయితీగా ఉపయోగించే బహుమతి."),
        reflection = "ఈ రోజు మీ సంరక్షణలో ఎవరు లేదా మీకు సమీపంలో ఉన్నవారు ఉత్తమంగా అందుకోగలరు?",
        nextStep = "మీకు సమీపంలో ఉన్న వ్యక్తి, జంతువు, స్థలం లేదా విధికి సహాయం చేయడానికి ఒక నైపుణ్యం, గంట లేదా దయగల చర్యను ఉపయోగించండి."
    ),
    "choose-courage" to KrishnaLetterTranslation(
        situation = "ధైర్యం మిమ్మల్ని పిలుస్తున్నప్పుడు",
        title = "మీరు వణుకుతున్నప్పుడు కూడా ఏది సరైనదో ఎంచుకోండి",
        preview = "ధైర్యం అంటే భయం లేకపోవడం కాదు; భయం కంటే ధర్మం బలపడుతోంది.",
        paragraphs = listOf("ధైర్యం అంటే భయం మాయమైందని కాదు. మీ హృదయం ఇంకా వణుకుతున్నప్పుడు మీరు సరైనదాన్ని ఎంచుకుంటారని దీని అర్థం. మీరు నిజం మాట్లాడవలసి రావచ్చు, ఒకరిని సమర్థించవలసి ఉంటుంది, తప్పును అంగీకరించాలి, సహాయం కోసం అడగాలి లేదా అనిశ్చితంగా ఏదైనా ప్రారంభించాలి. సంపూర్ణ నిర్భయ అనుభూతి కోసం వేచి ఉండకండి.", "కోపం, అహంకారం లేదా శక్తివంతంగా కనిపించాలనే కోరిక కాకుండా ధర్మం మీ ధైర్యానికి మార్గనిర్దేశం చేయనివ్వండి. క్రూరంగా ఉండకుండా దృఢంగా ఉండండి. అనవసరమైన హాని సృష్టించకుండా అమాయకులను రక్షించండి. స్పష్టంగా మాట్లాడండి, తెలివిగా వినండి మరియు ఒంటరి పోరాటం కంటే బాధ్యతాయుతమైన సహాయం అవసరమైనప్పుడు సురక్షితంగా బయటపడండి.", "మీ వణుకుతున్న వాయిస్ ఇప్పటికీ నిజం చెప్పగలదు. మీ చిన్న చర్య ఇప్పటికీ మరొక వ్యక్తి యొక్క విధిని మార్చగలదు. మీరు భయపడే బదులు విలువలతో వ్యవహరించే ప్రతిసారీ ధైర్యం పెరుగుతుంది. హీరోలు ఎలా కనిపించాలి అనే ఇమేజ్‌తో కాకుండా మీకు చెందిన ధైర్యమైన ఎంపికతో ప్రారంభించండి.", "మీ వాయిస్ వణుకుతున్నప్పుడు, నేను దానిని విన్నానని గుర్తుంచుకోండి. కోపం లేకుండా ధర్మం కోసం నిలబడండి మరియు క్రూరత్వం లేకుండా రక్షించండి."),
        reflection = "ఆలస్యం చేయమని భయపడి మిమ్మల్ని అడుగుతున్న సరైన చర్య ఏమిటి?",
        nextStep = "మీ ప్లాన్‌ని ఒక సురక్షితమైన వ్యక్తికి చెప్పండి, ఆపై సరైన చర్య కోసం ఒక ప్రశాంతమైన మరియు బాధ్యతాయుతమైన అడుగు వేయండి."
    ),
    "ready-to-grow" to KrishnaLetterTranslation(
        situation = "మీరు ఎదగడానికి సిద్ధంగా ఉన్నప్పుడు",
        title = "మీరు ఎక్కడ ప్రారంభించారో అసహ్యించుకోకుండా కాంతి వైపు పయనించండి",
        preview = "ఎదుగుదల నిజాయితీగా స్వీయ-చూడడం, ఓపిక పట్టడం మరియు ఒక సమయంలో ఒక ఉత్తమ ఎంపికతో ప్రారంభమవుతుంది. మీరు మార్చవలసిన వాటిని దాచడం మానేసినప్పుడు",
        paragraphs = listOf("వృద్ధి ప్రారంభమవుతుంది. మీ బలహీనమైన ప్రదేశాల గురించి సిగ్గుపడకండి. వాటిని స్పష్టంగా చూడండి మరియు ఓపికగా పని చేయండి. విత్తనం చిన్నదన్నందుకు తనను తాను ద్వేషించదు. ఇది కేవలం కాంతి వైపు చేరుతూనే ఉంటుంది.", "మిమ్మల్ని మీరు నిరుపయోగంగా పిలవకుండా ఉపయోగకరమైన దిద్దుబాటును అంగీకరించండి. గురువు, పెద్ద లేదా విశ్వసనీయ గురువు నుండి నేర్చుకోండి. ఏది కష్టమైనదో ఆచరించండి. మీ మనస్సు, శరీరం లేదా పాత్రను బలహీనపరిచే అలవాట్లను వదిలివేయండి. మీరు ఈ రాత్రికి ప్రతిదీ మార్చవలసిన అవసరం లేదు; మీరు ఈ రోజు ఒక నిజాయితీ వాగ్దానాన్ని నిలబెట్టుకోవాలి.", "మీ వృద్ధిని మరొక వ్యక్తి ప్రయాణంతో పోల్చవద్దు. మీ ప్రారంభ స్థానం, విధులు మరియు వేగం మీ స్వంతం. నిజం, స్థిరమైన ప్రయత్నం మరియు మీ ఎంపికలు సృష్టించే మంచితో మిమ్మల్ని మీరు కొలవండి. ప్రతి క్రమశిక్షణతో కూడిన రాబడి మార్పు ఇప్పటికే జరుగుతోందని రుజువు.", "మీరు సిగ్గు లేకుండా మార్చాలనుకుంటున్న బలహీనతను నాకు తీసుకురండి. నేను పరిపూర్ణతను ఆశించను; నేను నిజాయితీ, అభ్యాసం మరియు ఇష్టపడే హృదయాన్ని అడుగుతున్నాను."),
        reflection = "ఏ అలవాటు లేదా బలహీనత ఓపికగా మరియు నిజాయితీగా పని చేయమని అడుగుతోంది?",
        nextStep = "మీరు ప్రతిరోజూ ఏడు రోజుల పాటు పునరావృతం చేయగల ఒక చిన్న అభ్యాసాన్ని ఎంచుకోండి మరియు నేటి మొదటి ప్రయత్నాన్ని గుర్తించండి."
    ),
    "walk-dharma" to KrishnaLetterTranslation(
        situation = "సరైన మార్గం ఒంటరిగా అనిపించినప్పుడు",
        title = "గుంపు లేకుండా కూడా ధర్మంలో నడవండి",
        preview = "ప్రజాదరణ త్వరగా మారవచ్చు; స్వచ్ఛమైన హృదయం యొక్క శాంతి మీతో ఉంటుంది.",
        paragraphs = listOf("కొన్నిసార్లు ధర్మం మిమ్మల్ని అందరూ అంగీకరించే వాటిని తిరస్కరించమని అడుగుతుంది. మోసం చేయడానికి, అబద్ధాలు చెప్పడానికి, వేధించడానికి, మీ శరీరానికి హాని కలిగించడానికి లేదా క్రూరమైన జోక్‌లో చేరడానికి నిరాకరించినందుకు మీరు నవ్వవచ్చు. ప్రేక్షకులు మీ విలువలను బలహీనత అని పిలువవచ్చు, ఎందుకంటే మీ ఎంపిక వారిని వారి స్వంతంగా పరిశీలించేలా చేస్తుంది.", "జనాదరణను సత్యంగా పొరబడకండి. మెల్లగా నడవండి, కానీ ఆమోదం పొందడానికి మీ పాత్రను వదులుకోకండి. లేదు అని స్పష్టంగా చెప్పండి. అవసరమైనప్పుడు వదిలివేయండి. పరిస్థితి సురక్షితంగా లేకుంటే సహాయం కోసం విశ్వసనీయ పెద్దలను లేదా బాధ్యత గల వ్యక్తిని అడగండి. ధర్మం కోసం నిలబడటం అంటే ప్రతి ప్రమాదాన్ని ఒంటరిగా ఎదుర్కోవడం కాదు.", "మీ ఆరోగ్యం, నిజాయితీ మరియు భవిష్యత్తును గౌరవించే స్నేహితులను ఎంచుకోండి. అర్థం కాని వారితో ఓపికగా ఉండండి, కానీ మీ దిశను వారికి అప్పగించవద్దు. వేరుగా నిలబడి అసౌకర్యం దాటిపోతుంది; మీ విలువలను కాపాడుకునే శక్తి మీతో పాటు ప్రయాణిస్తుంది.", "సరైన రహదారి ఒంటరిగా అనిపిస్తే, నా చేయి తీసుకోండి. త్వరిత ఆమోదం కోసం మీ విలువలను వ్యాపారం చేయవద్దు."),
        reflection = "ఇతరులు ఆమోదించనప్పటికీ మీరు ఏ విలువను రక్షించాలి?",
        nextStep = "మీ స్పష్టమైన 'నో'ను ఒక వాక్యంలో వ్రాసి, మీకు మద్దతు ఇచ్చే విశ్వసనీయ వ్యక్తితో దాన్ని భాగస్వామ్యం చేయండి."
    ),
    "dream-discipline" to KrishnaLetterTranslation(
        situation = "మీ కలకి క్రమశిక్షణ అవసరమైనప్పుడు",
        title = "రోజువారీ అభ్యాసం కలలు కనేలా చేయనివ్వండి",
        preview = "సాధారణ రోజులలో ఉంచిన ఏకాగ్రత, తెలివైన పద్ధతులు మరియు వాగ్దానాల ద్వారా కల నిజమవుతుంది.",
        paragraphs = listOf("కోరికల ద్వారా మాత్రమే కల ఎదగదు. దీనికి మీ సమయం, దృష్టి మరియు స్థిరమైన కృషి అవసరం. కొన్ని రోజులు మీరు స్ఫూర్తిని అనుభవిస్తారు; ఇతర రోజుల్లో మీరు చేయరు. రెండింటిలోనూ నిజాయితీగా పని చేయండి. ఉత్సాహం నిశ్శబ్దంగా మారిన తర్వాత మీరు పాటించే వాగ్దానం క్రమశిక్షణ.", "తెలివిగా ప్లాన్ చేయండి. ఒక పరధ్యానాన్ని తీసివేయండి, పనిని స్పష్టమైన భాగాలుగా విభజించండి మరియు మార్గాన్ని అర్థం చేసుకునే వ్యక్తుల నుండి నేర్చుకోండి. మీ శరీరానికి అవసరమైనప్పుడు విశ్రాంతి తీసుకోండి, కానీ మీ శాశ్వత నివాసంగా ఉండకండి. స్మార్ట్ వర్క్ అంటే మీ పద్ధతిని తనిఖీ చేయడం, ఫీడ్‌బ్యాక్‌ని అంగీకరించడం మరియు అలసిపోయే బదులు మెరుగుపరచడం.", "తుది ఫలితం గురించి చింతిస్తూ నేటి శక్తిని వృధా చేసుకోకండి. మీ ముందున్న కర్తవ్యానికి మీ పూర్తి హృదయాన్ని ఇవ్వండి. నైపుణ్యం, ఓర్పు మరియు వినయంతో దానిని మోయగల వ్యక్తిగా ఎదగడానికి మీరు సిద్ధంగా ఉన్నారా అని మీ కల అడుగుతోంది.", "మీ కలను నాకు అందించండి, నేటి పని ద్వారా దానిని గౌరవించండి. నేను ప్రకాశవంతమైన స్ఫూర్తితో మాత్రమే కాకుండా ఎవరూ చూడని నిశ్శబ్ద అభ్యాసంలో కూడా మీతో ఉన్నాను."),
        reflection = "ప్రేరణ లేనప్పుడు కూడా మీ కలను ఏ రోజువారీ అభ్యాసం మరింత బలపరుస్తుంది?",
        nextStep = "ఈరోజు ఒక ఫోకస్డ్ పని వ్యవధిని షెడ్యూల్ చేయండి, ఒక పరధ్యానాన్ని తీసివేసి, స్పష్టమైన పనిని పూర్తి చేయండి."
    ),
    "valuable-gift" to KrishnaLetterTranslation(
        situation = "మీరు ఏమి ఇవ్వగలరు అని మీరు ఆలోచిస్తున్నప్పుడు",
        title = "ప్రపంచానికి మీరు అందించే మంచి అవసరం",
        preview = "సేవలో ఉపయోగించినప్పుడు మీ సమయం, నైపుణ్యం, శ్రద్ధ మరియు దయ పవిత్రంగా మారతాయి.",
        paragraphs = listOf("మీరు అందించడానికి విలువైనది ఏమీ లేదని ఎప్పుడూ నమ్మరు. మీకు గొప్ప సంపద లేదా ప్రభావం ఉండకపోవచ్చు, కానీ మీకు శ్రద్ధ, సమయం, నైపుణ్యాలు, దయ మరియు ధైర్యం ఉన్నాయి. ఓపికగా వినేవాడు ఒంటరి హృదయాన్ని తేలికపరచగలడు. ఒక ధైర్యమైన వాయిస్ ఒకరిని హాని నుండి రక్షించగలదు.", "మీకు ఏది సహజంగా వస్తుందో మరియు మీరు బాగా నేర్చుకోవడానికి ఇష్టపడే వాటిని గమనించండి. మీ బహుమతి బోధించడం, నిర్మించడం, శ్రద్ధ వహించడం, నిర్వహించడం, సృష్టించడం, వినడం లేదా ఇతరులు నివారించే సమస్యను పరిష్కరించడం. అభ్యాసం ద్వారా దాన్ని బలోపేతం చేయండి, ఆపై ప్రశంసలను మాత్రమే ఆకర్షించడం కంటే ఇది నిజంగా సహాయపడే చోట అందించండి.", "మరొక వ్యక్తి భిన్నంగా ప్రకాశిస్తున్నందున మీ కాంతిని దాచవద్దు. వారి బహుమానం మీ బహుమతిని తగ్గించదు. గర్వం లేకుండా మీ సామర్థ్యాన్ని అందించండి మరియు సిగ్గు లేకుండా దిద్దుబాటును స్వీకరించండి. ప్రతిభ తన స్వంత వ్యక్తిని మించి జీవితాన్ని పైకి లేపినప్పుడు అది అర్థవంతమవుతుంది.", "నేను మీలో ఉపయోగకరమైనదాన్ని ఉంచాను మరియు అది మరొక వ్యక్తి బహుమతిగా కనిపించాల్సిన అవసరం లేదు. దీన్ని బాగా నేర్చుకోండి, గర్వం లేకుండా అందించండి మరియు జీవితానికి సేవ చేయనివ్వండి."),
        reflection = "మీలోని ఏ సామర్థ్యం లేదా నాణ్యత మీకు మించిన వారికి సేవ చేయగలదు?",
        nextStep = "బోధించడానికి, రక్షించడానికి, సహాయం చేయడానికి లేదా ఉపయోగకరమైనదాన్ని సృష్టించడానికి ఈ వారం ముప్పై నిమిషాల పాటు ఒక బహుమతిని ఉపయోగించండి."
    ),
    "future-still-open" to KrishnaLetterTranslation(
        situation = "ఒక ఫలితం మీ భవిష్యత్తును మూసివేసినప్పుడు",
        title = "మీ భవిష్యత్తు ఒక ఫలితం కంటే పెద్దది",
