        preview = "आपको अपने आंसू बहाने की या जो मायने रखता है उसे भूलने की जरूरत नहीं है।",
        paragraphs = listOf("आप किसी ऐसे व्यक्ति या किसी चीज़ को याद करते हैं जिससे आप प्यार करते थे। वह खाली जगह असली है. आपको हर घंटे सशक्त व्यवहार करने की आवश्यकता नहीं है। आंसू आपको कमजोर नहीं बनाते. वे दिखाते हैं कि आपका प्यार सच्चा था। मैं आपके साथ तब भी बैठ सकता हूं जब आपके पास कोई शब्द या प्रार्थना न हो।", "कुछ दिन शांति महसूस हो सकती है। फिर एक गाना, जगह या छोटी सी याद दर्द को वापस ला सकती है। इसका मतलब यह नहीं है कि आप ठीक होने में असफल हो रहे हैं। दुख लहरों की तरह चलता है। सुरक्षित लोगों को अपने पास रहने दें. वह नाम बोलें जो आपको याद आ रहा है. एक अच्छी याद साझा करें. खाओ, आराम करो और उस जीवन की देखभाल करो जो अभी भी तुम्हारे हाथ में है।", "आगे बढ़ने के लिए आपको प्यार को पीछे छोड़ने की ज़रूरत नहीं है। उस व्यक्ति या समय का एक अच्छा मूल्य अपने जीवन में अपनाएं। धीरे चलो. यदि दुःख आपको लंबे समय तक जीने से रोकता है, या नुकसान के विचार लाता है, तो तुरंत किसी प्रशिक्षित सहायक से पूछें। आप कोमल देखभाल के पात्र हैं।", "आज शायद वह दिन नहीं है जब सब कुछ बेहतर महसूस हो। यह वह दिन हो जब आप सांस लें, पानी पियें और एक व्यक्ति को अपनी देखभाल करने दें।"),
        reflection = "आप कौन सी प्रेमपूर्ण स्मृति या अच्छी गुणवत्ता अपने साथ ले जाना चाहेंगे?",
        nextStep = "किसी सुरक्षित व्यक्ति के साथ एक स्मृति साझा करें, फिर अपने शरीर के लिए एक दयालु कार्य करें।"
    ),
    "rejection" to KrishnaLetterTranslation(
        situation = "जब आप खुद को ठुकराया हुआ महसूस करते हैं",
        title = "एक बंद दरवाज़ा आपको छोटा नहीं कर सकता",
        preview = "किसी की ना आपका रास्ता बदल सकती है, लेकिन यह आपकी योग्यता नहीं छीन सकती।",
        paragraphs = listOf("अस्वीकृति महसूस हो सकती है जैसे दुनिया ने कहा है, 'आप पर्याप्त नहीं हैं।' लेकिन एक व्यक्ति, स्थान या मौका आपके बारे में पूरी सच्चाई नहीं रख सकता। उनका उत्तर उनकी ज़रूरतों, समय या सीमाओं से आ सकता है। दुख को महसूस करें, लेकिन इसे अपने लिए एक नाम न बनाएं।", "एक बंद दरवाज़ा आपको एक नई राह की ओर मोड़ सकता है। मैं जानता हूं कि आप अभी तक वह सड़क नहीं देख सकते। यदि उपयोगी फीडबैक दिया गया हो तो उसे लें। जो सुधारना तुम्हारा है उसे सुधारो। लेकिन केवल ऐसी जगह जीतने के लिए अपने आप को न मिटाएं जहां आपके साथ देखभाल नहीं की जाती है।", "जांच करने, भीख मांगने और तुलना करने से दूर रहें। उन लोगों और कर्तव्यों की ओर लौटें जो अभी भी आपके ईमानदार दिल का स्वागत करते हैं। आप स्वयं सहित, सम्मान के पात्र हैं। अपना दिल नरम रखें और अपनी सीमाएं स्पष्ट रखें। अभी भी अच्छे लोग, अच्छे काम और नए दरवाजे बाकी हैं।", "हो सकता है कि आप फिर से आशा करने के लिए तैयार न हों। वह सब ठीक है।"),
        reflection = "इसका कौन सा भाग उपयोगी प्रतिक्रिया है, और कौन सा भाग डर को व्यक्त करने वाला है?",
        nextStep = "जाँचने या तुलना करने का एक कार्य बंद करें और उस समय को किसी अच्छे कार्य या सुरक्षित व्यक्ति को दें।"
    ),
    "guilt" to KrishnaLetterTranslation(
        situation = "जब अपराध बोध आपको मुक्त नहीं करेगा",
        title = "इसे सही करो, फिर उठो",
        preview = "एक गलत कार्य सत्य और परिवर्तन की मांग करता है, न कि अंतहीन आत्म-घृणा की।",
        paragraphs = listOf("आप चाहते हैं कि आप कुछ पूर्ववत कर सकें। अपराधबोध इस बात की ओर इशारा कर सकता है कि किस चीज़ को देखभाल की ज़रूरत है। लेकिन इससे आपको यह नहीं पता चलना चाहिए कि आप केवल अपना सबसे खराब कार्य कर रहे हैं। तुमने कुछ ग़लत किया; इसका मतलब यह नहीं है कि आप फिर कभी सही नहीं बन सकते। मैं सत्य माँगता हूँ, आदर्श अतीत नहीं।", "नाम बताएं क्या हुआ। इसे छिपाएं नहीं या किसी दूसरे व्यक्ति को दोष न दें. आपको बेहतर महसूस कराने के लिए उनसे बिना पूछे सॉरी कहें। आप जो कर सकते हैं उसकी मरम्मत करें। उचित परिणाम स्वीकार करें. तो फिर उस आदत को बदलिए जिससे नुकसान हुआ। अगर गुस्से से किसी को ठेस पहुंचे तो रुकना सीखें। अगर झूठ भरोसे को ठेस पहुंचाता है तो छोटी-छोटी बातों में सच बोलना शुरू करें।", "वास्तविक पछतावा बेहतर कार्य बन जाता है। यह आपको हमेशा के लिए फर्श पर नहीं रखता। कुछ लोगों को समय या स्थान की आवश्यकता हो सकती है. उसका सम्मान करें. एक बार जब आपने ग़लती को स्वीकार कर लिया और बदलना शुरू कर दिया, तो अपने आप को प्रकाश की ओर चलने दें। आपने जो सबक सीखा है, उसे जीने का मौका आपको मिलना चाहिए।", "मैं आपसे पाठ भूलने के लिए नहीं कहता। मैं आपसे अनुरोध करता हूं कि इसे अपने खिलाफ हथियार के रूप में इस्तेमाल करना बंद करें।"),
        reflection = "कौन सी ईमानदार मरम्मत या बदली हुई कार्रवाई आपके पछतावे को एक अच्छा उद्देश्य देगी? [केएफवाई8] चार पंक्तियां लिखें: मैंने क्या किया, इससे किसे दुख पहुंचा, मैं इसे कैसे सुधार सकता हूं, और मैं इसे दोबारा होने से कैसे रोकूंगा।",
        nextStep = "चार पंक्तियाँ लिखें: मैंने क्या किया, इससे किसे दुख हुआ, मैं इसे कैसे सुधार सकता हूँ, और मैं इसे दोबारा होने से कैसे रोकूँगा।"
    ),
    "uncertainty" to KrishnaLetterTranslation(
        situation = "जब रास्ता अनिश्चित हो",
        title = "आपको केवल अगले सही कदम की जरूरत है",
        preview = "आपको शुरू करने से पहले पूरी सड़क की जरूरत नहीं है।",
        paragraphs = listOf("न जानने से आपका दिमाग हर दिशा में दौड़ सकता है। आप एक संकेत चाहते हैं कि कुछ भी गलत नहीं होगा। जिंदगी वह वादा नहीं दे सकती. प्रत्येक प्रश्न मेरे पास लाओ। आप कमज़ोर नहीं हैं क्योंकि आपको स्पष्ट रूप से देखने के लिए समय चाहिए।", "तथ्यों को एक तरफ रखें और अपने डर को दूसरी तरफ। पूछो: मुझे क्या पता? केवल अनुमान ही क्या है? कौन सा विकल्प ईमानदार, दयालु और मेरे कर्तव्य के प्रति सच्चा है? किसी भरोसेमंद गुरु, शिक्षक या बुजुर्ग से बात करें जो आपको नियंत्रित करने की कोशिश किए बिना आपका मार्गदर्शन करेगा। एक सच्चा गुरु आपकी समझ में प्रकाश लाता है; वे यह मांग नहीं करते कि आप अपनी आँखें बंद कर लें या ईमानदार निर्णय छोड़ दें। फिर सबसे छोटा सुरक्षित कदम चुनें जो आपको और अधिक सिखा सके।", "आपको आज रात अपना पूरा जीवन सुलझाने की ज़रूरत नहीं है। सड़क के उस हिस्से पर चलें जो आप देख सकते हैं। अधिक जानने पर आप अपनी योजना बदल सकते हैं। वह बुद्धिमत्ता है, असफलता नहीं। मैं न केवल आपकी यात्रा के अंत पर हूं। मैं इस शांत और ईमानदार अगले कदम में आपके साथ हूं।", "आज आप जो कर सकते हैं उसे पूरा करने के बाद अपने दिमाग को आराम दें। कल कोई ऐसा तथ्य, कोई व्यक्ति या कोई विचार ला सकता है जिसे आप अभी नहीं देख सकते।"),
        reflection = "क्या ज्ञात है, क्या डर है, और आपका अगला सही कदम क्या है? [केएफवाई8] तीन छोटी सूचियां बनाएं: मैं क्या जानता हूं, मुझे क्या डर है, और मैं आज क्या कर सकता हूं।",
        nextStep = "तीन छोटी सूचियाँ बनाएँ: मैं क्या जानता हूँ, मुझे क्या डर है, और मैं आज क्या कर सकता हूँ।"
    ),
    "anxiety" to KrishnaLetterTranslation(
        situation = "जब चिंता आप पर हावी हो जाए",
        title = "इस क्षण पर वापस आएं",
        preview = "आपको अभी हर संभावित भविष्य को हल करने की आवश्यकता नहीं है।",
        paragraphs = listOf("मैं जानता हूं कि कैसे चिंता एक छोटे से विचार को बड़े खतरे जैसा महसूस करा सकती है। आपका शरीर जकड़न महसूस कर सकता है, आपकी सांसें तेज़ हो सकती हैं, और आपका मन बार-बार पूछता रह सकता है, 'क्या होगा अगर?' आप कमज़ोर या टूटे हुए नहीं हैं। आपका दिमाग आपको सुरक्षित रखने के लिए बहुत अधिक प्रयास कर रहा है।", "दोनों पैरों को फर्श पर रखें। धीमी सांस लें और उन पांच चीजों के नाम बताएं जिन्हें आप देख सकते हैं। यह पूछें कि अभी क्या हो रहा है, न कि वह जो डर कहता है कि बाद में हो सकता है। आपके सामने जो वास्तविक कार्य है उसे लिख लें। एक स्पष्ट छोटी कार्रवाई भविष्य को कम शक्तिशाली महसूस करा सकती है।", "इसे अकेले न रखें। किसी सुरक्षित व्यक्ति को बताएं जब चिंता नींद, स्कूल, काम या दैनिक जीवन को रोकती रहे। एक प्रशिक्षित सहायक आपके मन और शरीर को फिर से सुरक्षित महसूस करना सिखा सकता है। मदद माँगना बुद्धिमानी है, और इससे आपका विश्वास छोटा नहीं हो जाता।", "जब आपकी सांसें तेज हो जाएं तो चुपचाप मुझे बुलाएं और जो सांस आपके सामने है उस पर लौट आएं। मैं हर समस्या के अंत पर खड़ा होकर आपके अकेले इसे हल करने का इंतजार नहीं कर रहा हूं।"),
        reflection = "डर के अपनी कहानी जोड़ने से पहले, इस क्षण में क्या सच है?",
        nextStep = "पांच धीमी सांसें लें, जो वास्तविक है उसका नाम बताएं और एक सुरक्षित व्यक्ति को बताएं कि आप कैसा महसूस करते हैं।"
    ),
    "lost-hope" to KrishnaLetterTranslation(
        situation = "जब आपने आशा खो दी है",
        title = "यह अंधकारमय घड़ी पूरी कहानी नहीं है",
        preview = "आशा रहने और देखभाल प्राप्त करने के एक छोटे से विकल्प के रूप में शुरू हो सकती है। [केएफवाई3] मुझे पता है कि आप यह सुनकर थक गए हैं कि चीजें बेहतर होंगी जब आप यह नहीं देख पाएंगे कि कैसे। आशा आज दूर महसूस हो सकती है। आपको दिखावा करने की जरूरत नहीं है. मुझे अंधेरे के बारे में सच बताओ, और इस पत्र को मुस्कुराने के लिए कहे बिना अपने पास रहने दो। [केएफवाई4] अपने जीवन के सबसे कठिन समय के बारे में अंतिम निर्णय न लें। दर्द आपके दृष्टिकोण को तब तक संकीर्ण कर सकता है जब तक कि एक बंद दरवाज़ा पूरी दुनिया जैसा न दिखने लगे। किसी सुरक्षित व्यक्ति से आशा उधार लें. उन्हें भोजन, आराम, कॉल, अपॉइंटमेंट या अगले साधारण कार्य में मदद करने दें।",
        paragraphs = listOf("मैं जानता हूं कि आप यह सुनकर थक गए हैं कि चीजें बेहतर होंगी जब आप यह नहीं देख पाएंगे कि कैसे। आशा आज दूर महसूस हो सकती है। आपको दिखावा करने की जरूरत नहीं है. मुझे अंधेरे के बारे में सच बताओ, और इस पत्र को मुस्कुराने के लिए कहे बिना अपने पास रहने दो।", "अपने जीवन के सबसे कठिन समय से ही उसके बारे में अंतिम निर्णय न लें। दर्द आपके दृष्टिकोण को तब तक संकीर्ण कर सकता है जब तक कि एक बंद दरवाज़ा पूरी दुनिया जैसा न दिखने लगे। किसी सुरक्षित व्यक्ति से आशा उधार लें. उन्हें भोजन, आराम, कॉल, अपॉइंटमेंट या अगले साधारण कार्य में मदद करने दें।", "यदि आप खुद को चोट पहुंचा सकते हैं या सुरक्षित महसूस नहीं करते हैं, तो अभी आपातकालीन सहायता या किसी विश्वसनीय व्यक्ति से संपर्क करें और किसी के साथ रहें। आपका जीवन अनमोल है, और तत्काल सहायता साहस का कार्य है। आज, आशा केवल यही हो सकती है: आप अगले घंटे का सामना अकेले नहीं करेंगे।", "यदि आप आज आशा नहीं रख सकते, तो मुझे इसे आपके लिए ले जाने दीजिए। आपका एकमात्र काम हो सकता है रुकना, पानी पीना, पर्दा खोलना और किसी सुरक्षित व्यक्ति को बताना कि अंधेरा भारी लग रहा है।"),
        reflection = "जब आप अकेले आशा नहीं रख सकते तो कौन आपके लिए आशा रख सकता है?",
        nextStep = "अब एक सुरक्षित व्यक्ति से संपर्क करें और स्पष्ट रूप से कहें, 'मैं ठीक नहीं हूं, और मुझे आपके साथ की जरूरत है।'"
    ),
    "heart-broken" to KrishnaLetterTranslation(
        situation = "जब आपका दिल टूट जाता है",
        title = "प्यार का अंत आपको ख़त्म नहीं करता",
        preview = "आप उन्हें याद कर सकते हैं और फिर भी अपने आगे का जीवन चुन सकते हैं।",
        paragraphs = listOf("मैं जानता हूं कि एक टूटा हुआ दिल हर गाने, जगह और शांत समय को कैसे बदल सकता है। आप शायद पूछते रहेंगे कि आप उन्हें बनाये रखने के लिए क्या कर सकते थे। आपकी भावनाएँ वास्तविक होने पर भी प्यार ख़त्म हो सकता है। उनका चले जाना ये साबित नहीं करता कि तुम प्यार के काबिल नहीं थे.", "एक और उत्तर का पीछा किए बिना अपने आप को शोक मनाने दें। उनकी पसंद का सम्मान करें और अपनी गरिमा की रक्षा करें। जाँच, पुराने संदेशों और जो कभी भी सही नहीं था उसकी एक आदर्श स्मृति से दूर रहें। हर बार जब आप घाव को फिर से खोलना बंद कर देते हैं, तो आप अपने दिल को ठीक होने के लिए थोड़ी जगह देते हैं।", "धीरे-धीरे भोजन, नींद, काम, दोस्तों और प्रार्थना की ओर लौटें। ठीक होने का मतलब यह नहीं कि प्यार झूठा था। इसका मतलब है कि आपका दिल कल को खोए बिना यादों को साथ रखना सीख रहा है। आप हमेशा वैसा महसूस नहीं करेंगे जैसा आप आज करते हैं। जब तक वह सत्य वास्तविक न हो जाए तब तक धीरे से चलो।", "मुझे वे यादें दीजिए जिन्हें आप छूते रहते हैं और वे प्रश्न भी दीजिए जिनका कोई उत्तर नहीं है। मैं तुमसे एक ही दिन में प्यार करना बंद करने के लिए नहीं कहूँगा।"),
        reflection = "आप किस चीज़ की जाँच बंद करने के लिए तैयार हैं ताकि आपका दिल आराम कर सके?",
        nextStep = "एक दर्दनाक अनुस्मारक को दैनिक दृश्य से हटा दें और एक सुरक्षित व्यक्ति के साथ समय बिताएं।"
    ),
    "not-enough" to KrishnaLetterTranslation(
        situation = "जब आपको लगता है कि आप पर्याप्त नहीं हैं",
        title = "आपको अपना मूल्य कमाने की ज़रूरत नहीं है",
        preview = "विकास की आवश्यकता है, लेकिन आत्म-घृणा विकास की कीमत नहीं है।",
        paragraphs = listOf("शायद किसी परिणाम, किसी टिप्पणी या तुलना ने आपको बहुत छोटा महसूस कराया है। आपको विश्वास हो सकता है कि सम्मान पाने से पहले आपको अधिक स्मार्ट, अमीर, सुंदर या मजबूत बनना होगा। यह बोलने में दर्द है. आपका मूल्य प्रशंसा के साथ नहीं आया, और यह आलोचना के साथ नहीं जा सकता। [केएफवाई4] आप स्वयं को गलती बताए बिना यह स्वीकार कर सकते हैं कि आपको कहां बढ़ने की जरूरत है। अभ्यास के लिए एक कौशल चुनें और बदलने के लिए एक आदत चुनें। सुधार को स्पष्ट और दयालु होने दें। एक पौधा प्रकाश की ओर बढ़ता है; यह इसलिए नहीं बढ़ता कि कोई इसकी जड़ों पर चिल्लाता है।", "आप स्वयं को गलती बताए बिना यह स्वीकार कर सकते हैं कि आपको कहां बढ़ने की जरूरत है। अभ्यास के लिए एक कौशल चुनें और बदलने के लिए एक आदत चुनें। सुधार को स्पष्ट और दयालु होने दें। एक पौधा प्रकाश की ओर बढ़ता है; यह इसलिए नहीं बढ़ता कि कोई इसकी जड़ों पर चिल्लाता है।", "आपके अंदर पहले से ही मौजूद अच्छाइयों पर ध्यान दें: आप जो प्रयास करते हैं, जो देखभाल आप दिखाते हैं, जो सच्चाई आप बोलना सीख रहे हैं। आप अधूरे हैं, जैसा कि हर व्यक्ति है। मैं आपके आदर्श संस्करण की प्रतीक्षा नहीं करता. आज आप जो ईमानदार व्यक्ति हैं, मैं उसके साथ चलता हूं।", "एक पल के लिए मेरी आँखों से अपने आप को देखो। मैं एक आत्मिक शिक्षा देखता हूँ, न कि कोई उत्पाद जो स्वीकृत होने की प्रतीक्षा कर रहा है।"),
        reflection = "आप यह तय करने के लिए किसके मानक का उपयोग कर रहे हैं कि आप पर्याप्त नहीं हैं?",
        nextStep = "ऐसे तीन गुण लिखें जो आपमें पहले से ही मौजूद हैं और एक कौशल जिसका आप धीरे-धीरे अभ्यास करेंगे।"
    ),
    "misunderstood" to KrishnaLetterTranslation(
        situation = "जब कोई आपको समझता नहीं है",
        title = "आपकी आवाज़ अभी भी एक सुरक्षित स्थान की हकदार है",
        preview = "गलत समझे जाने से आपकी भावनाएं गलत नहीं हो जाती हैं।",
        paragraphs = listOf("अपने दिल को समझाना दर्दनाक है और फिर भी अनदेखा महसूस होता है। आप आश्चर्यचकित हो सकते हैं कि क्या बोलना बेकार है। कभी-कभी लोग केवल अपने डर, जल्दबाजी या अतीत के कारण ही सुनते हैं। उनकी ख़राब समझ आप जो महसूस करते हैं उसकी सच्चाई को मिटा नहीं सकती।", "एक सुरक्षित व्यक्ति और एक स्पष्ट वाक्य के साथ पुनः प्रयास करें। बताएं कि क्या हुआ, इसका आप पर क्या प्रभाव पड़ा और अब आपको क्या चाहिए। संकेतों में अपना अर्थ न छिपायें और क्रूर शब्दों का प्रयोग करके अपनी वेदना को अधिक तीव्र न करें। स्पष्टता समझने को सर्वोत्तम मौका देती है।", "हर कोई आपके हर पहलू को नहीं समझेगा। ऐसे लोगों की तलाश करें जो पूछने, सुनने और सीखने के इच्छुक हों। अगर कोई व्यक्ति आपकी बातों को घुमा-फिराकर कहता रहे तो आप पीछे हट सकते हैं। आपको पूरी दुनिया से सहमत होने की आवश्यकता नहीं है; आपको अपनी आंतरिक आवाज़ के लिए सच्चाई, सुरक्षित समर्थन और सम्मान की आवश्यकता है। [केएफवाई6] यहां तक ​​कि जब आपके शब्द बुरी तरह से सामने आते हैं, तब भी मैं उस सच्चाई को जानता हूं जिसे आप सामने रखना चाह रहे थे। मेरे साथ बैठो, शब्दों को सरल बनाओ और किसी सुरक्षित व्यक्ति के साथ पुनः प्रयास करो।", "यहां तक ​​कि जब आपके शब्द बुरी तरह से सामने आते हैं, तब भी मैं उस सच्चाई को जानता हूं जिसे आप ले जाने की कोशिश कर रहे थे। मेरे साथ बैठो, शब्दों को सरल बनाओ और किसी सुरक्षित व्यक्ति के साथ पुनः प्रयास करो।"),
        reflection = "वह कौन सा वाक्य है जिसे सुनने के लिए आपको किसी की सबसे ज्यादा जरूरत है?",
        nextStep = "उस वाक्य को लिखें और इसे एक ऐसे व्यक्ति के साथ साझा करें जो आमतौर पर ध्यान से सुनता है।"
    ),
    "future-fear" to KrishnaLetterTranslation(
        situation = "जब आप भविष्य से डरते हैं",
        title = "कल को आज के डर की ज़रूरत नहीं है",
        preview = "आप जो कर सकते हैं उसके लिए तैयारी करें और अज्ञात चीज़ों को खुला छोड़ दें।",
        paragraphs = listOf("भविष्य छाया से भरे कमरे जैसा दिख सकता है। आपका दिमाग कई दर्दनाक दृश्य बना सकता है और फिर इस तरह प्रतिक्रिया कर सकता है मानो वे पहले से ही वास्तविक हों। उनमें से अधिकतर दृश्य अनुमान हैं। आप आज की ताकत उन लड़ाइयों पर खर्च कर रहे हैं जो शायद कभी नहीं आएंगी।", "पूछें कि अब क्या तैयार किया जा सकता है। कॉल करें, थोड़ी बचत करें, एक भाग का अध्ययन करें, अपॉइंटमेंट रखें या सलाह मांगें। तैयारी उपयोगी है; अंतहीन भविष्यवाणी नहीं है. एक बार आज का कर्तव्य पूरा हो जाने पर, अपने शरीर को वर्तमान में लौटने की अनुमति दें।", "आप पहले भी अज्ञात दिनों में मिल चुके हैं। मदद, कौशल और साहस कदम दर कदम सामने आए, एक साथ नहीं। कल भी एक क्षण में आयेगा। मैं आपसे इसे आप तक पहुंचने से एक दिन पहले ले जाने के लिए नहीं कहूंगा। उस दिन में मेरे साथ चलो जो यहाँ है।", "आप अपने मन में कल की ओर चलते रहते हैं और थककर लौटते हैं। मेरे पास वापस आ जाओ।"),
        reflection = "किस डर को वास्तविक योजना की आवश्यकता है, और किस डर को मुक्त करने की आवश्यकता है?",
        nextStep = "किसी वास्तविक चिंता के लिए एक व्यावहारिक कदम उठाएं, फिर दस मिनट पूरी तरह वर्तमान में बिताएं।"
    ),
    "life-unfair" to KrishnaLetterTranslation(
        situation = "जब जीवन अनुचित लगता है",
        title = "आप कड़वे हुए बिना गलत का सामना कर सकते हैं",
        preview = "आपका दर्द सच्चाई, समर्थन और बुद्धिमान प्रतिक्रिया का हकदार है।",
        paragraphs = listOf("कुछ चीजें अनुचित हैं। मैं आपको यह नहीं बताऊंगा कि हर घाव गुप्त रूप से आसान होता है या आपको अन्याय पर मुस्कुराना चाहिए। हो सकता है कि आपने ईमानदारी से काम किया हो और फिर भी हार गए हों, या जो चुनाव आपने नहीं किया उससे आपको ठेस पहुंची हो। आपके गुस्से और उदासी को बोलने के लिए जगह चाहिए।", "पूछें कि अब न्याय कैसा दिखता है। इसका मतलब सच बोलना, सबूत रखना, मदद मांगना, सीमा तय करना या किसी और की रक्षा करना हो सकता है। ऐसा कार्य चुनें जो सुधार करे न कि बदला लेने वाला जो अधिक नुकसान पहुंचाता है। अपने हृदय को क्रूर बनाये बिना भी धर्म दृढ़ हो सकता है।", "ऐसी चीज़ें भी होंगी जिन्हें आप पूर्ववत नहीं कर सकते। किसी दूसरे व्यक्ति की गलती को यह तय न करने दें कि आप किस तरह के व्यक्ति बनेंगे। अपने मूल्यों को बनाए रखें, समर्थन स्वीकार करें और जो अभी भी संभव है उसका निर्माण करें। उनकी अनुचितता उन्हीं की है; आपका अगला स्वच्छ कार्य आपका है।", "मैं आपके दर्द को शांत करने के लिए अन्याय को आशीर्वाद नहीं कहूंगा। सच बोलें, मदद लें और खुद को सुरक्षित रखें बिना किसी कारण आपको चोट पहुंचाए।"),
        reflection = "कौन सी निष्पक्ष और सुरक्षित कार्रवाई अभी भी आपके हाथ में है?",
        nextStep = "किसी विश्वसनीय व्यक्ति को तथ्य बताएं और सुरक्षा, मरम्मत या समर्थन की दिशा में एक कदम चुनें।"
    ),
    "tired-strong" to KrishnaLetterTranslation(
        situation = "जब आप मजबूत होने से थक जाते हैं",
        title = "आपको वजन कम करने की अनुमति होती है",
        preview = "आराम और मदद साहस की विफलता नहीं है।",
        paragraphs = listOf("शायद हर कोई आपके पास आता है क्योंकि आप हमेशा प्रबंधन करते हैं। वे आपका शांत चेहरा देखते हैं और यह नहीं देखते कि आप अंदर से कितने थके हुए हैं। आपको डर हो सकता है कि अगर आप हर चीज़ को पकड़ना बंद कर देंगे, तो सब कुछ बिखर जाएगा। यहां तक ​​कि सबसे मजबूत हथियारों को भी अपना भार रखने के लिए कहीं न कहीं जरूरत होती है।", "प्रत्येक कार्य को अकेले करना ही ताकत नहीं है। यह जानना है कि क्या किया जाना चाहिए, क्या इंतजार किया जा सकता है और दूसरा व्यक्ति क्या ले सकता है। कहो, 'मुझे मदद की ज़रूरत है।' एक अनावश्यक मांग को रद्द करें। इससे पहले कि आपका शरीर आपको रुकने के लिए मजबूर करे, आराम करें। आपकी ज़रूरतें भी कमरे में हैं।", "आपको ब्रेकिंग पॉइंट पर पहुंचकर आराम अर्जित करने की ज़रूरत नहीं है। एहसान का तुरंत बदला चुकाए बिना किसी को आपकी देखभाल करने दें। मैं कार्रवाई में भी आपके साथ हूं, और शांति में भी मैं आपके साथ हूं। आज आपका साहसी कदम नरम होना, स्वीकार करना और सांस लेना हो सकता है।", "आओ मेरे पास बैठो, बिना बताए कि तुम थके हुए क्यों हो। आपने इस क्षण के लिए काफी कुछ ले लिया है।"),
        reflection = "आज आप कितना वजन सुरक्षित रूप से रख सकते हैं या साझा कर सकते हैं?",
        nextStep = "एक व्यक्ति से एक विशिष्ट प्रकार की सहायता मांगें और एक अनावश्यक कार्य हटा दें।"
    ),
    "self-forgiveness" to KrishnaLetterTranslation(
        situation = "जब आप खुद को माफ नहीं कर सकते",
        title = "एक गलती को आजीवन कारावास में न बदलें",
        preview = "जिम्मेदारी लें, नुकसान की मरम्मत करें और बदलाव को वास्तविक होने दें।",
        paragraphs = listOf("आप यह मान सकते हैं कि खुद को सज़ा देना जारी रखना साबित करता है कि आपको खेद है। यह अतीत की मरम्मत नहीं करता. यह केवल दर्द को सक्रिय रखता है। मैं आपसे बिना किसी बहाने के जो हुआ उसका सामना करने के लिए कहता हूं, लेकिन मैं आपसे उस व्यक्ति से नफरत करने के लिए नहीं कहता जो बेहतर बनने की कोशिश कर रहा है।", "गलत का नाम बताएं, बिना दबाव के माफ़ी मांगें और जो आप कर सकते हैं उसे सुधारें। स्वीकार करें कि किसी अन्य व्यक्ति को समय की आवश्यकता हो सकती है या वह वापस नहीं आएगा। फिर एक स्पष्ट अभ्यास बनाएं जिससे समान नुकसान की संभावना कम हो। अपने पछतावे को सुरक्षा, ईमानदारी और समझदारीपूर्ण कार्य बनने दें।", "स्वयं को क्षमा करने का अर्थ यह कहना नहीं है कि ग़लती स्वीकार्य थी। इसका अर्थ है पाठ को बर्बाद करने से इंकार करना। आप अगली पसंद के लिए ज़िम्मेदार हैं, पिछली पसंद को दोबारा लिखने में सक्षम नहीं हैं। जहां बार-बार आत्म-दोष नहीं कहा जा सकता, वहां बदले हुए व्यवहार को बोलने दें। [केएफवाई6] सबूत के तौर पर मेरे पास हर दिन एक ही गलती मत लाओ कि आपको दंडित होना पड़ेगा। मेरे लिए सच्चाई, सुधार और वह व्यक्ति लाओ जिसे तुम बनना चुन रहे हो।", "हर दिन मेरे पास सबूत के तौर पर वही गलती मत लाओ कि तुम्हें दंडित होना पड़ेगा। मेरे लिए सच्चाई, सुधार और वह व्यक्ति लाओ जिसे तुम बनना चुन रहे हो।"),
        reflection = "कौन सी मरम्मत या बदली हुई आदत आपके पछतावे को उपयोगी बनाएगी?",
        nextStep = "एक मरम्मत लिखें जो आप पेश कर सकते हैं और एक रेलिंग जो आपके भविष्य के विकल्पों का मार्गदर्शन करेगी।"
    ),
    "betrayal" to KrishnaLetterTranslation(
        situation = "जब किसी ने आपको धोखा दिया है",
        title = "उनकी पसंद आपके भरोसे को मूर्खतापूर्ण नहीं बनाती है",
        preview = "आप एक अच्छा दिल रख सकते हैं और समझदार सीमाएं बना सकते हैं।",
        paragraphs = listOf("विश्वासघात दुखदायी होता है क्योंकि आपने किसी को अपने दिल में सुरक्षित जगह दी है। अब आपको उन पर गुस्सा आ सकता है और भरोसा करने के लिए खुद पर शर्म आ सकती है। अपनी दयालुता को मूर्खतापूर्ण मत कहो। विश्वास एक उपहार था जो आपने दिया था। इसका दुरुपयोग करना उनकी अपनी मर्जी है।", "गपशप, सार्वजनिक शर्म या किसी अन्य रहस्य से आहत उत्तर न दें। जानें वास्तव में क्या हुआ था. यदि यह सुरक्षित है, तो एक स्पष्ट प्रश्न पूछें। वास्तविक माफी में स्वामित्व, मरम्मत और बदली हुई कार्रवाई शामिल है। परिवर्तन के बिना शब्द विश्वास का पुनर्निर्माण नहीं करते, चाहे वे कितने भी सुंदर क्यों न लगें।", "आप क्षमा कर सकते हैं और फिर भी दूरी बनाए रख सकते हैं। आप परवाह कर सकते हैं और फिर भी ना कह सकते हैं। विश्वास को छोटे-छोटे कदमों में तभी लौटने दें जब कार्य उसका समर्थन करें। एक व्यक्ति के विश्वासघात का मतलब यह नहीं है कि हर भावी मित्र भी ऐसा ही करेगा। अपना हृदय अच्छा रखें और अपनी सीमाएँ जागृत रखें। [केएफवाई6] मुझे पता है कि आपका दिल अब हर दरवाजे को दो बार क्यों जांचता है। सुरक्षा स्पष्ट होने से पहले उस पर भरोसा करने के लिए दबाव न डालें।", "मुझे पता है कि तुम्हारा दिल अब हर दरवाजे को दो बार क्यों जांचता है। सुरक्षा स्पष्ट होने से पहले उस पर भरोसा करने के लिए दबाव न डालें।"),
        reflection = "विश्वास फिर से बढ़ने से पहले क्या कार्रवाई - वादा नहीं - की आवश्यकता होगी?",
        nextStep = "आपको जिस सीमा की आवश्यकता है उसे लिखें और यदि बातचीत सुरक्षित है तो इसे शांति से साझा करें।"
    ),
    "letting-go" to KrishnaLetterTranslation(
        situation = "जब आपको किसी को जाने देना चाहिए",
        title = "प्यार वह छोड़ सकता है जो वह नहीं रख सकता",
        preview = "जाने देना सच्चाई और आपकी अपनी गरिमा दोनों का सम्मान कर सकता है।",
        paragraphs = listOf("कभी-कभी प्यार बना रहता है जबकि रिश्ता जारी नहीं रह पाता। हो सकता है कि आप सच्चाई जानते हों और फिर भी वापस पहुंच जाएं क्योंकि खाली जगह आपको डराती है। जाने देना इस बात का सबूत नहीं है कि आपने कभी परवाह नहीं की। यह अब आपकी देखभाल का सबसे ईमानदार रूप हो सकता है।", "उस दरवाज़े को बार-बार न खोलें जिसे बंद करने के लिए दोनों लोग सहमत हों। जो बात एक बार कहनी चाहिए, सम्मान के साथ कहिए. जो उनका है उसे लौटा दो, जो सीखा है उसे अपने पास रखो और छोटे संपर्कों को कम करो जो आशा को भ्रमित करते हैं। एक स्पष्ट अंत एक अंतहीन आधे-अलविदा की तुलना में दयालु है।", "दुख लहरों में आएगा। सुरक्षित लोगों को अपने पास खड़े रहने दें। जहां पुराने लोग रहते थे वहां नई दिनचर्या बनाएं। तुम प्रेम को फेंक नहीं रहे हो; आप इसे एक शृंखला में बदलने से इनकार कर रहे हैं। उन्हें उस भूमिका से मुक्त करें जिसे वे नहीं भर सकते, और स्वयं को जीने के लिए मुक्त करें।", "उनका नाम मेरे हाथों में रख दो जब इसे पकड़ने से तुम्हें दर्द होने लगे। आपको अच्छाइयों को मिटाने या दर्द को नकारने की ज़रूरत नहीं है।"),
        reflection = "कौन सा संपर्क या आदत अलविदा को अधूरा रख रही है?",
        nextStep = "एक सम्मानजनक सीमा चुनें जो दोनों दिलों को ठीक होने का मौका दे।"
    ),
    "family-struggling" to KrishnaLetterTranslation(
        situation = "जब आपका परिवार संघर्ष कर रहा हो",
        title = "आप सभी की देखभाल किए बिना देखभाल कर सकते हैं",
        preview = "अपना काम प्यार से करें, लेकिन सारा बोझ अकेले न उठाएं।",
        paragraphs = listOf("जब एक परिवार संघर्ष करता है, तो हर कमरे में चिंता हो सकती है। पैसा, स्वास्थ्य, संघर्ष या परिवर्तन आपको महसूस करा सकता है कि आपको सब कुछ ठीक करना होगा। आप अपनी ज़रूरतों के लिए भी दोषी महसूस कर सकते हैं। आप परिवार का हिस्सा हैं, लेकिन आपको उसका संपूर्ण सहारा बनने के लिए नहीं बनाया गया है।", "पूछें कि आज वास्तव में आपका कर्तव्य क्या है। एक काम में मदद करें, धीरे से बोलें और डरने के बजाय तथ्य साझा करें। प्रत्येक सक्षम व्यक्ति को उचित हिस्सा लेने दें। जब समस्या की आवश्यकता हो तो रिश्तेदारों, शिक्षकों, डॉक्टरों, परामर्शदाताओं या सेवाओं से मदद लें, केवल प्यार से अधिक मदद मिल सकती है।", "सामान्य जीवन के छोटे-छोटे लक्षणों को सुरक्षित रखें: एक साथ भोजन करना, अध्ययन का समय, सोना, टहलना या एक ईमानदार हंसी। हर अच्छे पल को कठिनाई से छीनने नहीं देना चाहिए। आपकी शांत देखभाल परिवार की मदद कर सकती है, और देखभाल प्राप्त करने से आपको स्थिर रहने में मदद मिलेगी। [केएफवाई6] मैं देख रहा हूं कि आप घर की हर समस्या को कितनी जल्दी सुनते हैं। मेरे प्रियजन, आप इस परिवार के सदस्य हैं, इसके एकमात्र बचावकर्ता नहीं।", "मैं देखता हूं कि आप घर की हर समस्या को कितनी जल्दी सुनते हैं। मेरे प्रियजन, आप इस परिवार के सदस्य हैं, इसके एकमात्र बचावकर्ता नहीं।"),
        reflection = "आपका उचित हिस्सा क्या है, और किसी और का क्या है?",
        nextStep = "एक उपयोगी पारिवारिक कार्य चुनें और उस बोझ के लिए मदद मांगें जिसे आप अकेले नहीं उठा सकते।"
