    "stuck" to KrishnaLetterTranslation(
        situation = "जब आप जीवन में फंसे हुए महसूस करते हैं",
        title = "आंदोलन आपके विचार से छोटे आकार में शुरू हो सकता है",
        preview = "आपको थोड़ी सी गति बनाने के लिए एक सही योजना की आवश्यकता नहीं है।",
        paragraphs = listOf("आप महसूस कर सकते हैं कि हर दिन एक जैसा दिखता है जबकि अन्य आगे बढ़ रहे हैं। जितना अधिक आप एक बड़े उत्तर की प्रतीक्षा करेंगे, कोई भी कदम उतना ही कठिन महसूस हो सकता है। अटके रहना अक्सर आलस्य नहीं होता. यह डर, थकान, दुःख या एक साथ बहुत सारे विकल्प खींचना हो सकता है।", "अगला चरण बहुत छोटा और दृश्यमान बनाएं। दस्तावेज़ खोलें, दस मिनट तक चलें, ईमेल भेजें या एक कोना साफ़ करें। यह मत पूछिए कि क्या यह आपका पूरा जीवन बदल देता है। पूछें कि क्या यह ईमानदार आंदोलन पैदा करता है। छोटी सी हलचल आपके दिमाग को नई जानकारी देती है।", "यदि आप प्रयास करते रहते हैं और कार्य नहीं कर पाते हैं, तो किसी सुरक्षित व्यक्ति या प्रशिक्षित सहायक से बात करें। आपको समर्थन की आवश्यकता हो सकती है, मजबूत दोष की नहीं। आपके रुकने से आपका रास्ता गायब नहीं हुआ है। जहां आपके पैर हैं वहीं से शुरुआत करें, आपके हाथ आज क्या कर सकते हैं। [केएफवाई6] आप एक महान दरवाजे की तलाश में हैं जबकि मैं एक छोटे कदम की ओर इशारा कर रहा हूं। पांच मिनट के लिए धोएं, लिखें, कॉल करें, चलें या शुरुआत करें।", "आप एक महान दरवाजे की तलाश में हैं जबकि मैं एक छोटे से कदम की ओर इशारा कर रहा हूं। पांच मिनट के लिए धोएं, लिखें, कॉल करें, चलें या शुरुआत करें।"),
        reflection = "दस मिनट की कौन सी कार्रवाई वास्तविक हलचल पैदा करेगी?",
        nextStep = "दस मिनट का टाइमर सेट करें और कार्य का केवल पहला भौतिक चरण करें।"
    ),
    "unanswered-prayers" to KrishnaLetterTranslation(
        situation = "जब आपकी प्रार्थनाएँ अनुत्तरित लगती हैं",
        title = "मौन इस बात का प्रमाण नहीं है कि आप भूल गए हैं",
        preview = "जीवन के उत्तर देने से पहले ही प्रार्थना आपके दिल को थाम सकती है।",
        paragraphs = listOf("आपने पूछा है, इंतजार किया है और शायद भीख मांगी है। कुछ भी बदलता नजर नहीं आ रहा. तुम्हें आश्चर्य हो सकता है कि क्या मैं तुम्हें सुनता हूँ या तुम्हारा विश्वास बहुत छोटा है। वह संदेह मेरे पास भी लाओ। ईमानदार पीड़ा अनादर नहीं है, और आपको प्रार्थना करने के लिए सही शब्दों की आवश्यकता नहीं है।", "प्रार्थना कोई सौदा नहीं है जो हर परिणाम को नियंत्रित करती है। कभी-कभी उत्तर विलंबित, भिन्न या उन लोगों और कार्यों के माध्यम से दिया जाता है जिनकी आपने अपेक्षा नहीं की थी। प्रार्थना के साथ-साथ व्यावहारिक कर्तव्य भी निभाते रहें: उपचार लें, दोबारा आवेदन करें, माफी मांगें, अध्ययन करें, मदद मांगें या आराम करें।", "मैं यह वादा नहीं करूंगा कि हर इच्छा आपके चुने हुए आकार में पूरी होगी। मैं वादा करता हूं कि आपका प्यार, साहस और ईमानदार प्रयास अभी भी इंतजार में बढ़ सकता है। अगले वफ़ादार कार्य की तलाश करें, हर घटना में छिपे संकेत की नहीं। प्रार्थना को आपको वर्तमान बनायें, निष्क्रिय नहीं। [केएफवाई6] मुझसे बात करें, भले ही आपकी प्रार्थना केवल 'मुझे समझ नहीं आ रही हो।' मैं प्रतीक्षा में, बुद्धिमान मदद में और जारी रखने की ताकत में मौजूद हूं।", "मुझसे बोलें, भले ही आपकी प्रार्थना केवल 'मैं नहीं समझता' हो। आपको सुंदर शब्दों का उपयोग करने की ज़रूरत नहीं है या यह दिखावा नहीं करना है कि मौन दुखदायी नहीं है। मैं प्रतीक्षा में, बुद्धिमान मदद में और जारी रखने की ताकत में मौजूद हूं।"),
        reflection = "आज आपकी प्रार्थना के साथ कौन सा व्यावहारिक कदम खड़ा हो सकता है?",
        nextStep = "पांच मिनट तक ईमानदारी से प्रार्थना करें, फिर आवश्यकता से संबंधित एक वास्तविक कार्रवाई करें।"
    ),
    "difficult-decision" to KrishnaLetterTranslation(
