        title = "मूल्यों को वहां ले जाने दें जहां डर नहीं जा सकता",
        preview = "एक स्पष्ट विकल्प तथ्यों, कर्तव्य और ईमानदार परिणामों से शुरू होता है।",
        paragraphs = listOf("दो सड़कों पर नुकसान हो सकता है, या कई आवाजें आपको अलग-अलग दिशाओं में खींच रही होंगी। आप चुनने से पहले निश्चितता चाहते हैं, लेकिन महत्वपूर्ण विकल्प शायद ही कभी इसकी पेशकश करते हैं। आप तब भी सावधानी से निर्णय ले सकते हैं, तब भी जब आप हर परिणाम को नियंत्रित नहीं कर सकते।", "तथ्यों को अनुमान से अलग करें। पूछें कि कौन सा विकल्प ईमानदार, सुरक्षित और आपके कर्तव्य के प्रति सच्चा है। विचार करें कि किसकी मदद की जा सकती है या किसको नुकसान पहुँचाया जा सकता है। किसी भरोसेमंद गुरु, शिक्षक या बुद्धिमान बुजुर्ग की तलाश करें जिसे आपके उत्तर से कोई लाभ न हो। उनका महत्व यह नहीं है कि वे आपके लिए आपका जीवन चुनते हैं, बल्कि यह है कि वे अंधे धब्बों को उजागर करते हैं, ईमानदार प्रश्न पूछते हैं और आपको धर्म की ओर लौटाते हैं। ध्यान दें कि क्या डर, घमंड या दबाव आपको जल्दी करने की कोशिश कर रहा है।", "अब उपलब्ध सत्य के साथ सर्वोत्तम कार्रवाई चुनें। नए तथ्य सामने आने पर आप समायोजित कर सकते हैं; वह बुद्धिमत्ता है, कमजोरी नहीं। एक बार जब आप पसंद की अच्छी तरह से जांच कर लें, तो सही वादा प्रदान करने की चिंता करना बंद कर दें। अपने मूल्यों को आगे बढ़ने दें।", "जिस भाग को आप गुप्त रूप से चाहते हैं उसे छिपाए बिना मेरे लिए दोनों विकल्प लाएँ। हम सत्य, कर्तव्य, हानि और उन लोगों को देखेंगे जो परिणाम ला सकते हैं।"),
        reflection = "कौन सा विकल्प सत्य, जिम्मेदारी और दीर्घकालिक शांति की सबसे अच्छी रक्षा करता है?",
        nextStep = "तथ्यों, कर्तव्यों, संभावित प्रभावों और एक बुद्धिमान व्यक्ति को लिखें जिससे आप परामर्श लेंगे।"
    ),
    "lost-purpose" to KrishnaLetterTranslation(
        situation = "जब आप अपना उद्देश्य खो चुके हों",
        title = "अर्थ की शुरुआत उस एक व्यक्ति से हो सकती है जिसकी आप मदद करते हैं",
        preview = "इससे पहले कि आपका दिन मायने रखे, आपको किसी बड़े मिशन की जरूरत नहीं है।",
        paragraphs = listOf("जीवन उन कार्यों की एक सूची जैसा लग सकता है जिनके पीछे कोई कारण नहीं है। आप सोच सकते हैं कि बाकी सभी को बुलावा मिल गया है जबकि आप केवल समय गुजार रहे हैं। उद्देश्य हमेशा अचानक सुनाई देने वाली आवाज़ नहीं होती. अक्सर यह देखभाल, सीखने, काम और सेवा के माध्यम से चुपचाप बढ़ता है।", "देखें कि आपके हाथ में पहले से क्या है: आपका शरीर, अध्ययन, परिवार, कौशल, वादा या वह व्यक्ति जिसे आपकी ज़रूरत है। एक कर्तव्य को पूरे ध्यान से करो। अर्थ सामान्य कार्य में तब प्रवेश करता है जब यह किसी की रक्षा करता है, सिखाता है, उपचार करता है या उसके जीवन को थोड़ा बेहतर बनाता है।", "आपको अन्वेषण करने की अनुमति है। ध्यान दें कि क्या चीज़ शांत ऊर्जा लाती है, न कि केवल त्वरित प्रशंसा। पूछें कि आप किस समस्या के साथ रहना चाहते हैं। आपकी भूमिका कई बार बदल सकती है जबकि इसके अंतर्गत गहरे मूल्य सत्य बने रहते हैं। जहां आप खड़े हैं वहां उपयोगी बनकर शुरुआत करें।", "अपने जीवन को सार्थक कहने से पहले किसी भव्य संकेत की प्रतीक्षा न करें। मैं अक्सर उस व्यक्ति में पाया जाता हूं जिसे सुनने की जरूरत होती है, जिस काम के लिए देखभाल की जरूरत होती है और जिस वादे को निभाने की जरूरत होती है।"),
        reflection = "आपके पास पहले से मौजूद एक कौशल से किसकी या क्या मदद मिल सकती है?",
