    "change" to KrishnaLetterTranslation(
        situation = "जब परिवर्तन भयावह लगता है",
        title = "आप एक समय में एक नया कदम उठा सकते हैं",
        preview = "परिवर्तन समायोजन मांगता है, तत्काल साहस नहीं।",
        paragraphs = listOf("एक अच्छा बदलाव भी आपके दिल को असहज कर सकता है। पुराना जीवन ज्ञात था, और नये का अभी तक कोई परिचित आकार नहीं है। डर का मतलब हमेशा यह नहीं होता कि बदलाव गलत है। कभी-कभी इसका मतलब केवल यह होता है कि आपको परवाह है और आप पूरी सड़क नहीं देख सकते।", "नाम बताएं जो स्थिर रहेगा: आपके मूल्य, एक व्यक्ति, एक दिनचर्या, एक कौशल या जिस तरह से आप अपनी देखभाल करते हैं। फिर जो आने वाला है उसके बारे में एक तथ्य जानें। एक स्पष्ट विवरण किसी बड़े अज्ञात को छोटा बना सकता है। हर चीज़ पर नियंत्रण करने की कोशिश किए बिना आप जो कर सकते हैं, उसे तैयार करें।", "नौसिखिया बनने के लिए खुद को समय दें। आप पुराने को याद कर सकते हैं और फिर भी नए का स्वागत कर सकते हैं। वे भावनाएँ एक साथ रह सकती हैं। मैं आपसे हर बदलाव को पसंद करने के लिए नहीं कह रहा हूं। मैं आपसे इसके अगले छोटे भाग में अपना सच्चा स्वरूप लाने के लिए कह रहा हूँ। [केएफवाई6] आप एक हाथ से पुराने जीवन को पकड़ सकते हैं और दूसरे हाथ से नए जीवन की ओर बढ़ सकते हैं। मैं समझता हूँ।", "आप एक हाथ से पुराने जीवन को पकड़ सकते हैं जबकि दूसरे हाथ से नए की ओर बढ़ सकते हैं। मैं समझता हूँ।"),
        reflection = "जब बाकी सब कुछ बदल जाए तो क्या स्थिर रह सकता है?",
