        preview = "ध्यान की कमी का मतलब मूल्य की कमी नहीं है।",
        paragraphs = listOf("शायद किसी ने फोन नहीं किया, आपको धन्यवाद नहीं दिया या ध्यान नहीं दिया कि आप कितना सामान लेकर आए हैं। आपको प्रतिस्थापित करना आसान और याद रखना कठिन लग सकता है। मानव का ध्यान असमान होता है और अक्सर जल्दबाजी करता है। इसकी चुप्पी दुख पहुंचा सकती है, लेकिन यह इस दुनिया में आपके स्थान का सही माप नहीं है।", "गायब होकर और यह देखने का इंतजार करके प्यार का परीक्षण न करें कि कौन खोजता है। ईमानदारी से पहुंचें. कहें, 'मैं आपके साथ समय बिताना चाहूंगा,' या, 'मुझे आज समर्थन की ज़रूरत है।' लोगों को छिपे हुए दर्द को पढ़ने के लिए कहने के बजाय शब्दों पर प्रतिक्रिया देने का उचित मौका दें।", "उस जीवन में भी लौटें जो आपके स्पर्श को जानता है: एक कर्तव्य, जानवर, पौधा, परिवार का सदस्य, मित्र या कौशल। आपकी उपस्थिति तालियों से अधिक परिवर्तन लाती है। यदि एक वृत्त आपको नज़रअंदाज करता रहता है, तो वृत्त को चौड़ा करें। ऐसे लोग हैं जो आपका नाम जान सकते हैं और आपकी देखभाल को महत्व दे सकते हैं।", "मैंने वैराग्य को मूल्य के साथ भ्रमित नहीं किया है। मैं आपके द्वारा तैयार किया गया भोजन, आपके द्वारा भेजा गया संदेश, वह कार्य जिसकी किसी ने प्रशंसा नहीं की और जब आप थके हुए थे तब आपने जो देखभाल की वह सब देख रहा हूँ।"),
        reflection = "चुपचाप प्रतीक्षा करने के बजाय आप कहां शामिल होने के लिए कह सकते हैं?",
