        paragraphs = listOf("पैसे का डर दिन के हर हिस्से में प्रवेश कर सकता है। आपको किसी को बताने में शर्म आ सकती है, फँसना पड़ सकता है या डर लग सकता है। वित्तीय संघर्ष एक वास्तविक समस्या है, लेकिन यह आपके लिए कोई नैतिक नाम नहीं है। आपका संतुलन आपकी गरिमा, प्रेम या पुनर्निर्माण की क्षमता को नहीं माप सकता।", "तथ्यों को प्रकाश में लाएँ। सूची बनाएं कि क्या आता है, क्या जाना चाहिए और कौन सा भुगतान सबसे जरूरी है। जहां संभव हो वहां नए कर्ज को रोकें और आवश्यक खर्च न करें। इसमें शामिल लोगों या सेवाओं से जल्दी बात करें; चुप्पी अक्सर फीस, भय और विकल्पों को कठिन बना देती है।", "एक सरल योजना के लिए किसी भरोसेमंद, आर्थिक रूप से बुद्धिमान व्यक्ति से मदद मांगें। त्वरित धन के उन वादों से बचें जो गोपनीयता या उच्च जोखिम की मांग करते हैं। ईमानदार काम, छोटी बचत और धैर्यवान मरम्मत धीमी लग सकती है, लेकिन वे आपके भविष्य की रक्षा करते हैं। अपने पूरे जीवन का मूल्यांकन किए बिना अगला स्पष्ट कदम उठाएँ।", "मेरे पास संख्याएँ वैसे ही लाओ जैसे वे हैं, न कि डर के कारण उन्हें चिल्लाता रहता है। हम उन्हें शर्म या खतरनाक शॉर्टकट से हल नहीं करेंगे।"),
        reflection = "सबसे जरूरी नंबर कौन सा है जिसका आपको स्पष्ट रूप से सामना करना होगा?",
