        preview = "देखभाल को बिना शर्म के अपने शरीर, दिमाग और दिल तक पहुंचने दें।",
        paragraphs = listOf("बीमारी आपकी योजनाओं, ऊर्जा और आपके शरीर को देखने के तरीके को बदल सकती है। आप क्रोधित, भयभीत या थके हुए महसूस कर सकते हैं कि इसे किसी समस्या की तरह हल किया जा रहा है। आप अभी भी एक संपूर्ण व्यक्ति हैं. जब आपकी ताकत, गति या स्वतंत्रता बदलती है तो आपका मूल्य नहीं गिरता।", "किसी प्रशिक्षित डॉक्टर से देखभाल लें और लक्षण ईमानदारी से साझा करें। जब तक आप योजना को समझ न लें तब तक प्रश्न पूछें। किसी को अपॉइंटमेंट, भोजन, दवा या आराम में मदद करने दें। प्रार्थना उपचार में सहायता कर सकती है; इसे आपके शरीर की आवश्यक कुशल देखभाल का स्थान नहीं लेना चाहिए। सहायता स्वीकार करना समर्पण नहीं है.", "अपने आप को हर पल कृतज्ञ महसूस करने के लिए मजबूर न करें। दुःख और छोटी-छोटी अच्छी चीज़ों के लिए जगह बनाएँ जो अभी भी संभव हैं। बातचीत, धूप, संगीत या पूरा किया गया कार्य अर्थपूर्ण हो सकता है। मैं आज आपके पास जो शरीर है उससे मैं आपके करीब हूं, न कि केवल उस शरीर से जिसे आप मिस करते हैं। [केएफवाई6] मैं आज इस शरीर में आपके साथ हूं, न कि केवल उस स्वस्थ शरीर में जिसे आप याद करते हैं या पुनः प्राप्त करने की आशा करते हैं। कुशल देखभाल, दवा, आराम और प्यार भरे हाथ आप तक पहुँचें।", "मैं आज इस शरीर में आपके साथ हूं, न कि केवल उस स्वस्थ शरीर में जिसे आप याद करते हैं या पुनः प्राप्त करने की आशा करते हैं। कुशल देखभाल, दवा, आराम और प्यार भरे हाथ आप तक पहुँचें।"),
