    "happy" to KrishnaLetterTranslation(
        situation = "जब आप खुश महसूस करते हैं",
        title = "अपनी खुशी को दयालुता बनने दें",
        preview = "किसी अन्य व्यक्ति के दर्द पर अपनी खुशी बनाए बिना इस उज्ज्वल क्षण का आनंद लें।",
        paragraphs = listOf("मुझे खुशी है कि आज आपका दिल हल्का महसूस कर रहा है। मुस्कुराएं, हंसें और जो अच्छा है उसका आनंद लें। खुश रहने के लिए आपको दोषी महसूस करने की जरूरत नहीं है। खुशी आपके दिमाग को नई ताकत देती है और आपको याद दिलाती है कि जीवन में सुंदरता, दोस्ती और अनुग्रह भी है।", "लेकिन अपनी खुशी की जड़ों को धीरे से देखें। इसे प्रेम, ईमानदार प्रयास, साझा सफलता या शांतिपूर्ण हृदय से आने दें। कभी भी इसलिए जश्न न मनाएं क्योंकि किसी को ठेस पहुंची, असफल हुआ, हार गया या नीचे धकेल दिया गया। दूसरे व्यक्ति के दर्द से पैदा हुई खुशी लंबे समय तक शुद्ध नहीं रहेगी।", "अपनी ख़ुशी में किसी को आमंत्रित करें। उन लोगों को धन्यवाद जिन्होंने आपकी मदद की. उस व्यक्ति को प्रोत्साहित करें जो अभी भी संघर्ष कर रहा है। एक अच्छा दिल बिना घमंड किए जश्न मना सकता है और दूसरे व्यक्ति को छोटा महसूस कराए बिना चमक सकता है। जब आपकी खुशी दयालुता बन जाती है, तो वह आपके साथ खत्म होने की बजाय बढ़ती है।", "केवल अपने आंसू ही नहीं, बल्कि अपनी हंसी भी मेरे पास लाओ। मैं उस आनंद से प्रसन्न होता हूं जो स्वच्छ, आभारी और दयालु है।"),
