        preview = "स्वस्थ गौरव यह तय किए बिना प्रयास को याद रखता है कि आप दूसरों से ऊपर हैं।",
        paragraphs = listOf("आपने शायद कुछ ऐसा किया होगा जो पहले असंभव लगता था। आपके द्वारा बनाए गए साहस, अभ्यास या आत्म-नियंत्रण पर ध्यान दें। यह कहना स्वस्थ है, 'मैं बड़ा हो गया।' आपको दूसरे लोगों को सहज महसूस कराने के लिए अपने पुराने स्व का अपमान करने या अपनी प्रगति को छिपाने की ज़रूरत नहीं है।", "गर्व को ध्यान से रखें। इसे गर्म होने दें, तेज़ नहीं। आप किसी अन्य आत्मा से महान नहीं हैं क्योंकि आपने आज अच्छा प्रदर्शन किया। उनका संघर्ष छिपा हो सकता है, और उनका समय अलग हो सकता है। अपनी उपलब्धि को हथियार, तुलना या सीखना बंद करने का कारण न बनाएं।", "परिणाम के पीछे के मूल्यों पर गर्व करें: ईमानदारी, धैर्य, साहस, दयालुता या अनुशासन। तालियाँ फीकी पड़ने पर भी वे गुण बने रह सकते हैं। इस क्षण को यह साबित करने दें कि विकास संभव है, फिर उस विश्वास का उपयोग विनम्र मन से अपने अगले कर्तव्य का सामना करने के लिए करें। [केएफवाई6] मुझे खुशी है कि आप अंततः अपनी वृद्धि देख सकते हैं। उस अभिमान को मुकुट नहीं, दीपक की तरह धारण करो।", "मुझे खुशी है कि आप अंततः अपना विकास देख सकते हैं। उस अभिमान को मुकुट नहीं, दीपक की तरह धारण करो।"),
        reflection = "आपके किस गुण ने इस विकास को संभव बनाया?",
        nextStep = "उस गुण का नाम बताएं, उसका समर्थन करने वाले को धन्यवाद दें और आज फिर से उसका अभ्यास करें।"
    ),
    "excited" to KrishnaLetterTranslation(
        situation = "जब आप उत्साहित महसूस करें",
        title = "अपनी ऊर्जा को एक उचित दिशा दें",
        preview = "उत्साह उज्ज्वल ऊर्जा है; धैर्य और सत्य को मार्गदर्शन करने दें कि वह कहाँ जाता है।",
        paragraphs = listOf("कुछ नया आपके दिमाग को आगे की ओर दौड़ने पर मजबूर कर रहा है। उस चिंगारी का आनंद लें. उत्साह आपको शुरुआत करने, निर्माण करने और जुड़ने में मदद कर सकता है। आपको खुद को छोटा बनाने की जरूरत नहीं है. हर शांत विचार को दूर धकेले बिना अच्छी ऊर्जा को अपने अंदर से गुजरने दें।", "इससे पहले कि आप वादा करें, खरीदें, पोस्ट करें या निर्णय लें, रुकें। उत्साह केवल चमकते हिस्से को देख सकता है और लागत, जोखिम या कर्तव्य को भूल सकता है। तथ्यों की जांच करें. बड़े विकल्प पर सोएं. पूछें कि क्या यह रास्ता आपके और प्रभावित लोगों के लिए सुरक्षित, ईमानदार और सही है।", "फिर पूरे मन से कार्य करें। केवल परिणाम की कल्पना करने के बजाय अच्छी तैयारी करें। बिना यह मांगे समाचार साझा करें कि हर कोई इसे उसी तरह महसूस करे। ज्ञान के साथ जुड़ने वाली ऊर्जा स्थिर क्रिया बन जाती है; दिशाहीन ऊर्जा अक्सर पछतावे में बदल जाती है।", "मैं महसूस कर सकता हूं कि आपके विचार कितनी तेज़ी से चल रहे हैं। मुझे हर उज्ज्वल संभावना बताएं, फिर मेरे साथ इतनी देर तक बैठें कि पूरा रास्ता देख सकें।"),
        reflection = "कौन सी सरल तैयारी आपके उत्साह को वास्तविक प्रगति में बदलने में मदद करेगी?",
        nextStep = "अगले तीन व्यावहारिक चरण लिखें और कोई बड़ा वादा करने से पहले सबसे छोटे चरण को पूरा करें।"
    ),
    "peaceful" to KrishnaLetterTranslation(
        situation = "जब आप शांति महसूस करते हैं",
        title = "उस शांति की रक्षा करें जो आपको देखने में मदद करती है",
        preview = "शांति एक खाली विराम नहीं है; यह एक स्पष्ट स्थान है जहाँ से अच्छी तरह से रहा जा सकता है।",
        paragraphs = listOf("आपका दिमाग कुछ देर के लिए शांत है। हर खुली जगह को शोर, चिंता या स्क्रीन से भरने में जल्दबाजी न करें। इस शांति में आराम करो. अपनी सांस, आकाश, किसी परिचित चेहरे या इस क्षण की सरल सुरक्षा पर ध्यान दें।", "शांति का मतलब यह नहीं है कि हर समस्या समाप्त हो गई है। इसका मतलब है कि कोई समस्या अभी आप पर हावी नहीं हो रही है। इस स्पष्ट स्थान से आप बिना घबराए अपना कर्तव्य देख सकते हैं और जीतने की कोशिश किए बिना बोल सकते हैं। बुद्धिमानी से चुनाव करने के लिए शांति का प्रयोग करें, आवश्यक कार्रवाई से बचने के लिए नहीं।", "जानें कि किस चीज़ ने इस शांति को बढ़ने में मदद की। शायद यह प्रार्थना, नींद, ईमानदार काम, प्रकृति, संगीत, क्षमा या एक स्वस्थ सीमा थी। उस अभ्यास को अपने पास रखें. एक शांतिपूर्ण हृदय दूसरों के लिए आश्रय बन सकता है जब वह धैर्यपूर्वक सुनता है और निष्पक्षता से कार्य करता है।", "थोड़ी देर और इस शांति में मेरे साथ रहो। आपको इसे भरने या समझाने की जरूरत नहीं है."),
        reflection = "आज किस चीज़ ने आपके दिमाग को शांत होने में मदद की?",
