        preview = "सच्चा प्यार एक उपहार है जिसे संजोकर रखा जाना चाहिए, न कि नियंत्रण करने के लिए एक कब्ज़ा।",
        paragraphs = listOf("किसी की परवाह आपके दिल तक पहुंच गई है। इसे प्राप्त करें। आपको हर तरह के शब्द पर संदेह करने या यह जांचने की ज़रूरत नहीं है कि वह व्यक्ति रहेगा या नहीं। सुरक्षित, ईमानदार प्यार आपको याद दिलाए कि निकटता गर्मजोशीपूर्ण, सम्मानजनक और भय से मुक्त हो सकती है।", "प्यार को इतनी कसकर मत पकड़ो कि उसकी हवा निकल जाए। एक व्यक्ति आपके वश में नहीं है। उनकी सीमाओं, सच्चाई, कर्तव्यों और अन्य रिश्तों का सम्मान करें। प्यार पासवर्ड, चुप्पी या दर्द के माध्यम से सबूत की मांग नहीं करता है। यह चाहता है कि दोनों लोग सुरक्षित और संपूर्ण रहें।", "ध्यान, ईमानदारी और स्थिर देखभाल के माध्यम से प्यार लौटाएं। कहो कि तुम क्या महत्व रखते हो. विश्वास को पवित्र रखें. अगर यह प्यार परिवार या दोस्ती से है तो इसे रोमांस से कम महत्वपूर्ण न समझें। हर साफ़ बंधन आपके दिल को सिखा सकता है कि स्वामित्व के बिना कैसे देना है।", "इस प्यार को तब तक परखे बिना प्राप्त करें जब तक यह टूट न जाए। जहां भी देखभाल ईमानदार, सुरक्षित और मुफ़्त है, मैं वहां मौजूद हूं।"),
        reflection = "आज आप एक प्यार भरे बंधन को कैसे सुरक्षित और स्वतंत्र महसूस करा सकते हैं?",
        nextStep = "एक व्यक्ति को बताएं कि आप उनके बारे में क्या महत्व रखते हैं और उनकी एक आवश्यकता या सीमा का सम्मान करें।"
    ),
    "hopeful" to KrishnaLetterTranslation(
