        preview = "आशा दिशा दिखा सकती है; आपकी ईमानदार कार्रवाई से यात्रा शुरू होती है।",
        paragraphs = listOf("एक छोटी सी रोशनी लौट आई है। शायद आप एक बेहतर परिणाम, एक ठीक हुए बंधन या एक नई शुरुआत की कल्पना कर सकते हैं। उस आशा का स्वागत है. यह वादा नहीं करता कि हर राह आसान होगी। यह आपको बताता है कि आपकी कहानी में अभी भी आगे बढ़ने की गुंजाइश है।", "आशा की जड़ें दें। जानें लक्ष्य आपसे क्या चाहता है. ऐसी योजना बनाएं जो सत्य, समय और आपकी सीमाओं का सम्मान करे। अपना पूरा मन एक ही सटीक परिणाम पर केंद्रित न करें। कभी-कभी आशा उस दरवाजे तक ले जाती है जो आप चाहते हैं, और कभी-कभी यह दूसरा दरवाजा ढूंढने का साहस देती है।", "उन लोगों के साथ सावधानी से आशा साझा करें जो दुखी हैं। उन्हें मुस्कुराने या उनके दर्द को नज़रअंदाज़ करने के लिए न कहें। उनके पास बैठें, सुनें और वास्तविक सहायता प्रदान करें। आशा तब सबसे मजबूत होती है जब यह सच्चाई के लिए जगह बनाती है और किसी को संभावित कदम उठाने में मदद करती है।", "आपके अंदर की यह छोटी सी रोशनी मेरे लिए अनमोल है। इसे सत्य और कार्य से सुरक्षित रखें, केवल कल्पना से नहीं।"),
        reflection = "कौन सा कार्य दिखाएगा कि आपकी आशा वास्तविक हो रही है?",
        nextStep = "एक चरण चुनें जिसे आप इस सप्ताह पूरा कर सकते हैं और उसके बगल में एक स्पष्ट समय रखें।"
    ),
    "relieved" to KrishnaLetterTranslation(
        situation = "जब आप राहत महसूस करें",
        title = "सांस लें, सीखें और छोड़ें",
        preview = "खतरा या दबाव कम हो गया है; अपने शरीर को आराम दें और अपनी बुद्धि को रहने दें।",
        paragraphs = listOf("कोई भारी चीज़ गुजर गई है या छोटी हो गई है। हो सकता है कि आपका शरीर आख़िरकार हार मान रहा हो। धीमी सांस लें. आपको तुरंत अगली चिंता की खोज करने की आवश्यकता नहीं है। राहत आपके दिमाग का यह कहने का तरीका है कि वह कुछ समय के लिए अपनी सुरक्षा को कम कर सकता है।", "यदि कोई कठिन परिणाम टाला जा सके, तो बिना शर्म के पीछे मुड़कर देखें। किस चेतावनी, सहायता या विकल्प ने आपकी रक्षा की? वह सबक रखो. राहत से आपको ऐसी समस्या के प्रति लापरवाह नहीं होना चाहिए जिसे अभी भी मरम्मत की आवश्यकता है। ईमानदारी से किया गया काम, क्षमा याचना, योजना या सुरक्षा का जो कदम बाकी रह गया हो उसे ख़त्म कर लें।", "फिर आराम करें। पानी पिएं, खाएं, सोएं या किसी ऐसे व्यक्ति से बात करें जो आपके पास रहता हो। उन्हें धन्यवाद दें। आपको डर के बाद अंतरिक्ष का आनंद लेने की अनुमति है। राहत को आपको अधिक सावधानी के साथ जीवन में वापस लाने दें, न कि आपको उसी टाले जा सकने वाले खतरे में वापस भेज दें।", "अब साँस लो, मेरे प्रियजन। ख़तरे के गुज़र जाने के बाद आपको उसे अपने मन में ज़िंदा रखने की ज़रूरत नहीं है।"),
        reflection = "इस दबाव के हटने के बाद क्या सबक रहना चाहिए?",
