    ),
    "confident" to KrishnaLetterTranslation(
        situation = "जब आप आत्मविश्वास महसूस करें",
        title = "आत्मविश्वास को काम आने दें",
        preview = "सुनने, तैयारी करने और सीखने के लिए जगह छोड़ते समय अपनी क्षमता पर भरोसा रखें।",
        paragraphs = listOf("आप तैयार महसूस करते हैं। यह ताकत अभ्यास, अनुभव या अंततः स्वयं को स्पष्ट रूप से देखने से आ सकती है। सिर उठा के। आत्मविश्वास आपको बोलने, शुरू करने और जो सही है उसकी रक्षा करने में मदद करता है। आपको सिकुड़ने की ज़रूरत नहीं है ताकि दूसरों को कभी चुनौती महसूस न हो। [केएफवाई4] फिर भी, आत्मविश्वास कोई वादा नहीं है कि आप गलत नहीं हो सकते। तथ्य सुनें. कम शक्ति वाले लोगों का सम्मान करें। नेतृत्व करने से पहले प्रश्न पूछें. किसी कमरे में सबसे मजबूत व्यक्ति स्वीकार कर सकता है, 'मुझे नहीं पता,' योजना बदल सकता है और छोटा महसूस किए बिना श्रेय दे सकता है।", "फिर भी, आत्मविश्वास कोई वादा नहीं है कि आप गलत नहीं हो सकते। तथ्य सुनें. कम शक्ति वाले लोगों का सम्मान करें। नेतृत्व करने से पहले प्रश्न पूछें. किसी कमरे में सबसे मजबूत व्यक्ति स्वीकार कर सकता है, 'मुझे नहीं पता,' योजना बदल सकता है और छोटा महसूस किए बिना श्रेय दे सकता है।", "अपने आत्मविश्वास का उपयोग जिम्मेदारी लेने के लिए करें, ध्यान नियंत्रित करने के लिए नहीं। किसी शांत व्यक्ति को बोलने के लिए आमंत्रित करें। किसी ऐसे व्यक्ति का बचाव करें जिसके साथ गलत व्यवहार किया जा रहा हो। कठिन कार्य को ईमानदारी से करने का प्रयास करें। जब ताकत सच्चाई की रक्षा करती है और दूसरों के लिए जगह बनाती है, तो यह घमंड की बजाय साहस बन जाती है।", "मेरे साथ खड़े रहो और अपनी ताकत का अच्छा उपयोग करो। स्पष्ट बोलें, कड़ी मेहनत करें और उस व्यक्ति की रक्षा करें जिसकी आवाज को नजरअंदाज किया जाता है।"),
        reflection = "क्योंकि आप अपने आत्मविश्वास का अच्छी तरह से उपयोग करते हैं तो कौन अधिक सुरक्षित या मजबूत महसूस कर सकता है?",
        nextStep = "एक साहसिक कार्य करें और ऐसा करते समय दूसरे व्यक्ति की आवाज़ के लिए जगह बनाएं।"
    ),
    "inspired" to KrishnaLetterTranslation(
        situation = "जब आप प्रेरित महसूस करें",
        title = "चिंगारी फीकी पड़ने से पहले शुरुआत करें",
        preview = "प्रेरणा एक निमंत्रण है; अनुशासन इसे किसी उपयोगी चीज़ में बदल देता है।",
        paragraphs = listOf("किसी विचार, व्यक्ति या सत्य ने आपको जगाया है। एक पल के लिए, आप देख सकते हैं कि जीवन क्या बन सकता है। उस चिंगारी का सम्मान करें. इससे पहले कि शोर इसे कवर कर ले, इसे लिख लें। प्रेरणा बहुमूल्य है, लेकिन यह किसी लंबे कार्य की पहली सांस मात्र है। [केएफवाई4] हर दिन इस शक्तिशाली को महसूस करने के लिए इंतजार न करें। एक छोटी दिनचर्या चुनें जो मूड सामान्य होने पर भी जारी रह सके। स्पष्ट समय पर अध्ययन, अभ्यास, निर्माण या सेवा करें। बार-बार दोहराया गया एक ईमानदार दस मिनट आपको एक उज्ज्वल घंटे से भी आगे ले जा सकता है और उसके बाद कुछ भी नहीं।", "हर दिन इस शक्तिशाली को महसूस करने की प्रतीक्षा न करें। एक छोटी दिनचर्या चुनें जो मूड सामान्य होने पर भी जारी रह सके। स्पष्ट समय पर अध्ययन, अभ्यास, निर्माण या सेवा करें। बार-बार दोहराया गया एक ईमानदार दस मिनट आपको एक उज्ज्वल घंटे से भी आगे ले जा सकता है और उसके बाद कुछ भी नहीं।", "जांचें कि आपकी प्रेरणा धर्म का सम्मान करती है। एक खूबसूरत लक्ष्य के लिए झूठ, नुकसान या अपने वास्तविक कर्तव्यों की उपेक्षा की आवश्यकता नहीं होनी चाहिए। यदि यह अच्छा है, तो इसे आपकी छवि से अधिक लाभ होने दें। कुछ ऐसा बनाएं जो सिखाता हो, सुरक्षा करता हो, उपचार करता हो या दुनिया में ईमानदार सुंदरता लाता हो।", "मैंने यह चिंगारी आपके ध्यान में रखी है; अब अभ्यास से इसका सम्मान करें। भावना ख़त्म होने से पहले शुरू करें और जब काम सामान्य हो जाए तो वापस आ जाएँ।"),
        reflection = "यह प्रेरणा आपसे कौन सा उपयोगी कार्य शुरू करने के लिए कह रही है?",
        nextStep = "विचार को एक वाक्य में लिखें और इसे आज से शुरू करते हुए पंद्रह केंद्रित मिनट बिताएं।"
    ),
    "belonging" to KrishnaLetterTranslation(
        situation = "जब आपको लगे कि आप अपने हैं",
        title = "सर्कल को व्यापक बनाने में मदद करें",
        preview = "अपनेपन का एक सच्चा स्थान आपको स्वयं होने देता है और दूसरों के लिए भी जगह बनाता है।",
        paragraphs = listOf("आपको ऐसे लोग या जगह मिल गई है जहां आपके कंधे नरम हो सकते हैं। आप परिचित, स्वागत योग्य और किसी चीज़ का हिस्सा महसूस करते हैं। उस उपहार को संजोकर रखें। अपनापन ताकत देता है क्योंकि यह दिल से कहता है, 'आपको हर दिन का अकेले सामना नहीं करना पड़ेगा।'", "ईमानदारी और देखभाल के साथ इस घेरे की रक्षा करें। गपशप में शामिल होकर, नुकसान छिपाकर या किसी अलग व्यक्ति को बाहर करके अपना स्थान बनाए न रखें। जिस समूह को एकजुट महसूस करने के लिए पीड़ित की आवश्यकता होती है वह प्रेम का अभ्यास नहीं कर रहा है। वास्तविक अपनापन आपको अपने मूल्यों को बाहर छोड़ने के लिए नहीं कहता।", "किनारे पर खड़े व्यक्ति को देखें। उनका नाम जानें. उन पर दबाव डाले बिना उन्हें आमंत्रित करें. स्थान साझा करें और अपनी कहानी से भिन्न कहानी सुनें। सबसे सुरक्षित समुदाय तब बनते हैं जब सुरक्षित महसूस करने वाले लोग उस सुरक्षा का उपयोग स्वागत, बचाव और शामिल करने के लिए करते हैं। [केएफवाई6] मुझे खुशी है कि आपको एक ऐसा घेरा मिल गया है जहां आपका दिल आराम कर सकता है। अब गौर करें कि इसके ठीक बाहर कौन खड़ा है।", "मुझे खुशी है कि आपको एक ऐसा घेरा मिल गया है जहां आपका दिल आराम कर सकता है। अब गौर करें कि इसके ठीक बाहर कौन खड़ा है।"),
        reflection = "आपके आस-पास कौन है जो इस साधारण संकेत का इंतजार कर रहा होगा कि उनका स्वागत है?",
        nextStep = "किसी एक व्यक्ति को बातचीत, भोजन, खेल या साझा कार्य में आमंत्रित करें और उनकी बात सुनें।"
    ),
    "disappointed" to KrishnaLetterTranslation(
