        title = "शांत से भागने से पहले गहराई से देखें",
        preview = "बोरियत उद्देश्य, आराम, चुनौती या आपका पूरा ध्यान मांग सकती है।",
        paragraphs = listOf("कुछ भी दिलचस्प नहीं लगता और आपका हाथ त्वरित शोर तक पहुंचता रहता है। अपने आप को जज मत करो. बोरियत तब प्रकट हो सकती है जब कोई कार्य बहुत आसान हो, बहुत कठिन हो, बार-बार दोहराया जाए या अर्थ से अलग हो जाए। यह तब भी आ सकता है जब आपका दिमाग थका हुआ हो।", "प्रत्येक खाली सेकंड को भरने से पहले रुकें। पूछें कि आपको क्या चाहिए: आराम, हलचल, चुनौती, साथ या कोई स्पष्ट कारण। यदि कोई कर्तव्य पूरा करना ही है तो उसे छोटे-छोटे हिस्सों में बाँट लें और उस पर पूरा ध्यान दें। यदि आपको आराम की आवश्यकता है, तो ऐसा आराम चुनें जो वास्तव में आपको तरोताजा कर दे।", "शांति भी जिज्ञासा का द्वार खोल सकती है। किसी पक्षी को देखें, चित्र बनाएं, कुछ मरम्मत करें, पढ़ें, घर पर मदद करें या सीखें कि कोई सामान्य वस्तु कैसे काम करती है। जीवित रहने के लिए आपको निरंतर उत्साह की आवश्यकता नहीं है। ध्यान एक साधारण दिन में आश्चर्य प्रकट कर सकता है। [केएफवाई6] इससे पहले कि आप अधिक शोर की ओर दौड़ें, मेरे साथ बैठें और पूछें कि इस खालीपन को क्या चाहिए। यह आराम, चुनौती, आंदोलन, संगति या अर्थ हो सकता है।", "इससे पहले कि आप अधिक शोर की ओर दौड़ें, मेरे साथ बैठें और पूछें कि इस खालीपन को क्या चाहिए। यह आराम, चुनौती, आंदोलन, संगति या अर्थ हो सकता है।"),
        reflection = "क्या आपकी बोरियत आराम, चुनौती, अर्थ या जुड़ाव मांग रही है?",
