    "homesick" to KrishnaLetterTranslation(
        situation = "जब आपको घर की याद आती है",
        title = "जिन मूल्यों को आप जीते हैं उनमें घर लेकर चलें",
        preview = "दूरियां दुख पहुंचा सकती हैं, लेकिन प्यार और परिचित रास्ते आपके साथ यात्रा कर सकते हैं।",
        paragraphs = listOf("आपको परिचित आवाज़ें, भोजन, कमरे, सड़कें या आपके जाने से पहले जिस तरह का जीवन महसूस होता था, उसकी याद आती है। नई जगह अच्छी होने पर भी घर की याद आ सकती है। घर छूटने का मतलब यह नहीं है कि आपने गलत चुनाव किया है। इसका मतलब है कि आपकी जड़ें आपके लिए मायने रखती हैं।", "उन जड़ों को रहने की जगह दें। किसी को बुलाएं, परिचित भोजन बनाएं, कोई छोटा अनुष्ठान करें या किसी मित्र से अपनी भाषा में बात करें। फिर धीरे से एक बात सीखें कि आप अभी कहाँ हैं। बार-बार, सामान्य संपर्क से कोई नई जगह कम अजीब हो जाती है।", "हर नए व्यक्ति की तुलना घर के किसी व्यक्ति से न करें। नये बंधनों का अपना आकार हो। आप जहां से आए हैं वहां से प्यार कर सकते हैं और जहां आप खड़े हैं वहीं आगे बढ़ सकते हैं। घर केवल आपके पीछे की जगह नहीं है; यह आपकी देखभाल और मूल्यों में भी रहता है। [केएफवाई6] मैं उन आवाजों, गंधों और छोटी-छोटी आदतों को जानता हूं जिनकी ओर आपका दिल पहुंच रहा है। उन्हें प्यार से ले जाएं, लेकिन जहां आप अभी खड़े हैं, वहां का दरवाजा बंद न करें।", "मैं उन आवाजों, गंधों और छोटी-छोटी आदतों को जानता हूं जिनकी ओर आपका दिल पहुंच रहा है। उन्हें प्यार से ले जाएं, लेकिन जहां आप अभी खड़े हैं, वहां का दरवाजा बंद न करें।"),
        reflection = "घर का कौन सा छोटा सा हिस्सा आपको इस जगह से दूर रखे बिना आराम देगा?",
        nextStep = "आज एक परिचित अनुष्ठान रखें और अपने आसपास के किसी एक व्यक्ति या स्थान से अपना परिचय कराएं।"
    ),
    "child-truth" to KrishnaLetterTranslation(
        situation = "जब आप सच बोलने से डरते हैं",
        title = "सच्चाई आपको सुरक्षा में वापस ला सकती है",
        preview = "हो सकता है कि आपने गलती की हो, लेकिन इसे छिपाने से डर और बढ़ सकता है।",
        paragraphs = listOf("शायद कुछ टूट गया, किसी नियम की अनदेखी हुई या कोई अन्य व्यक्ति परेशान हो सकता है। आपका दिमाग जल्दी से एक अलग कहानी गढ़ रहा है क्योंकि आप सज़ा से डरते हैं। डर महसूस करना आपको बुरा नहीं बनाता. लेकिन सच्चाई सुरक्षा और विश्वास की ओर लौटने का पहला रास्ता है। [केएफवाई4] एक सुरक्षित वयस्क चुनें और सरलता से शुरुआत करें: 'मुझे आपको बताना होगा कि वास्तव में क्या हुआ था।' बताएं कि आपने क्या किया, आगे क्या हुआ और क्या किसी को चोट लग सकती है। पहले झूठ को बचाने के लिए नया झूठ न जोड़ें। एक सच्ची गलती को समझा जा सकता है, सुधारा जा सकता है और रोका जा सकता है।", "एक सुरक्षित वयस्क चुनें और बस शुरुआत करें: 'मुझे आपको यह बताना होगा कि वास्तव में क्या हुआ था।' बताएं कि आपने क्या किया, आगे क्या हुआ और क्या किसी को चोट लग सकती है। पहले झूठ को बचाने के लिए नया झूठ न जोड़ें। एक सच्ची गलती को समझा जा सकता है, सुधारा जा सकता है और रोका जा सकता है।", "आपको अभी भी उचित परिणाम का सामना करना पड़ सकता है। ईमानदारी जिम्मेदारी नहीं मिटाती; यह जिम्मेदारी को शुरू करने के लिए एक साफ़ जगह देता है। यदि आपके सच बोलने पर कोई वयस्क आपको डराता है, धमकाता है या चोट पहुँचाता है, तो किसी अन्य विश्वसनीय वयस्क से बात करें। सत्य को संरक्षण की ओर ले जाना चाहिए, दुरुपयोग की ओर नहीं।", "सच्चाई के साथ मेरे पास आओ, भले ही तुम्हारी आवाज़ कांपती हो। किसी गलती को छुपाने के लिए बनाई गई कहानी की तुलना में उसे अधिक आसानी से सुधारा जा सकता है।"),
        reflection = "कौन सा सुरक्षित वयस्क आपको पूरी सच्चाई बताने में मदद कर सकता है?",
        nextStep = "एक स्पष्ट वाक्य का उपयोग करके किसी सुरक्षित वयस्क को बताएं कि क्या हुआ और पूछें कि आप इसे कैसे सुधार सकते हैं।"
    ),
    "left-out-school" to KrishnaLetterTranslation(
