        title = "उनका दायरा आपकी कीमत तय नहीं करता है",
        preview = "बाहर किए जाने से दुख होता है, लेकिन अपनापन हासिल करने के लिए आपको निर्दयी बनने की जरूरत नहीं है।",
        paragraphs = listOf("आप दूसरों को एक साथ बात करते, खेलते या बैठते हुए देख सकते हैं जबकि कोई आपका नाम नहीं पुकारता। वह ख़ाली एहसास स्कूल को बहुत लंबा बना सकता है। कृपया यह निर्णय न लें कि आप अयोग्य हैं क्योंकि एक समूह ने जगह नहीं बनाई। आपकी दयालुता और उपहार अभी भी इस दुनिया में हैं। [केएफवाई4] हर किसी को प्रभावित करने की कोशिश करने के बजाय एक सौम्य शुरुआत की तलाश करें। किसी एक व्यक्ति से एक सरल प्रश्न पूछें, ऐसी गतिविधि में शामिल हों जिसका आप वास्तव में आनंद लेते हैं या किसी अन्य व्यक्ति का स्वागत करें जो अकेला हो। अच्छी दोस्ती अक्सर दो लोगों के बीच चुपचाप बढ़ती है, इससे पहले कि वह एक बड़ा दायरा बन जाए।", "हर किसी को प्रभावित करने की कोशिश करने के बजाय एक सौम्य शुरुआत की तलाश करें। किसी एक व्यक्ति से एक सरल प्रश्न पूछें, ऐसी गतिविधि में शामिल हों जिसका आप वास्तव में आनंद लेते हैं या किसी अन्य व्यक्ति का स्वागत करें जो अकेला हो। अच्छी दोस्ती अक्सर दो लोगों के बीच चुपचाप बढ़ती है, इससे पहले कि वह एक बड़ा दायरा बन जाए।", "यदि लोग आपको बार-बार बहिष्कृत करते हैं, मज़ाक उड़ाते हैं या धमकाते हैं, तो माता-पिता, शिक्षक या परामर्शदाता को बताएं। आप मदद मांग कर परेशानी पैदा नहीं कर रहे हैं. उन समूहों से दूर रहें जो प्रवेश की कीमत के रूप में क्रूरता की मांग करते हैं। वह स्थान जो आपसे किसी अन्य व्यक्ति को नुकसान पहुंचाने के लिए कहता है, वह सच्चा संबंध नहीं है।", "मैं तुम्हें किनारे पर खड़ा हुआ देख रहा हूं और सोच रहा हूं कि तुम्हारे साथ क्या गलत है। उनका दायरा आपकी योग्यता का पैमाना नहीं है।"),
        reflection = "एक छोटे से नमस्ते या शामिल होने के अनुरोध के लिए कौन पर्याप्त सुरक्षित महसूस करता है?",
        nextStep = "एक दयालु व्यक्ति से बात करें और यदि बहिष्कार या धमकाना जारी रहता है तो किसी विश्वसनीय वयस्क को बताएं।"
