    "student-focus" to KrishnaLetterTranslation(
        situation = "जब आप अपनी पढ़ाई पर ध्यान केंद्रित नहीं कर पाते",
        title = "एक छोटे से काम पर लौटें",
        preview = "भटकते दिमाग को एक स्पष्ट शुरुआत की जरूरत होती है, न कि अधिक अपमान की।",
        paragraphs = listOf("पेज खुला है लेकिन आपका ध्यान फ़ोन, किसी चिंता या काम के अलावा किसी और चीज़ की ओर जा रहा है। अपने आप को बहुत जल्दी आलसी मत कहो। आपका मन किसी ऐसे कार्य से थका हुआ, चिंतित, भ्रमित या अभिभूत हो सकता है जिसका कोई स्पष्ट प्रारंभिक बिंदु नहीं है।", "शुरुआत छोटी करें। एक प्रश्न या एक पृष्ठ चुनें. फ़ोन दूर रखें, एक छोटा टाइमर सेट करें और केवल वही सामग्री अपने सामने रखें जिसकी आपको ज़रूरत है। जब ध्यान भटक जाए तो उस पर ध्यान दें और वापस लौट आएं। वापसी ही वह व्यायाम है जो एकाग्रता बनाता है।", "केंद्रित अवधि के बाद, एक वास्तविक ब्रेक लें और जांचें कि किस चीज़ ने आपको अवरुद्ध किया है। जब आपको समझ न आए तो किसी शिक्षक या भरोसेमंद वयस्क से पूछें। यदि ध्यान संबंधी समस्याएं लंबे समय तक जीवन के कई हिस्सों को प्रभावित करती हैं, तो प्रशिक्षित मदद मदद कर सकती है। ध्यान केंद्रित करने में कठिनाई कोई नैतिक विफलता नहीं है।", "मेरे लिए बेचैन मन लाओ, कल पूर्ण बनने का वादा नहीं। हम काम को छोटा करेंगे: एक स्पष्ट कार्य, एक शांत स्थान और पूर्ण ध्यान की एक छोटी अवधि।"),
        reflection = "सबसे छोटा अध्ययन कार्य कौन सा है जिसे आप अभी स्पष्ट रूप से पूरा कर सकते हैं?",
        nextStep = "एक विकर्षण को दूर करें और एक बीस मिनट की फोकस अवधि पूरी करें और उसके बाद पांच मिनट का ब्रेक लें।"
