        title = "तैयारी रखें, घबराएं नहीं",
        preview = "परीक्षा मायने रखती है, लेकिन यह आपके संपूर्ण मूल्य या भविष्य को नहीं माप सकती।",
        paragraphs = listOf("आपका मन परीक्षा शुरू होने से पहले ही प्रत्येक प्रश्न को हल करने का प्रयास कर रहा होगा। तैयारी उपयोगी है; अपनी कल्पना में आपदा को दोहराना नहीं है। अगले विषय, अगले अभ्यास प्रश्न और अगले स्वस्थ घंटे पर वापस लौटें जो वास्तव में आपके हाथ में है। [केएफवाई4] आखिरी मिनट की हताशा भरी पढ़ाई के लिए नींद, भोजन और शांति का सौदा न करें। एक थका हुआ दिमाग जो अच्छी तरह से जानता है उसका उपयोग नहीं कर सकता। आवश्यक चीजों की समीक्षा करें, आपको जो चाहिए उसे तैयार करें और उचित समय पर रुकें। परीक्षा के दौरान, साँस लें, ध्यान से पढ़ें और जो आप समझते हैं उससे शुरू करें।", "आखिरी मिनट की हताशा भरी पढ़ाई के लिए नींद, भोजन और शांति का सौदा न करें। एक थका हुआ दिमाग जो अच्छी तरह से जानता है उसका उपयोग नहीं कर सकता। आवश्यक चीजों की समीक्षा करें, आपको जो चाहिए उसे तैयार करें और उचित समय पर रुकें। परीक्षा के दौरान, साँस लें, ध्यान से पढ़ें और जो आप समझते हैं उससे शुरू करें।", "इसके बाद, हर अनिश्चित उत्तर को दोबारा दोहराकर खुद को दंडित न करें। फिलहाल काम पूरा हो गया है. माता-पिता, शिक्षक, गुरु, मित्र या भाई-बहन को धन्यवाद देना याद रखें जिन्होंने आपको समझाया, प्रोत्साहित किया, समय दिया या चुपचाप आप पर विश्वास किया। उनकी मदद आपके प्रयास को कम नहीं करती; इसे पहचानने से आपकी उपलब्धि अधिक ईमानदार हो जाती है और आपका हृदय अधिक विनम्र हो जाता है। एक परिणाम अगली पद्धति का मार्गदर्शन कर सकता है, लेकिन यह आपकी बुद्धिमत्ता, अच्छाई या उद्देश्य का नाम नहीं दे सकता। आप जो परिणाम चाहते हैं और जिस परिणाम से आपको सीखना चाहिए, मैं उसमें आपके साथ हूं।", "परिणाम मेरे हाथ में रखें और तैयारी अपने हाथ में रखें। यह परीक्षा एक दिन में कुछ उत्तरों को माप सकती है; यह आपके पूरे दिमाग, दिल या भविष्य को नहीं माप सकता।"),
        reflection = "कौन सी तैयारी अभी भी उपयोगी है, और कौन सी चिंता अब दूर हो सकती है?",
        nextStep = "एक केंद्रित समीक्षा पूरी करें, अपनी सामग्री तैयार करें और नींद की पूरी अवधि सुरक्षित रखें।"
    ),
    "youth-peer-pressure" to KrishnaLetterTranslation(
        situation = "जब दोस्त आप पर दबाव डालते हैं",
        title = "अपनेपन की कीमत आपके मूल्यों पर नहीं होनी चाहिए",
        preview = "भीड़ किसी हानिकारक विकल्प को सुरक्षित या सही नहीं बना सकती।",
        paragraphs = listOf("शायद वे हंस रहे हैं, आपको चुनौती दे रहे हैं या कह रहे हैं कि हर कोई ऐसा करता है। आपको डर है कि एक 'नहीं' आपको कमज़ोर या अकेला दिखा देगा। याद रखें कि दबाव अक्सर चुटकुलों के पीछे छिपा होता है। जो कोई भी आपके स्वास्थ्य, ईमानदारी, शरीर या सुरक्षा की मांग करता है वह आपकी दोस्ती की रक्षा नहीं कर रहा है।", "आपको लंबी बहस की जरूरत नहीं है। कहें, 'नहीं, मैं ऐसा नहीं कर रहा हूं,' सुरक्षित स्थान की ओर बढ़ें और किसी ऐसे व्यक्ति से संपर्क करें जिस पर आप भरोसा करते हैं। यदि दबाव में मादक पदार्थ, खतरनाक ड्राइविंग, यौन गतिविधि, हिंसा या कोई असुरक्षित रहस्य शामिल है, तो तुरंत छोड़ दें और वयस्क सहायता लें।", "किसी समूह को खोने से दुख हो सकता है। लेकिन एक पल के लिए अकेले खड़े रहना उनकी मंजूरी के बीच अपना निर्णय खोने से बेहतर है। ऐसे लोगों की तलाश करें जो खुद को धोखा दिए बिना जीवन का आनंद ले सकें। आपके योग्य मित्रताएँ आपके नंबर के लिए जगह छोड़ देंगी।", "आप अपने स्वास्थ्य, शरीर, ईमानदारी या भविष्य के लिए भीड़ के ऋणी नहीं हैं। एक सच्चा दोस्त यह मांग नहीं करेगा कि आप अपनापन साबित करने के लिए खुद को धोखा दें।"),
        reflection = "यह दबाव आपसे किस मूल्य या सुरक्षा सीमा को धोखा देने के लिए कह रहा है?",
        nextStep = "एक स्पष्ट इनकार का अभ्यास करें और उस व्यक्ति का संपर्क बचाएं जो आपको सुरक्षित निकलने में मदद कर सकता है।"
    ),
    "identity-confusion" to KrishnaLetterTranslation(
        situation = "जब आप नहीं जानते कि आप कौन हैं",
        title = "आपको अधूरा रहने की अनुमति है",
        preview = "पहचान मूल्यों, ईमानदार अनुभव और समय के माध्यम से बढ़ सकती है।",
        paragraphs = listOf("लोग पूछते रह सकते हैं कि आप क्या बनेंगे, आप कहां हैं या आप किसी और की तरह क्यों नहीं हैं। हो सकता है आपके पास स्पष्ट उत्तर न हो. अनिश्चितता का मतलब खालीपन नहीं है. यह वह ईमानदार स्थान हो सकता है जहां आपको पता चलता है कि वास्तव में आपका क्या है। [केएफवाई4] ध्यान दें कि क्या चीज़ आपको जीवित महसूस कराती है, आप किस तरह का नुकसान पहुंचाने से इनकार करते हैं और आप कौन से कर्तव्य ईमानदारी से निभा सकते हैं। कौशल आज़माएं, अलग-अलग लोगों से मिलें और हर अनुभव को एक स्थायी लेबल में डाले बिना सीखें। जैसे-जैसे आप बड़े होते हैं आप अपनी समझ बदल सकते हैं।", "ध्यान दें कि क्या चीज़ आपको जीवित महसूस कराती है, आप किस प्रकार का नुकसान पहुँचाने से इनकार करते हैं और आप कौन से कर्तव्य ईमानदारी से निभा सकते हैं। कौशल आज़माएं, अलग-अलग लोगों से मिलें और हर अनुभव को एक स्थायी लेबल में डाले बिना सीखें। जैसे-जैसे आप बड़े होते हैं आप अपनी समझ बदल सकते हैं।", "अपने स्वयं के मूल्यों को सुनने से पहले किसी भीड़, रिश्ते या ऑनलाइन छवि को आपको परिभाषित न करने दें। किसी अन्य व्यक्ति को अपने जीवन का स्वामित्व दिए बिना सुरक्षित मार्गदर्शन प्राप्त करें। आपकी पहचान बिना किसी विरोधाभास के परिवार, विश्वास, प्रश्न, उपहार और परिवर्तन को धारण कर सकती है।", "आपको अधूरा रहने की अनुमति है। केवल इसलिए लेबल पहनने में जल्दबाजी न करें क्योंकि अनिश्चितता असहज महसूस कराती है।"),
        reflection = "आप अपने जीवन में कौन से तीन मूल्य व्यक्त करना चाहते हैं, चाहे आप कोई भी रास्ता चुनें?",
        nextStep = "तीन मान लिखें और एक छोटी सी कार्रवाई करें जिससे उनमें से एक आज दिखाई दे।"
    ),
    "parent-failing" to KrishnaLetterTranslation(
        situation = "जब आपको लगे कि आप एक माता-पिता के रूप में असफल हो रहे हैं",
        title = "आपकी अगली मरम्मत पूर्णता से अधिक मायने रखती है",
        preview = "पालन-पोषण की एक गलती विनम्रता, मरम्मत और विकास का स्थान बन सकती है।",
        paragraphs = listOf("आपको चिल्लाना, छूटे हुए संकेत या प्रतिक्रिया याद हो सकती है जिसे आप वापस लेना चाहते हैं। तुलना आपको केवल बाहर से दूसरे परिवार दिखाती है और फिर नालायक बताती है। आपके बच्चे को ऐसे माता-पिता की ज़रूरत नहीं है जो एक आदर्श छवि की रक्षा करते हों। उन्हें ऐसे माता-पिता की ज़रूरत है जो देखने और मरम्मत करने के इच्छुक हों।", "बिना कोई बहाना जोड़े सटीक गलती बताएं: 'मैं चिल्लाया। वह भयावह और गलत था।' सुनिए बच्चे का अनुभव। मरम्मत की पेशकश करें और बताएं कि आप अलग तरीके से क्या करेंगे। माफ़ी आपके अधिकार को ख़त्म नहीं करती; यह सिखाता है कि प्राधिकार भी सत्य का उत्तर देता है।", "फिर आपको जो मदद चाहिए वह मांगें। थकावट, आघात, संघर्ष या मानसिक-स्वास्थ्य तनाव के लिए समर्थन की आवश्यकता हो सकती है, न कि अधिक निजी शर्म की। कोई नाटकीय वादा करने के बजाय एक बार दोहराई जा सकने वाली प्रतिक्रिया बदलें। एक शांत विराम, साप्ताहिक बातचीत या पेशेवर मार्गदर्शन से घर में बदलाव की शुरुआत हो सकती है। [केएफवाई6] मैं आपसे ऐसा माता-पिता बनने के लिए नहीं कहता जो कभी गलती नहीं करता। मैं आपसे नोटिस करने, माफी मांगने, मरम्मत करने और वापस लौटने के लिए कहता हूं।", "मैं आपसे ऐसा माता-पिता बनने के लिए नहीं कहता जो कभी गलतियाँ नहीं करता। मैं आपसे नोटिस करने, माफी मांगने, मरम्मत करने और वापस लौटने के लिए कहता हूं।"),
        reflection = "आपको छिपाने के बजाय किस विशिष्ट प्रतिक्रिया की मरम्मत की आवश्यकता है?",
        nextStep = "एक पूर्ण क्षमायाचना दें और एक व्यावहारिक परिवर्तन लिखें जिसे आप अगली बार उसी स्थिति में उपयोग करेंगे।"
    ),
    "child-pulls-away" to KrishnaLetterTranslation(
        situation = "जब आपका बच्चा दूर जा रहा हो",
        title = "बिना पीछा किए दरवाजा खुला रखें",
        preview = "बढ़ती स्वतंत्रता संबंध बदल देती है; इसका मतलब हमेशा यह नहीं होता कि प्यार गायब हो गया है।",
        paragraphs = listOf("वह बच्चा जिसने कभी आपको सब कुछ बताया था, अब एक शब्द में उत्तर दे सकता है, दरवाजा बंद कर सकता है या पहले दोस्तों की ओर मुड़ सकता है। डर आपको हर चुप्पी पर सवाल उठाने के लिए प्रेरित कर सकता है। कुछ दूरी विकास का हिस्सा है, जबकि कुछ चुप्पी उस चोट का संकेत हो सकती है जिस पर ध्यान देने की जरूरत है।", "बहुत अधिक प्रश्नों के बिना कनेक्शन प्रदान करें। उन्हें चाय, ड्राइव या अपने बगल में किसी साधारण काम के लिए आमंत्रित करें। एक खुला प्रश्न पूछें और तुरंत चुप्पी न भरें। खतरे, दुर्व्यवहार, पदार्थों और गंभीर मानसिक संकट के आसपास स्पष्ट सुरक्षा सीमाएँ बनाए रखते हुए सामान्य गोपनीयता का सम्मान करें।", "उन्हें पास खींचने के लिए अपराध बोध का प्रयोग न करें। अपनी देखभाल को भरोसेमंद बनने दें: जब सच्चाई आती है तो शांत रहें, जब सुरक्षा मायने रखती है तो दृढ़ रहें और इस बात में रुचि रखें कि वे कौन बन रहे हैं। यदि परिवर्तन अचानक, अत्यधिक या चेतावनी के संकेतों से जुड़ा है, तो अस्वीकृति मानने के बजाय प्रशिक्षित सहायता लें।", "हर चुप्पी का पीछा डर या नियंत्रण से न करें। बढ़ते बच्चों को जगह की ज़रूरत होती है, लेकिन फिर भी उन्हें एक ऐसे दरवाज़े की ज़रूरत होती है जो बिना शर्म के खुलता हो।"),
        reflection = "किस प्रकार का संबंध आपके बच्चे के लिए मांग के बजाय सुरक्षित महसूस हो सकता है?",
        nextStep = "एक कम दबाव वाली साझा गतिविधि की पेशकश करें और जब तक अनुरोध न किया जाए, सलाह दिए बिना सुनें।"
    ),
    "work-taken-over" to KrishnaLetterTranslation(
        situation = "जब काम आपके जीवन पर हावी हो जाए",
        title = "आपका कर्तव्य उसे निभाने वाले व्यक्ति पर हावी नहीं होना चाहिए",
        preview = "काम मायने रखता है, लेकिन स्वास्थ्य, रिश्ते और आंतरिक जीवन भी जिम्मेदारियां हैं।",
        paragraphs = listOf("काम सुबह का पहला विचार और रात में आखिरी स्क्रीन हो सकता है। यहाँ तक कि आराम भी पीछे छूटता हुआ महसूस होता है। ईमानदार कर्तव्य पवित्र है, लेकिन अंतहीन उपलब्धता उत्कृष्टता के समान नहीं है। केवल आउटपुट के इर्द-गिर्द बनी जिंदगी अंततः काम करने वाले व्यक्ति को कमजोर कर देती है। [केएफवाई4] ईमानदारी से देखें कि क्या आवश्यक है, महत्वाकांक्षा क्या है और डर क्या बन गया है। एक रोक बिंदु निर्धारित करें, भोजन और नींद की रक्षा करें और यथार्थवादी अपेक्षाओं का संचार करें। यदि कार्यस्थल स्थायी आपातकाल पर निर्भर करता है, तो पैटर्न का दस्तावेजीकरण करें और जहां संभव हो, जिम्मेदार समर्थन या सुरक्षित रास्ता तलाशें।", "ईमानदारी से देखें कि क्या आवश्यक है, क्या महत्वाकांक्षा है और क्या भय बन गया है। एक रोक बिंदु निर्धारित करें, भोजन और नींद की रक्षा करें और यथार्थवादी अपेक्षाओं का संचार करें। यदि कार्यस्थल स्थायी आपातकाल पर निर्भर करता है, तो पैटर्न का दस्तावेजीकरण करें और जहां संभव हो, जिम्मेदार समर्थन या सुरक्षित रास्ता तलाशें।", "अपना ध्यान किसी ऐसे व्यक्ति या चीज़ पर लौटाएं जिसे उत्पादकता के रूप में नहीं मापा जा सकता है। परिवार से बात करें, टहलें, प्रार्थना करें या प्रदर्शन किए बिना बैठें। आपका कैरियर आपकी पहचान के बिना आपके उपहारों का उपयोग कर सकता है। विश्राम समय की चोरी नहीं है जब यह निर्णय, स्वास्थ्य और स्वच्छ कार्य की रक्षा करता है।", "आपका काम आपके कर्तव्य का हिस्सा है; यह आपका संपूर्ण जीवन नहीं है। मैं आपसे नींद, स्वास्थ्य, परिवार, मौन और उस व्यक्ति से भी मिलता हूं जो आप उपलब्धि से दूर हो जाते हैं।"),
        reflection = "काम का कौन सा हिस्सा सच्चा कर्तव्य है, और कौन सा हिस्सा डर को रोकने से इनकार करता है?",
        nextStep = "आज एक स्पष्ट समाप्ति समय निर्धारित करें और स्वास्थ्य, संबंध या मौन के लिए बिना विचलित हुए तीस मिनट दें।"
