        preview = "अपने उद्देश्य को विषाक्त करने के लिए खोई हुई प्रशंसा की अनुमति दिए बिना निष्पक्षता की तलाश करें।",
        paragraphs = listOf("हो सकता है कि आपने समस्याएं हल की हों, दूसरों का समर्थन किया हो या जिम्मेदारी निभाई हो, जबकि किसी और ने ध्यान आकर्षित किया हो। दुख होना स्वाभाविक है. विनम्रता के लिए यह दिखावा करने की आवश्यकता नहीं है कि अनुचितता स्वीकार्य है या आपके योगदान को बार-बार मिटाने की अनुमति नहीं है।", "तथ्य इकट्ठा करें और शांत बातचीत के लिए कहें। अपने योगदान का वर्णन करें, स्पष्ट प्रतिक्रिया का अनुरोध करें और क्रेडिट, भूमिका या विकास पर सीधे चर्चा करें। किसी अन्य व्यक्ति की सफलता पर हमला करने या छिपे हुए प्रयास को संचार का एकमात्र रूप बनाने से बचें। लोग हमेशा उस काम को नहीं पहचान पाते जो उन्हें कभी नहीं दिखाया जाता।", "यदि प्रशंसा अभी भी नहीं मिलती है, तो तय करें कि स्थिति इस जगह के बारे में क्या सिखाती है। यदि आवश्यक हो तो स्वस्थ अवसरों की खोज करते हुए ईमानदारी के साथ आगे बढ़ें। आक्रोश को सावधानीपूर्वक किए गए कार्य को लापरवाही में न बदलने दें। आपका मूल्य एक उपाधि से बड़ा है, लेकिन निष्पक्ष व्यवहार अभी भी एक स्पष्ट आवाज़ का हकदार है। [केएफवाई6] मैं देख रहा हूं कि आपका सावधानीपूर्वक किया गया काम जिसकी कोई प्रशंसा नहीं हुई और वह जिम्मेदारी जो आपने बिना दिखावे के निभाई। मानवीय प्रशंसा देर से या अनुपस्थित हो सकती है, लेकिन कड़वाहट को अपनी पेशकश को दूषित न करने दें।", "मैं आपके सावधानीपूर्वक किए गए कार्य को देख रहा हूं जिसकी कोई प्रशंसा नहीं हुई और आपकी जिम्मेदारी बिना दिखावे के निभाई गई। मानवीय प्रशंसा देर से या अनुपस्थित हो सकती है, लेकिन कड़वाहट को अपनी पेशकश को दूषित न करने दें।"),
