    "couple-arguments" to KrishnaLetterTranslation(
        situation = "जब हर बातचीत एक तर्क बन जाती है",
        title = "लड़ाई को रोकें और आवश्यकता का पता लगाएं",
        preview = "एक रिश्ता तब तक ठीक नहीं हो सकता जब तक दोनों लोग केवल जीतने के लिए लड़ रहे हों।",
        paragraphs = listOf("बहस एक छोटे से मुद्दे से शुरू हो सकती है और जल्दी ही हर पुराने घाव को इकट्ठा कर सकती है। दोनों लोग ऊंचे स्वर में बोलते हैं क्योंकि किसी को भी सुना हुआ महसूस नहीं होता। इससे पहले कि क्रूर शब्द रिश्ते के खिलाफ नए सबूत बन जाएं, रुकें। जब आप स्पष्ट रूप से वापस लौटने का वादा करते हैं तो विराम परित्याग नहीं है।", "शांत होने पर, हमेशा या कभी नहीं जैसे लेबल के बिना किसी एक घटना का वर्णन करें। इसके नीचे की भावना और आवश्यकता को नाम दें। तब तक सुनें जब तक आप दूसरे व्यक्ति की चिंता को निष्पक्ष रूप से दोहरा न सकें। समझ के लिए सहमति की आवश्यकता नहीं होती है, लेकिन यह आपको एक-दूसरे के कल्पित संस्करण से लड़ने से रोकता है।", "एक व्यावहारिक परिवर्तन और इसकी समीक्षा के लिए एक समय पर सहमत हों। यदि धमकियाँ, नियंत्रण, हिंसा या भय है, तो सुरक्षा और प्रशिक्षित सहायता को प्राथमिकता दें; संचार तकनीकें दुरुपयोग का समाधान नहीं करतीं। प्यार में असहमति हो सकती है, लेकिन इसका इस्तेमाल नुकसान सहने की मांग के लिए नहीं किया जाना चाहिए।", "मैं उस विराम में मौजूद हूं जहां आप दोनों जीतने की कोशिश करना बंद कर देते हैं। व्यक्ति पर हमला किए बिना घाव के बारे में बोलें।"),
        reflection = "बार-बार दिए जा रहे तर्क के पीछे आप क्या व्यक्त करना चाह रहे हैं?",
        nextStep = "एक मुद्दे पर बीस मिनट की शांत बातचीत का अनुरोध करें और प्रत्येक एक विशिष्ट परिवर्तन पर सहमत हों।"
