        paragraphs = listOf("शायद एक झूठ, छिपी हुई पसंद या टूटे हुए वादे ने आपके बंधन की सुरक्षा को बदल दिया है। हो सकता है कि दोनों दिल तुरंत राहत चाहते हों, लेकिन भरोसे को उसकी पुरानी जगह पर वापस नहीं लाया जा सकता। जिस व्यक्ति को नुकसान पहुँचाया गया है उसे प्रश्नों, सीमाओं और अपनी गति के लिए जगह की आवश्यकता है। [केएफवाई4] यदि आपने नुकसान पहुंचाया है, तो दूसरे व्यक्ति को सांत्वना दिए बिना पूरी सच्चाई बताएं। उचित पारदर्शिता स्वीकार करें और जो सुधारा जा सकता है उसे सुधारें। यदि आपको नुकसान पहुँचाया गया है, तो निर्णय लें कि आपको परिवर्तन के किस साक्ष्य की आवश्यकता है। क्षमा तत्काल पहुंच को बाध्य नहीं करती या बुद्धिमानी की सीमाएं नहीं हटाती।", "यदि आपने नुकसान पहुंचाया है, तो दूसरे व्यक्ति को सांत्वना दिए बिना पूरी सच्चाई बताएं। उचित पारदर्शिता स्वीकार करें और जो सुधारा जा सकता है उसे सुधारें। यदि आपको नुकसान पहुँचाया गया है, तो निर्णय लें कि आपको परिवर्तन के किस साक्ष्य की आवश्यकता है। क्षमा तत्काल पहुंच को बाध्य नहीं करती या बुद्धिमानी की सीमाएं नहीं हटाती।", "छोटे-छोटे वादे चुनें जिन्हें लगातार निभाया जा सके। हर असहमति में घाव को एक हथियार के रूप में दोबारा खोले बिना प्रगति की समीक्षा करें। कुछ रिश्ते फिर से बन सकते हैं; दूसरों को दूरी की आवश्यकता हो सकती है। जब उल्लंघन गंभीर हो, बार-बार दोहराया जाए या दुर्व्यवहार से जुड़ा हो तो प्रशिक्षित सहायता लें।", "एक माफी के माध्यम से विश्वास वापस नहीं लिया जा सकता। सत्य को सुसंगत बनने दें, प्रश्नों को धैर्यपूर्वक उत्तर मिलने दें और घाव भरने तक सीमाएँ बनी रहने दें।"),
        reflection = "कौन सा लगातार व्यवहार विश्वास को सुरक्षित बनाएगा, न कि केवल शांत?",
        nextStep = "व्यवहार बदल रहा है या नहीं, इसकी समीक्षा के लिए एक स्पष्ट वादे, एक सीमा और एक तारीख पर सहमत हों।"
