    "depending-on-others" to KrishnaLetterTranslation(
        situation = "जब आपको दूसरों पर निर्भर रहना पड़ता है",
        title = "देखभाल प्राप्त करने से आपकी गरिमा कम नहीं होती है",
        preview = "मदद की आवश्यकता आपकी दिनचर्या को बदल सकती है, लेकिन यह आपके मूल्य या आवाज को नहीं मिटाती है। [केएफवाई3] शायद बीमारी, उम्र या स्थिति अब आपको उन कार्यों के लिए मदद मांगने पर मजबूर कर रही है जिन्हें आप पहले आसानी से करते थे। आपको बोझ बनने का डर हो सकता है. याद रखें कि मानव जीवन हमेशा देने और लेने के माध्यम से आगे बढ़ा है। स्वतंत्रता कभी भी एकमात्र प्रमाण नहीं थी कि आपका जीवन मायने रखता है।",
        paragraphs = listOf("शायद बीमारी, उम्र या स्थिति अब आपको उन कार्यों के लिए मदद मांगने पर मजबूर कर रही है जिन्हें आप पहले आसानी से करते थे। आपको बोझ बनने का डर हो सकता है. याद रखें कि मानव जीवन हमेशा देने और लेने के माध्यम से आगे बढ़ा है। स्वतंत्रता कभी भी एकमात्र प्रमाण नहीं थी कि आपका जीवन मायने रखता है।", "अपनी प्राथमिकताओं को नाम दें और विकल्पों को अभी भी आपके लिए उपलब्ध रखें। सहायकों को अपने साथ बात करने के लिए कहें, अपने आसपास नहीं। असुविधा या सीमाओं को स्पष्ट रूप से व्यक्त करते हुए धन्यवाद के साथ देखभाल स्वीकार करें। अच्छी देखभाल गरिमा की रक्षा करती है और नियंत्रण की अनुमति के रूप में निर्भरता का उपयोग नहीं करती है।", "रिश्तों में कार्यों और चिकित्सा से भी अधिक शामिल होने दें। कोई स्मृति साझा करें, किसी अन्य व्यक्ति के दिन के बारे में पूछें, प्रार्थना करें, हंसें या आमंत्रित होने पर सलाह दें। यदि कोई आपकी उपेक्षा करता है, डराता है, फायदा उठाता है या आपको नुकसान पहुंचाता है, तो किसी अन्य विश्वसनीय व्यक्ति या जिम्मेदार सेवा को बताएं। निर्भरता कभी भी आपकी सुरक्षा के अधिकार को रद्द नहीं करती। [केएफवाई6] मदद प्राप्त करने से वह जीवन नहीं मिट जाता जिसमें आपने कई अन्य लोगों की मदद की। खुद को बोझ कहे बिना देखभाल को आप तक पहुंचने दें।", "सहायता प्राप्त करने से वह जीवन नहीं मिट जाता जिसमें आपने कई अन्य लोगों की मदद की। खुद को बोझ कहे बिना देखभाल को आप तक पहुंचने दें।"),
        reflection = "कौन सा विकल्प या प्राथमिकता आपको अपनी देखभाल में अधिक सम्मानित महसूस करने में मदद करेगी? [केएफवाई8] देखभाल करने वाले को एक प्राथमिकता स्पष्ट रूप से बताएं और मौजूदा के लिए माफी मांगे बिना एक आवश्यक सहायता प्राप्त करें।",
        nextStep = "देखभालकर्ता को एक प्राथमिकता स्पष्ट रूप से बताएं और मौजूदा के लिए माफी मांगे बिना आवश्यक सहायता प्राप्त करें।"
    ),
    "caring-for-ill" to KrishnaLetterTranslation(
        situation = "जब आप किसी बीमार व्यक्ति की देखभाल कर रहे हैं",
        title = "आपकी देखभाल मायने रखती है, और आपका जीवन भी मायने रखता है",
        preview = "प्यार देखभाल करने वाले को गायब किए बिना गहराई से सेवा कर सकता है।",
        paragraphs = listOf("आपका दिन दवाओं, नियुक्तियों, अनिश्चितता और बाधित नींद के आसपास व्यवस्थित हो सकता है। दूसरे लोग उस व्यक्ति के बारे में पूछ सकते हैं जो बीमार है और यह पूछना भूल जाते हैं कि आप कैसे हैं। आपकी देखभाल वास्तविक है, लेकिन थकावट ही एकमात्र प्रमाण नहीं है कि आपका प्यार सच्चा है।", "लिखिए कि क्या किया जाना चाहिए और क्या साझा किया जा सकता है। केवल यह कहने के बजाय कि चीजें कठिन हैं, रिश्तेदारों, दोस्तों या सेवाओं से विशिष्ट सहायता के लिए पूछें। भोजन, आराम, चिकित्सा आवश्यकताओं और जीवन के एक छोटे से हिस्से की रक्षा करें जो आपका है। एक बहुत थका हुआ देखभालकर्ता भी देखभाल का पात्र है।", "आपको एक ही घंटे में प्यार, गुस्सा, डर और थकान महसूस हो सकती है। ये एहसास आपको बेवफा नहीं बनाते. जब भार उठाना बहुत भारी हो जाए तो किसी सुरक्षित व्यक्ति से बात करें और प्रशिक्षित मदद लें। यदि देखभाल की जरूरतें आपकी क्षमता से अधिक हैं, तो प्रशिक्षित सहायता मांगना जिम्मेदार है, परित्याग नहीं। [केएफवाई6] मैं नियुक्तियां देखता हूं, नींद में बाधा आती है और शांत भय रहता है कि अन्य लोग ध्यान न दें। सेवा पवित्र है, लेकिन आपको इसके अंदर गायब होने की आवश्यकता नहीं है।", "मैं नियुक्तियाँ, बाधित नींद और शांत भय देखता हूँ कि अन्य लोग ध्यान न दें। सेवा पवित्र है, लेकिन आपको इसके अंदर गायब होने की आवश्यकता नहीं है।"),
        reflection = "देखभाल भार का कौन सा हिस्सा कोई अन्य व्यक्ति सुरक्षित रूप से ले जा सकता है?",
        nextStep = "एक व्यक्ति से एक विशिष्ट कार्य के लिए पूछें और इस सप्ताह आराम की एक निर्बाध अवधि सुरक्षित रखें।"
    ),
    "grief-returns" to KrishnaLetterTranslation(
        situation = "जब दुख अप्रत्याशित रूप से लौटता है",
        title = "एक लौटती लहर आपके उपचार को नहीं मिटाती है",
        preview = "एक तारीख, गीत या स्थान बिना किसी चेतावनी के प्यार और दर्द को जगा सकता है।",
        paragraphs = listOf("आपने खुद को स्थिर महसूस किया होगा और फिर अचानक खुद को रोते हुए पाया होगा जैसे कि नुकसान नया हो। इसे असफलता मत कहिये. दुख एक सीधी रेखा में नहीं चलता. दिल मौसमों, वर्षगाँठों, ध्वनियों और सामान्य क्षणों के माध्यम से याद करता है जो कभी दो लोगों के थे।", "लहर को गुजरने दें बिना यह तय किए कि यह हमेशा के लिए रहेगी। नाम बताएं कि इसे किसने जगाया? कोई स्मृति साझा करें, चुपचाप बैठें, प्रार्थना करें या किसी ऐसे व्यक्ति से संपर्क करें जो समझता हो। पानी, भोजन और आराम से शरीर की देखभाल करें। आपको भावना को उत्पादक बनाने की आवश्यकता नहीं है।", "जब लहर नरम हो जाए, तो धीरे से उस कर्तव्य या रिश्ते पर लौट आएं जो अभी भी आपके हाथ में है। निरंतर जीवन जीना उस व्यक्ति को धोखा नहीं देता जिसे आप चूकते हैं। यदि दुःख भारी, खतरनाक बना रहता है या लंबे समय तक दैनिक जीवन में बाधा डालता है, तो प्रशिक्षित सहायता आध्यात्मिक देखभाल के साथ-साथ चल सकती है। [केएफवाई6] इस लौटती लहर का मतलब यह नहीं है कि आप ठीक होने में विफल रहे हैं। प्यार महीनों तक शांत रह सकता है और फिर किसी डेट, गाने या परिचित जगह के जरिए बयां हो सकता है।", "इस लौटती लहर का मतलब यह नहीं है कि आप ठीक होने में विफल रहे हैं। प्यार महीनों तक शांत रह सकता है और फिर किसी डेट, गाने या परिचित जगह के जरिए बयां हो सकता है।"),
        reflection = "आज किस स्मृति या क्षण को सम्मानित करने की मांग की जा रही है?",
        nextStep = "एक सुरक्षित व्यक्ति के साथ एक स्मृति साझा करें और अपने वर्तमान जीवन के लिए देखभाल का एक सौम्य कार्य चुनें।"
    ),
    "leader-decision" to KrishnaLetterTranslation(
        situation = "जब दूसरे आपके निर्णय पर निर्भर हों",
        title = "सत्ता को कार्य करने से पहले सुनने दें",
        preview = "एक नेता की पसंद को लोगों, सच्चाई और दीर्घकालिक कल्याण की रक्षा करनी चाहिए - न कि केवल दिखावे की।",
        paragraphs = listOf("लोग आपके उत्तर की प्रतीक्षा कर रहे होंगे जबकि आप ऐसे तथ्य ले जा रहे हैं जिन्हें वे नहीं देख सकते। निश्चित दिखने का दबाव बुद्धिमान बनने की इच्छा से भी अधिक प्रबल हो सकता है। यह समझने के लिए पर्याप्त धीमे रहें कि निर्णय की लागत कौन वहन करेगा, विशेष रूप से कम शक्ति वाले लोग।", "ईमानदार असहमति को आमंत्रित करें और पूछें कि कौन सा सबूत आपके मन को बदल देगा। मिशन की जरूरतों को अपने अहंकार की जरूरतों से अलग करें। एक लोकप्रिय निर्णय अभी भी गलत हो सकता है, और एक असुविधाजनक निर्णय के लिए अभी भी करुणा, स्पष्टीकरण और नुकसान को कम करने की योजना की आवश्यकता हो सकती है।", "फिर निर्णय लें और जिम्मेदारी लें। जब चुनाव आपका हो तो टीम के पीछे न छुपें और सफल होने पर सारा श्रेय न लें। जब तथ्य बदल जाएं तो परिणाम की समीक्षा करें और सही दिशा अपनाएं। जब सत्ता धर्म के प्रति जवाबदेह रहती है तो नेतृत्व सेवा बन जाता है।", "इससे पहले कि लोग आपके निर्णय का पालन करें, मेरे पास वह शक्ति लाएँ जो उसमें निहित है। विशेष रूप से उन लोगों की बात सुनें जो लागत वहन करेंगे लेकिन उनके पास कम अधिकार हैं।"),
        reflection = "आपने अभी तक किसकी आवाज़ या परिणाम पर विचार नहीं किया है?",
        nextStep = "निर्णय लेने या पुष्टि करने से पहले कम अधिकार वाले एक प्रभावित व्यक्ति से ईमानदार इनपुट के लिए पूछें।"
    ),
    "faith-dry" to KrishnaLetterTranslation(
        situation = "जब आपका विश्वास सूख जाता है",
        title = "ईमानदारी भक्ति का एक रूप हो सकती है",
        preview = "ईमानदारी से चलते रहने के लिए आपको कृष्ण के करीब महसूस करने का दिखावा करने की ज़रूरत नहीं है।",
        paragraphs = listOf("प्रार्थना एक ख़ाली कमरे से लौटते हुए शब्दों की तरह महसूस हो सकती है। जो अभ्यास कभी गर्मजोशी लाता था, वह अब सामान्य या दूर का लग सकता है। अपनी भावना का मूल्यांकन करने के लिए भावनाओं पर ज़ोर न डालें या किसी अन्य व्यक्ति की भक्ति का उपयोग न करें। एक शांत मौसम यह साबित नहीं करता कि प्यार ख़त्म हो गया है। [केएफवाई4] मेरे लिए सत्य लाओ: 'मैं तुम्हें महसूस नहीं करता, लेकिन मैं यहां हूं।' आध्यात्मिक अनुभव की मांग किए बिना एक कविता धीरे-धीरे पढ़ें, एक मिनट बैठें या एक तरह का कार्य करें। प्रबल भावना के अभाव में ईमानदार अभ्यास से ही भक्ति बनी रह सकती है।", "मेरे लिए सत्य लाओ: 'मैं तुम्हें महसूस नहीं करता, लेकिन मैं यहां हूं।' एक श्लोक धीरे-धीरे पढ़ें, एक मिनट के लिए बैठें या आध्यात्मिक अनुभव की मांग किए बिना एक तरह का कार्य करें। प्रबल भावना के अभाव में ईमानदार अभ्यास से ही भक्ति बनी रह सकती है।", "जांच करें कि क्या थकावट, दुःख, निराशा या अनुत्तरित प्रश्नों पर ध्यान देने की आवश्यकता है। एक बुद्धिमान, भरोसेमंद व्यक्ति से बात करें जो बिना किसी डर के सवाल पूछने की अनुमति देता है। जिस विश्वास को कभी पूछने की अनुमति नहीं दी गई वह नाजुक बना रह सकता है। अपने प्रश्नों को आपको शर्मसार करने के बजाय सच्चाई को गहरा करने दें।", "आपको मेरे करीब रहने के लिए किसी भावना को मजबूर करने की ज़रूरत नहीं है। मेरे लिए शांत प्रार्थना, अनुत्तरित प्रश्न और यहाँ तक कि संदेह भी लाओ।"),
        reflection = "आप किस ईमानदार प्रश्न या निराशा को प्रार्थना में लाने से डरते हैं?",
        nextStep = "एक ईमानदार प्रार्थना लिखें और प्रेरित महसूस करने की प्रतीक्षा किए बिना सेवा का एक छोटा सा कार्य पूरा करें।"
    ),
    "moving-on" to KrishnaLetterTranslation(
