        situation = "जब उनकी उपस्थिति से आपको शांति मिलती है",
        title = "शांति को सत्य की आवश्यकता होती है, दिखावे की नहीं",
        preview = "कुछ असुविधाएं रिश्तों को बढ़ने में मदद करती हैं; बार-बार भय और अनादर नहीं होता।",
        paragraphs = listOf("इस व्यक्ति के कॉल करने या कमरे में प्रवेश करने से पहले आपका शरीर तनावग्रस्त हो सकता है। आप हर शब्द का पूर्वाभ्यास कर सकते हैं क्योंकि छोटी-छोटी बातें अक्सर दोषारोपण, नियंत्रण या संघर्ष बन जाती हैं। आपका शरीर आपको जो बता रहा है उसे खारिज न करें, लेकिन अकेले एक कठिन दिन से निर्णय न लें।", "पूछें कि पैटर्न क्या रहा है। क्या आप बिना किसी डर के ईमानदारी से बात कर सकते हैं? क्या वे आपकी ना का सम्मान करते हैं? क्या नुकसान के बाद मरम्मत संभव है? एक स्वस्थ बंधन में असहमति, चुनौती और विकास शामिल हो सकते हैं। किसी अन्य व्यक्ति को शांत रखने के लिए आपको नींद खोने, सच्चाई छिपाने या छोटा बनने की आवश्यकता नहीं होनी चाहिए।", "एक स्पष्ट सीमा निर्धारित करें और बुद्धिमानी से समर्थन प्राप्त करें। यदि कोई धमकी, हिंसा, पीछा करना, नियंत्रण या दुर्व्यवहार है, तो निजी बैठक के बजाय सुरक्षा और प्रशिक्षित सहायता चुनें। आप दूर से ही किसी को शुभकामनाएं दे सकते हैं। शांति की रक्षा करना हर समस्या को टालना नहीं है; यह बार-बार होने वाले नुकसान को सामान्य बनने से इनकार कर रहा है। [केएफवाई6] मैं आपसे हर कड़ी बात को हानिकारक कहने के लिए नहीं कहता, लेकिन मैं आपसे बार-बार डर और अनादर के अंदर जीने के लिए भी नहीं कहता। सत्य को तुम्हें पैटर्न दिखाने दो।", "मैं आपसे हर कड़ी बात को हानिकारक कहने के लिए नहीं कहता, लेकिन मैं आपसे बार-बार डर और अनादर के अंदर जीने के लिए भी नहीं कहता। सत्य को तुम्हें पैटर्न दिखाने दो।"),
        reflection = "क्या आपकी शांति स्वस्थ विकास या बार-बार होने वाले नुकसान के कारण भंग हो गई है?",
        nextStep = "पैटर्न को तथ्यों में लिखें और इसे किसी विश्वसनीय व्यक्ति के साथ साझा करें जो सत्य और सुरक्षा का समर्थन करेगा।"
    ),
    "returning-to-hurt" to KrishnaLetterTranslation(
        situation = "जब आप उस चीज़ पर लौटते रहते हैं जो आपको चोट पहुँचाती है",
        title = "एक परिचित दरवाजा अभी भी दर्द का कारण बन सकता है",
        preview = "वापस लौटना आपको मूर्ख नहीं बनाता है, लेकिन पैटर्न एक और वादे से अधिक का हकदार है।",
        paragraphs = listOf("शायद आप चले गए और वापस आ गए, ब्लॉक कर दिया और फिर से कॉल किया, या खुद से वादा किया कि इस बार अलग होगा। खाली जगह की तुलना में परिचित दर्द कम भयावह लग सकता है। आशा है कि एक अच्छी याददाश्त बनी रहेगी जबकि आपका दिमाग बार-बार होने वाले नुकसान को एक तरफ धकेल देता है।", "अपने आप को शर्मिंदा मत करो। शर्म अक्सर लोगों को उसी चक्र में वापस भेज देती है। लिखें कि हर बार क्या हुआ, क्या वादा किया गया था और वास्तव में क्या बदला। स्थिर कार्यों पर भरोसा करें, न कि केवल आंसुओं, उपहारों या खूबसूरत शब्दों पर जो तब दिखाई देते हैं जब आप जाने वाले होते हैं।", "समर्थन के साथ अगला चुनाव करें। किसी को सुरक्षित बताएं, खतरे की ओर वापस जाने के लिए आसान रास्ते निकालें और दुर्व्यवहार, लत या मजबूत भावनात्मक निर्भरता शामिल होने पर प्रशिक्षित मदद लें। किसी व्यक्ति को खोने का मतलब यह नहीं कि वापस लौटना बुद्धिमानी है। आप सुरक्षा चुनते समय भी प्यार, दुःख और लालसा महसूस कर सकते हैं।", "शर्मिंदा मत होइए कि आप लौट आए। अज्ञात भविष्य की तुलना में परिचित दर्द अधिक आसान लग सकता है।"),
        reflection = "आशा आपसे कौन से तथ्य भूलने के लिए कहती रहती है?",
        nextStep = "दोहराए गए पैटर्न को लिखें और एक सुरक्षित व्यक्ति से आपके द्वारा चुनी गई सीमा को बनाए रखने में मदद करने के लिए कहें।"
    ),
    "friendship-changed" to KrishnaLetterTranslation(
        situation = "जब दोस्ती अब पहले जैसी नहीं रही",
        title = "हर दूरी को एक दुश्मन की जरूरत नहीं होती",
        preview = "दोस्ती अतीत को झूठा बनाए बिना समय, विकास और नए कर्तव्यों के माध्यम से बदल सकती है।",
        paragraphs = listOf("एक दोस्त जो कभी आपके दिन के हर हिस्से को जानता था, वह अब कम कॉल कर सकता है, अलग तरीके से जवाब दे सकता है या बहुत दूर लग सकता है। आपको आश्चर्य हो सकता है कि आपने क्या गलत किया। कभी-कभी चोट लगती है जिसके लिए बात करने की ज़रूरत होती है। कभी-कभी दो जिंदगियां अलग-अलग गति से चलने लगती हैं।", "एक बार ध्यान से पूछें: 'मुझे हमारे बीच दूरी महसूस हो रही है। क्या कुछ गड़बड़ है?' बचाव की तैयारी किए बिना सुनें। यदि मरम्मत की आवश्यकता है, तो ईमानदार रहें। यदि जीवन बदल गया है, तो अपराधबोध, लगातार जाँच या आपके द्वारा साझा की गई हर चीज़ की याद दिलाने के माध्यम से निकटता को मजबूर न करें।", "दोस्ती ने जो दिया उसके लिए धन्यवाद। यदि बंधन अभी भी दयालु है तो दरवाज़ा खुला रखें, लेकिन नए लोगों और कर्तव्यों के लिए भी जगह बनाएं। एक बदलती दोस्ती अपने साथ आई हंसी, मदद या विकास को नहीं मिटाती। आप पुराने बंधन के पुराने आकार की मांग किए बिना उसका सम्मान कर सकते हैं। [केएफवाई6] कुछ मित्रताएं एक मौसम में घनिष्ठता से चलती हैं और दूसरे मौसम में धीरे-धीरे बदल जाती हैं। हर दूरी को दुश्मन की कहानी में मत बदलो।", "कुछ मित्रताएँ एक मौसम में घनिष्ठता से चलती हैं और दूसरे मौसम में धीरे-धीरे बदल जाती हैं। हर दूरी को दुश्मन की कहानी में मत बदलो।"),
        reflection = "क्या इस दोस्ती को मरम्मत, नए आकार या सौम्य अलविदा की ज़रूरत है?",
        nextStep = "एक ईमानदार बातचीत करें, फिर उस रिश्ते को उतनी ही ऊर्जा दें जो अभी मौजूद है और देखभाल कर रहा है।"
    ),
    "outgrown-place" to KrishnaLetterTranslation(
        situation = "जब आप किसी स्थान से आगे निकल जाते हैं",
        title = "विकास उस स्थान का सम्मान कर सकता है जहां से इसकी शुरुआत हुई थी",
        preview = "एक स्थान पिछले सीज़न के लिए अच्छा हो सकता है और फिर भी आपकी अगली ड्यूटी के लिए बहुत छोटा हो सकता है।",
        paragraphs = listOf("किसी नौकरी, समूह, शहर या भूमिका ने एक बार आपको सुरक्षित और उपयोगी महसूस करने में मदद की होगी। अब आप अधिक सीखने, अलग ढंग से सेवा करने या अधिक सच्चाई के साथ जीने के लिए प्रेरित महसूस कर सकते हैं। छोड़ने से उत्साह और अपराधबोध दोनों हो सकता है, खासकर जब अच्छे लोगों ने वहां आपकी मदद की हो। [केएफवाई4] विकास को उन लोगों से बेहतर होने के साथ भ्रमित न करें जो रुके हुए हैं। पूछें कि क्या आप वास्तविक मूल्य की ओर बढ़ रहे हैं या केवल सामान्य प्रयास से भाग रहे हैं। कर्तव्यों को सफाई से पूरा करें, निष्पक्ष सूचना दें, दूसरों को जो चाहिए उसे साझा करें और उन लोगों को धन्यवाद दें जिन्होंने पहला दरवाजा खोला।", "विकास को उन लोगों से बेहतर होने के साथ भ्रमित न करें जो रुके हुए हैं। पूछें कि क्या आप वास्तविक मूल्य की ओर बढ़ रहे हैं या केवल सामान्य प्रयास से भाग रहे हैं। कर्तव्यों को सफाई से पूरा करें, निष्पक्ष सूचना दें, दूसरों को जो चाहिए उसे साझा करें और उन लोगों को धन्यवाद दें जिन्होंने पहला दरवाजा खोला।", "फिर अपने आप को जाने की अनुमति दें। आप अपने जीवन में समान दीवारें रखे बिना भी अच्छी आदतें, दोस्ती और सबक अपना सकते हैं। जड़ें किसी पेड़ को बीज बने रहने के लिए नहीं कहतीं। कृतज्ञता को पीछे की ओर देखने दें जबकि साहस अगला ईमानदार कदम आगे बढ़ाता है। [केएफवाई6] विकास से एक पुराना कमरा बहुत छोटा महसूस हो सकता है, लेकिन इसे अहंकार के साथ मत छोड़ें। उस स्थान को धन्यवाद दें जहां आपका पुराना संस्करण रखा हुआ था। [केएफवाई7] क्या आप धर्म की ओर बढ़ना छोड़ रहे हैं, या केवल उस कठिनाई से बच रहे हैं जो आपका पीछा करेगी?", "विकास से एक पुराना कमरा बहुत छोटा महसूस हो सकता है, लेकिन घमंड के साथ मत छोड़ें। उस स्थान को धन्यवाद दें जहां आपका पुराना संस्करण रखा हुआ था।"),
        reflection = "क्या आप धर्म की ओर बढ़ने के लिए जा रहे हैं, या केवल उस कठिनाई से बच रहे हैं जो आपका पीछा करेगी?",
        nextStep = "आप जिस दिशा में आगे बढ़ रहे हैं उसे लिखें, एक कर्तव्य को अच्छी तरह से पूरा करें और एक व्यक्ति को धन्यवाद दें जिसने आपको यहां बढ़ने में मदद की।"
    ),
    "guilty-choosing-self" to KrishnaLetterTranslation(
        situation = "जब आप खुद को चुनने के लिए दोषी महसूस करते हैं",
        title = "आत्म-देखभाल स्वार्थ के समान नहीं है",
        preview = "आपका स्वास्थ्य, सुरक्षा और ईमानदार सीमाएं भी आपके कर्तव्य का हिस्सा हैं।",
        paragraphs = listOf("आपने जान लिया होगा कि प्यार का मतलब हमेशा हाँ कहना है। जब आप आराम करते हैं, किसी अनुरोध को अस्वीकार करते हैं या कोई ऐसा रास्ता चुनते हैं जो दूसरों को नापसंद है, तो अपराध बोध आपको तुरंत स्वार्थी कह देता है। लेकिन हर मांग को पूरा करने में बिताया गया जीवन आपके सच्चे कर्तव्यों, स्वास्थ्य या उद्देश्य के लिए कोई ताकत नहीं छोड़ सकता।", "ईमानदारी से चुनाव को देखें। क्या आप उचित कर्तव्य से बच रहे हैं, या वास्तविक आवश्यकता की रक्षा कर रहे हैं? स्वार्थ के कारण दूसरों की उपेक्षा होती है। स्वस्थ आत्म-देखभाल में आपको मिटाए बिना दूसरों को शामिल किया जाता है। आप अपना वादा निभा सकते हैं और फिर भी मदद मांग सकते हैं। आप परिवार से प्यार कर सकते हैं और फिर भी अनादर, खतरे या नियंत्रण से इनकार कर सकते हैं।", "दयालुता के साथ अपनी सीमा स्पष्ट करें, लेकिन उसे पाने की अनुमति के लिए हमेशा बहस न करें। जो लोग आपकी चुप्पी से लाभान्वित हुए वे आपके परिवर्तन को निर्दयी कह सकते हैं। स्थिर, निष्पक्ष कार्यवाहियाँ सत्य दिखाएं। अपना ख्याल रखें ताकि आप जो दें वह ताकत से आए, डर और छिपे गुस्से से नहीं।", "अपना स्वास्थ्य, सुरक्षा और ईमानदार सीमाएँ चुनना केवल अपने बारे में देखभाल करने के समान नहीं है। मेरे लिये दोष लाओ और सत्य से उसका परीक्षण करो।"),
        reflection = "क्या यह अपराध बोध किसी वास्तविक कर्तव्य की ओर इशारा कर रहा है, या आपको स्वस्थ सीमा रखने के लिए दंडित कर रहा है?",
        nextStep = "उस कर्तव्य का नाम बताएं जिसे आप निभाएंगे और वह सीमा बताएं जो आपके स्वास्थ्य, सुरक्षा या शांति की रक्षा करेगी।"
    ),
    "memories-pull-back" to KrishnaLetterTranslation(
        situation = "जब यादें आपको पीछे खींचती रहती हैं",
        title = "आज को छोड़े बिना याद रखें",
        preview = "अतीत को एकमात्र ऐसा स्थान बने बिना सम्मानित किया जा सकता है जहां आपका दिल रहता है।",
        paragraphs = listOf("एक गीत, स्थान, संदेश या शांत समय आपको इतनी पूरी तरह से वापस ले जा सकता है कि आज गायब हो जाता है। कुछ यादें गर्माहट लाती हैं। अन्य लोग पछतावे और लालसा को फिर से खोलते हैं। आप उन्हें दोहराना जारी रख सकते हैं क्योंकि अतीत ज्ञात लगता है जबकि वर्तमान अभी भी खाली लगता है।", "हर स्मृति से मत लड़ो। एक क्षण के लिए इसके साथ बैठें और जो आपको याद आता है उसका नाम बताएं: व्यक्ति, सुरक्षा, आशा या स्वयं का संस्करण। सबक और प्यार बनाए रखें. फिर ध्यान दें कि स्मृति क्या छोड़ जाती है, जिसमें दर्द, सीमाएँ या कर्तव्य भी शामिल हैं जो उस समय के थे।", "अपनी इंद्रियों के माध्यम से लौटें। अपने पैरों को महसूस करें, चारों ओर देखें और तारीख बताएं। किसी उपस्थित व्यक्ति को बुलाएं, एक कार्य पूरा करें या सावधानी से एक नई स्मृति बनाएं। यदि दर्दनाक यादें दैनिक जीवन, नींद या सुरक्षा पर हावी हो जाती हैं, तो प्रशिक्षित सहायता लें। अब वापस लौटने में आप समर्थन के पात्र हैं।", "एक स्मृति श्रृंखला बने बिना एक दीपक बन सकती है। जब पुराना दृश्य लौट आए तो मेरे साथ बैठो।"),
        reflection = "आप वास्तव में स्मृति के नीचे क्या याद करते हैं?",
        nextStep = "दस मिनट तक एक स्मृति का सम्मान करें, फिर आज अपने जीवन में किसी व्यक्ति या कर्तव्य को पूरा एक घंटा दें।"
    ),
    "closure-never-came" to KrishnaLetterTranslation(
        situation = "जब आप जिस दरवाजे को बंद करना चाहते थे वह कभी नहीं आया",
        title = "आप अपने दरवाजे को बंद कर सकते हैं",
        preview = "माफी या जवाब कभी नहीं आ सकता है, लेकिन आपके जीवन को इसके लिए इंतजार नहीं करना पड़ेगा।",
        paragraphs = listOf("आप अभी भी उनके समझाने, नुकसान स्वीकार करने या ऐसे शब्द कहने का इंतजार कर रहे होंगे जिससे सब कुछ स्पष्ट हो जाएगा। आपका दिमाग एक और बातचीत का निर्माण करता रहता है। बंद होने से ऐसा महसूस होता है मानो यह किसी अन्य व्यक्ति की ईमानदारी के अंदर बंद है, और वे इसे कभी पेश नहीं कर सकते। [केएफवाई4] इसे स्वीकार करने का मतलब यह नहीं है कि नुकसान सही था। इसका मतलब है कि उनके कार्यों ने जो दिखाया है उसका सामना करना। जो प्रश्न बचे हैं उन्हें लिखें और केवल वही उत्तर दें जिसकी अनुमति तथ्य देते हैं। कुछ रिक्त स्थान रिक्त ही रहने चाहिए. उन्हें अपने विरुद्ध दोष से न भरें।", "इसे स्वीकार करने का मतलब यह नहीं है कि नुकसान सही था। इसका मतलब है कि उनके कार्यों ने जो दिखाया है उसका सामना करना। जो प्रश्न बचे हैं उन्हें लिखें और केवल वही उत्तर दें जिसकी अनुमति तथ्य देते हैं। कुछ रिक्त स्थान रिक्त ही रहने चाहिए. उन्हें अपने विरुद्ध दोष से न भरें।", "अपने स्वयं के सत्य के माध्यम से समापन करें: जो हुआ उसे नाम दें, पाठ चुनें, सीमा निर्धारित करें और ऐसे उत्तर के लिए वापस लौटना बंद करें जिसमें हर बार अधिक शांति खर्च होती है। कोई काउंसलर, बुजुर्ग या भरोसेमंद दोस्त आपकी कहानी का गवाह बन सकता है। उपचार शुरू होने से पहले आपको उस व्यक्ति की सहमति की आवश्यकता नहीं है जिसने आपको चोट पहुंचाई है। [केएफवाई6] आपको कभी भी माफी या उत्तर नहीं मिलेगा जो कहानी को साफ-सुथरा बना देगा। उस बंद दरवाजे पर प्रतीक्षा करके किसी अन्य व्यक्ति को आजीवन अपनी शांति पर नियंत्रण न दें।", "हो सकता है कि आपको कभी भी वह माफ़ी या उत्तर न मिले जो कहानी को साफ़-सुथरा बना दे। उस बंद दरवाजे पर प्रतीक्षा करके किसी अन्य व्यक्ति को आजीवन अपनी शांति पर नियंत्रण न दें।"),
        reflection = "स्वयं को स्थानांतरित करने की अनुमति देने से पहले आप अभी भी किसी अन्य व्यक्ति से कौन सा उत्तर देने के लिए कह रहे हैं?",
        nextStep = "उनके कार्यों के आधार पर उत्तर लिखें, एक सीमा चुनें और सात दिनों के लिए एक प्रकार की जाँच रोक दें।"
    ),
    "love-trust-gone" to KrishnaLetterTranslation(
        situation = "जब प्यार बना रहता है लेकिन भरोसा खत्म हो जाता है",
        title = "प्यार सुरक्षा की आवश्यकता को दूर नहीं करता है",
        preview = "एक दिल अभी भी परवाह कर सकता है जबकि बुद्धिमान निर्णय के लिए प्रमाण, सीमा या दूरी की आवश्यकता होती है।",
        paragraphs = listOf("आप अभी भी किसी ऐसे व्यक्ति से प्यार कर सकते हैं जिसने झूठ बोला, वादा तोड़ा या आपको असुरक्षित महसूस कराया। यह भ्रमित करने वाला हो सकता है. भरोसा टूटने पर प्यार बंद नहीं होता. लेकिन बार-बार की गई हरकतों से जो नुकसान हुआ है, उसे अकेले प्यार से दोबारा नहीं बनाया जा सकता।", "सच्चाई, खुले उत्तर, निभाए वादे और अपनी सीमाओं के प्रति सम्मान के माध्यम से विश्वास धीरे-धीरे लौटता है। इसलिए जल्दबाजी न करें क्योंकि उन्हें खेद है या आप अच्छे दिन चूक गए हैं। यदि आपने नुकसान पहुँचाया है, तो स्वीकार करें कि दूसरे व्यक्ति को समय की आवश्यकता हो सकती है। यदि आपको नुकसान पहुँचाया गया है, तो आप पूर्ण पहुँच प्रदान किए बिना कार्रवाई देख सकते हैं।", "कुछ बंधन लगातार मरम्मत और प्रशिक्षित मदद से ठीक हो सकते हैं। कुछ को दूरी या अंत की आवश्यकता होती है, खासकर जब नुकसान जारी रहता है। क्षमा के लिए तथ्यों को भूलने की आवश्यकता नहीं है। आप अपने शरीर, दिमाग और भविष्य की रक्षा करने वाली सीमा चुनते समय अपने दिल में प्यार रख सकते हैं।", "सुरक्षा टूटने के बाद भी प्यार बना रह सकता है। प्यार को इस सबूत के तौर पर इस्तेमाल न करें कि विश्वास तुरंत वापस आना चाहिए।"),
        reflection = "विश्वास को सुरक्षित बनाने के लिए वादे की नहीं, किस कार्रवाई की आवश्यकता होगी?",
        nextStep = "अधिक भरोसा देने से पहले आवश्यक एक स्पष्ट सीमा और एक स्थिर कार्रवाई लिखें।"
    ),
    "beginning-betrays-past" to KrishnaLetterTranslation(
        situation = "जब दोबारा शुरुआत करना अतीत को धोखा देने जैसा लगता है",
        title = "आगे बढ़ना अपने साथ प्यार भी ले जा सकता है",
        preview = "एक नया जीवन उस व्यक्ति, सपने या मौसम को नहीं मिटाता है जो उसके पहले मायने रखता था।",
        paragraphs = listOf("आपको डर हो सकता है कि दोबारा मुस्कुराने, दोबारा प्यार करने या नया सपना बुनने का मतलब है कि अतीत कम मायने रखता है। आपका एक हिस्सा दर्द के करीब रहता है क्योंकि दर्द वफादार लगता है। आप यह मान सकते हैं कि आगे बढ़ने से कोई न कोई कीमती चीज़ पीछे छूट जाती है।", "प्यार इस बात से नहीं मापा जाता कि आप कितनी देर तक जीवन को नकारते हैं। आपने जो खोया है उसमें से एक मूल्य, आदत, कहानी या दयालुता अपने साथ रखें। इसे उस व्यक्ति को आकार देने दें जो आप बनते हैं। अतीत ज्ञान और प्रेम के रूप में यात्रा कर सकता है; इसे एक वजन के रूप में यात्रा करने की आवश्यकता नहीं है जो हर नए कदम को रोक देता है।", "धीरे-धीरे आगे बढ़ें। एक नई शुरुआत यह मांग नहीं करती कि आप हर दिन भूल जाएं या खुश महसूस करें। यह केवल इतना ही पूछता है कि आप आज के दिन को भी अर्थपूर्ण होने दें। स्मृति बोलें, जो पवित्र है उसे रखें और उस व्यक्ति, कर्तव्य या आशा के लिए एक छोटा सा स्थान खोलें जो अभी यहां है। [केएफवाई6] आगे बढ़ने से वह व्यक्ति, सपना या जीवन नहीं मिट जाता जिससे आप प्यार करते थे। अतीत के सर्वोत्तम को एक मूल्य के रूप में अपने साथ रखें, वजन के रूप में नहीं।", "आगे बढ़ने से वह व्यक्ति, सपना या जीवन नहीं मिट जाता जिससे आप प्यार करते थे। अतीत के सर्वोत्तम को एक मूल्य के रूप में अपने साथ रखें, वजन के रूप में नहीं।"),
        reflection = "अतीत के किस हिस्से को आप दर्द के बजाय प्यार के रूप में ले जा सकते हैं?",
        nextStep = "अतीत से एक मूल्य चुनें और इस सप्ताह एक नई कार्रवाई के माध्यम से इसे जीएं।"
    ),
    "rise-again" to KrishnaLetterTranslation(
        situation = "जब आप फिर से उठने के लिए तैयार हों",
        title = "सबक के साथ उठें, वजन से नहीं",
        preview = "गिरना आपकी अंतिम कहानी नहीं है; एक ईमानदार कदम आपकी वापसी की शुरुआत कर सकता है।",
        paragraphs = listOf("मैंने देखा कि किस चीज़ ने आपको नीचे गिराया। मैंने वह प्रयास देखा जिस पर किसी का ध्यान नहीं गया और वह दर्द जो आपने अपनी मुस्कान के पीछे छिपाया था। लेकिन यह क्षण आपकी कहानी का अंत नहीं है। गिरना आपको कमज़ोर नहीं बनाता, और खड़े होने के लिए समय की ज़रूरत आपको कम योग्य नहीं बनाती।", "धीरे-धीरे उठें। आपको एक दिन में मजबूत बनने की जरूरत नहीं है. एक ईमानदार कदम उठाएँ, फिर दूसरा। कल को सज़ा के तौर पर मत ढोओ. इसकी सीख लेकर चलें. पूछें कि क्या बदलाव होना चाहिए, बुद्धिमानी भरी मदद स्वीकार करें और शांत दिमाग और बेहतर समझ के साथ फिर से शुरुआत करें।", "मैं आपसे दुनिया के सामने कुछ भी साबित करने के लिए नहीं कह रहा हूं। मैं आपसे अपने भीतर बढ़ रही ताकत पर भरोसा करने के लिए कह रहा हूं। अगर आपको आराम की जरूरत है तो आराम करें, लेकिन हार के अंदर घर न बनाएं। आपके जीवन में अभी भी काम, प्रेम और धर्म आपके हाथों का इंतज़ार कर रहे हैं।", "उठो, मेरे प्रियजन। एक ही दिन में सब कुछ साबित करने की कोशिश न करें."),
        reflection = "ऐसा कौन सा सबक है जिसे आप शर्मिंदगी उठाए बिना आगे बढ़ा सकते हैं?",
