        title = "यह पल आपके पूरे जीवन का फैसला नहीं कर सकता",
        preview = "डर आज जोर से हो सकता है, लेकिन यह आपकी पूरी ताकत या भविष्य को नहीं जानता है।",
        paragraphs = listOf("यह क्षण शक्तिशाली लग सकता है। हो सकता है कि आपका दिमाग आपको एक ही बार में हर ख़तरा दिखा रहा हो और कह रहा हो कि आगे जो आएगा उसे आप संभाल नहीं सकते। विराम। आप पहले ही उन दिनों को पार कर चुके हैं जब आपने सोचा था कि आप कभी जीवित नहीं रह पाएंगे। वह शक्ति जो तुम्हें तब संभाले हुए थी, उसने तुम्हें नहीं छोड़ा है।", "अपने पूरे जीवन को एक डरे हुए घंटे में हल करने का प्रयास न करें। अपनी सांस को शांत रखें और केवल अगले सही कदम पर ध्यान दें। जहां जरूरत हो वहां मदद मांगें. जो आपके नियंत्रण में है उसे सावधानी से करें और कल के उन हिस्सों से लड़ना बंद करें जो अभी तक नहीं आए हैं।", "एक कठिन क्षण उस ताकत को प्रकट कर सकता है जिसे आराम ने कभी भी उपयोग करने के लिए नहीं कहा। यह दिन आपको स्थिरता, धैर्य और विश्वास सिखाए। समस्या वास्तविक हो सकती है, लेकिन डर यह तय नहीं करता कि इसका सामना करते समय आप कौन बनेंगे। [केएफवाई6] यह क्षण जोरदार हो सकता है, लेकिन यह उस ताकत से बड़ा नहीं है जो मैंने आपके भीतर रखी है। जब तक आप अगला सही काम न करें, मुझे भविष्य अपने पास रखने दीजिए।", "यह क्षण ज़ोरदार हो सकता है, लेकिन यह उस ताकत से बड़ा नहीं है जो मैंने आपके भीतर रखी है। जब तक आप अगला सही काम न करें, मुझे भविष्य अपने पास रखने दीजिए।"),
        reflection = "इस भयावह क्षण के अंदर अगला सही कदम क्या छिपा है? [केएफवाई8] पांच धीमी सांसें लें, एक चीज लिखें जिसे आप नियंत्रित कर सकते हैं और बड़ी चिंता पर लौटने से पहले इसे करें।",
        nextStep = "पाँच धीमी साँसें लें, एक चीज़ लिखें जिसे आप नियंत्रित कर सकते हैं और बड़ी चिंता पर लौटने से पहले इसे करें।"
    ),
    "life-purpose" to KrishnaLetterTranslation(
        situation = "जब आप चाहते हैं कि आपका जीवन मायने रखे",
        title = "उद्देश्य आपके पास मौजूद अच्छे से शुरू होता है",
        preview = "एक सार्थक जीवन ईमानदार कर्तव्यों, सेवा और देखभाल के साथ साझा किए गए उपहारों के माध्यम से बनता है।",
        paragraphs = listOf("आप एक महान उद्देश्य के प्रकट होने की प्रतीक्षा कर रहे होंगे। आप सोच सकते हैं कि आपका जीवन केवल प्रसिद्धि, धन या किसी बड़ी उपलब्धि से ही मायने रखेगा। लेकिन अर्थ अक्सर चुपचाप शुरू होता है: किसी की रक्षा करना, जो आप जानते हैं उसे सिखाना, कोई वादा निभाना या प्यार से आवश्यक काम करना।", "अपने पास खड़े कर्तव्य को देखो। ईमानदारी से पढ़ाई करें. ईमानदारी से काम करें. अपने परिवार, प्रकृति और हर जीवित प्राणी का ख्याल रखें। उस व्यक्ति की मदद करें जिसकी ज़रूरत आप सचमुच पूरी कर सकते हैं। दीपक यह नहीं पूछता कि कितने लोग उसकी रोशनी का गुणगान करेंगे। वह चमकता है क्योंकि प्रकाश देना उसका स्वभाव है।", "आपका उद्देश्य बढ़ सकता है और बदल सकता है, लेकिन आपके मूल्य हर चरण में मार्गदर्शन कर सकते हैं। जीवन को थोड़ा सुरक्षित, समझदार या दयालु बनाने के लिए अपने कौशल का उपयोग करें। सेवा का कोई भी ईमानदार कार्य अर्थ से छोटा नहीं होता। आप जो अच्छा करते हैं वह जितना आपने देखा है उससे कहीं अधिक दूर तक जा सकता है।", "सेवा करने से पहले किसी भव्य संकेत की प्रतीक्षा न करें। मैं आपसे आपके नजदीक की ड्यूटी में उस व्यक्ति से मिलता हूं जिसे देखभाल की जरूरत है और जिस उपहार का आप ईमानदारी से उपयोग करते हैं।"),
        reflection = "आज आपके निकट कौन या कौन सा व्यक्ति आपकी सर्वोत्तम देखभाल प्राप्त कर सकता है?",
        nextStep = "अपने आस-पास किसी व्यक्ति, जानवर, स्थान या कर्तव्य की मदद करने के लिए एक कौशल, घंटे या दयालु कार्रवाई का उपयोग करें।"
    ),
    "choose-courage" to KrishnaLetterTranslation(
        situation = "जब साहस आपको बुला रहा हो",
        title = "जब आप कांप रहे हों तब भी जो सही है उसे चुनें",
        preview = "साहस भय का अभाव नहीं है; यह धर्म का भय से अधिक मजबूत होना है।",
        paragraphs = listOf("साहस का मतलब यह नहीं है कि डर ख़त्म हो गया है। इसका मतलब यह है कि आप वही चुनते हैं जो सही है जबकि आपका दिल अभी भी कांप रहा है। आपको सच बोलने, किसी का बचाव करने, गलती स्वीकार करने, मदद मांगने या कुछ अनिश्चित शुरुआत करने की आवश्यकता हो सकती है। पूरी तरह से निडर महसूस करने की प्रतीक्षा न करें।", "क्रोध, अहंकार या शक्तिशाली दिखने की इच्छा को नहीं, बल्कि धर्म को आपके साहस का मार्गदर्शन करने दें। क्रूर हुए बिना दृढ़ रहें। अनावश्यक नुकसान पहुंचाए बिना निर्दोषों की रक्षा करें। स्पष्ट रूप से बोलें, समझदारी से सुनें और जब खतरे की स्थिति हो तो अकेले लड़ाई के बजाय जिम्मेदार मदद की जरूरत हो तो सुरक्षित रूप से दूर हट जाएं।", "आपकी कांपती आवाज़ अभी भी सच बता सकती है। आपका छोटा सा कार्य भी दूसरे व्यक्ति की किस्मत बदल सकता है। हर बार जब आप डर के बजाय मूल्यों से काम करते हैं तो साहस बढ़ता है। उस साहसी विकल्प से शुरुआत करें जो आपका है, न कि इस छवि से कि नायकों को कैसा दिखना चाहिए।", "जब आपकी आवाज कांपती है, तो याद रखें कि मैं इसे सुनता हूं। क्रोध के बिना धर्म के लिए खड़े रहें और क्रूरता के बिना रक्षा करें।"),
        reflection = "डर आपको देरी करने के लिए कह रहा है तो यह कौन सा सही काम है?",
        nextStep = "किसी सुरक्षित व्यक्ति को अपनी योजना बताएं, फिर सही कार्रवाई की ओर एक शांत और जिम्मेदार कदम उठाएं।"
    ),
    "ready-to-grow" to KrishnaLetterTranslation(
        situation = "जब आप बढ़ने के लिए तैयार हों",
        title = "जहां से आपने शुरुआत की थी, उससे नफरत किए बिना प्रकाश की ओर बढ़ें",
        preview = "विकास ईमानदार आत्म-दर्शन, धैर्यपूर्ण अभ्यास और एक समय में एक बेहतर विकल्प के साथ शुरू होता है।",
        paragraphs = listOf("विकास तब शुरू होता है जब आप यह छिपाना बंद कर देते हैं कि क्या बदलाव की जरूरत है। अपनी कमजोरियों पर शर्मिंदा न हों. उन्हें स्पष्ट रूप से देखें और उन पर धैर्यपूर्वक काम करें। एक बीज अपने छोटे होने के कारण खुद से नफरत नहीं करता। यह बस प्रकाश की ओर पहुंचता रहता है।", "अपने आप को बेकार कहे बिना उपयोगी सुधार स्वीकार करें। किसी शिक्षक, बड़े या विश्वसनीय गुरु से सीखें। जो कठिन है उसका अभ्यास करें. उन आदतों को छोड़ें जो आपके मन, शरीर या चरित्र को कमजोर करती हैं। आपको आज रात सब कुछ बदलने की ज़रूरत नहीं है; आज आपको एक ईमानदार वादा निभाने की ज़रूरत है।", "अपने विकास की तुलना किसी अन्य व्यक्ति की यात्रा से न करें। आपका प्रस्थान बिंदु, कर्तव्य और गति आपकी अपनी है। अपने आप को सच्चाई, निरंतर प्रयास और आपके द्वारा चुने गए विकल्पों से पैदा होने वाली भलाई के आधार पर मापें। प्रत्येक अनुशासित वापसी इस बात का प्रमाण है कि परिवर्तन पहले से ही हो रहा है।", "वह कमजोरी मेरे पास लाओ जिसे आप बिना किसी शर्म के बदलना चाहते हैं। मैं पूर्णता की आशा नहीं करता; मैं ईमानदारी, अभ्यास और इच्छुक हृदय की माँग करता हूँ।"),
        reflection = "कौन सी आदत या कमजोरी धैर्यवान और ईमानदार काम मांग रही है?",
        nextStep = "एक छोटा अभ्यास चुनें जिसे आप सात दिनों तक प्रतिदिन दोहरा सकते हैं और आज के पहले प्रयास को चिह्नित करें।"
    ),
    "walk-dharma" to KrishnaLetterTranslation(
        situation = "जब सही रास्ता अकेला महसूस हो",
        title = "भीड़ के बिना भी धर्म पर चलें",
        preview = "लोकप्रियता तेजी से बदल सकती है; साफ़ दिल की शांति आपके साथ रहती है।",
        paragraphs = listOf("कभी-कभी धर्म आपसे उस चीज़ को अस्वीकार करने के लिए कहेगा जिसे बाकी सभी लोग स्वीकार करते हैं। धोखा देने, झूठ बोलने, धमकाने, अपने शरीर को नुकसान पहुंचाने या क्रूर मजाक में शामिल होने से इनकार करने पर आपका मजाक उड़ाया जा सकता है। भीड़ आपके मूल्यों को कमजोरी कह सकती है क्योंकि आपकी पसंद उन्हें अपने मूल्यों की जांच करने पर मजबूर कर देती है।", "लोकप्रियता को सच्चाई समझने की गलती न करें। धीरे चलो, लेकिन अनुमोदन प्राप्त करने के लिए अपने चरित्र को मत त्यागो। साफ-साफ ना कहो. जब जरूरत हो तब निकलें. यदि स्थिति असुरक्षित हो तो किसी विश्वसनीय वयस्क या जिम्मेदार व्यक्ति से मदद मांगें। धर्म के लिए खड़े होने का मतलब अकेले ही हर खतरे का सामना करना नहीं है।", "ऐसे मित्र चुनें जो आपके स्वास्थ्य, ईमानदारी और भविष्य का सम्मान करें। उन लोगों के साथ धैर्य रखें जो नहीं समझते हैं, लेकिन उन्हें अपनी दिशा का नियंत्रण न सौंपें। अलग खड़े होने की असुविधा दूर हो जाएगी; अपने मूल्यों को बनाए रखने की ताकत आपके साथ चलेगी।", "अगर सही रास्ता अकेला लगता है, तो मेरा हाथ थाम लो। त्वरित अनुमोदन के लिए अपने मूल्यों का व्यापार न करें।"),
        reflection = "आपको किस मूल्य की रक्षा करनी चाहिए, भले ही दूसरे इसे स्वीकार न करें?",
        nextStep = "अपना स्पष्ट 'नहीं' एक वाक्य में लिखें और इसे किसी विश्वसनीय व्यक्ति के साथ साझा करें जो आपका समर्थन करेगा।"
    ),
    "dream-discipline" to KrishnaLetterTranslation(
        situation = "जब आपके सपने को अनुशासन की आवश्यकता हो",
        title = "दैनिक अभ्यास को सपने को पूरा करने दें",
        preview = "एक सपना केंद्रित प्रयास, बुद्धिमान तरीकों और सामान्य दिनों में किए गए वादों के माध्यम से साकार हो जाता है।",
        paragraphs = listOf("कोई भी सपना केवल इच्छाओं से विकसित नहीं हो सकता। इसके लिए आपके समय, फोकस और स्थिर प्रयास की आवश्यकता है। कुछ दिन आप प्रेरित महसूस करेंगे; अन्य दिनों में आप ऐसा नहीं करेंगे। दोनों पर ईमानदारी से काम करें. अनुशासन वह वादा है जिसे आप उत्तेजना शांत होने के बाद निभाते हैं।", "सोच-समझकर योजना बनाएं। एक विकर्षण को दूर करें, कार्य को स्पष्ट भागों में विभाजित करें और उन लोगों से सीखें जो पथ को समझते हैं। जब आपके शरीर को इसकी आवश्यकता हो तो आराम करें, लेकिन आराम को अपना स्थायी घर न बनाएं। स्मार्ट वर्क का मतलब है अपने तरीके की जांच करना, फीडबैक स्वीकार करना और केवल थकने के बजाय सुधार करना।", "अंतिम परिणाम की चिंता में आज की ताकत बर्बाद न करें। अपने सामने जो कर्तव्य है उसके प्रति अपना पूरा मन लगा दो। आपका सपना पूछ रहा है कि क्या आप उस व्यक्ति के रूप में विकसित होने के इच्छुक हैं जो इसे कौशल, धैर्य और विनम्रता के साथ निभा सकता है।", "मुझे अपना सपना दो, फिर आज के काम के माध्यम से इसका सम्मान करो। मैं न केवल उज्ज्वल प्रेरणा में बल्कि उस शांत अभ्यास में भी आपके साथ हूं जिसे कोई नहीं देखता।"),
        reflection = "प्रेरणा न होने पर भी कौन सा दैनिक अभ्यास आपके सपने को मजबूत बनाएगा?",
        nextStep = "आज एक केंद्रित कार्य अवधि निर्धारित करें, एक विकर्षण हटाएं और एक स्पष्ट कार्य पूरा करें।"
    ),
    "valuable-gift" to KrishnaLetterTranslation(
        situation = "जब आप सोचते हैं कि आप क्या दे सकते हैं",
        title = "दुनिया को उस भलाई की आवश्यकता है जो आप दे सकते हैं",
        preview = "आपका समय, कौशल, ध्यान और दयालुता पवित्र हो सकती है जब इसका उपयोग सेवा में किया जाए।",
        paragraphs = listOf("कभी भी यह विश्वास न करें कि आपके पास देने के लिए कुछ भी मूल्यवान नहीं है। हो सकता है कि आपके पास बहुत अधिक धन या प्रभाव न हो, लेकिन आपके पास ध्यान, समय, कौशल, दया और साहस है। एक धैर्यवान श्रोता अकेले दिल को हल्का कर सकता है। एक बहादुर आवाज़ किसी को नुकसान से बचा सकती है।", "ध्यान दें कि आपके अंदर स्वाभाविक रूप से क्या आता है और आप क्या अच्छी तरह से सीखने के इच्छुक हैं। आपका उपहार पढ़ाना, निर्माण करना, देखभाल करना, व्यवस्थित करना, सृजन करना, सुनना या किसी समस्या का समाधान करना हो सकता है जिसे दूसरे टालते हैं। अभ्यास के माध्यम से इसे मजबूत करें, फिर इसे वहां पेश करें जहां यह केवल प्रशंसा आकर्षित करने के बजाय वास्तव में मदद कर सकता है।", "अपनी रोशनी को छुपाएं नहीं क्योंकि दूसरा व्यक्ति अलग तरह से चमकता है। उनका उपहार आपके उपहार को कम नहीं करता है। बिना घमंड के अपनी योग्यता प्रदान करें और बिना शर्म के सुधार प्राप्त करें। एक प्रतिभा तब सार्थक हो जाती है जब वह उस व्यक्ति के जीवन को ऊपर उठा देती है जिसके पास वह है।", "मैंने आपके भीतर कुछ उपयोगी चीज़ रखी है, और इसे किसी अन्य व्यक्ति के उपहार की तरह दिखने की ज़रूरत नहीं है। इसे अच्छी तरह से सीखें, बिना अभिमान के इसे पेश करें और इसे जीवन की सेवा करने दें।"),
        reflection = "आपमें कौन सी क्षमता या गुण है जो आपसे परे किसी की सेवा कर सकता है?",
        nextStep = "इस सप्ताह तीस मिनट के लिए एक उपहार का उपयोग सिखाने, सुरक्षा करने, मदद करने या कुछ उपयोगी बनाने के लिए करें।"
    ),
    "future-still-open" to KrishnaLetterTranslation(
        situation = "जब एक परिणाम आपके भविष्य को बंद कर देता है",
        title = "आपका भविष्य एक परिणाम से बड़ा होता है",
        preview = "एक परीक्षा, अस्वीकृति या गलती आपके अगले कदम का मार्गदर्शन कर सकती है, लेकिन यह आपके पूरे भविष्य का नाम नहीं ले सकती।",
        paragraphs = listOf("इसका एक परिणाम यह हो सकता है कि हर सड़क बंद दिखेगी। एक परीक्षा, साक्षात्कार, अस्वीकृति या गलती आपको बता सकती है कि एक बार क्या हुआ था। यह आपको वह सब कुछ नहीं बता सकता जो आप बन सकते हैं। किसी दुखद परिणाम को अपने लिए स्थायी नाम में न बदलें।", "नतीजे आपको बताएंगे। पूछें कि किस ज्ञान, अभ्यास, समय या पद्धति में बदलाव की आवश्यकता है। किसी शिक्षक, गुरु या कुशल व्यक्ति से ईमानदार प्रतिक्रिया लें। जब लक्ष्य अभी भी सही हो तो फिर से तैयारी करें, या जब बुद्धि दिखाए कि आपके उपहार कहीं और हैं तो एक अलग रास्ता चुनें।", "कुछ दरवाजे बंद हो जाते हैं क्योंकि वे आपकी सड़क नहीं हैं। दूसरे आपसे बेहतर तैयारी के साथ लौटने के लिए कहते हैं। अंतर जानने के लिए धैर्य रखें. आपका भविष्य एक संकीर्ण द्वार नहीं है; यह मूल्यों, कौशलों, रिश्तों और अभी भी बनने की प्रतीक्षा कर रहे कई विकल्पों के माध्यम से बनाया गया है।", "एक परिणाम उस भविष्य को बंद नहीं कर सकता जो मैंने आपके सामने रखा है। सीखें, अपना तरीका बदलें और फिर से तैयारी करें, या ध्यान दें कि समझदार दरवाजा अब खुल रहा है।"),
        reflection = "क्या यह परिणाम आपको फिर से तैयारी करने, अपना तरीका बदलने या किसी अन्य रास्ते पर ध्यान देने के लिए कह रहा है?",
        nextStep = "किसी बुद्धिमान व्यक्ति से विशिष्ट प्रतिक्रिया के लिए पूछें और दिन समाप्त होने से पहले अगला व्यावहारिक कदम लिखें।"
    ),
    "next-step-strength" to KrishnaLetterTranslation(
        situation = "जब आपको अगला कदम उठाने के लिए ताकत की आवश्यकता होती है",
        title = "आपको केवल एक कदम के लिए पर्याप्त रोशनी की आवश्यकता होती है",
        preview = "विश्वास कार्रवाई को नहीं हटाता; यह आपको पूरी सड़क साफ़ होने से पहले शुरू करने की ताकत देता है।",
        paragraphs = listOf("शुरू करने से पहले आपको पूरी सड़क देखने की ज़रूरत नहीं है। अगला सही कदम उठाने के लिए आपको केवल पर्याप्त विश्वास की आवश्यकता है। हर संदेह के ख़त्म होने का इंतज़ार न करें। आप जो जानते हैं उससे शुरुआत करें और ईमानदार कार्रवाई से पता चले कि आगे क्या होता है।", "कॉल करें, किताब खोलें, माफ़ी मांगें, मदद मांगें या काम शुरू करें। ऐसा कार्य चुनें जो सत्य और कर्तव्य का पालन करता हो, न कि वह जो केवल त्वरित राहत देता हो। यदि कदम गंभीर जोखिम उठाता है, तो बुद्धिमान मार्गदर्शन लें और आगे बढ़ने से पहले एक सुरक्षित योजना बनाएं।", "मेरी उपस्थिति का मतलब यह नहीं है कि आपको शांत रहना चाहिए और अपना कर्तव्य पूरा करने के लिए मेरा इंतजार करना चाहिए। मैं तुम्हें स्थिरता, लोग, बुद्धि और अवसर देता हूं; आपके हाथों को अभी भी कार्य करना चाहिए। आज का एक ईमानदार कदम आपके कल लौटने का रास्ता बन सकता है।", "मेरे साथ चलने के लिए आपको पूरी सड़क देखने की ज़रूरत नहीं है। उस सत्य से शुरुआत करें जिसे आप जानते हैं और जो कर्तव्य आपके सामने हैं।"),
        reflection = "सबसे छोटा सही कदम क्या है जिसके बारे में आप पहले से ही जानते हैं कि आपको उठाने की जरूरत है?",
        nextStep = "उस चरण को अगले एक घंटे के भीतर करें, फिर अगला कदम तब लिखें जब आपका साहस जागृत हो।"
    ),
)
